window.UKDI_DATA={"meta":{"title":"Ruang UKDI","source":"Buku-UKDI.pdf","pages":247,"scope":"595 soal lengkap yang dapat dibaca dari PDF: Paket 1 sebanyak 198, Paket 2 sebanyak 200, dan Paket Prediksi sebanyak 197. Nomor 137–138 Paket 1 tidak ditemukan dalam PDF. Pada halaman PDF 243, bagian scan yang rusak membuat Paket Prediksi nomor 186–188 tidak dapat dipulihkan sebagai soal utuh. Sebanyak 27 pembahasan awal diperiksa terhadap referensi; soal lainnya merupakan transkripsi yang belum ditelaah ulang secara medis.","reviewedAt":"28 Oktober 2026","editorial":"Pembahasan disusun dengan bantuan AI dan ditautkan ke rujukan yang diperiksa; belum ditelaah dokter pengampu. Bukan bank soal resmi UKMPPD dan skor bukan prediksi kelulusan.","reviewedCount":27,"totalQuestions":595,"excluded":[{"package":"Paket 1","numbers":[137,138],"reason":"Halaman/nomor tidak terdapat pada PDF sumber."},{"package":"Paket Prediksi","numbers":[186,187,188],"reason":"Bagian bawah halaman PDF 243 rusak/tidak terbaca; stem dan/atau pilihan nomor 186–188 tidak dapat dipulihkan utuh. Isi tidak ditebak."}]},"refs":{"who-dia":{"org":"WHO","title":"Diarrhoeal disease","year":"2024","url":"https://www.who.int/news-room/fact-sheets/detail/diarrhoeal-disease","section":"Bagian Dehydration; klasifikasi berdasarkan kombinasi tanda klinis.","accessed":"28 Oktober 2026"},"who-pocket":{"org":"WHO","title":"Pocket Book: Diarrhoea","year":"2013","url":"https://www.ncbi.nlm.nih.gov/books/NBK154434/","section":"Tabel 12 dan penilaian dehidrasi pada anak.","accessed":"28 Oktober 2026"},"thyroid":{"org":"NICE","title":"NG145 — Thyroid disease","year":"2019; diperbarui 2023","url":"https://www.nice.org.uk/guidance/ng145/chapter/Recommendations","section":"Rekomendasi 1.6.21–1.6.25: antitiroid dan konteks penggunaan PTU.","accessed":"28 Oktober 2026"},"hmb":{"org":"NICE","title":"NG88 — Heavy menstrual bleeding","year":"2018; diperbarui 2021","url":"https://www.nice.org.uk/guidance/ng88/chapter/Recommendations","section":"Penilaian perdarahan, dampak kualitas hidup; bukan sekadar jumlah pembalut.","accessed":"28 Oktober 2026"},"uti":{"org":"UKHSA / GOV.UK","title":"Diagnosis of urinary tract infections","year":"2025","url":"https://www.gov.uk/government/publications/urinary-tract-infection-diagnosis/diagnosis-of-urinary-tract-infections-quick-reference-tools-for-primary-care","section":"Pielonefritis: demam, menggigil, nyeri pinggang dan bukti infeksi urin.","accessed":"28 Oktober 2026"},"tia":{"org":"NHS","title":"Transient ischaemic attack","year":"Halaman daring","url":"https://www.nhs.uk/conditions/transient-ischaemic-attack-tia/","section":"Gejala fokal sementara dan perlunya penilaian segera.","accessed":"28 Oktober 2026"},"sicca":{"org":"Penelitian klinis asli","title":"Treatment of Rhinitis Sicca Anterior","year":"2014","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4005055/","section":"Latar belakang/gejala: hidung kering, iritasi, krusta dan epistaksis. Studi intervensi nonacak; bukan pedoman terapi.","accessed":"28 Oktober 2026"},"twins":{"org":"NICE","title":"NG137 — Twin and triplet pregnancy","year":"2019; diperbarui 2024","url":"https://www.nice.org.uk/guidance/ng137/chapter/Recommendations","section":"Bagian 1.1: diagnosis, korionisitas dan amnionisitas dengan ultrasonografi.","accessed":"28 Oktober 2026"},"hook":{"org":"CDC","title":"DPDx — Intestinal Hookworm","year":"Halaman daring","url":"https://www.cdc.gov/dpdx/hookworm/","section":"Siklus hidup, penetrasi kulit, perdarahan usus dan anemia.","accessed":"28 Oktober 2026"},"imp":{"org":"CDC","title":"Clinical Guidance for Impetigo","year":"2025","url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/impetigo.html","section":"Lesi papul-pustul menjadi krusta madu; S. aureus maupun S. pyogenes.","accessed":"28 Oktober 2026"},"phar":{"org":"CDC","title":"Clinical Guidance for GAS Pharyngitis","year":"2025","url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/strep-throat.html","section":"Gejala faringitis, keterbatasan diagnosis etiologi secara klinis.","accessed":"28 Oktober 2026"},"hear":{"org":"RCGP","title":"Deafness and hearing loss toolkit","year":"Halaman daring","url":"https://elearning.rcgp.org.uk/mod/book/tool/print/index.php?id=12532","section":"Bagian Rinne dan Weber; interpretasi lateralisasi.","accessed":"28 Oktober 2026"},"storm":{"org":"Endotext","title":"Thyroid Storm","year":"2025","url":"https://www.ncbi.nlm.nih.gov/books/NBK278927/","section":"Clinical recognition dan faktor pencetus: infeksi serta putus antitiroid.","accessed":"28 Oktober 2026"},"mas":{"org":"WA Health / CAHS","title":"Meconium Aspiration Syndrome","year":"2023","url":"https://www.health.wa.gov.au/-/media/HSPs/CAHS/Documents/Health-Professionals/Neonatology-guidelines/Meconium-Aspiration-Syndrome-MAS.pdf","section":"Gambaran klinis dan diagnosis banding distres napas pada neonatus.","accessed":"28 Oktober 2026"},"cluster":{"org":"NHS Scotland","title":"Headache — guide to differentiating headache","year":"2025","url":"https://www.rightdecisions.scot.nhs.uk/dg-refhelp/neurology/headache/","section":"Tabel cluster: nyeri unilateral orbital, gejala otonom, durasi 15–180 menit.","accessed":"28 Oktober 2026"},"wil":{"org":"SciPy","title":"Wilcoxon signed-rank test","year":"Dokumentasi daring","url":"https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.wilcoxon.html","section":"Uji dua sampel berpasangan, asumsi distribusi selisih dan rank absolut.","accessed":"28 Oktober 2026"},"facial":{"org":"NIH / NINDS","title":"Bell’s Palsy","year":"Halaman daring","url":"https://health.nih.gov/health-topics-a-z/bellspalsy","section":"Kelemahan nervus fasialis dan pemeriksaan dahi, kelopak, serta mulut.","accessed":"28 Oktober 2026"},"hirsch":{"org":"NIDDK / NIH","title":"Diagnosis of Hirschsprung Disease","year":"Halaman daring","url":"https://www.niddk.nih.gov/health-information/digestive-diseases/hirschsprung-disease/diagnosis","section":"Temuan colok dubur, pencitraan, dan konfirmasi biopsi rektum.","accessed":"28 Oktober 2026"},"icd10":{"org":"WHO","title":"ICD-10 mental disorders: clinical descriptions","year":"1992","url":"https://cdn.who.int/media/docs/default-source/classification/other-classifications/9241544228_eng.pdf","section":"F20.0 skizofrenia paranoid dan F65.3 voyeurism; konteks klasifikasi lama.","accessed":"28 Oktober 2026"},"icd11":{"org":"WHO","title":"ICD-11: Clinical descriptions and diagnostic requirements","year":"2024","url":"https://www.who.int/publications/i/item/9789240077263/","section":"Manual diagnosis mutakhir: skizofrenia dan gangguan parafilik.","accessed":"28 Oktober 2026"},"voy":{"org":"WHO","title":"ICD-10 F65.3 Voyeurism","year":"2016","url":"https://icd.who.int/browse10/2016/en#/F65.3","section":"Mengamati perilaku intim tanpa sepengetahuan orang yang diamati.","accessed":"28 Oktober 2026"},"eye":{"org":"College of Optometrists","title":"Conjunctivitis (bacterial)","year":"2025","url":"https://www.college-optometrists.org/clinical-guidance/clinical-management-guidelines/conjunctivitis_bacterial","section":"Ringkasan publik: onset akut mata merah dan sekret, biasanya tanpa nyeri.","accessed":"28 Oktober 2026"},"seiz":{"org":"WHO","title":"Antiseizure medicines for established status epilepticus","year":"2023","url":"https://www.who.int/teams/mental-health-and-substance-use/mental-health-gap-action-programme/resources-centre/epilepsy-and-seizures/Antiseizure-medicines-for-management-of-established-status-epilepticus","section":"Pilihan lini kedua setelah dua dosis benzodiazepin; beberapa alternatif setara.","accessed":"28 Oktober 2026"},"htn":{"org":"NICE","title":"NG136 — Hypertension in adults","year":"2019; diperbarui 2026","url":"https://www.nice.org.uk/guidance/ng136/chapter/Recommendations","section":"Rekomendasi 1.5.1–1.5.2: tekanan darah sangat tinggi dan tanda kerusakan organ akut.","accessed":"28 Oktober 2026"},"para":{"org":"BAUS","title":"Balanitis & foreskin conditions","year":"Halaman daring","url":"https://www.baus.org.uk/trainees/balanitis_foreskin_conditions.aspx","section":"Parafimosis: preputium tertahan di belakang glans; kegawatdaruratan urologi.","accessed":"28 Oktober 2026"},"thal":{"org":"NHLBI / NIH","title":"Thalassemia — Diagnosis","year":"2022","url":"https://www.nhlbi.nih.gov/health/thalassemia/diagnosis","section":"Darah lengkap, uji hemoglobin dan pemeriksaan genetik.","accessed":"28 Oktober 2026"},"thal-s":{"org":"NHLBI / NIH","title":"Thalassemia — Symptoms","year":"2022","url":"https://www.nhlbi.nih.gov/health/thalassemia/symptoms","section":"Anemia, ikterus dan pembesaran limpa/hati pada bentuk berat.","accessed":"28 Oktober 2026"},"tb":{"org":"WHO","title":"Module 4: Treatment and care — summary","year":"2025","url":"https://www.ncbi.nlm.nih.gov/books/NBK613091/","section":"Pembaruan rekomendasi 1.7: kategori II ditinggalkan; uji kepekaan obat menentukan terapi.","accessed":"28 Oktober 2026"},"tb-id":{"org":"Kementerian Kesehatan RI","title":"Juknis Penatalaksanaan TB Sensitif Obat di Indonesia","year":"2025","url":"https://p2.kemkes.go.id/wp-content/uploads/2025/12/Buku-Petunjuk-Teknis-Penatalaksanaan-Tuberkulosis-Sensitif-Obat-di-Indonesia_FINAL.pdf","section":"Alur diagnosis dan pemeriksaan cepat molekuler; klasifikasi SO/RO dan pemilihan pengobatan sesuai hasil.","accessed":"28 Oktober 2026"},"lipid":{"org":"NICE","title":"NG238 — Lipid modification","year":"2023","url":"https://www.nice.org.uk/guidance/ng238/chapter/recommendations","section":"Statin untuk reduksi risiko kardiovaskular; keputusan berdasarkan risiko keseluruhan.","accessed":"28 Oktober 2026"},"bal":{"org":"CDC","title":"DPDx — Balantidiasis","year":"Halaman daring","url":"https://www.cdc.gov/dpdx/balantidiasis/","section":"Morfologi protozoa bersilia, makronukleus dan manifestasi disentri.","accessed":"28 Oktober 2026"}},"questions":[{"id":"p1-001","number":1,"package":"Paket 1","topic":"Anak","title":"Menilai dehidrasi","page":2,"stem":"Anak perempuan 4 tahun mengalami diare cair >10 kali sejak kemarin, tanpa lendir atau darah. Anak rewel dan haus, mata cekung, air mata berkurang, bibir kering, turgor menurun, akral hangat. Apa derajat dehidrasinya?","options":["Tanpa dehidrasi","Dehidrasi ringan–sedang","Dehidrasi sedang–berat","Dehidrasi berat","Dehidrasi sangat berat"],"bookKey":"B","answer":"B","reason":"Kombinasi rewel, mata cekung dan haus mendukung some dehydration, yang sepadan dengan dehidrasi ringan–sedang pada pilihan buku. Yang dinilai adalah gabungan tanda, bukan frekuensi BAB saja.","others":["Tanpa dehidrasi tidak cocok karena sudah ada beberapa tanda kehilangan cairan.","Kategori sedang–berat bukan klasifikasi tiga kelompok WHO.","Dehidrasi berat memerlukan kombinasi tanda seperti letargi, tidak mampu minum, atau cubitan kulit kembali sangat lambat. Tanda tersebut tidak dijelaskan.","Sangat berat juga bukan kategori tersendiri dalam klasifikasi WHO."],"takeaway":"Rewel + haus + mata cekung → pikirkan some dehydration.","refs":["who-dia","who-pocket"],"note":"","status":"sesuai","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-002","number":2,"package":"Paket 1","topic":"Penyakit Dalam","title":"Antitiroid vs pereda gejala","page":3,"stem":"Perempuan 24 tahun memiliki benjolan leher, berdebar, tremor dan sering berkeringat. Nadi 120/menit, mata eksoftalmus. TSH rendah, FT3 dan FT4 meningkat. Di antara pilihan berikut, obat mana yang menekan produksi hormon tiroid?","options":["Bisoprolol","Alprazolam","Levotiroksin","Fenobarbital","Propiltiourasil"],"bookKey":"E","answer":"E","reason":"Gambaran mengarah ke hipertiroidisme, kemungkinan Graves. PTU adalah antitiroid yang menghambat sintesis hormon; di antara opsi ini paling sesuai untuk terapi penyebab.","others":["Bisoprolol membantu gejala adrenergik tetapi tidak mengatasi peningkatan sintesis hormon.","Alprazolam tidak mengobati produksi hormon tiroid.","Levotiroksin menambah hormon tiroid dan tidak sesuai pada hipertiroidisme ini.","Fenobarbital bukan terapi antitiroid standar."],"takeaway":"Bedakan obat yang mengurangi produksi hormon dengan obat yang meredakan palpitasi.","refs":["thyroid"],"note":"PTU bukan pilihan awal universal untuk semua pasien Graves. NICE menawarkan karbimazol saat antitiroid dipilih; PTU dipertimbangkan pada keadaan tertentu, termasuk kehamilan/intoleransi. Metimazol/karbimazol tidak tersedia dalam opsi buku. Pertanyaan dirumuskan ulang untuk menegaskan mekanisme.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-003","number":3,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Perdarahan menstruasi memanjang","page":3,"stem":"Perempuan 23 tahun menstruasi 1–14 Januari, lalu 2–15 Februari. Tidak ada perdarahan di antara siklus. Mengganti pembalut 2–3 kali sehari. Apa istilah yang dimaksud dalam pilihan buku?","options":["Hipermenorea","Menoragia","Metroragia","Oligomenorea","Menometroragia"],"bookKey":"A","answer":null,"reason":"Fakta yang jelas adalah durasi perdarahan memanjang dengan interval antarsiklus relatif tetap. Buku memilih hipermenorea, tetapi pemakaian istilah hipermenorea dan menoragia tidak konsisten antarreferensi. Keduanya sering dipakai untuk perdarahan banyak; membedakannya hanya berdasarkan lama haid tidak aman.","others":["Metroragia merujuk perdarahan di luar pola menstruasi.","Oligomenorea merujuk menstruasi jarang, tidak ditunjukkan oleh interval sekitar satu bulan.","Menometroragia menggabungkan perdarahan tidak teratur dengan perdarahan banyak/memanjang.","Jumlah pembalut saja tidak cukup untuk memastikan volume kehilangan darah."],"takeaway":"Sebutkan pola secara deskriptif: perdarahan menstruasi memanjang; jangan bergantung pada istilah lama yang tumpang tindih.","refs":["hmb"],"note":"Kunci A dipertahankan sebagai catatan buku, bukan jawaban tunggal yang terverifikasi. Tidak masuk skor.","status":"ambigu","scored":false,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-004","number":4,"package":"Paket 1","topic":"Penyakit Dalam","title":"Demam dan nyeri ketok CVA","page":4,"stem":"Perempuan 27 tahun demam 39,3°C, menggigil dan nyeri pinggang kanan. Ada nyeri ketok sudut kostovertebra kanan, leukositosis, leukosit urin 10–12/LPB dan silinder leukosit. Diagnosis paling mungkin?","options":["Sistitis akut","Divertikulitis","Pielonefritis","Apendisitis","Vesikolitiasis"],"bookKey":"C","answer":"C","reason":"Demam tinggi, menggigil, nyeri pinggang dan nyeri ketok CVA dengan piuria mendukung infeksi saluran kemih atas, yaitu pielonefritis. Silinder leukosit memperkuat keterlibatan ginjal.","others":["Sistitis lebih sering menimbulkan disuria, urgensi dan nyeri suprapubik tanpa tanda sistemik menonjol.","Divertikulitis dan apendisitis tidak paling menjelaskan pola CVA serta temuan urin ini.","Batu kandung kemih lebih sesuai dengan gejala berkemih/hematuria; tanda infeksi ginjal lebih kuat pada kasus ini."],"takeaway":"Demam + nyeri pinggang/CVA + bukti infeksi urin → pielonefritis.","refs":["uti"],"note":"","status":"sesuai","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-005","number":5,"package":"Paket 1","topic":"Neurologi","title":"Defisit neurologis yang menghilang","page":4,"stem":"Laki-laki 68 tahun tiba-tiba bicara pelo saat bangun tidur. Keluhan menghilang dalam 4 jam. Ia memiliki hipertensi dan diabetes. Di antara opsi buku, diagnosis kerja paling mungkin?","options":["Stroke in evolution","Stroke nonhemoragik","Stroke hemoragik","RIND","Transient ischemic attack"],"bookKey":"E","answer":"E","reason":"Episode neurologis fokal yang pulih sepenuhnya mendukung dugaan TIA. Ini tetap perlu evaluasi segera; gejala yang membaik tidak berarti risikonya selesai.","others":["Stroke in evolution berarti defisit berkembang/progresif.","Stroke iskemik atau hemoragik tidak dapat dipastikan hanya dari tekanan darah dan waktu gejala.","RIND adalah istilah lama, biasanya untuk defisit yang lebih lama; bukan klasifikasi modern yang diutamakan."],"takeaway":"Gejala stroke yang hilang tetap darurat untuk evaluasi TIA dan pencegahan stroke.","refs":["tia"],"note":"Durasi <24 jam adalah definisi klinis historis. Pencitraan dapat menunjukkan infark walau gejala pulih; karena itu diagnosis di sini bersifat dugaan TIA, bukan konfirmasi tanpa pencitraan.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-006","number":6,"package":"Paket 1","topic":"THT","title":"Hidung kering dan mimisan","page":5,"stem":"Laki-laki 55 tahun, tukang sapu jalan yang sering terpapar debu, mengalami hidung kering, iritasi dan mimisan singkat berulang selama sebulan. Diagnosis yang paling sesuai dengan opsi buku?","options":["Rinitis vasomotor","Rinitis alergi","Rinitis medikamentosa","Rinitis sika","Rinitis akut"],"bookKey":"D","answer":"D","reason":"Rinitis sika berarti keluhan dominan kekeringan mukosa hidung, yang dapat disertai krusta, iritasi dan epistaksis. Pola ini lebih cocok dibanding rinitis dengan rinorea dominan.","others":["Rinitis vasomotor lebih sering berupa rinorea/kongesti karena pemicu nonalergi.","Rinitis alergi lebih sesuai dengan bersin, gatal dan rinorea terkait alergen.","Rinitis medikamentosa memerlukan riwayat penggunaan dekongestan topikal berlebihan.","Rinitis akut biasanya memiliki perjalanan infeksi akut dengan rinorea/kongesti."],"takeaway":"Kekeringan mukosa + iritasi + epistaksis ringan mengarah ke rinitis sika dalam konteks soal.","refs":["sicca"],"note":"Rujukan merupakan penelitian gejala, bukan pedoman terapi. Epistaksis menetap/berulang tetap memerlukan pemeriksaan penyebab lokal maupun sistemik.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-007","number":7,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Tiga bagian besar janin","page":6,"stem":"Ibu hamil 28 minggu memiliki perut lebih besar daripada usia kehamilan. Teraba tiga bagian besar janin, banyak bagian kecil, serta dua balotemen. Diagnosis paling mungkin?","options":["Mola hidatidosa","Oligohidramnion","Hidrosefalus","Gemeli","Kehamilan ektopik terganggu"],"bookKey":"D","answer":"D","reason":"Beberapa bagian besar janin dan dua balotemen meningkatkan kecurigaan kehamilan kembar. Temuan palpasi merupakan petunjuk; ultrasonografi mengonfirmasi jumlah janin dan menentukan korionisitas serta amnionisitas.","others":["Mola dapat membuat uterus lebih besar tetapi tidak menjelaskan beberapa bagian janin yang jelas.","Oligohidramnion tidak menjelaskan uterus besar dan multipel bagian janin.","Hidrosefalus tidak menjelaskan dua balotemen dan banyak bagian besar.","Kehamilan ektopik terganggu memiliki pola kegawatdaruratan yang berbeda."],"takeaway":"Curiga kembar dari palpasi; konfirmasi dan klasifikasikan dengan USG.","refs":["twins"],"note":"","status":"sesuai","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-008","number":8,"package":"Paket 1","topic":"Parasitologi","title":"Bermain tanpa alas kaki","page":6,"stem":"Anak 5 tahun diare dengan darah pada feses. Ia sering bermain di tanah/pasir tanpa sandal. Dari pilihan ini, cacing usus mana yang paling sesuai dengan pola penularan perkutaneus dan kehilangan darah usus?","options":["Necator americanus","Ancylostoma braziliense","Wuchereria bancrofti","Enterobius vermicularis","Strongyloides stercoralis"],"bookKey":"A","answer":"A","reason":"Cacing tambang N. americanus masuk melalui kulit sebagai larva filariform dan cacing dewasa melekat pada usus sehingga menyebabkan kehilangan darah, terutama pada infeksi berat. Ini paling sesuai dengan arah pertanyaan buku.","others":["A. braziliense pada manusia lebih khas menyebabkan cutaneous larva migrans.","W. bancrofti menyebabkan filariasis limfatik.","Enterobius lebih khas dengan gatal perianal malam hari.","Strongyloides juga masuk melalui kulit, tetapi petunjuk kehilangan darah pada soal lebih mengarah ke cacing tambang."],"takeaway":"Tanpa alas kaki → larva perkutaneus; cacing tambang → kehilangan darah/anemia.","refs":["hook"],"note":"Paparan tanah dan diare berdarah tidak membuktikan spesies. Kasus klinis nyata memerlukan pemeriksaan feses dan diagnosis banding disentri. Pertanyaan diperjelas untuk menanyakan pola cacing tambang.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-009","number":9,"package":"Paket 1","topic":"Kulit","title":"Krusta kuning madu","page":7,"stem":"Anak 7 tahun mengalami papul-pustul agak gatal di sekitar hidung dan mulut. Lesi mudah pecah dan tertutup krusta tebal kuning madu. Diagnosis paling mungkin?","options":["Ektima","Impetigo krustosa","Impetigo bulosa","Folikulitis/furunkel","Acne vulgaris"],"bookKey":"B","answer":"B","reason":"Lesi superfisial yang pecah lalu membentuk krusta madu merupakan gambaran khas impetigo nonbulosa atau impetigo krustosa.","others":["Ektima lebih dalam dan membentuk ulkus.","Impetigo bulosa ditandai bula flaksid.","Folikulitis/furunkel berpusat pada folikel rambut atau membentuk nodul/abses.","Acne biasanya disertai komedo dan pola distribusi berbeda."],"takeaway":"Krusta madu pada lesi superfisial anak → impetigo nonbulosa.","refs":["imp"],"note":"Buku menyebut Streptococcus dan hanya anak. Pembaruan: S. aureus maupun S. pyogenes dapat menjadi penyebab; orang dewasa juga dapat terkena.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-010","number":10,"package":"Paket 1","topic":"THT","title":"Nyeri telan dan faring hiperemis","page":7,"stem":"Perempuan 19 tahun sakit tenggorokan, demam dan nyeri telan selama 3 hari. Faring hiperemis-edema, dinding posterior bergranula; tonsil T1/T1 tidak hiperemis. Tidak pilek atau suara serak. Diagnosis anatomis paling sesuai?","options":["Tonsilitis akut","Limfadenitis","Faringitis akut","Laringitis akut","Rinitis akut"],"bookKey":"C","answer":"C","reason":"Lokasi peradangan dominan di faring dengan odinofagia mendukung faringitis. Tonsil tidak tampak meradang dan tidak ada serak yang mengarahkan ke laring.","others":["Tonsilitis memerlukan keterlibatan tonsil yang lebih menonjol.","Limfadenitis dapat menyertai, tetapi bukan lokasi utama keluhan.","Laringitis lebih khas dengan disfonia/serak.","Rinitis lebih dominan dengan gejala hidung."],"takeaway":"Kenali lokasi inflamasi sebelum menebak patogen.","refs":["phar"],"note":"Tidak ada pilek/serak tidak otomatis membuktikan streptokokus. Etiologi bakteri memerlukan penilaian dan, sesuai pedoman, tes yang relevan.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-011","number":11,"package":"Paket 1","topic":"THT","title":"Menilai sisi gangguan pendengaran","page":7,"stem":"Perempuan 23 tahun mengalami penurunan pendengaran. Tes Rinne positif, Weber lateralisasi ke kiri, dan Schwabach memendek. Dengan asumsi gangguan unilateral sederhana, diagnosis mana paling sesuai?","options":["Tuli konduktif kanan","Tuli konduktif kiri","Tuli sensorineural kanan","Tuli sensorineural kiri","Tuli campuran"],"bookKey":"D","answer":"C","reason":"Pada tuli sensorineural unilateral, Weber cenderung terdengar lebih kuat di telinga yang lebih baik. Lateralisasi ke kiri berarti gangguan sensorineural kanan lebih masuk akal. Rinne positif tidak menyingkirkan tuli sensorineural.","others":["Tuli konduktif sederhana biasanya memberikan Rinne negatif pada sisi yang terkena.","Tuli sensorineural kiri biasanya melateralisasikan Weber ke kanan, bukan kiri.","Tuli campuran memerlukan bukti gangguan konduktif sekaligus sensorineural; data ini belum menunjukkannya."],"takeaway":"SNHL: Weber ke telinga yang lebih baik. CHL: Weber ke sisi yang sakit.","refs":["hear"],"note":"Kunci buku D bertentangan dengan interpretasi Weber dalam kasus ini. Jawaban pembahasan C; asumsi unilateral perlu dicatat. Konfirmasi klinis menggunakan audiometri.","status":"koreksi","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-012","number":12,"package":"Paket 1","topic":"Penyakit Dalam","title":"Koma pada riwayat hipertiroid","page":8,"stem":"Perempuan 26 tahun koma, sebelumnya sulit tidur dan tubuh terasa hangat. Ia menghentikan pengobatan setelah 3 bulan, kemudian mengalami batuk berdahak. Nadi 120/menit, tiroid membesar difus, GDS 80 mg/dL. Diagnosis paling mungkin di antara opsi?","options":["Koma hipoglikemia","Hipotiroid subklinis","Hipertiroid subklinis","Krisis tiroid","Koma miksedema"],"bookKey":"D","answer":"D","reason":"Tirotoksikosis yang tidak terkontrol, kemungkinan infeksi sebagai pencetus, takikardi dan gangguan kesadaran berat mengarah ke krisis tiroid. Diagnosis bersifat klinis dan memerlukan penilaian sistemik.","others":["GDS 80 mg/dL tidak mendukung hipoglikemia sebagai penjelasan utama.","Gangguan tiroid subklinis tidak menjelaskan dekompensasi berat seperti koma.","Koma miksedema lebih cocok dengan hipotiroid berat, sering dengan hipotermia dan bradikardi."],"takeaway":"Putus antitiroid + pencetus infeksi + dekompensasi sistemik → curiga thyroid storm.","refs":["storm"],"note":"Kasus tidak memuat seluruh parameter skor krisis tiroid. Ini jawaban paling mungkin dari opsi, bukan diagnosis pasti hanya berdasarkan GDS dan nadi.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-013","number":13,"package":"Paket 1","topic":"Anak","title":"Distres napas setelah ketuban mekonium","page":8,"stem":"Bayi cukup bulan usia 10 jam merintih, sianosis, napas cuping hidung dan retraksi interkostal. Air ketuban mengandung mekonium; tali pusat dan kuku tampak kehijauan. Diagnosis paling mungkin?","options":["Respiratory distress syndrome","Asfiksia neonatorum","Hyaline membrane disease","Transient tachypnoea of newborn","Sindrom aspirasi mekonium"],"bookKey":"E","answer":"E","reason":"Distres respirasi pada bayi cukup bulan dengan paparan mekonium kuat mengarah ke sindrom aspirasi mekonium. Mekonium dapat menyumbat jalan napas dan menimbulkan inflamasi serta gangguan pertukaran gas.","others":["RDS/hyaline membrane disease lebih khas defisiensi surfaktan pada bayi prematur; dua opsi ini juga tumpang tindih.","Asfiksia dapat menyertai tetapi kurang spesifik menjelaskan keseluruhan petunjuk.","TTN juga menyebabkan takipnea, tetapi pewarnaan mekonium dan distres ini lebih mendukung aspirasi."],"takeaway":"Bayi cukup bulan + mekonium + distres respirasi → curiga MAS.","refs":["mas"],"note":"","status":"sesuai","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-014","number":14,"package":"Paket 1","topic":"Neurologi","title":"Nyeri orbital dengan gejala otonom","page":9,"stem":"Perempuan 50 tahun mengalami serangan nyeri kepala unilateral di pelipis dan sekitar mata. Pada sisi nyeri, mata merah dan berair serta hidung berair. Pemeriksaan di luar serangan tidak menunjukkan kelainan. Diagnosis paling mungkin?","options":["Cluster headache","Neuralgia trigeminal","Tension-type headache","Migrain dengan aura","Migrain tanpa aura"],"bookKey":"A","answer":"A","reason":"Nyeri orbital/temporal unilateral dengan lakrimasi, injeksi konjungtiva dan rinorea ipsilateral merupakan pola trigeminal autonomic cephalalgia, terutama cluster headache dari opsi ini.","others":["Neuralgia trigeminal lebih khas nyeri seperti sengatan singkat yang dipicu sentuhan/aktivitas.","Tension-type biasanya bilateral, menekan, tanpa pola otonom unilateral menonjol.","Migrain dapat unilateral tetapi pola gejala otonom kuat ini lebih mendukung cluster; aura tidak disebutkan."],"takeaway":"Orbital unilateral + lakrimasi/rinorea ipsilateral → pikirkan cluster.","refs":["cluster"],"note":"Buku menulis durasi serangan 5–80 menit. Rujukan yang diperiksa menyebut 15–180 menit. Durasi tiap serangan tidak tersedia pada stem, sehingga diagnosis perlu konfirmasi pola lengkap.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-015","number":15,"package":"Paket 1","topic":"Kesehatan Masyarakat","title":"Uji sebelum–sesudah","page":9,"stem":"Pengetahuan peserta tentang TBC diukur sebelum dan sesudah penyuluhan pada orang yang sama. Hasil dikategorikan baik, sedang, buruk. Uji mana yang dimaksud dari pilihan buku?","options":["t berpasangan","Wilcoxon","Chi-square","Spearman","One-way ANOVA"],"bookKey":"B","answer":"B","reason":"Buku mengarahkan ke Wilcoxon karena dua pengukuran berpasangan dengan tingkat pengetahuan berurutan. Di antara pilihan yang tersedia, ini jawaban yang lazim dimaksud dalam soal dasar.","others":["t berpasangan memerlukan pengukuran numerik dan asumsi distribusi selisih.","Chi-square independensi biasa tidak memperhitungkan pasangan subjek.","Spearman menilai hubungan peringkat, bukan perbedaan sebelum–sesudah.","One-way ANOVA biasa untuk perbandingan kelompok independen dan tidak sesuai desain ini."],"takeaway":"Tentukan dulu: tujuan perbandingan, skala data, dan apakah subjek berpasangan.","refs":["wil"],"note":"Wilcoxon memakai rank selisih dan asumsi tertentu. Untuk hanya tiga kategori ordinal, desain analisis perlu dinilai lebih teliti; sign test atau pendekatan marginal homogeneity dapat lebih tepat bergantung tujuan/data. Kunci ini bukan aturan universal untuk semua data ordinal.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-016","number":16,"package":"Paket 1","topic":"Neurologi","title":"Lagoftalmus dan sudut mulut","page":10,"stem":"Perempuan 50 tahun mengalami bibir tertarik ke kanan dan lagoftalmus. Nervus manakah yang paling mungkin terganggu dari pilihan berikut?","options":["N. VI kiri","N. VII kiri","N. VIII kiri","N. IX kiri","N. X kiri"],"bookKey":"B","answer":"B","reason":"N. fasialis mempersarafi otot ekspresi wajah termasuk orbicularis oculi. Kelemahan sisi kiri membuat penutupan mata terganggu dan mulut tertarik ke sisi kanan yang lebih kuat.","others":["N. VI mengatur abduksi mata, bukan otot ekspresi wajah.","N. VIII berkaitan dengan pendengaran dan keseimbangan.","N. IX dan X terutama terkait fungsi faring/laring, bukan pola kelemahan wajah ini."],"takeaway":"Kelopak sulit menutup + kelemahan ekspresi wajah → N. VII.","refs":["facial"],"note":"Menentukan saraf tidak sama dengan menentukan penyebab. Buku menyimpulkan stroke terlalu jauh; onset mendadak setelah jatuh perlu evaluasi neurologis dan temuan wajah atas/bawah secara lengkap.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-017","number":17,"package":"Paket 1","topic":"Bedah","title":"Belum BAB sejak lahir","page":11,"stem":"Bayi 1 minggu belum pernah BAB sejak lahir, muntah setelah menyusu dan perut distensi. Feses menyemprot setelah colok dubur. Enema kontras menunjukkan bagian distal menyempit dan proksimal melebar. Diagnosis paling mungkin?","options":["Meconium plug","Stenosis rektum","Meconium ileus","Penyakit Hirschsprung","Stenosis membran anus"],"bookKey":"D","answer":"D","reason":"Keterlambatan pengeluaran mekonium, distensi dan zona transisi pada enema mengarah ke Hirschsprung. Segmen tanpa sel ganglion gagal relaksasi dan menyebabkan obstruksi fungsional.","others":["Meconium plug dapat menyebabkan sumbatan awal tetapi tidak paling menjelaskan keseluruhan pola zona transisi dan temuan ini.","Meconium ileus terutama melibatkan usus halus dan memiliki konteks yang berbeda.","Stenosis anatomis rektum/anus perlu dibedakan dengan pemeriksaan; pola klasik ini lebih mendukung aganglionosis."],"takeaway":"Curiga Hirschsprung dari gejala; konfirmasi dengan biopsi rektum.","refs":["hirsch"],"note":"","status":"sesuai","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-018","number":18,"package":"Paket 1","topic":"Psikiatri","title":"Perilaku seksual dan syarat diagnosis","page":11,"stem":"Seorang perempuan merasa bergairah ketika melihat suaminya berhubungan seksual dengan orang lain. Buku meminta memilih istilah dari daftar ini. Informasi tentang persetujuan, durasi, distres dan gangguan fungsi tidak tersedia.","options":["Fetisisme","Eksibisionisme","Nekrofilia","Voyeurisme","Masokisme"],"bookKey":"D","answer":null,"reason":"Kunci buku D menggambarkan fokus melihat aktivitas seksual. Akan tetapi, skenario tidak memastikan pengamatan tanpa sepengetahuan/persetujuan ataupun kriteria gangguan. Fantasi atau perilaku konsensual tidak otomatis merupakan gangguan mental.","others":["Fetisisme memusat pada objek/bagian tubuh tertentu.","Eksibisionisme menekankan memperlihatkan alat kelamin kepada orang lain yang tidak mengharapkannya.","Nekrofilia berkaitan dengan jenazah; masokisme dengan rasa sakit/penghinaan.","Data skenario tidak cukup untuk menegakkan gangguan voyeuristik."],"takeaway":"Bedakan pola ketertarikan dengan diagnosis gangguan; nilai persetujuan, distres, fungsi dan durasi.","refs":["voy","icd11"],"note":"Tidak ada satu diagnosis gangguan yang dapat dipastikan. Kunci buku disimpan untuk transparansi; soal tidak masuk skor.","status":"ambigu","scored":false,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-019","number":19,"package":"Paket 1","topic":"Mata","title":"Mata merah dengan visus baik","page":12,"stem":"Perempuan 32 tahun mengalami mata merah selama 3 hari tanpa nyeri. Visus baik dan terdapat sekret purulen pada konjungtiva tarsal. Diagnosis anatomis paling sesuai?","options":["Konjungtivitis","Iritis","Glaukoma akut","Keratitis","Uveitis"],"bookKey":"A","answer":"A","reason":"Mata merah dengan sekret dan visus tetap baik tanpa nyeri lebih sesuai dengan konjungtivitis. Sekret purulen mengarah ke etiologi bakteri, tetapi etiologi perlu dinilai dalam konteks klinis.","others":["Iritis/uveitis lebih sering disertai fotofobia dan nyeri.","Glaukoma akut umumnya menimbulkan nyeri hebat dan gangguan visus.","Keratitis menimbulkan nyeri/fotofobia dan dapat menurunkan visus; perlu menilai kornea."],"takeaway":"Mata merah + sekret + visus baik + tanpa nyeri → konjungtivitis lebih mungkin.","refs":["eye"],"note":"Redaksi buku bertentangan: awalnya tertulis tidak ada sekret mukopurulen, lalu ditemukan sekret purulen. Ringkasan memakai temuan pemeriksaan; kontradiksi ditampilkan di sini.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-020","number":20,"package":"Paket 1","topic":"Neurologi","title":"Kejang setelah dua benzodiazepin","page":12,"stem":"Laki-laki 27 tahun mengalami kejang berulang tanpa pulih sadar di antara serangan. Kejang tetap berlangsung setelah dua pemberian diazepam injeksi. Obat berikut yang sesuai sebagai pilihan terapi lanjutan?","options":["Propofol","Fenitoin","Midazolam","Asam valproat","Fenobarbital"],"bookKey":"B","answer":null,"reason":"Ini mengarah ke established convulsive status epilepticus. Setelah dua dosis benzodiazepin yang adekuat, diperlukan obat antikejang lini berikut dengan pemantauan dan dukungan resusitasi. Fenitoin memang salah satu pilihan.","others":["WHO juga menerima valproat dan fenobarbital, selain fosfenitoin serta levetirasetam, sesuai fasilitas dan pemantauan.","Karena beberapa opsi buku dapat diterima, fenitoin bukan satu-satunya jawaban yang benar menurut rujukan yang diperiksa.","Anestesia/infus sedasi dipertimbangkan pada tata laksana refrakter dengan dukungan spesialis."],"takeaway":"Jangan menambah benzodiazepin tanpa batas; lanjutkan algoritme dengan obat lini berikut dan pemantauan.","refs":["seiz"],"note":"Kunci lama B tidak lagi unik: B, D atau E dapat sesuai dalam kerangka WHO, bergantung konteks. Soal tidak masuk skor tunggal.","status":"ambigu","scored":false,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-021","number":21,"package":"Paket 1","topic":"Penyakit Dalam","title":"Angka tekanan darah belum cukup","page":13,"stem":"Laki-laki 55 tahun nyeri kepala dan mual. Tekanan darah 210/140 mmHg, pemeriksaan generalis dan motorik disebut normal. Apa klasifikasi paling tepat menurut informasi yang tersedia?","options":["Hipertensi urgensi","Hipertensi emergensi","Hipertensi derajat II","Migrain","Stroke hemoragik"],"bookKey":"B","answer":null,"reason":"Tekanan darah ini sangat tinggi dan membutuhkan penilaian segera. Namun, emergensi hipertensi ditentukan oleh kerusakan organ target akut, bukan angka tekanan darah atau nyeri kepala saja. Kasus belum memberikan bukti yang cukup untuk memastikan emergensi.","others":["Tanpa kerusakan organ akut, hipertensi berat tanpa emergensi lebih mungkin, tetapi pemeriksaan untuk menyingkirkannya belum lengkap.","Pemeriksaan motorik normal tidak menyingkirkan semua kerusakan organ, misalnya retinopati akut, cedera ginjal atau gagal jantung.","Migrain/stroke hemoragik tidak dapat dipastikan hanya dari keluhan tersebut."],"takeaway":"Cari kerusakan organ akut sebelum melabeli emergensi hipertensi.","refs":["htn"],"note":"Kunci buku B tidak cukup didukung stem. Dibutuhkan status mental, funduskopi dan evaluasi organ sesuai gejala. Tidak masuk skor.","status":"ambigu","scored":false,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-022","number":22,"package":"Paket 1","topic":"Psikiatri","title":"Halusinasi dan waham menonjol","page":14,"stem":"Perempuan 34 tahun sejak 3 tahun sering mendengar suara menghina dan merasa pikirannya dikendalikan kekuatan gaib. Ia yakin diguna-guna. Tidak ada episode mood dominan yang dijelaskan. Dalam klasifikasi lama pada opsi buku, diagnosis paling mungkin?","options":["Skizofrenia hebefrenik","Skizofrenia paranoid","Skizofrenia simpleks","Skizofrenia residual","Skizoafektif"],"bookKey":"B","answer":"B","reason":"Dalam kerangka ICD-10 yang digunakan opsi, halusinasi auditorik dan waham yang menonjol dengan perjalanan lama paling cocok dengan skizofrenia paranoid. Diagnosis klinis tetap memerlukan penilaian fungsi, penggunaan zat, kondisi medis dan konteks budaya.","others":["Hebefrenik lebih menonjol dengan disorganisasi perilaku/pembicaraan dan afek.","Simpleks/residual lebih menonjol dengan gejala negatif, tidak menjelaskan gejala positif aktif ini.","Skizoafektif memerlukan komponen gangguan mood yang tidak dijelaskan pada stem."],"takeaway":"Pahami kerangka klasifikasi yang sedang ditanyakan, lalu cocokkan pola gejalanya.","refs":["icd10","icd11"],"note":"Istilah subtipe skizofrenia paranoid merupakan klasifikasi lama. ICD-11 menggunakan diagnosis skizofrenia beserta penjelas perjalanan/gejala, bukan subtipe lama. Jawaban dinilai hanya dalam konteks opsi historis.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-023","number":23,"package":"Paket 1","topic":"Bedah","title":"Preputium tidak dapat dikembalikan","page":14,"stem":"Anak 5 tahun mengalami pembengkakan ujung penis. Kulit yang tertarik ke belakang glans menjepit dan tidak dapat dikembalikan ke posisi semula. Diagnosis paling mungkin?","options":["Parafimosis","Hipospadia","Fimosis","Epispadia","Striktur uretra"],"bookKey":"A","answer":"A","reason":"Parafimosis adalah preputium yang telah diretraksi kemudian tertahan di belakang glans. Jeratan menyebabkan edema dan dapat mengganggu aliran darah, sehingga merupakan kegawatdaruratan urologi.","others":["Fimosis berarti preputium sulit/tidak dapat ditarik ke belakang sejak awal.","Hipospadia dan epispadia berkaitan dengan letak muara uretra.","Striktur uretra adalah penyempitan lumen uretra, bukan jeratan kulit glans."],"takeaway":"Fimosis: tidak bisa ditarik. Parafimosis: sudah tertarik, tidak bisa dikembalikan.","refs":["para"],"note":"Buku menulis frenulum; struktur yang relevan pada parafimosis adalah preputium. Ringkasan membetulkan istilah anatomi tersebut.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-024","number":24,"package":"Paket 1","topic":"Anak","title":"Anemia mikrositik dan ikterus","page":15,"stem":"Anak 9 tahun pucat sejak usia 6 tahun, kulit dan sklera ikterik, serta splenomegali. Hb 6,6 g/dL; MCV/MCH menurun; apusan darah menunjukkan anisositosis, polikromasi dan target cell. Diagnosis paling mungkin?","options":["Defisiensi asam folat","Defisiensi besi","Anemia aplastik","Defisiensi asam askorbat","Talasemia"],"bookKey":"E","answer":"E","reason":"Anemia mikrositik kronis disertai petunjuk hemolisis, pembesaran limpa dan target cell membuat talasemia paling mungkin dari opsi ini. Konfirmasi membutuhkan uji hemoglobin dan, bila perlu, pemeriksaan genetik.","others":["Defisiensi folat cenderung makrositik.","Defisiensi besi dapat mikrositik, tetapi ikterus dan splenomegali pada pola ini lebih mendukung hemolisis.","Aplasia biasanya ditandai kegagalan produksi beberapa lini sel; tidak paling sesuai dengan pola hemolisis ini.","Defisiensi vitamin C tidak paling menjelaskan keseluruhan gambaran."],"takeaway":"Mikrositik + hemolisis + splenomegali → pertimbangkan talasemia.","refs":["thal","thal-s"],"note":"Target cell tidak spesifik dan tidak menentukan subtipe talasemia. Pernyataan HbA tidak ada/HbF tinggi tidak berlaku untuk semua jenis talasemia.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-025","number":25,"package":"Paket 1","topic":"Penyakit Dalam","title":"TB kambuh: perbarui pendekatan","page":15,"stem":"Laki-laki 35 tahun batuk 3 minggu dengan hemoptisis. Dua tahun sebelumnya telah menyelesaikan OAT 6 bulan dan dinyatakan sembuh. Kini BTA positif. Buku meminta memilih regimen berikut.","options":["2RHZ–4RH","2RHE–4RH","2RHZE–4RH","2RHZES–1RHZE–5R3H3E3","2RHZE–4RH + streptomisin"],"bookKey":"D","answer":null,"reason":"Buku memilih regimen kategori II untuk kasus yang pernah diobati. Pendekatan itu sudah ditinggalkan WHO. Pada TB berulang, lakukan pemeriksaan resistansi/kepekaan obat agar regimen dipilih sesuai hasil, riwayat terapi dan pedoman program yang berlaku.","others":["Regimen tidak boleh ditentukan hanya dari status pernah berobat dan BTA positif.","Tidak ada pilihan yang sepenuhnya mewakili langkah evaluasi resistansi sebelum menentukan regimen.","Menambah streptomisin secara rutin berdasarkan kunci lama bukan pembaruan yang tepat."],"takeaway":"TB berulang → nilai resistansi; jangan menghafal kategori II sebagai pilihan otomatis.","refs":["tb","tb-id"],"note":"Kunci D adalah catatan historis dan tidak dijadikan jawaban terapi masa kini. Tidak masuk skor. Dosis/regimen harus mengikuti program nasional dan hasil pemeriksaan.","status":"usang","scored":false,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-026","number":26,"package":"Paket 1","topic":"Penyakit Dalam","title":"Obat penurun LDL","page":16,"stem":"Perempuan 55 tahun memiliki kolesterol total 325 mg/dL dan LDL 165 mg/dL. Dari pilihan berikut, obat mana merupakan statin untuk menurunkan LDL dan risiko kardiovaskular?","options":["Allopurinol","Atorvastatin","Probukol","Gemfibrozil","Fenofibrat"],"bookKey":"B","answer":"B","reason":"Atorvastatin menghambat HMG-CoA reduktase dan merupakan statin yang digunakan untuk menurunkan LDL serta risiko kejadian kardiovaskular pada indikasi yang sesuai.","others":["Allopurinol digunakan untuk masalah hiperurisemia, bukan penurun LDL utama.","Gemfibrozil dan fenofibrat merupakan fibrat yang lebih terkait penanganan trigliserida pada konteks tertentu.","Probukol bukan pilihan rutin utama dalam pedoman reduksi risiko kardiovaskular ini."],"takeaway":"Kenali kelas obat: atorvastatin → statin → penurunan LDL.","refs":["lipid"],"note":"Nyeri leher/pusing tidak membuktikan hiperkolesterolemia sebagai penyebab. Keputusan terapi dan dosis memerlukan penilaian risiko, komorbid, interaksi dan penyebab sekunder. Pertanyaan difokuskan pada kelas obat.","status":"konteks","scored":true,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-027","number":27,"package":"Paket 1","topic":"Parasitologi","title":"Morfologi parasit perlu diperjelas","page":16,"stem":"Laki-laki 34 tahun mengalami diare berdarah-berlendir, nyeri perut dan penurunan berat badan. Buku menggambarkan parasit bergerak cepat dengan redaksi morfologi yang kurang jelas pada scan. Organisme mana yang dimaksud oleh kunci?","options":["Entamoeba coli","Entamoeba histolytica","Giardia lamblia","Balantidium coli","Dientamoeba fragilis"],"bookKey":"D","answer":null,"reason":"Kunci buku D mengarah ke Balantidium coli. Ciri pembeda yang seharusnya dicari adalah protozoa besar bersilia dengan makronukleus menyerupai ginjal/kacang. Gejala disentri saja tidak dapat membedakannya dari amebiasis.","others":["E. histolytica juga dapat menyebabkan disentri; perlu morfologi yang lebih spesifik.","Giardia biasanya menyebabkan diare malabsorptif tanpa darah.","E. coli adalah ameba usus nonpatogen; bedakan namanya dari bakteri Escherichia coli.","Dientamoeba tidak memiliki silia khas Balantidium."],"takeaway":"Disentri memberi arah; morfologi parasit menentukan identifikasi.","refs":["bal"],"note":"Deskripsi di buku/scan tidak cukup tegas untuk membuktikan D. Tidak ditambahkan temuan silia seolah-olah tertulis dalam stem; soal tidak masuk skor.","status":"ambigu","scored":false,"checked":"2026-10-28","adaptation":"Ringkasan kasus dari buku; ejaan dirapikan.","reviewed":true},{"id":"p1-028","number":28,"package":"Paket 1","topic":"Campuran","title":"Soal 028 · Seorang wanita berusia 30 tahun datang dengan…","page":17,"stem":"Seorang wanita berusia 30 tahun datang dengan keluhan terdapat benjolan di payudara kiri dengan diameter 3 cm, tidak mobile, dan terdapat pembesaran pada maksilla sebesar IO cm. Pada pemeriksaan tampak pengaktifan nodul besarnya bervariasi h-2. Stadium penyakit tersebut adalahm","options":["TINIMO","TINOMI","T2NIMO","T3NIMO","T4NIM1"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Klasifikasi TNM pada karsinoma mammae Tx Tumor primer tidak dapat ditentukan Tis Karsinoma in situ dan penyakit paget pada papilla tanpa teraba tumor TO Tidak ada bukti adanya tumor primer TI Tumor < 2 cm T2 Tumor 2-5cm T3 Tumor > 5 cm T4 Tumor dengan penyebaran langsung ke dinding thoraks atau ke kulit dengan tanda oedem, tukak atau peau d'orange Nx Kelenjar regional tidak dapat ditentukan NO Tidak teraba kelenjar axilla NI Teraba kelenjar axilla homolateral yang tidak melekat N2 Teraba kelenjar axilla homolateral yang melekat satu sama Iain atau melekat pada jaringan sekitarnya N3 Terdapat kelenjar mamaria interna homolateral Mx Tidak dapat ditentukan metastasis jauh MO Tidak ada metastasis jauh MI Terdapat metastasis jauh termasuk ke kelenjar supraklavikular","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-029","number":29,"package":"Paket 1","topic":"Anak","title":"Soal 029 · Seorang bayi perempuan berusia 1 1 hari…","page":18,"stem":"Seorang bayi perempuan berusia 1 1 hari dibawa Oleh orang tuanya ke RS dengan keluhan keluar tinja dari vagina. Berdasarkan penjelasan dari orang tuanya diketahui bayi lahir di bidan, cukup bulan, dan langsung menangis. Pemeriksaan fisik didapatkan, keadaan umum baik, bayi aktif, anus ada, serta BAK baik. Diagnosis dari kondisi di atas adalahm","options":["Rektouretra fistula","Anomali vagina","Rektovaginal fistula","Atresia ani","Hirschprung disease"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gambaran klinis yang terdapat pada pasien adalah keluhan keluar tinja dari vagina.Hasil pemeriksaan keadaan umum baik. Oleh sebab itu, diperlukan pemeriksaan rektovaginal dengan jalanmenjalankan jari telunjuk di dalam rektum danibu jari didalamvagina.Jika fistula ditemukan, ada hubungan antara keduanya.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-030","number":30,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 030 · Seorang Iaki-laki berusia 16 tahun datang dengan…","page":18,"stem":"Seorang Iaki-laki berusia 16 tahun datang dengan keluhan sesak napas saat beraktivitas. Keluhan ini sudah dirasakan sejak 3 bulan yang lalu. Pada auskultasi jantung ditemukan bunyi jantung 1 mengeras dan terdapat opening snap saat diastolic dengan nada rendah di apeks. Hepar pasien tidak membesar. Kelainan jantung yang dialami Oleh pasien adalah","options":["Stenosis mitral","Stenosis aorta","Stenosis pulmonal","Regurgitasi mitral","Prolaps katup mitral"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gangguan katup jantung : Gangguan katup Auskultasi Stenosis aorta Suara kedua jantung (S2) yang lembut atau tidak terdengar dan murmur ejeksi sistolik yang kasar. Paling terdengar pada apeks dan menjalar ke area aorta (sterna kanan atas) dan leher. Stenosis pulmonal Murmur ejeksi sistolik yang kasar menjalar ke region pulmo dan bertambah keras saat inspirasi. Terdapat split yang lebar pada suara kedua jantung dengan komponen P2 yang lemah Regurgitasi mitral Pansistolik murmur monofasik dari suara I jantung (SI) ke suare kedua jantung (S2) pada apeks dan menjalar ke axilla Stenosis mitral Suara pertama jantung keras dan sering dapat teraba. Murmur dapa didahului opening snap dan dengan Ciri khas murmur berfrekuens rendah yang meningkat dengan sistol atrial dan olah raga Prolaps mitral Gambaran klinis berupa mitral regurgitasi","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-031","number":31,"package":"Paket 1","topic":"Campuran","title":"Soal 031 · Seorang Iaki-laki berusia 50 tahun datang ke…","page":19,"stem":"Seorang Iaki-laki berusia 50 tahun datang ke IGD dengan keluhan nyeri dada sebelah kiri. Nyeri dada dirasakan terutama saat berjalan kurang lebih 200 m. Nyeri juga dirasakan saat beraktivitas dan makan pagi. Nyeri berkurang dengan istirahat. Pemeriksaan foto toraks dan EKG terkesan normal. Diagnosis yang paling tepat pada pasien ini adalah.„","options":["Infark miokard akut","CHF","Efusi perikardium","Stable angina","Unstable angina"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Angina pectoris stabil : nyeri dada angina yang konsisten dan dapat diprediksi kapan akan timbul. Umumnya terjadi saat aktivitas fisik atau stres emosional dan menghilang dengan istirahat atau obat nitrat. Gambaran elektrokardiografi biasanya normal dan kadar enzim dalam batas normal. Pada pasien ini mengalami gejala angina yang mereda dengan istirahat dan hasil EKG normal. 32. Seorang laki-laki berusia 30 tahun ditemukan meninggal di rumahnya. Hasil Otopsi","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-032","number":32,"package":"Paket 1","topic":"Kulit","title":"Soal 032 · ditemukan jejas jerat di leher arah serong…","page":19,"stem":"ditemukan jejas jerat di leher arah serong dari depan ke atas belakang. Lebar jejas 4 cm dengan dasar berwarna coklat dan terdapat bengkak di samping. Mukosa bibir dan ujung ujung jari berwarna biru. Muka berwarna gelap dan mata berwarna kemerahan• Terdapat bendungan pembuluh darah pada seluruh organ dalam. Tidak ada tanda tanda kekerasan. Penyebab kematian pada kasus di atas adalah...","options":["Sianosis pada mukosa dan kulit","Penjeratan pada leher menutup jalan nafas","Bendungan darah pada organ","Rusaknya organ leher","Mati lemas"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Mekanisme kematian pada kasus gantung : a. Kerusakan pada batang otak dan medulla spinalis, terjadi akibat dislokasi atau fraktur vertebra ruas leher, misalnya judicial hanging ( hukum gantung) a. Asfiksia, akibat terhambat aliran udara pernapasan b. Iskemia, akibat terhambatnya aliran arteri-arteri leher c. Refleks vagal","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-033","number":33,"package":"Paket 1","topic":"Mata","title":"Soal 033 · Seorang pasien wanita berusia 22 tahun GIPoAo…","page":20,"stem":"Seorang pasien wanita berusia 22 tahun GIPoAo diantar Oleh bidan ke IGD dengan kelemahan pada kedua tungkai, penglihatan kabur, muntah-muntah dan nyeri epigastrium. Pemeriksaan vital sign didapatkan tekanan darah 170/100 mmHg. Dari hasil pemeriksaan urine didapatkan proteinuria (+++). Diagnosis yang paling tepat pada pasien ini adalah...","options":["PER","PEB","Impending eclampsia","Eklampsi","Superimposed hypertension"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Impending eklampsia adalah preeklampsi berat disertai dengan keluhan-keluhan : a. Nyeri kepala didaerah frontal, kadang pada daerah oksipital yang tidak hilang dengan pengobatan. b. Nyeri pada epigastrium atau pada kuadran atas sebagai akibat kapsula hepatica dlisoni teregang karena perdarahan atau mungkin karena sebab sentral. c. Gangguan penglihatan karena spasme arteriol, iskemik, edema dan kadang ablasio retina atau sebab sentral.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-034","number":34,"package":"Paket 1","topic":"Campuran","title":"Soal 034 · Seorang perempuan berusia 20 tahun datang dengan…","page":20,"stem":"Seorang perempuan berusia 20 tahun datang dengan keluhan terdapat benjolan di bahu kiri sebesar kelereng sejak 2 tahun yang lalu. Pada pemeriksaan fisik ditemukan massa subkutis berukuran 2 x 3 cm, konsistensi kenyal lunak, tidak nyeri, dan mudah digerakkan dengan jari sekitar. Diagnosis pada pasien ini adalah...","options":["Lipoma","Fibroma","Ateroma","Fibrosarkoma","Neurofibroma"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Lipoma adalah tumor kulit yang lazim ditemukan, yang terdiri dari sel lemak matang. Tumor ini merupakan massa lunak tidak nyeri yang timbul tunggal dan jarang majemuk. Lipoma yang tampak sebagai lemak dengan permukaan lebih rata, berwarna sedikit lebih tua daripada lemak normal. Lipoma bersifat lunak, mudah digerakkan dari sekitarnya dan tidak nyeri.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-035","number":35,"package":"Paket 1","topic":"Neurologi","title":"Soal 035 · Seorang laki-laki berusia 30 tahun datang dengan…","page":21,"stem":"Seorang laki-laki berusia 30 tahun datang dengan penurunan kesadaran, sebelumnya pasien mengeluh sakit pada perut kanan bawah. Pada pemeriksaan fisik didapatkan defans muscular (+), tekanan darah 1 10/60 mmHg, nadi 120x/menit, RR 24 x/menit, suhu 38.5 C. Pemeriksaan laboratorium Hb IO, trombosit 250.000, leukosit 22.000. Diagnosis yang tepat pada pasien ini adalah...","options":["Syok hipovolemik","Syok sepsis","Syok kardiogenik","Syok obstruktif","Syok neurogenik"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Syok adalah kumpulan gejala akibat perfusi selular tidak cukup, asupan 02 tidak cukup untuk metabolisme. Sedangkan syok sepsis adalah SIRS + fokus infeksi, tanda-tanda SIRS yaitu takikardi (>90x/menit), takipnea (>20x/menit), suhu (<36 atau >38), leukosit (<4000 atau >12000). Pada kasus ini pasien kondisi tidak sadar setelah sebelumnya sakit perut kanan bawah. Bisa dipikirkan kemungkinan app perforasi — peritonitis — sepsis.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-036","number":36,"package":"Paket 1","topic":"Campuran","title":"Soal 036 · Seorang Iaki-laki berusia 23 tahun datang dengan…","page":21,"stem":"Seorang Iaki-laki berusia 23 tahun datang dengan keluhan sejak 5 hari yang lalu mengalami nyeri di ujung kaki kanan. Pemeriksaan jari di kaki kanan tampak pucat dan dingin dibandingkan dengan ujung jari kaki kiri. Sejak 3 minggu yang lalu, pasien mengalami sakit kepala terus-menerus. Tekanan darah di lengan kiri dan kanan sama, tetapi tekanan darah di tungkai kanan lebih lemah dari yang lain. Diagnosis yang paling tepat untuk pasien tersebut","options":["Tromboangitis obliterans","Arteritis takayasu","Tromboflebitis","Arteriosclerosis","Aterosklerosis obliterans"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Arteritis takayasu adalah penyakit inflamasi yang sering mengenai aorta ascenden dan cabang aorta yang menyebabkan obstruksi pada aorta dan arteri utamanya. Kriteria diagnosis: >Usia≤ 40 tahun >Klaudikasio ekstremitas > Menurunnyapulsasiarteribrachialis Perbedaan tekanan darah > 10 mmHg antara kedua lengan Bruit arterisubklavia atau aorta >Abnormalitas angiogram","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-037","number":37,"package":"Paket 1","topic":"Campuran","title":"Soal 037 · Seorang laki-laki berusia 35 tahun, datang dengan…","page":22,"stem":"Seorang laki-laki berusia 35 tahun, datang dengan keluhan demam yang telah dirasakan sejak I minggu yang lalu,demam dirasakan naikturun. Demam disertai dengan perubahan kencing menjadi kuning pekat seperti air teh. Dari hasil anamnesis diketahui bahwa pasien pernah menderita penyakit kuning 6 tahun yang lalu dan masih mengkonsumsi alkohol sampai sekarang. Pemeriksaan darah ditemukan virus yang masih aktif bereplikasi. Penanda yang tepat pada kasus di atas adalah...","options":["HbeAg","HbsAg","HBcAg","IgG anti HAV","IgG anti HAV"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"-Tanda - Intepretasi Hepatitis A IgM HAV Infeksi akut IgG HAV Infeksi dimasa lalu Hepatitis B HBsAg Infeksi aktif/sedang berlangsung. Muncul sebelum gejala muncul HbeAg Bukti replikasi virus dan infektivitas IgM anti HBc Infeksi akut Window period HbsAg (-), anti HBS belum (+) Anti HBS Resolusi penyakit aktif Petanda imunitas (petanda tunggal pasca imunisasi) IgG anti HbC Anfeksi HBV lampau HbsAg (-), kronis HbsAg (+) IgG anti Hbe Replikasi virus <<, infektivitas HBV DNA Replikasi aktif virus di hepar Hepatitis C Anti HCV atau HCV RNA Sedang menderita hepatitis C","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-038","number":38,"package":"Paket 1","topic":"Campuran","title":"Soal 038 · Seorang anak Iaki-laki usia 7 tahun terdapat…","page":22,"stem":"Seorang anak Iaki-laki usia 7 tahun terdapat gangguan mental dan ditemukan tanda- tanda wanita yaitu bersuara tinggi. Pada pemeriksaan fisik didapatkan pertumbuhan pada payudaranya, testil kecil dan alat genital bagian luar tampak normal. Pada analisis semen tidak didapatkan spermatozoa. Pemeriksaan karyotyping DNA, ditemukan tambahan seks kromosom X sehingga nomenklaturya 47+XXY dan formula kromosomnya adalah trisomi kromosom seks. Diagnosis yang paling mungkin adalah...","options":["Sindrom turner","Sindrom Jacobs","Sindrom marfan","Sindrom down","Sindrom klinefelter"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"a. Sindrom down (Trisomi 21) Ciri-ciri: retardasi mental, dagu kecil, mongoloid face, hidung pipih, Iipatan palmar tunggal, makroglosia,jarak lebar antara ibu jari kaki dan jari kedua. b. Sindrorm jacobs (47+XYY) Ciri-ciri : berwajah kriminal, suka menusuk-nusuk mata c. Sindrom marfan (Kelainan genetik pada jaringan kolagen) Ciri-ciri : jangkung, ekstremitas panjang, jari-jari tipis dan panjang. Komplikasi serius: aneurisma aorta d. Sindrom klinefelter (47+XXY pada laki-laki) Ciri-ciri: hipogonadisme (fitur seks sekunder berkurang), fertilitas berkurang. e. Sindrom turner (45+)(0 pada perempuan) Ciri-ciri: pendek, webbed neck, amenorea, steril.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-039","number":39,"package":"Paket 1","topic":"Neurologi","title":"Soal 039 · Seorang Iaki-laki berusia 23 tahun dibawa ke…","page":23,"stem":"Seorang Iaki-laki berusia 23 tahun dibawa ke IGD RS dengan penurunan kesadaran 2 jam yang lalu. Sebelumnya pasien mengalami demam hilang timbul. 3 hari sebelumnya pasien demam tinggi, menggigil dan keringat dingin. Pada pemeriksaan vital sign didapatkan TD 100/70mmHg, Nadi 88x/menit, RR 20x/menit, Suhu 38,5 C, kulit tampak pucat, konjungtiva anemis. Pada pemeriksaan Iainya ditemukan plasmodium sausage shape. Penyebab penurunan kesadaran dari pasien adalah.„","options":["Malaria falciparum","Malaria ovale","Malaria vivax","Malaria malariae","Malaria kuartana"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"c","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-040","number":40,"package":"Paket 1","topic":"Kulit","title":"Soal 040 · Seorang anak berusia 5 tahun diantar Oleh…","page":24,"stem":"Seorang anak berusia 5 tahun diantar Oleh ibunya ke puskesmas dengan keluhan muncul bintil-bintil di bagian perut. Dari pemeriksan dermatologi didapatkan papul milier, berwarna putih seperti lilin, multiple dan berbentuk kubah yang di tengahnya terdapat lekukan dan jika dipijat tampak keluar masa berwarna putih seperti nasi. Diagnosis pasien tersebut adalah...","options":["Moluscum contagiosum","Varisela","Varisela Zooster","Scabies","Pedikulosis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Moluskum contagiosum adalah penyakit yang disebabkan Oleh virus poks. Kelainan kulit berupa papul miliar kadang lentikular dan berwarna putih seperti lilin berbentuk kubah yang ditengahnya terdapat lekukan, jika dipencet akan keluar massa berwarna putih seperti nasi. Predileksi di muka, badan dan ektremitas sedangkan pada orang dewasa didaerah pubis dan genitalia eksterna.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-041","number":41,"package":"Paket 1","topic":"Anak","title":"Soal 041 · Seorang bayi Iaki-laki berusia 3 bulan dibawa…","page":24,"stem":"Seorang bayi Iaki-laki berusia 3 bulan dibawa ke RS dengan keluhan penis tampak tidak normal. Pada pemeriksaan fisik ditemukan dorsal penis hampir menempel ke kulit abdomen. Tampak mukosa uretra pada dorsal penis dengan efek meluas dari skrotum sampai dengan gland penis, dan celah tulang pubis tampak melebar. Diagnosis pada pasien ini adalah...","options":["Epispadia","Hipospadia penile shaft","Hipospadia penoskrotal","Hipospadia perineal","Hipospadia panesratal"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Epispadia merupakan kelainan anomali congenital pada uretra yang terletak di bagian dorsal. Tipe epispadia : a. Tipe glandular : uretra terbuka pada Sisi dorsal glans, luar dan datar b. Tipe penile : meatus uretra terletak diantara simfisis pubis dan sulkus koronal. Pada distal biasanya terdapat lekukan sepanjang meatus sampai ke glans c. Tipe penopubik : meatus uretra terletak pada penopubic junction dan seluruh penis memiliki lekukan dorsal pada bagian distal hingga mencapai glans","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-042","number":42,"package":"Paket 1","topic":"Neurologi","title":"Soal 042 · Seorang perempuan berusia 24 tahun dibawa ke…","page":24,"stem":"Seorang perempuan berusia 24 tahun dibawa ke IGD dengan riwayat tertabarak sepeda motor. Pemeriksaan fisik didapat kesadaran compos mentis, vital sign : TD 100/60, Nadi 100 x/menit, pulsasi lemah, RR 30 x/menit. Pasien tidak dapat berjalan dan mengerang kesakitan. Didapat hematom pada tungkai atas kanan, nyeri tekan (+), nyeri sumbu akral dingin dan pucat. Tindakan pertama yang dilakukan adalah...","options":["Resusitasi","Reposisi","Imobilisasi","Kenali dan hentikan perdarahan","Airway management"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Primary survey : 1. Airway management 4. Disability 2. Breathing 5. Environment 3. Circulation Secondary Survey a. History tamponade : Allergic, Medication, Pastillness, Lastmeals, Event b. Physical exam: head to toe c. Every orifice examination d. Complete Neurological examination e. Special diagnostic tests","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-043","number":43,"package":"Paket 1","topic":"Bedah","title":"Soal 043 · Seorang perempuan berusia 40 tahun, datang dengan…","page":25,"stem":"Seorang perempuan berusia 40 tahun, datang dengan keluhan heartburn, yang sudah dira- sakan sekitar 3 tahun kumat-kumatan. Telah dilakukan pemeriksaan USG abdomen, EKG, dan foto toraks PA menunjukkan hasil yang normal. Untuk lebih menunjang diagnose kemudian dilakukan pemeriksaan gastroduodenografi. Kelainan yang dapat ditemukan melalui pemer- iksaan gastroduodenografi ini adalah„.","options":["Gastritis atrofikans","Akalasia","Esofagitis","Sliding hernia","Duodenitis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Heartburn merupakan rasa terbakar susternal/retrosternal. Keluhan ini mirip dengan keluhan pada pasien dengan serangan angina pectoris. Keluhan heartburn biasanya merupakan gejala yang mengarah pada diagnosis esofagitis. Pada pasien ini hasil pemeriksaan EKG tidak menunjukkan adanya kelainan sehingga kecurigaan pada angina pectoris dapat disingkirkan. Dengan pemeriksaan gastroduodenografi diharapkan keadaaan mukosa esofagus dapat teramati.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-044","number":44,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 044 · Seorang wanita usia 30 tahun datang dengan…","page":25,"stem":"Seorang wanita usia 30 tahun datang dengan keluhan tidak haid sejak 2 bulan yang Pada pemeriksaan fisik vital sign dalam batas normal, pemeriksaan obsetrik didapatW warna kebiruan pada vagina yang merupakan tanda obsetrik kehamilan. Disebut apakah tanda ini?","options":["Tanda Hegar","Tanda Piscacek","Tanda Chadwick","Tanda Bandl","Tanda Braxton-Hicks"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tanda Hegar: segmen bawah uterus lembek pada perabaan Tanda Piscacek: uterus membesar ke salah satu jurusan Tanda Chadwick: Selama kehamilan < 6 minggu, mukosa vagina sering kelihatan gelap merah kebiruan atau merah muda (livid) Tanda Band': cincin yang terbentuk akibat retraksi segmen atas dan segmen bawah uterus yang terjadi pada kelahiran macet seperti distosia bahu. Hal ini menjadi petanda bahwa akan segera terjadi ruptur uterus. Harus segera dilakukan sc. Tanda Braxton-Hicks: uterus berkontraksi saat dirangsang. Tanda uterus ini khas pada masa kehamilan. 45. Seorang wanita berusia 50 tahun datang dengan keluhan nyeri pada jempol kaki yang dirasakan saat bangun tidur. Pasien merasakan keluhan ini sejak 1 hari yang lalu setelah mengkonsumsi soto babat. Pemeriksaan vital sign dalam batas normal. Pemeriksaan fisik","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-045","number":45,"package":"Paket 1","topic":"Campuran","title":"Soal 045 · ditemukan jempol bengkak, hyperemia, dan terdapat nyeri…","page":26,"stem":"ditemukan jempol bengkak, hyperemia, dan terdapat nyeri tekan. Diagnosis yang tepat pada pasien ini adalah...","options":["Sistemik Lupus Eritematosus","Osteoarthritis","Osteoporosis","Artritis Gout","Rheumatoid artritis"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Artritis gout merupakan suatu sindrom klinis yang mempunyai gambaran khas yaitu arthritis akut sebagai respon inflamasi jaringan terhadap pembentukan Kristal monosodium urat monohidrat. Manifestasi klinis : a. Arthritis, tofi dan batu ginjal (mikrotofi, nefrolithiasis, pielonefritis kronis) b. Serangan sering pada malam hari Pemeriksaan penunjang : a. Kadar asam urat > 6 mg% b. Leukositosis ringan c. LED meningkat d. Kadar asam urat urin >500 mg5/liter per 24 jam e. Pemeriksaan cairan tofi ditemukan gambaran Kristal urat pada sediaan mikroskopik","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-046","number":46,"package":"Paket 1","topic":"THT","title":"Soal 046 · Seorang laki-laki berusia 23 tahun, datang ke…","page":27,"stem":"Seorang laki-laki berusia 23 tahun, datang ke praktek dokter umum dengan mengatakan bahwa dirinya terancam akan dibunuh Oleh saudaranya. Pasien juga mengaku sebagai keluarga gubernur, walaupun sesungguhnya ia tidak ada hubungan. Hal ini diketahuinya karena ia mendengar suara bisikan di telinganya akibatnya ia tidak bisa bekerja dan tidal( berani keluar rumah, susah tidur dan tidak mau mandi. Hal ini sudah berlangsung selama 2 bulan. Pada pemeriksaan, tidak ditemukan kelainan. Gejala kejiwaan apa yang terdapat pada pasien tersebut?","options":["Depersonalisasi","Ilusi","Derealisasi","Halusinasi","Delusi"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Delusi adalah keyakinan tentang suatu isi pikiran yang tidak sesuai dengan kenyataan atau tidak cocok dengan intelegensi dan latar belakang kebudayaannya biarpun dibuktikan kemustahilan hal itu.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-047","number":47,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 047 · Seorang wanita berusia 26 tahun G,PoAo hamil…","page":27,"stem":"Seorang wanita berusia 26 tahun G,PoAo hamil 28 minggu datang dengan keluhan batuk yang tidak kunjung sembuh sejak 3 minggu ini. Batuk berdahak kental disertai darah. Terkadang disertai demam ringan dan keringat pada malam hari. Dokter mendiagnosis TBC. Berikut adalah obat yang harus dihindari karena dapat menyebabkan gangguan pendengaran pada janin adalah.„","options":["Rifampisin","Etambutol","Isoniazid","Streptomicin","Pirazinamid"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Efek Samping Penyebab Penatalaksanaan Gatal dan kemerahan kulit Semua jenis OAT Ikuti petunjuk penatalaksaan di bawi Tuli Streptomisin Strptomisin dihentikan, ganti Etambl Gangguan keseimbangan Streptomisin Strptomisin dihentikan, ganti Etambl Ikterus tanpa penyebab lain Hampir semua Hentikan semua OAT sampai ikterus OAT menghilang Bingung muntah-muntah Hampir semua Hentikan semua OAT, segera lakukan (permulaan ikterus karena obat) OAT fungsi hati Gangguan penglihatan Etambutol Hentikan Etambutol Purpura dan renjatan (Syok) Rifampisin Hentikan Rifampisin","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-048","number":48,"package":"Paket 1","topic":"Bedah","title":"Soal 048 · Seorang laki-laki 24tahun dibawa ke IGD setelah…","page":28,"stem":"Seorang laki-laki 24tahun dibawa ke IGD setelah mengalami kecelakaan lalu lintas terjatuh dari sepeda motor. Saat terjatuh selangkangan terbentur Stang motor. Pada pemeriksaan fisik didapatkan airway, breathing dan circulation dalam batas normal. Status lokalis : terdapat jejas pada daerah suprapubik, bulging (+), hematom pada penis dan scrotum. Pada meatus uretra eksterna ditemukan bercak darah yang sudah mengering, nyeri tekan suprapubik. Apakah kondisi yang dialami pasien tersebut?","options":["Fraktur pelvis","Ruptur vesica urinaria","Trauma scrotum","Contusio penis","Ruptur uretra"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Daerah selangkangan terkena Stang straddle injury Gejala ruptur uretra : 1. Ruptur uretra anterior Bloody discharge, hematoma scrotum dan pelvis 2. Ruptur uretra posterior Hematoma perineum, fraktur pelvis, floating prostat pada pemeriksaan RT","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-049","number":49,"package":"Paket 1","topic":"Kesehatan Masyarakat","title":"Soal 049 · Seorang laki-laki berusia 28 tahun datang ke…","page":28,"stem":"Seorang laki-laki berusia 28 tahun datang ke Puskesmas dengan keluhan badan terasa dingin sejak pagi hari yang disertai dengan mual dan muntah. Pasien sudah mengalami demam sejak 5 hari yang lalu dan sempat mengalami BAB hitam. Pemeriksaan vital sign didapatkan tekanan darah 100/70 mmHg, frekuensi nadi 110 x/menit, Iaju napas 22 x/menit, suhu 36,40C. Terdapat juga hematomegali dan nyeri perut. Pemeriksaan laboraturium didapatkan Hb: 15,3 g/dL, leukosit: 1700 /uL, Hct 47%, trombosit: 45.000/ uL Diagnosis pada pasien di atas adalah.„","options":["DBD gradel","DBD grade II","DBD grade III","DBD grade IV","DBD grade V"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"; Klasifikasi Derajat Penyakit Infeksi Virus Dengue Diagnosis Gejala klinis Pemeriksaan Laboratorium Demam dengue Demam disertai 2 atau Leucopenia lebih tanda : sakit kepala, Trombositopenia, tidak nyeri retro-orbita, mialgia, ditemukan bukti kebocoran athralgia plasma Demam berdarah Gejala di atas + uji Trombositopenia, ditemukan dengue (DBD) bendung (+) bukti kebocoran plasma DBD II Gejala di atas+perdarahan Trombositopenia, ditemukan spontan bukti kebocoran plasma DBD Ill Gejala di atas+kegagalan Trombositopenia, ditemukan sirkulasi (kulit dingin, bukti kebocoran plasma lembab, gelisah) DBD IV Syok berat disertai dengan Trombositopenia, ditemukan tekanan darah dan nadi bukti kebocoran plasma tak terukur 50. Seorang bayi laki-laki dari ibu P2A1 lahir spontan dengan berat badan 3300 gram, panjang badan 50 cm. Pada saat Jahir bayi langsung menangis, bergerak aktif, frekuensi denyut jantung 145x/menit dan ekstremitas kebiruan. Berapakah nilai APGAR bayi tersebut? e. 10 Jawaban : D Pembahasan: 1 2 Appearance Biru ekstrimitas Biru pada ekstrimitas saja Merah dan badan Pulse < IOOx/menit > IOOx/menit Grimace/Refiex menyeringai Batuk Activity flaksid fleksi Aktif Respiratory merintih Menangis kuat","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-050","number":50,"package":"Paket 1","topic":"Anak","title":"Soal 050 · S Seorang bayi laki-laki daribu P2A, lahir…","page":29,"stem":"S Seorang bayi laki-laki daribu P2A, lahir spontan dengan berat badan 3300 gram, panjang badan 50 cm. Pada saat lahir bayi langsung menangis, bergerak aktif, frekuensi denyut jantung 145x/menit dan ekstremitas kebiruan. Berapakah nilai APGAR bayi tersebut?","options":["6","7","8","9","10"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"0 1 2 Appearance Biru ekstrimitasBiru pada ekstrimitas saja Merah dan badan Pulse <100x/menit > 100x/menit Grimace/Reflex menyeringai Batuk Activity flaksid fleksi Aktif Respiratory merintih Menangis kuat","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-051","number":51,"package":"Paket 1","topic":"Campuran","title":"Soal 051 · Sepasang suami istri telah menikah selama 2…","page":29,"stem":"Sepasang suami istri telah menikah selama 2 tahun dan belum mempunyai keturunan• Siklus haid istri normal, suami juga dilakukan pemeriksaan analisis sperma dengan hasil didapatkan jumlah sperma 2,5 cc, berwarna putih, bau khas, jumlah 15 juta/cc, motilitas 18%, bentuk sperma normal. Diagnosis yang paling tepat adalah.„","options":["Oligosperma dan tetrasperma","Impotensi dini","Oligosperma dan astenosperma","Azosperma dan tetrasperma","Azosperma dan astenosperma"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Cara membaca analisis sperma: a.Normozoospermia:karakteristik normal b. Oligozoospermia : konsentrasi spermatozoa < 15 juta/ml C. Asthenozoospermia : jumlah sperma yang masih hidup dan bergerak secara aktif dalam waktu 1 jam setelah ejakulasi <50 % d. Teratozoospermia :jumlah sperma dengan morfologi normal kurang dari 30% e. Oligoasthenoteratozoospermia : kelainan campuran dari 3 variabel yang disebut di atas f. Azoospermia :tidak adanya spermatozoa dalam sperma g.Aspermia : sama sekali tidak terjadi ejakulasi sperma","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-052","number":52,"package":"Paket 1","topic":"Campuran","title":"Soal 052 · Seorang kepala dinas kabupaten akan melakukan distribusi…","page":30,"stem":"Seorang kepala dinas kabupaten akan melakukan distribusi sumber daya di wilayahnya. Distribusi dilakukan merata disetiap daerah dengan memberikan tambahan sumber daya di tempat yang memerlukan lebih banyak. Prinsip etika yang dilakukan adalah","options":["Beneficence","Non maleficence","Justice","Autonomy","Maleficence"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Prinsip justice: Merawat semua orang dengan perhatian dan kualitas yang sama Mendistribusikan keuntungan maupun beban dengan merata","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-053","number":53,"package":"Paket 1","topic":"Neurologi","title":"Soal 053 · Seorang wanita berusia 28 tahun mengalami kecelakaan…","page":30,"stem":"Seorang wanita berusia 28 tahun mengalami kecelakaan lalu lintas dan dibawa ke IGD RS dengan penurunan kesadaran. Pada pemeriksaan, didapatkan GCS pasien E3V3M3. keadaan posisi pasien pada saat itu adalah.„","options":["Dekortikasi","Deserebrasi","Respon perintah","Menjauhi nyeri","Melokalisir nyeri"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Eye (mata) Respon suara (verbal) Movement (pergerakan) E4 membuka mata spontan V5 sadar terorientasi M6 menuruti perintah E3 terhadap suara V4 disorientasi/bingung M5 melokalisasi nyeri E2 terhadap nyeri V3 kata-kata saja M4 fleksi terhadap nyeri El tidak merespon V2 mengerang M3 fleksi abnormal terhadap nyeri VI tidak respon (dekortikasi) M2 ekstensi abnormal terhadap nyeri (deserebrasi) MI tidak ada respon terhadap nyeri","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-054","number":54,"package":"Paket 1","topic":"Psikiatri","title":"Soal 054 · Seorang perempuan 30 tahun datang dengan keluhan…","page":31,"stem":"Seorang perempuan 30 tahun datang dengan keluhan dada berdebar-debar,terasa sesak bila berada didalam lift, merasa gelisah, keringatan dan mulut kering. Hal tersebut selalu dirasakan jika ia berada diruangan yang sempit. 2 bulan yang lalu kakaknya meninggal karena sesak dan kekurangan udara. Diagnosis yang tepat pada pasien di atas adalah...","options":["gangguan panik","gangguan fobia","gangguan psikotik","gangguan cemas","gangguan depresi"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gangguan fobia adalah anxietas yang dicetuskan Oleh situasi atau objek yang jelas dan spesifik (dari luar individu) yang sebenarnya tidak membahayakan. Ditandai dengan rasa cemas berlebihan disertai gangguan otonom. Pada pasien ini, disebut Claustrofobia yaitu takut tempat sempit.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-055","number":55,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 055 · Seorang wanita berusia 32 tahun, datang dengan…","page":31,"stem":"Seorang wanita berusia 32 tahun, datang dengan keluhan dalam 3 bulan terjadi penurunan berat badan sebanyak 12 Kg. Pasien juga merasa lebih mudah tersinggung, sering gelisah, serta berdebar-debar. Saat ini pasien sedang tidak hamil. Hasil pemeriksaan fisik : eksoptalmus (+), pembesaran kelenjar tiroid (+). Hasil pemeriksaan tes fungsi tiroid didapatkan TSH rendah, T4 tinggi. Diagnosis yang tepat adalah.„","options":["Kanker tiroid","Hipertiroidisme","Penyakit Basedow","Penyakit Hashimoto","Penyakit Graves"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hipertiroidisme pada penyakit graves adalah akibat antibody reseptor TSH yang merangsang aktivitas tiroid. Gambaran : a. Letih, apatis b. Berkeringat, tidak tahan panas c. Sistem kardiovaskular : palpitasi d. Sistem neuromuscular : gugup, agitasi, tremor, miastenia gravis e. Sistem gastrointestinal : berat badan turun, diare f. kulit : miksedema pretibital g. Struma : defus dengan/tanpa bising h. Mata : lakrimasi meningkat, kemosis (edem konjungtiva), proptosis, eksoptalmUS diplopia, penglihatan kabur","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-056","number":56,"package":"Paket 1","topic":"Mata","title":"Soal 056 · Seorang laki-laki berusia 45 tahun datang kepuskesmas…","page":31,"stem":"Seorang laki-laki berusia 45 tahun datang kepuskesmas dengan keluhan penglihatn kabur saat membaca dekat. Keluhan tidak disertai penglihatan kabur saat melihat Pada pemeriksaan oftalmikus mata kanan dan kiri 6/6. Berapa kekuatan lensa un kelainan ini?","options":["S+I.OOD","S+1.50D","S+2.OOD","S + 2.50 D","S + 3.00 D"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Presbiopia terjadi jika pungtum proksimum letaknya jauh dari jarak baca seseorang (lebih dari 35cm). Presbiopia kebanyakan timbul mulai usia kira-ira 40 tahun. Jarak baca perlu diberi bantuan adisi S+ untuk mendekatkan punctum proksimum. 40 tahun S+l.oo 45 tahun S+1.50 50 tahun S+2.oo 55 tahun S+2.50 60 tahun S+3.oo","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-057","number":57,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 057 · Seorang pria berusia 40 tahun datang dengan…","page":32,"stem":"Seorang pria berusia 40 tahun datang dengan keluhan demam sejak 2 hari yang lalu. Keluhan disertai nyeri pinggang dan menggigil. Pasien tidak mempunyai riwayat sakit ginjal, diabetes mellitus, dan batu saturan kencing. BAK pasien hanya sedikit dan terasa nyeri di suprapubik sejak I minggu sebelumnya. Pemeriksaan vital sign dalam batas normal kecuali suhu 38,50C. Pada pemeriksaan urine lengkap hasil apakah yang mungkin didapatkan?","options":["Silinder eritrosit","Silinder leukosit","Hematuria +3","Reduksi +3","Protein +3"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus ini pasien memiliki manifestasi klinis infeksi saluran kemih yaitu demam tinggi, menggigil, sakit pinggang (gejala pielonefritis), serta nyeri suprapubik. Pada pemeriksaan urine, akan ditemukan bakteriuria bermakna. Bila ditemukan silinder leukosit, kemungkinan pielonefritis perlu dipikirkan. Jika setelah 48 jam pemberian terapi, infeksi menetap disertai leukosuria. Karenanya, diperlukan terapi selama 5-10 hari.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-058","number":58,"package":"Paket 1","topic":"Campuran","title":"Soal 058 · Seorang wanita berusia 32 tahun datang dengan…","page":32,"stem":"Seorang wanita berusia 32 tahun datang dengan keluhan sakit pada ibu jari, jari kedua, dan jari ketiga kanan. Pasien adalah seorang ibu rumah tangga dan sering menggunakan tangan kanannya untuk mengerjakan pekerjaan rumah tangga.. Pada pemeriksaan fisik tanda vital dalam batas normal. Tes apa yang tepat bagi pasien tersebut?","options":["Tes Laseque","Tes Kontralateral Leg Laseque","Tes Patrick","Tes Tinel","Tes Kernig"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Diagnosis pasien tersebut di atas adalah carpal tunnel syndrome. Penegakkan diagnosis dengan tes Phalen yaitu dengan flexi maksimal pergelangan tangan > I menit yang akan memperburuk gejala dan tes tinel dengan cara mengetuk di atas saraf pada pergelangan tangan yang dapat memicu parestesi pada distribusi nervus medianus. Konfirmasi diagnosis dengan pemeriksaan elektrofisiologi yang menunjukkan penurunan kecepatan sensoris atau motorik pada pergelangan tangan. 59. Seorang wanita berusia 25 tahun, korban tabrak lari meninnggal di tempat kejadian","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-059","number":59,"package":"Paket 1","topic":"Bedah","title":"Soal 059 · ditemukan tanpa identitas. Jenazah dibawa ke rumah…","page":33,"stem":"ditemukan tanpa identitas. Jenazah dibawa ke rumah sakit untukdilakukan otopsi. Setelah menunggu keluarga 2 x 24 jam, ternyata tidak ada yang datang. Maka dilakukan upaya identifikasi otopsi. Cara apakah yang paling mudah digunakan untuk mengidentifikasi korban?","options":["Sidik jari","Gigi geligi","Golongan darah","DNA","Rambut"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Terdapat 9 metode identifikasi pada jenazah : a. Metode visual (wajah) b. Pakaian c. Perhiasan d. Dokumen (kartu identitas) e. Medis (tattoo,cacat) f. Gigi (Pemeriksaan gigi di Indonesia belum merata) g. Sidikjari h. Serologi (golongan darah) Eksklusi (umumnya pada korban massal) Pada kasus di atas cara yang paling mudah dan bermakna dalam menentukan identita; korban adalah pemeriksaan sidikjari.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-060","number":60,"package":"Paket 1","topic":"Campuran","title":"Soal 060 · Seorang laki-laki berusia 48 tahun datang dengan…","page":33,"stem":"Seorang laki-laki berusia 48 tahun datang dengan keluhan nyeri dada sebelah kiri sejak 2 jam yang lalu. Nyeri dirasakan seperti tertindih beban berat dan menjalar sampaike lengan kiri. Pasien memiliki riwayat merokok sejak remaja. Pemeriksaan fisik didapatkan tekanan darah 160/100 mmHg. Pada pemeriksaan EKG didapatkan irama sinus, nadi 88x/menit, elevasi segmen ST di lead II, Ill, aVF. Diagnosis apakah yang mungki0 pada pasien ini?","options":["Infark miokard anterior","Infark miokard anteroseptal","Infark miokard inferior","Infark miokard septal","Infark miokard lateral"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Anteroseptal : VI-V3 -5 LAD Anterior : VI-V4 LAD Anterior ekstensif : VI-V6 proximal left coronary artery V5-V6, I, aVL : anterolateral left circumflex coronary artery V7-V9 : posterior right coronary artery 11. Ill, avF : inferior right coronary artery","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-061","number":61,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 061 · Seorang wanita berusia 60 tahun, datang ke…","page":34,"stem":"Seorang wanita berusia 60 tahun, datang ke RS dengan keluhan perdarahan pervaginam sejak 1 bulan yang lalu. Pasienjuga mengeluhkan nyeri tulang pinggul, keputihan berbau, dan benjolan di vagina. Pada pemeriksaan inspekulo didapatkan porsio rapuh dan mudah berdarah. Diagnosis yang paling tepat pada kasus di atas adalahm","options":["Karsinoma endometrium","Karsinoma ovarium","Karsinoma tuba","Karsinoma serviks","Karsinoma vulva"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada karsinoma servix, keputihan adalah gejala yang paling sering ditemukan. Getah yang keluar dari vagina semakin lama berbau busuk akibat infeksi dan nekrosis jaringan sehingga pertumbuhan menjadi semakin ulseratif. Gejala Iain adalah perdarahan setelah melakukan senggama, serta gejala yang disebabkan Oleh metastase seperti obstruksi total vesika urinaria, stadium lanjut akan ditemukan keluhan cepat lelah, penurunan berat badan dan anemia. Pemeriksaan fisik pada serviks teraba membesar, ireguler dan teraba lunak.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-062","number":62,"package":"Paket 1","topic":"Kulit","title":"Soal 062 · Seorang perempuan berusia 35 tahun datang ke…","page":34,"stem":"Seorang perempuan berusia 35 tahun datang ke IGD dengan keluhan tidak bisa BAB selama 5 hari. Keluhan tersebut disertai dengan mual, muntah, dan perut kembung. Vital sign dalam batas normal. Dilakukan pemeriksaan BNO dan tampak gambaran seperti \"pigura\" dari dinding abdomen. Diagnosis yang tepat adalah...","options":["Divertikulitis","Apendisitis","Enterokolitis","Peritonitis","Ileus obstruktif"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gambaran umum dari obstruksi komplit adalah timbulnya konstipasi atau obstipasi. Muntah timbul kemudian dan tidak terjadi bila katup ileosekal mampu mencegah refluks. Bila akibat refluks isi kolon terdorong ke dalam usus halus, akan tampak gangguan pada usus halus. Muntah yang fekal akan terjadi kemudian. Pada pemeriksaan fisik akan menunjukkan distensi abdomen dan timpani, gerakan usus akan tampak pada pasien yang kurus dan akan terdengar metallicsound pada auskultasi. Nyeri yang terlokasi, dan terabanya massa menunjukkan adanya strangulasi. Pada gambaran radiologi, kolon yang mengalami distensi menunjukkan gambaran seperti \"pigura\" dari dinding abdomen.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-063","number":63,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 063 · Seorang pasien perempuan berusia 26 tahun datang…","page":35,"stem":"Seorang pasien perempuan berusia 26 tahun datang ke praktik dokter umum dengan keluhan demam tinggi sejak 4 hari yang lalu. Demam terjadi setiap 2 hari. Keluhan demam juga disertai dengan mual dan muntah. Pasien sedang hamil 8 bulan dan baru saja pulang dari Papua. Terapi yang paling tepat untuk pasien tersebut adalah„.","options":["Kuinin","Primakuin","Klorokuin","Paramitamin","Asteramin"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kehamilan terjadi penurunan imunitas. Pencegahan pada ibu hamil pada daerah endemik malaria sangat penting karena komplikasi kehamilan karena malaria adalah abortus, BBLR, hipoglikemia dan malaria congenital. Pencegahan yang tepat adalah dengan pemberian klorokuin 250 mg tiap minggu mulai dari kehamilan trisemester Ill sampai I bulan post partum.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-064","number":64,"package":"Paket 1","topic":"Campuran","title":"Soal 064 · Seorang Iaki-laki berusia 27 tahun diantar Oleh…","page":35,"stem":"Seorang Iaki-laki berusia 27 tahun diantar Oleh istrinya ke dokter dengan keluhan sering memeriksa apakah pintu rumahnya sudah dikunci. Menurut istrinya keluhan terlihat sejak 3 bulan yang lalu dan bertambah parah sehingga pasien menjadi sering tidak bisa tidur. Pasien mengatakan bahwa ia selalu terganggu Oleh pikiran bahwa pintu rumah Iupa dikunci atau tidak dikunci dengan cara yang benar, sehingga menjadi cemas dan terdorong untuk berulang-ulang mengecek pintu rumahnya. Diagnosis yang paling tepat pada kasus di atas adalahm","options":["Fobia spesifik","Fobia social","Gangguang cemas","Gangguan obsesif kompulsif","Serangan panik"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"distress atau gangguan aktivita. Gejala obsesional harus memiliki gejala sebagai berikut: a. Harus disadari sebagai pikiran atau impuls dari diri individu sendiri b. Sedikitnya ada satu piran atau tindakan yang masih tidak berhasil dilawan oleh penderita C.F Pikiran untuk melaksanakan tindakan tersebut di atas bukan merupakan hal yang memberi kepuasan atau kesenangan (sekedar perasan lega dari ketegangan atau anxietas tidak dianggap sebagai kesenangan seperti maksud di atas). d.F Pikiran, bayangan atau impuls tersebut harus merupakan pengulangan yang tidak menyenangkan.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-065","number":65,"package":"Paket 1","topic":"Bedah","title":"Soal 065 · Seorang laki-laki berusia 26 tahun datang ke…","page":36,"stem":"Seorang laki-laki berusia 26 tahun datang ke IGD RS dengan keluhan bengkak pada kantung dan buah zakar kiri. Keluhan dirasakan sejak 3 hari yang lalu setelah mengangkat benda berat. Pada pemeriksaan fisik didapatkan skrotum dan testis kiri bengkak, kemerahan dan nyeri. Nyeri berkurang jika skrotum diangkat. Pasien diketahui menderita sakit kelenjar parotis 5 hari yang lalu. Diagnosis yang tepat pada kasus di atas adalah...","options":["Tumor testis","Torsio testis","Hernia inguinalis","Hidrokel","Epididimo — orkitis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Epididimitis akut atau orkitis akut merupakan radang di dalam skrotum. Pada pemeriksaan didapatkan pembengkakan seluruh testis yang tidak nyeri, konsistensi agak kenyal seperti karet. 66. Seorang peneliti ingin mempelajari hubungan antara merokok dengan kejadian penyakit jantung koroner. Populasi sampel adalah semua penduduk usia di atas 40 tahun sebesar 1000 orang. Pada penelitian didapatkan hasil dari 300 orang perokok terdapat 75 orang diantaranya menderita PJK sedangkan 700 orang yang tidak merokok terdapat 50 orang yang menderita PJK. Berapa besar risiko kelompok perook menderita PJK? c. 3,5 b. 4,3 Jawaban : C Pembahasan: PJK Tanpa PJK Perokok 75 (a) 225 (b) 300 Bukan perokok 50 (c) 650 (d) 700 Jumlah 125 825 1 ooo Studi kohort : resiko relatif (RR) Rumus : (a/a+b) : (c/C+d) = (75/800) . • (50/700) =","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-066","number":66,"package":"Paket 1","topic":"Kesehatan Masyarakat","title":"Soal 066 · Seorang peneliti ingin mempelajari hubungan antara merokok…","page":36,"stem":"Seorang peneliti ingin mempelajari hubungan antara merokok dengan kejadian penyakit jantung koroner. Populasi sampel adalah semua penduduk usia di atas 40 tahun sebesar 1000 orang. Pada penelitian didapatkan hasil dari 300 orang perokok terdapat 75 orang diantaranya menderita PJK sedangkan 700 orang yang tidak merokok terdapat 50 orang yang menderita PJK. Berapa besar risiko kelompok perook menderita PJK?","options":["3","4.3","3.5","2.5","2.3"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"PJK Tanpa PJK Perokok 75 (a) 225 (b) 300 Bukan perokok 50 (c) 650 (d) 700 Jumlah 125 825 1000 Studikohort :resiko relatif (RR) Rumus : (a/a+b) : (c/c+d) = (75/800) : (50/700) = 3,5","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-067","number":67,"package":"Paket 1","topic":"Campuran","title":"Soal 067 · Seorang anak perempuan berusia 8 tahun diantar…","page":37,"stem":"Seorang anak perempuan berusia 8 tahun diantar Oleh ibunya dengan keluhan timbul bintik-bintik merah diseluruh tubuh. Bintik-bintik merah tersebut berisi cairan yang cepat membesar dan mudah pecah, muncul pertama kali di badan lalu ke wajah dan anggota gerak. Paien baru pertama kali mengalami keluhan seperti ini didahului Oleh demam yang tidak begitu tinggi. Teman sekelas pasien juga mempunyai gejala yang sama. Diagnosis yang tepat untuk pasien ini adalah...","options":["Penyakit mukokutan","Morbili","Herpes simpleks","Herpes zoster","Varicella"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Varicella merupakan suatu penyakit infeksi akut menular yang disebabkan Oleh virus Varicella Zoster dengan manifestasi klinis berupa vesikel pada kulit dan mukosa. Disebabkan Oleh Varicella Zoster virus termasuk herpes virus. Masa inkubasi 14-16 hari, terdapat gejala prodromal : demam tidak terlalu tinggi, malaise, sakit kepala, anoreksia. Pemeriksaan didapatkan eritem yang berubah cepat menjadi papula kemudian vesikel dengan penyebaran sentrifugal dari badan ke wajah dan ekstremitas dengan gambaran polimorfik. Vesikel berisi cairan jernih kemudian pecah membentuk krusta. Pada laboratorium dilakukan dengan pengecatan Giemsa dan hematoksisilin eosin (bahan: kerokan dasar vesikel), isolasi virus, serologi : complement fixation test, neutralization test, ELISA.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-068","number":68,"package":"Paket 1","topic":"Anak","title":"Soal 068 · Seorang anak berusia 8,5 bulan dengan berat…","page":37,"stem":"Seorang anak berusia 8,5 bulan dengan berat badan 8,4 kg, dibawa ke dokter Oleh ibunya dengan keluhan tidak mau makan dan minum sejak 2 hari yang lalu. Tidak dijumpai panas dan mual. Anak terus menangis (rewel) karena merasakan nyeri. Pemeriksaan fisik UUB cekung. Diagnosis yang tepat pada kondisi di atas adalah...","options":["Stomatitis","Mononukleosis infeksiosa","Moniliasis","Difteri","Tumor tonsil"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Bayi yang rewel tidak mau makan serta minum sering disebabkan oleh infeksi jamur di rongga mulut/moniliasis Akibatnya, dapat terjadi dehidrasi pada bayi bila tidak seger ditangani.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-069","number":69,"package":"Paket 1","topic":"Mata","title":"Soal 069 · Seorang anak perempuan berusia 9 tahun dibawa…","page":37,"stem":"Seorang anak perempuan berusia 9 tahun dibawa Oleh ibunya ke poliklinik dengan keluhan matanya berair terus dan keluar sekret berwarna kuning kehijauan pada punctum ductus nasolakrimalis. Selain itu, kulit di daerah tersebut nampak kemerahan dan bengkak. Diagnosis pada pasien ini adalah...","options":["Perdarahan subkonjungtiva","Obstruksi duktus nasolakrimalis","Dry eye syndrome","Dakriosistitis","Dakrioadenitis"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dakriosistitis akut adalah peradangan supuratif sakus Iakrimalis disertai dengan selulitis jaringan di atasnya. Penyebabnya adalah penyumbatan ductus nasolakrimalis. Gejalanya adalah epifora dan regurgitasi pada penekanan daerah sakus Iakrimalis. Stadium lanjut dapat terjadi komplikasi fistula. Peradangan berupa pembengkakan, merah dan nyeri biasanya disertai pembengkakan kelenjar preaurikuler.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-070","number":70,"package":"Paket 1","topic":"Neurologi","title":"Soal 070 · Seorang anak laki-laki berusia 7 tahun dibawa…","page":38,"stem":"Seorang anak laki-laki berusia 7 tahun dibawa Oleh orang tuanya ke dokter dengan keluhan sering tiba-tiba kejang. Setiap kali kejang, lamanya sekitar 5 — 10 detik. Hal ini seringkali terjadi di rumah tanpa disertai panas. Pemeriksaan fisik tidak ditemukan kelainan. Pemeriksaan penunjang yang dibutuhkan untuk menunjang diagnosis pada pasien ini adalah...","options":["EEG","MRI","EKG","CT-Scan","Rontgen kepala"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus di atas, diagnosisnya mengarah ke epilepsi. Sebab, adanya bangkitan kejang tanpa demam.Pemeriksaan penunjang yang dapat menegakkan epilepsi adalah EEG. Kelainan EEG yang sering dijumpai pada pasien epilepsi disebut epileptiform discharge atau epileptiform activity. Gambaran yang terekam saat serangan maupun di luar serangan, berupa gelombang runcing, gelombang paku, runcing lambat, dan paku lambat.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-071","number":71,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 071 · Seorang perempuan berusia 35 tahun P3Ao datang…","page":38,"stem":"Seorang perempuan berusia 35 tahun P3Ao datang dengan keluhan terdapat benjolan di payudara kanan, dirasakan sejak 1 bulan yag lalu. Kakak kandung pasien meninggal karena kanker payudara 4 tahun yang lalu. Pasien memiliki riwayat menggunakan alat kontrasepsi oral selama IO tahun. Pada pemeriksaan fisik payudara kanan didapatkan benjolan dengan diameter 2,5 cm, berbatas tegas, kenyal dan mudah digerakkan. Tidak terdapat pembesaran kelenjar getah bening axilla. Diagnosis yang tepat adalah...","options":["Fibrosing adenosis mamma","Fibroadenoma mamma","Fibricystic disease","Tumor mamma sinistra","Phylloides tumor"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Fibroadenoma mamma : USia muda, kenyal, diameter kecil, mobile, prognosis baik, tidak nyeri Fibrocystic disease : massa kistik, dipengaruhi Oleh menstruasi, nyeri Tumor Mamma sinistra : massa, konsistensi keras, terfiksir, discharge, peau d orange, pus berbau, prognosis biasanya buruk Phylloides tumor : usia tua, gejala seperti FAM, massa berukuran besar","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-072","number":72,"package":"Paket 1","topic":"THT","title":"Soal 072 · Seorang Iaki-laki berusia 35 tahun datang dengan…","page":39,"stem":"Seorang Iaki-laki berusia 35 tahun datang dengan keluhan suara parau sejak 2 bulan yang lalu. Pasien adalah seorang penyanyi dengan jadwal latihan vocal dan tampil yang padat Pasien sudah beberapa kali berobat namun tidak ada perubahan. Pada pemeriksaar laringoskopi ditemukan pergerakan pita suara baik serta gambaran sebuah massa bula kecil sebesar kacang hijau, berwarna keputihan, unilateral pada bagian tengah pita suara Diagnosis yang tepat pada pasien ini","options":["Vocal nodule","Papiloma laring","Keratosis laring","Paresis pita suara","Laringomalasia"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Vocal nodule merupakan kelainan yang biasanya disebabkan Oleh penyalahgunaan suara dalam waktu lama, seperti guru, penyanyi dan Iainnya. Gejalanya terdapat suara parau, kadang disertai batuk. Pemeriksaan laringoskop langsung dan tidak langsung terlihat nodul di pita suara sebesar kacang hijau aau lebih kecil, berwarna keputihan yang sering terlihat pada sepertiga anterior atau tengah pita suara, dapat unilateral atau bilateral.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-073","number":73,"package":"Paket 1","topic":"Anak","title":"Soal 073 · Seorang anak laki-laki usia 2 tahun diantar…","page":39,"stem":"Seorang anak laki-laki usia 2 tahun diantar Oleh ibunya karena belum bisa berbicara. Ibu baru menyadari saat anak usia 2 tahun ini. Pada saat bayi, anak tersebut belum pernah mengoceh atau berbicara sepatah katapun dan jika dipanggil tidak merespon. Riwayat kelahiran premature dan ada riwayat kuning. Pada pemeriksaan otoskopi mebran timpani intak dan reflek cahaya +/+. Diagnosis yang tepat pada pasien ini","options":["ADHD","Cerebral palsy","Tuli congenital","Autisme","Retardasi mental"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"ADHD merupakan hiperaktivitas/impulsivitas dan/atau sulit untuk fokus. pertama,dikuti hipertonia Tuli congenital :tidak berbicara, tidak merespon, risiko tinggi pada bayi prematur karena sistem auditori belum sempurna Autisme merupakan gangguan komunikasi, gangguan interaksi sosial, perilaku repetitive Retardasi mental :IQ dan keterampilan adaptif (sosial, bahasa, masak dan lainnya.) di bawahrata-rata","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-074","number":74,"package":"Paket 1","topic":"THT","title":"Soal 074 · Seorang laki-laki berusia 70 tahun datang dengan…","page":40,"stem":"Seorang laki-laki berusia 70 tahun datang dengan keluhan pendengaran menurun. Pasien merasa sulit menangkap pembicaraan orang Iain, terutama jika ditempat yang ramai dan jika berbicara selalu lebih keras. Pada pemeriksaan otoskopi didapatkan membrana timpani intak dan tidak didapatkan tanda radang. Hasil pemeriksaan garputala, rhine kedua telinga hantaran udaranya lebih panjang daripada hantaran tulang, tes swabach lebih pendek dari pemeriksa dan tes weber tidak bisa membedakan kanan dan kiri. Apakah diagnosis yang tepat pada pasien ini?","options":["Presbiakusis","Otosklerosis","Meniere disease","Neuroma akustik","noise induce hearing loss"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Prebiaskusis : Merupakan proses Degeneratif Tidak ada kelainan anatomis Termasuk tipe tuli sensorineural Rinne Webber Schwabach Normal sama Tuli Konduktif Lateralisasi ke telinga sakit Memanjang Tuli Sensorineural Lateralisasi ke telinga sehat Memendek","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-075","number":75,"package":"Paket 1","topic":"THT","title":"Soal 075 · Seorang perempuan berusia 28 tahun datang ke…","page":40,"stem":"Seorang perempuan berusia 28 tahun datang ke klinik praktek anda dengan keluhan bersin-bersin setiap menyapu lantai. Bersin lebih dari 6x disertai dengan ingus yang encer dan hidung buntu. Keluhan dirasakan sudah 2 tahun dan hamper dialami setiap hari. Keluhan Iain disertai telinga gatal dan kadang terasa basah. Keluhan ini sangat mengganggu aktivitasnya. Pada pemeriksaan fisik hidung didapatkan cavum nasi kanan dan kiri sempit, konka inferior hipertrofi, mukosa warna pucat dan tampak secret serous jernih. Pemeriksaan apa yang diperlukan untuk membantu penegakkan diagnosis pasien tersebut?","options":["Pemeriksaan kadar lgE","Pemeriksaan eosinofil hidung","Tes provokasi hidung","Skin prick tes","Pemeriksaan eosinofil darah"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Diagnosis pasien di atas adalah rhinitis alergi. pemeriksaan skin prick test dilakukan untuk mengetahui allergen dan lebih spesifik. Pada pemeriksaan kadar lgE dan eosinofil tidak spesifik. 76. Seorang pasien perempuan berusia 26 tahun dibawa ke IGD dalam kondisi tidak sadar Oleh keluarganya. Sebelumnya pasien merupakan korban tabrak lari. Pada pemeriksaan fisik didapatkan TD 90/70 mmHg, nadi 130 x/menit, RR 30x/menit, Suhu 37,30C. Perkiraan kehilangan darah 30-40%. Menurut ATLS, berapakah klasifikasi syok perdarahan pada pasien tersebut? c. Ill d. IV Jawaban : C Pembahasan: Parameter Blood loss(ml) <750 750-1500 1500-2000 >2000 Blood loss(%) 15-30% Pulserate <100 >100 >120 > 140 (beats/min) Blood pressure Normal Normal Decreased Decreased Respiratory rate 14—20 20-30 30-40 (bpm) Urine output 20-30 5-15 Negligible (ml/hour) CNS symptoms Normal Anxious Confused Lethargic","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-076","number":76,"package":"Paket 1","topic":"Campuran","title":"Soal 076 · Seorang pasien perempuan berusia 26 tahun dibawa…","page":41,"stem":"Seorang pasien perempuan berusia 26 tahun dibawa ke IGD dalam kondisitidak sadar 76. oleh keluarganya. Sebelumnya pasien merupakan korban tabrak lari Pada pemeriksaan fisikdidapatkan TD 90/70 mmHg, nadi 130 x/menit, R 30x/menit, Suhu 37,3°C. Perkiraan kehilangan darah 30-40%. Menurut ATLS, berapakah klasifkasi syok perdarahan pada pasien tersebut?","options":["I","II","III","IV","V"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Parameter 1 111 IV Blood loss(ml) <750 750-1500 1500-2000 >2000 Blood loss(%) <15% 15-30% 30-40% >40% Pulserate <100 >100 >120 >140 (beats/min) Blood pressure Normal Normal Decreased Decreased Respiratory rate 14-20 20-30 30-40 >35 (bpm) Urine output >30 20-30 5-15 Negligible (ml/hour) CNS symptoms Normal Anxious Confused Lethargic","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-077","number":77,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 077 · Seorang Iaki-laki berusia 37 tahun, datang dengan…","page":41,"stem":"Seorang Iaki-laki berusia 37 tahun, datang dengan keluhan terdapat benjolan pada leher depan. Pasien menderita nyeri dan demam I minggu sebelumnya. Tidak ada keluhan jantung berdebar dan berkeringat. Hasil pemeriksaan fisik didapatkan massa bulat, kenyal, mudah digerakkan, ukuran 2x3x2 cm, ikut bergerak bila menelan, dan ada warna kemerahan di sekitar benjolan. Hasil pemeriksaan laboratorium LED meningkat' leukositosis, T3 dan T4 meningkat. Diagnosis pada pasien ini adalahm","options":["Tiroiditis akut","Karsinoma tiroid","Goiter difusa toksik","Goiter nodosa toksik","Goiter nodosa nontoksik"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"pada tiroiditis akut sebagian besar disebabkan Oleh infeksi supurasi pada kelenjar tiroid. Gejala yang menonjol adalah nyeri tiroid yang seringkali menjalar hingga tenggorokan atau telinga. Pasien mengalami nyeri telan. Pada pemeriksaan fisik terdapat pembesaran kelenjar tiroid (goiter) yang kadang asimetris, dapat ditemukan kemerahan di kulit atas kelenjar tiroid. Terdapat gejala sistemik demam dan limfadenopati. Tiroiditis akut sebagian besar disebabkan Oleh infeksi (bakteri atau jamur), factor iatrogenik (setelah terapi radiasi), pemberian obat-obatan (interferon, amiodaron).","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-078","number":78,"package":"Paket 1","topic":"Kulit","title":"Soal 078 · Seorang laki-laki berusia 30 tahun datang dengan…","page":42,"stem":"Seorang laki-laki berusia 30 tahun datang dengan keluhan timbul bintik-bintik merah pada seluruh tangan dan kaki. Pasien juga mengeluh saat sikat gigi gusi sering berdarah dan kulit mudah lebam apabila terbentur sesuatu. Keluhan tersebut sudah dirasakan Oleh pasien sejak 3 bulan yang lalu. Pemeriksaan laboraturium didapatkan hasil Hb: 8,6 g/dL, leukosit: 7500, trombosit: 110.000, Hct: 24,2%. Diagnosis yang tepat pada pasien ini adalah„.","options":["Idiopathic Trombocytopenic Purpura (ITP)","Limfoma maligna","Polisitemia vera","Leukemia","Hemophilia"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"ITP merupakan kelainan autoimun dimana autoantibody IgG dibentuk untuk mengikat trombosit. Gambaran klinis : a. Anak-anak : tersering Oleh infeksi virus dan biasanya dapat sembuh sendiri b. Perdarahan mukosadankulit,terseringadalah epistaksis,perdarahan mulut, menoragi, purpura, ptekie c. Pemeriksaan fisik keadaan umum baik Pemeriksaan penunjang : a. Darah rutin : trombosit < 150.000/ml b. Apusan darah tepi : morfologi sel darah normal, kecuali trombosit sedikit membesar sebagai respon destruksi trombosit","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-079","number":79,"package":"Paket 1","topic":"Campuran","title":"Soal 079 · Seorang pasien perempuan berusia 55 tahun datang…","page":42,"stem":"Seorang pasien perempuan berusia 55 tahun datang dengan keluhan sulit menelan sejak I bulan yang lalu. Kesulitan menelan ini terutama menelan cairan, narnun masih mampu menelan makanan padat. Pasien juga mengeluhkan nyeri di daerah ulu hati dan penurunan berat badan. Pemeriksaan radiologi menunjukkan penyempitan di bagian distal esophagus menyerupai ekor tikur (mouse tail appearance). Diagnosis yang tepat pada pasien ini","options":["Diverticulum esofagus","Faringitis akut","Akalasia","Ileus paralitik","Ileus obstrukif"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"adalah disfagia, regriai nyer didaerh sute dan pnrunan berat badn. Disfagia dapat terjaditiba-tibaetelahmenelanataubilaada gangguan mosl Caran lebisusahditelandaripadaendaadatRegurgitaidapat timutelmaau padasaat berbaringering terjadipaamalamhari saat tidr ehinggadaat rd pneumonia aspirasil.Pada stadium permulaan dapat terjadi rasa terbakar dan nyeri daerh substernal, sedangkan stadium lanjut dapat timbul nyeri hebat didaerah epigastrium dan rasa nyeri ini menyerupai gambaran angina pectoris.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-080","number":80,"package":"Paket 1","topic":"Campuran","title":"Soal 080 · Seorang laki-laki berusia 27 tahun dibawa ke…","page":43,"stem":"Seorang laki-laki berusia 27 tahun dibawa ke IGD Oleh keluarganya karena muntah darah berwarna hitam sejak 2 jam yang lalu. Menurut keluarganya, pasien mengalami keluhan demam sejak 5 hari yang lalu, disertai nyeri kepala, persendian dan mual muntah. Pemeriksaan vital sign tekanan darah 90/60 mmHg, frekuensi nadi 1 IO kali/menit„ RR: 24 kali/menit, Suhu: 38,50C. Pemeriksaan fisik terdapat petekie dan hepatomegali. Penatalaksanaan yang tepat pada pasien ini adalah...","options":["Kristaloid 5-7 cc/kgBB dalam 20 menit 20 menit","Kristaloid 7-10 cc/kgBB dalam 20 menit dapat diulang","Kristaloid 10-20 cc/kgBB dalam 20 menit","Kristaloid 20-30 cc/kgBB dalam","Transfusi darah IO cc/kgBB dan"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Incidence Rate = Jumlah penderita baru Jumlah penduduk = 10+15+10+5+10+10+20 1 10.000","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-081","number":81,"package":"Paket 1","topic":"Kesehatan Masyarakat","title":"Soal 081 · Sebagai dokter Puskesmas Kecamatan Cendrawasih, jumlah penduduk…","page":45,"stem":"Sebagai dokter Puskesmas Kecamatan Cendrawasih, jumlah penduduk per 1 Januari 2012 sebesar 90.000 orang dan pada 31 Desember 2012 sebanyak 110.000 orang. Penderita diabetes melitus: Januari 50 penderita lama dan 10 baru; Maret 15 baru; Mei 10 baru; Juli 5 baru; Agustus 10 baru; September 10 baru; Desember 20 baru. Berapakah incidence rate kasus DM di kecamatan tersebut?","options":["0,25%","0,63%","0,07%","0,08%","0,12%"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Perhitungan dalam buku: 80 kasus baru dibagi 110.000 penduduk = sekitar 0,07%. Definisi penyebut dan periode perlu diperiksa ulang sebelum menerapkan perhitungan epidemiologis.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-082","number":82,"package":"Paket 1","topic":"Bedah","title":"Soal 082 · Ditemukan mayat Iaki-laki di pinggir sungai dengan…","page":45,"stem":"Ditemukan mayat Iaki-laki di pinggir sungai dengan tangan terikat dan Iuka dibagian kepala. Pada mayat terdapat gelembung udara pada hidung yang mudah pecah, dijumpai lumpur dan air pada saluran nafas. Kemungkinan penyebab kematian adalah...","options":["Dipukul","Terjatuh","Keracunan CO","Tenggelam","Lumpur dan air"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Berikut adalah tanda-tanda kematian akibat tenggelam : a. Bila sternum diangkat saat otopsi, paru-paru akan terlihat memenuhi rongga mediastinum, sehingga rongga kosong di atas jantung hilang b. Paru-paru pucat, spongiosa, dan dapat tertekan pada bagian dalam thorax dengan sangat kuat sehingga tampak indentasi costa pada permukaan paru c. Adanya air dalam mulut, saluran pernapasan, paru-paru, esofagus dan perut bukan merupakan petunjuk yang dapat diterima, karena dapat timbul setelah kematian Busa yang berasal dari hidung dan mulut merupakan salah satu tanda klasik kasus tenggelam d. Distensi paru yang hebatjuga merupakan salah satu tanda klasik","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-083","number":83,"package":"Paket 1","topic":"THT","title":"Soal 083 · Seorang ibu membawa anak perempuannya berusia 8…","page":45,"stem":"Seorang ibu membawa anak perempuannya berusia 8 tahun ke dokter dengan keluhan rasa mengganjal ditenggorokan sejak 1 minggu yang lalu. Keluhan dirasakan hilang timbul . Pemeriksaan fisik didapatkan tonsil T3-T3, hiperemis (-), permukaan berbenjol- benjol dengan kripta melebar. Diagnosis pada pasien ini adalah.„","options":["Tonsilitis folikularis","Tonsilitis parenkimatosa","Tonsilitis lakunaris","Tonsilitis akut","Tonsilitis kronis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tonsilitis kronis terjadi akibat rangsangan menahun dari rokok, beberapa jenis makanan, higiene mulut yang buruk, pengaruh cuaca, kelelahan fisik, dan pengobatan tonsilitis akut yang tidak adekuat. Pada pemeriksaan, tampak tonsil membesar dengan permukaan yang tidak rata, kripta melebar, dan beberapa kripte terisi Oleh detritus. Pasien seringkali datang dengan keluhan rasa mengganjal di tenggorokan, tenggorokan dirasakan kering, dan napas berbau.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-084","number":84,"package":"Paket 1","topic":"Campuran","title":"Soal 084 · Seorang pasien perempuan berusia 48 tahun datang…","page":46,"stem":"Seorang pasien perempuan berusia 48 tahun datang dengan keluhan nyeri dan bengkak pada ibu jari kaki kiri sejak kemarin setelah makan makanan laut. Dilakukan pemeriksaan laboratorium dan didapatkan kadar asam urat pasien 7,5 mg%. Terapi yang tepat pada pasien ini adalah„.","options":["Indometacin + Kolkisin","Indometacin + Alupurinol","Kolkisin + Alupurinol","Kolkisin + Probenesid","Indometacin + Alupurinol"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Artritis gout merupakan suatu sindrom klinis yang mempunyai gambaran khas yaitu arthritis akut sebagai respon inflamasi jaringan terhadap pembentukan kristal monosodium urat monohidrat. Pemeriksaan penunjang : a. Kadar asam urat>6 mg% b. Leukositosis ringan c. LED meningkat d. Kadar asam urat urin >500 mg5/liter per 24 jam e. Pemeriksaan cairan tofi ditemukan gambaran kristal urat pada sediaan mikroskopik Penatalaksanaan: a. Saat serangan : Tidak tergesa-gesa menurunkan kadar asam urat karena penurunan mendadak mencetuskan serangan lain Obat yang diberikan : kolkisin, OAINS, kortikosteroid, analgetik kecuali aspirin yang dapat menghambat ekskresi asam urat diginjal dan memperberat hiperurisemia, tirah baring b. Periode antara Mengurangi endapan asarn urat dalam jaringan dan menurunkan frekuensi serta keparahan serangan Diet : menurunkan berat badan, diet rendah purin, banyak minum Obat : urikosurik (probenesid), inhibitor xantin oksidase/allopurinol","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-085","number":85,"package":"Paket 1","topic":"Anak","title":"Soal 085 · Seorang bayi usia 2 minggu dibawa ibunya…","page":47,"stem":"Seorang bayi usia 2 minggu dibawa ibunya ke RS dengan keluhan muntah. Muntah baru muncul di usia 2 minggu ini. Muntah kadang menyemprot dan seperti ada bercak kopi. Muntah biasanya muncul 30 menit setelah bayi minum susu. Setelah muntah, bayi menyusu Iagi dengan kuat. Pada pemeriksaan fisik teraba massa berbentuk zaitun di epigastrium. Pemeriksaan radiologi didapatkan tanda string sign. Diagnosis pasien ini adalah...","options":["Stenosis pylorus hipertrofi","Intussusepsi","Hirchsprung","Hernia diafragmatika","Atresia duodenum"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hipertrofi stenosis pylorus adalah hipertrofi lapisan otot pilorus gaster, menyebabkan obstruksi. Gejala dan tanda : Muntah nonbilier mulai usia 4 minggu setiap setelah makan (<3 jam), kalau berat bisa proyektil Pasien tidak demam, nafsu makan baik Pemeriksaan Fisik : Pilorus teraba di epigastrium seperti buah zaitun Pemeriksaan Penunjang : • USG: tebal dan panjang pilorus • Enema barium: double track sign, string sign, shoulder sign","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-086","number":86,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 086 · Seorang perempuan berusia 35 tahun yang mengidap…","page":47,"stem":"Seorang perempuan berusia 35 tahun yang mengidap diabetes melitus tipe l, mengalami gagal ginjal progresifdalam kurun Waktu 2 tahun terakhir. Pasien belum pernah melakukan dialysis. Pemeriksaan fisikdalam batas normal. Pada pemeriksaan la boratorium didapatkan Hb 8,8 g/dL dan hematokrit 27,9%. Faktor penyebab dari kondisi di atas adalah•••","options":["Anemia sideroblastik","Perdarahan akut","Infeksi saluran kemih","Defisiensi enzim eritrosit","Defisiensi eritropoietin"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"antara lain menurunnya eritropoiesis akibat: a. Menurunnya produksi eritropoiesis yaitu akibat berkurangnya parenkim ginjal, menurunnya afinitas Hb terhadap O, merendahnya set point dari erythropoietin tissue oxygenationhematocrite(feed backmechanism) b. Adanya faktor-faktor diluar eritropoietin (akibat hemolisis oleh efek toksin uremik terhadap membran eritosit, defisiensi besi .Karena perdarahan kronik yang sering terjadi pada penderita GGK atau akibat hemodialisis, adanya defisiensi asam folat).","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-087","number":87,"package":"Paket 1","topic":"Campuran","title":"Soal 087 · Seorang perempuan berusia 50 tahun, datang ke…","page":48,"stem":"Seorang perempuan berusia 50 tahun, datang ke dokter dengan keluhan nyeri perut kanan atas sejak 2 bulan yang lalu, dan dirasakan semakin memberat sejak 3 hari yang lalu. Nyeri hilang timbul, dirasa menembus ke punggung atas dan kedua bahu. Pemeriksaan fisik didapatkan demam (+), defans muscular (+), hepar tidak teraba membesar, murphy sign (+). Pemeriksaan USG didapatkan gambaran pembesaran kandung empedu, 9,5 mm, terdapat double rims. Diagnosis yang tepat pada pasien tersebut adalah...","options":["Kolesistitis akut","Kolelitiasis","Hidrops renalis","Tumor vesika fellea","Kolangitis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kolesistitis akut adalah reaksi inflamasi akut dinding kandung empedu. Manifestasi klinis : gangguan pencernaan, mual dan muntah, nyeri perut kanan atas atau rasa tidak enak di epigastrium, nyeri menjalar ke bahu atau subscapula, demam, dan ikterus (bila terdapat batu diductus koledokusistikus), gejala nyeri perut bertambah bila banyak makan berlemak. Pemeriksaan fisik terdapat tanda nyeri tekan dan defans muscular. Tanda Murphy terjadi bila inspirasi maksimal terhenti pada penekanan perut ke atas. Pemeriksaan penunjang didapatkan leukositosis, hiperbilirubinemia ringan, peningkatan fosfatase alkali. Foto polos radiologi kadang terlihat batu empedu, hasil yang lebih baik dan pasti dilakukan dengan USG abdomen.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-088","number":88,"package":"Paket 1","topic":"Mata","title":"Soal 088 · Seorang pasien perempuan berusia 30 tahun datang…","page":48,"stem":"Seorang pasien perempuan berusia 30 tahun datang dengan keluhan penurunan tajam penglihatan pada mata kanan. Riwayat mata kanan terkena batu ketika sedang berjalan 2 minggu yang lalu. Mata memerah, nyeri, silau, terdapat kotoran mata. Pemeriksaan fisik didapatkan tampak lesi satelit pada kornea, injeksi kornea, konjungtiva hiperemesis, visus 6/72. Diagnosis yang tepat pada pasien ini adalah...","options":["Konjungtivitis bakterial","Konjungtivitis alergi","Keratitis bakteri","Keratitis jamur","Keratokonjungtivitis sicca"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Keratitis jamur (keratomikosis) merupakan inflamasi yang disebabkan karena i jamur (dan menyebabkan peradangan) pada kornea. Faktor predisposisinya acialah trauma, pemakaian dengan lensa kontak dan steroid topical. Gejalanya adalah adanya rasa mengganjal, nyeri yang bertambah berat, penglihatan yang menurun secara tiba, kemerahan pada mata, lakrimasi berlebihan dan fotopobia. Klinisnya berupa injeu konjungtiva, defek epitel, supurasi, infiltrasi stroma dan adanya reaksi bilik mata depan_ Manifestasi klinis yang lebih spesifik adalah adanya infiltrasi bercak-bercak putih, lesi satelit, hipopion dan plak endotel.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-089","number":89,"package":"Paket 1","topic":"Bedah","title":"Soal 089 · Seorang perempuan usia 23 tahun dibawa ke…","page":49,"stem":"Seorang perempuan usia 23 tahun dibawa ke IGD setelah mengalami kecelakaan lalu lintas 2 jam yang lalu. Pasien mengalami kecelakaan motor dan terjatuh saat menghindari lubang, setelah kejadian pasien masih sadar. Tidak ada mual dan muntah. Tampak Iuka lecet pada lengan kanan. Vital sign dalam batas normal. Pemeriksaan fisik pada ekstremitas superior dekstra terdapat memar dan nyeri tekan. Dilakukan pemeriksaan radiologi dan didapatkan hasil pada foto rontgen terdapat garis halus pada os radius dan os ulna di bagian proksimal. Diagnosis pada pasien ini","options":["Fraktur radius ulna proksimal","Fraktur radius ulna distal","Fraktur galeazzi","Fraktur antebrachii","Fraktur monteggia"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus patah tulang lengan bawah berkaitan dengan fraktur os radius dan atau 05 ulna. Pada pemeriksaan fisik didapati tanda-tanda fraktur. Pada pemeriksaan radiologis perlu diperhatikan adanya Iuksasi sendi radioulnar proksimal atau distal, yang lebih dicurigai apabila ditemukan fraktur hanya pada salah satu tulang disertai dislokasi. Pada fraktur yang tidak berubah posisinya, dilakukan pemasangan gips di atas siku. Pada fraktur yang posisinya berubah, dilakukan reposisi tertutup, kemudian dipasang gips di atas siku","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-090","number":90,"package":"Paket 1","topic":"Campuran","title":"Soal 090 · Seorang pasien Jaki-Jaki berusia 27 tahun datang…","page":49,"stem":"Seorang pasien Jaki-Jaki berusia 27 tahun datang dengan keluhan sesak napas Keluhan dirasakan sejak 1 minggu yang lalu, disertai dengan adanya bunyi mengi. Sesak napas muncul 2-3 kali per hari. Pasien kesulitan untuk berbicara dan menjawab dengan terbata• bata. Diagnosis pada pasien ini","options":["Asma intermiten sedang","Asma intermiten berat","Asma persisten sedang","Asma persisten berat","Status asmatikus"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Asma adalah gangguan inflamasi kronik jalan nafas yang melibatkan berbagai sel inflamasil Pada penyakit ini terjadi hiperaktivitas bronkus, obstruksijlan nafas dan gejala pernafasan (mengi/sesak). Klasifikasi derajat asma berdasarkan tingkat keparahan: Derajat asma Gejala Fungsi paru Asma intermiten a. Siang hari ≤ 2x/minggu a.VariabilitasAPE<20% b. Serangan singkat b.VEP1≥ 80%nilai c. Tidak ada gejala antar serangan prediksi d. Intensitas serangan bervariasi c.APE≥80%nilaiterbaik e. Gejala malam≤ 2 x/sebulan Asma Persisten a. Siang hari > 2x/minggu a. VariabilitasAPE20-30% ringan b. Serangan dapat mempengaruhi b. VEP1≥80%nilai aktivitas prediksi C. Gejalamalam>2x/bulam C. APE≥80%nilaiterbaik Asma Persisten a. Siang hari ada gejala VariabilitasAPE>30% a. Sedang b. Serangan mempengaruhi aktivitas b. VEP1 60-80% nilai C. Serangan ≥ 2 x/minggu prediksi d. Serangan berlangsung berhari-hari C. APE 60-80% nilai e. Sehari-hari menggunakan inhalasi terbaik B-2 agonis kerja singkat f. Gejalamalam>1 x/minggu Asma Persisten a. Siang hariterusmenerusadagejala a. VariabilitasAPE>30% Berat b. Aktivitasfisikterbatas b. VEP1≤ 60%nilai C. Setiap malam hari sering timbul prediksi gejala C. APE≤60%nilaiterbaik","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-091","number":91,"package":"Paket 1","topic":"Campuran","title":"Soal 091 · Seorang perempuan berusia 55 tahun datang dengan…","page":50,"stem":"Seorang perempuan berusia 55 tahun datang dengan keluhan nyeri pada pergelangan tangan kanan sejak I tahun yang lalu. Keluhan disertai rasa kebas dan kesemutan pada telapak tangan sekitar ibu jari yang bertambah hebat terutama pada malam hari. Pada pemeriksaan fisik tampak atrofi otot thenar, tes phalen (+). Tidak ada riwayat trauma pada pergelangan tangan. Diagnosis yang tepat pada pasien ini adalah...","options":["Carpal tunnel syndrome","Osteoarthritis","Neuropati","Artitis rematoid","Myasthenia gravis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala pada carpal tunnel syndrome : Rasa kebas, dan parasthesia (seakan-akan terbakar dan bergetar) di ibu jari, telunjuk, dan jari tengah, atau pada beberapa pasien terjadi di telapak tangan. Mengenai nervus medianus Susah menggenggam dan mengepalkan tangan.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-092","number":92,"package":"Paket 1","topic":"Neurologi","title":"Soal 092 · Seorang pasien laki-laki berusia 70 tahun datang…","page":51,"stem":"Seorang pasien laki-laki berusia 70 tahun datang ke IGD dengan keluhan nyeri kembung, muntah berwarna hijau. Sejak 3 hari yang lalu pasien mengeluh nyeri perut hilang timbul. Pasien juga mengeluh tidak bisa buang air besar dan buang angin. pasien buang air besar campur darah dan lendir dan didapatkan penurunan berat badan sejak 1 hari yang lalu. Pada pemeriksaan fisik ditemukan kesadaran somnolen, tekanan darah 95/60 mmHg, laju respirasi 30 kali/menit, nadi 1 IO kali/menit, suhu 39,20C. Pada pemeriksaan abdomen didapatkan darm steifung (+), darm contour (+) ,metallicsound (+). Pada foto polos abdomen tampak air fluid level. Diagnosis yang paling tepat pada pasien ini adalah„.","options":["Appendisitis","Peritonitis","Ileus obstruktif","Ileus paralitik","Ileus non mekanis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Ileus obstruktif merupakan kerusakan atau hilangnya pasase isi usus yang disebabkan Oleh sumbatan mekanik. Gejala pada ileus obstruksi antara Iain nyeri kolik abdomen, mual, muntah, perut distensi dan tidak bisa buang air besar. Pada ileus obstruksi Ietak tinggi umumnya terjadi mual dan muntah. Jika obstruksi di distal terjadi nyeri abdomen, Pada pemeriksaan fisik abdomen didapatkan abdomen tampak distensi, terdapat darm contour (gambaran usus) dan darm steifung (gambaran gerakan usus), pada auskultasi terdengar hiperperistaltik berlanjut menjadi metallic sound. Tahap selanjutnya peristaltik akan melemah dan menghilang. Pemeriksaan radiologis pada posisi terlentang didapatkan hearing bone appearance, posisi setengah duduk tampak step ladder appearance. Foto polos abdomen terdapat gambaran step ladder dan air fluid level. 93. Seorang Iaki-laki berusia 25 tahun penderita epilepsi telah mengkonsumsi Obat epilepsi sejak 2 tahun yang lalu. Pasien tersebut sekarang mengeluh lemah, letih' dan telinganya sering berdenging. Pemeriksaan fisik tanda vital dalam batas normal'","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-093","number":93,"package":"Paket 1","topic":"Campuran","title":"Soal 093 · Paket 1","page":51,"stem":"menyebabkan kondisi tersebut di atas adalah..","options":["Klonazepam","Karbamazepine","Fenobarbital","Asam valproate","Fenitoin"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada pasien ini terjadi anemia megaloblastik yang ditandai dengan lemah, letih, lesu, telinga berdenging, pucat, lidah merah seperti daging. Pada MCV meningkat dan MCH masih normal. Obat anti epilepsi yang menyebabkan efek samping berupa anemia megaloblastik adalah fenitoin.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-094","number":94,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 094 · Seorang perempuanberusia40tahun G P A datangkepuskesmasdengan keluhantimbul…","page":52,"stem":"Seorang perempuanberusia40tahun G P A datangkepuskesmasdengan keluhantimbul '4 30 perdarahan dari jalan lahir setelah 6 minggu terlambat menstruasi sejak tadi pagi. Pasien mengaku dari vagina sudah keluar gumpalan darah yang disertai selaput. Perdarahan berhenti setelah gumpalan tersebut keluar. Pemeriksaan inspekulo menunjukkan serviks menutup tanpa adanya darah. Pada pemeriksan laboratorium didapatkan tes kehamilan (+). Diagnosis apakah yang tepat pada pasien tersebut?","options":["Abortus komplet","Abortus inkomplet","Abortus imminens","Abortus insipiens","Missed abortion"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Abortus komplit terjadi apabila hasil konsepsi lahir dengan lengkap. Pada abortus komplit perdarahan segera berkurang setelah isi rahim dikeluarkan paling lambat 10 hari perdarahan berhenti sama sekali karena dalam masa ini Iuka rahim telah sembuh dan terjadi epitelisasi. Hasil tes kehamilan dapat (+) hingga 2-3 minggu pasca abortus.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-095","number":95,"package":"Paket 1","topic":"Campuran","title":"Soal 095 · Seorang pasien Iaki-laki berusia 27 tahun datang…","page":52,"stem":"Seorang pasien Iaki-laki berusia 27 tahun datang dengan keluhan nyeri kepala sebelah kanan. Nyeri kepala dirasakan berdenyut. Pasien menyangkal adanya gejala berputar, berkunang-kunang, tampak garis/benang atapun yang lain sebelum munculnya nyeri kepala. Pasien bekerja sebagai seorang sales. Diagnosis yang tepat pada pasien ini adalah.„","options":["Cluster headache","Tension headache","Migraine with aura","Migraine without aura","Classic migraine"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Migrain tanpa aura ditandai dengan nyeri kepala berulang dengan manifestasi serangan selama 4 - 72 jam, nyeri kepala unilateral, berdenyut, bertambah berat dengan aktivitas fisik dan diikuti nausea dan fotopobia dan fonofobia.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-096","number":96,"package":"Paket 1","topic":"Campuran","title":"Soal 096 · Seorang perempuan berusia 55 tahun, datang ke…","page":53,"stem":"Seorang perempuan berusia 55 tahun, datang ke poliklinik RS ingin melakukan medical check up. Dari pemeriksaan fisik didapatkan berat badan 68 kg dan tinggi badan 168 Termasuk kategori apakah status gizi dari pasien tersebut?","options":["Normoweight","Underweight","Overweight","Obese I","Obese II"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Klasifikasi IMT Underweight < 18,5 Normal Overweight 223 Dengan risiko 23-24,9 Obese I 25-29 Obese II 2 30 68 = 24. Pasien tersebut termasuk dalam kategori overweight. TB2 2,8224","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-097","number":97,"package":"Paket 1","topic":"Campuran","title":"Soal 097 · Seorang pasien Iaki-laki berusia 60 tahun datang…","page":53,"stem":"Seorang pasien Iaki-laki berusia 60 tahun datang ke RS dengan keluhan tangan bergetar. Keluhan sudah dirasakan sejak I bulan. Pada pemeriksaan terlihat pasien berjalan condong ke depan, tangan dan bibirnya bergetar, wajah seperti topeng (mask face), dan terdapat cogwhell phenomen saat pemeriksaan tonus otot. Vital sign dalam batas normal Diagnosis yang tepat pada pasien ini adalah...","options":["Tremor essensial","Huntington disease","Tic fasialis","Khorea","Penyakit Parkinson"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Parkinson terjadi karena penurunan kadar dopamine akibat kematian neuron di pars kompakta substansia nigra sebesar 40-50%. Etiologi belum diketahui. Gejala pada parkinson adalah tremor, rigiditas, akinesia/bradikinesia dan hilangnya efek posturnal Tremor terjadi saat istirahat dan bergerak. Akinesia dapat dilihat dari wajah seperti topeng' suara kecil, liur menetes, gerakan cepat yang tak terkontrol, tulisan yang mengecil' cara berjalan langkah kecil-kecil dan kegelisahan motorik.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-098","number":98,"package":"Paket 1","topic":"Campuran","title":"Soal 098 · Seorang pria berusia 45 tahun datang ke…","page":54,"stem":"Seorang pria berusia 45 tahun datang ke dokter dengan keluhan sakit pinggang. Keluhan ini hilang timbul dengan sendirinya dalam waktu lama. Nyeri pinggang bawah menjalar sampai ke paha belakang. Pasien tidak pernah mengalami nyeri saat BAK ataupun terbangun berkali-kali pada malam hari untuk BAK. Nafsu makan tidak berkurang. Vital sign dala batas normal. Pemeriksaan fisik tidak ada nyeri ketok abdomen. Termasukjenis nyeri apakah yang dialami Oleh pasien tersebut?","options":["Psikogenik","Homotopic","Wandering","Neurogenik","Labor"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"• Nyeri psikogenik adalah gejala nyeri fisik yang berasal dari gangguan psikologik • Nyeri homotopic merupakan istilah nyeri pada lokasi yang cedera • Nyeri wandering adalah nyeri yang berulang kali dan berubah-ubah letaknya • Nyeri neurogenik merupakan nyeri yang disebabkan lesi atau kelainan pada saraf organ tersebut. • Nyeri labor adalah nyeri ritmik dengan peningkatan frekuensi dan keparahan yang disebabkan kontraksi uterus saat persalinan.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-099","number":99,"package":"Paket 1","topic":"Campuran","title":"Soal 099 · Seorang laki-laki berusia 50 tahun datang ke…","page":54,"stem":"Seorang laki-laki berusia 50 tahun datang ke poliklinik dengan keluhan sulit BAK dan kaki bengkak sejak 3 bulan yang lalu. Terdapat riwayat kencing batu tetapi belum pernah dioperasi sekitar 15 tahun yang lalu. Pasien juga mengeluh mual dan muntah. Kadar ureum 115, creatinin 5,8, glukosa 168. Penyebab mual dan muntah dari pasien tersebut adalah„.","options":["Infeksi saluran kemih","Sindrom uremikum","Sindrom metabolik","Batu saluran kemih","Glukosa tidak terkontrol"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus di atas, pasien mengalami sindrom uremikum yang dapat menimbulkan berbagai macam gejala pada pasien. DERMATOLOGIC NEUROLOGIC Pallor Fatigue Pruritus Drowsiness Dry skin Peripheral neuropathy Yellow-gray color Irritability Decreased perspiration Depression Brittle, dry hair Decreased concentration ENDOCRINE ability Hypothyroidism Insomnia Hyperparathyroidism OCULAR Retinopathy CARDIOVASCULAR Red eye Congestive heart failure RESPIRATORY Hypertension Uremic lung Pericarditis Pleuritis HEMATOLOGIC Pulmonary edema Anemia Bleeding tendency METABOLIC Susceptibility to infection Hyperglycemia Hypertriglyceridemia GASTROINTESTINAL Hyperuricemia Nausea Metabolic acidosis Vomiting Anorexia REPRODUCTIVE GI bleeding Infertility Diarrhea Decreased libido Uremic fetor Impotence MUSCULOSKELETAL Amenorrhea Renal osteodystrophy Delayed puberty Osteomalacia Osteitis fibrosa Osteosclerosis Soft tissue calcification Retarded growth","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-100","number":100,"package":"Paket 1","topic":"THT","title":"Soal 100 · Seorang laki-laki berusia 23 tahun datang ke…","page":55,"stem":"Seorang laki-laki berusia 23 tahun datang ke puskesmas dengan keluhan nyeri pada telinga kiri setelah dikorek-korek dengan cotton bud. Keluhan juga disertai dengan penurunan pendengaran dan keluar cairan encer kekuningan. Pada pemeriksaan telinga didapatkan nyeri pada saat daun telinga ditarik. Pada pemeriksaan otoskopi didapatkan liang telinga sebagian besar bengkak, terdapat cairan encer kekuningan, membrana timpani intak dan warna suram. Diagnosis pada pasien tersebut adalah...","options":["Otomikosis","Otitis eksterna difusa","Otitis eksterna sirkumskripta","Otitis media supuratif akut","Perikondritis"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Otitis Eksterna dibagi menjadi 2 yaitu : a. Otitis Eksterna sirkumkripta Gejala : Furunkel, nyeri perikondrium, sekret (-) b. Otitis Eksterna difusa Gejala : 2/3 dalam liang telinga, nyeri tekan tragus, liang telinga sempit, sekret (+) bau, pembesaran KGB 101. Seorang perempuan berusia 24 tahun datang dengan keluhan nyeri perut kanan bawah sejak 2 hari yang lalu, Pasien juga merasa nyeri pada bagian ulu hati. Selain itu terdapat mual, muntah dan tidak nafsu makan. Dari pemeriksaan fisik didapatkan TD 120/80 ,N 80 x/menit, RR 16x/menit, Suhu 37,8 C. terdapat nyeri tekan McBurney, nyeri lepas (+). Pada pemeriksaan laboratorium ditemukan leukosit 9000, neutrofil 86%. Berapakah Skor Alvarado pada pasien ini? Jawaban : D Pembahasan: ALVARADO SCALE for the diagnosis of Appendicitis Manifestasions Value Symptoms Migration of pain Anorexia 1 Nausea and/or vomiting 1 Signs Right lower quadrant 2 tenderness rebound 1 Elevated temperature Laboratory values Leukocytosis 2 Left shift in leukocyte count 1 Total point 10 Keterangan : 0-4 : bukan appendisitis 5-6 : kemungkinan appendisitis kecil 7-8 : kemungkinan besar appendisitis 9-10 : hampir pasti mengalami appendicitis","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-101","number":101,"package":"Paket 1","topic":"Campuran","title":"Soal 101 · Seorang perempuan berusia 24 tahundatang dengan keluhan…","page":56,"stem":"Seorang perempuan berusia 24 tahundatang dengan keluhan nyeri perut kanan bawah sejak2hari yang lal,Pasienjugaerasa nyerpadbagianuluhatielainituterda mual, muntah dan tidak nafsu makan. Dari pemeriksaan fsik didapatkan TD 120/80 ,N 80 x/menit, R 16x/menit, Suhu 37,8 C. terdapat nyeri tekan McBurney, nyeri lepas (+). Pada pemeriksan laboratorium ditemukan leukosit 9000, neutrofl 86%.Berapakah skor Alvarado pada pasien ini?","options":["5","6","7","8","9"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"ALVARADOSCALEforthediagnosisofAppendicitis Manifestasions Value Symptoms Migration of pain 1 Anorexia 1 Nausea and/orvomiting 1 Signs Right lower quadrant 2 tenderness rebound 1 Elevated temperature 1 Laboratory values Leukocytosis 2 Left shift in leukocyte count 1 Total point 10 Keterangan: 0-4: bukan appendisitis 5-6:kemungkinan appendisitiskecil 7-8: kemungkinan besar appendisitis 9-10 : hampir pasti mengalami appendicitis","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-102","number":102,"package":"Paket 1","topic":"Anak","title":"Soal 102 · Seorang bayi berusia 6 hari dibawa ibunya…","page":56,"stem":"Seorang bayi berusia 6 hari dibawa ibunya ke IGD RS dengan keluhan utama kejang. Ibunya juga mengeluhkan kaku pada bagian leher, perut dan punggung bayi, tidak mau menetek serta mulut yang mencucu.MeIaIui anamnesis lebih lanjut, didapatkan bahwa ibu bersalin didukun beranak dengan peralatan seadanya serta tidak pernah melakukan pemeriksaan kehamilan. Diagnosis yang tepat pada pasien ini adalah...","options":["Tetanus neonatorum","Meningitis","Encephalitis","Perdarahan intra kranial","Meningoencefalitisneonatorum"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tetanus neoatorum adalah penyakit yang disebabkan karena clostridium tetani. Clostridium tetani merupakan suatu bakteri gram positif, anaerob dan membentuk spora. Masa inkubasi 3-10 hari. Pada tetanus neonatorum beberapa hal yang perlu adalah : a. Penolong persalinan (sering terjadi pada dukun bayi yang belum mendapat pelatihan) b. Ramuan yang dibubuhkan pada tali pusat c. Alat yang dipakai pada pemotongan tali pusat d. Imunisasi ibu selama dan sebelum kehamilan e. Sejak kapan bayi tidak mau menetek f. Selang waktu gejala tidak mau menetek dengan gejala spasme pertama Pada pemeriksaan fisik didapatkan kesadaran intak, kejang, sulit menelan, mulut mencucu seperti ikan, trismus, kaku otot leher, punggung dan perut dan spasme dapat terjadi spontan atau terhadap rangsangan dengan frekuensi yang bervariasi.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-103","number":103,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 103 · Seorang mayat laki-laki ditemukan tergantung di pohon.Dari…","page":57,"stem":"Seorang mayat laki-laki ditemukan tergantung di pohon.Dari hasil otopsi didapatkan adanya tanda-tanda hipoksia,bendungan organ dalam dan pembesaranjantung.Jenis hipoksiajenis apakahpada pasien ini? a.Hipoksia hipoksik d.Hipoksia histotoksik metabolik b. Hipoksia stagnan e.Hipoksia histotoksik substrat Hipoksia anemik Jawaban:B Pembahasan: Hipoksia adalah keadaan dimana terjadi kekurangan O ditingkat jaringan. Jenis hipoksia: 1. Hipoksiahipoksik(anoksiaanoksik yaituapabila POdarah arteri berkurang 2. HipoksiaanemikyaituapabilaOdaraharterinormaltetapimengalamienervasi 3. Hipoksiastagnan;akibatsirklaiyang lambat merupakamasalahbagiorgansei ginjal dan jantung saat terjadi syok. jaringan paling sering diakibatkan oleh keracunan sianida. tepat pada pasien tersebut adalah...","options":["Eritemamultiform","Selulitis","Folikulitis","Ektima","Erisipelas"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Erisipelasadalahpenyakitinfeksiakutyang disebabkankarenainfeksi streptococcus. Gejalanya adalahkonstitusi demam,malaise.Penyakit ini menyerang lapisankulitbaik epidermis maupun dermis, didahului oleh trauma sehingga predileksinya biasanya tungkai bawah.UKK berupa eritema yang berwarna merah cerah,berbatas tegas, dan pinggirnyameninggi dengantandaradangakut,dapatdisertaiedema,vesikel,danbula. Terdapatleukositosispadapemeriksaanlaboratorium.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-104","number":104,"package":"Paket 1","topic":"Kulit","title":"Soal 104 · Seorang pasien laki-laki berusia 30 tahun datang…","page":57,"stem":"Seorang pasien laki-laki berusia 30 tahun datang ke puskesmas dengan keluhan tinnbul lesi kemerahan pada paha dan terasa nyeri. Pada pemeriksaan dermatologi didapatkan lesi dengan diameter 4 cm dan terdapat pembesaran limfatik yang nyata. Diagnosis yang tepat pada pasien tersebut adalah„.","options":["Eritema multiform","Selulitis","Folikulitis","Ektima","Erisipelas"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Erisipelas adalah penyakit infeksi akut yang disebabkan karena infeksi streptococcus. Gejalanya adalah konstitusi demam, malaise. Penyakit ini menyerang lapisan kulit baik epidermis maupun dermis, didahului Oleh trauma sehingga predileksinya biasanya tungkai bawah. UKK berupa eritema yang berwarna merah cerah, berbatas tegas, dan pinggirnya meninggi dengan tanda radang akut, dapat disertai edema, vesikel, dan bula. Terdapat leukositosis pada pemeriksaan laboratorium.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-105","number":105,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 105 · Seorang pasien perempuan berusia 30 tahun dibawa…","page":58,"stem":"Seorang pasien perempuan berusia 30 tahun dibawa ke IGD dengan keluhan nyeri perut bawah mendadak Pasien tidak mengeluhkan adanya demam dan keputihan. Pasien baru saja melepas IUD I ,5 bulan yang lalu karena berencana untuk hamil kembali. Pemeriksaan fisik tekanan darah 70/ palpasi, nadi 1 1 5 x/menit, laju pernafasan 24 x/menit, konjungtiva anemis, abdomen distensi, nyeri tekan dan nyeri lepas perdarahan pervaginam (+), nyeri goyang serviks Hb = 6,6 g/dL, pemeriksaan kehamilan Diagnosis yang tepat pada pasien tersebut adalah...","options":["Kehamilan ektopik terganggu","Abortus imminens","Kista ovari yang rupture","Apendisitis akut","Peritonitis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kehamilan ektopik terganggu adalah implantasi dan pertumbuhan hasil konsepsi diluar endometrium kavum uteri. Anamnesis ditemukan amenore, kadang terdapat tanda hamil muda, nyeri perut bagian bawah, nyeri bahu, tenesmus, perdarahan pervaginam setelah nyeri perut bawah. Pemeriksaan fisik pasien tampak kesakitan dan pucat, jika terjadi perdarahan rongga perut pasien dapat terjadi syok. Pemeriksaan ginekologi ditemukan tanda kehamilan muda, nyeri goyang portio, uterus teraba membesar dan kadang teraba tumor disamping uterus dengan batas sukar ditentukan, kavum douglas menonjol, berisi darah dan nyeri bila diraba. Laboratorium didapatkan Hb menurun setelah 24 jam dan jumlah sel darah merah dapat meningkat.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-106","number":106,"package":"Paket 1","topic":"Parasitologi","title":"Soal 106 · Seorang anak perempuan berusia 9 tahun dibawa…","page":58,"stem":"Seorang anak perempuan berusia 9 tahun dibawa ibunya ke dokter dengan keluhan gatal di kaki yang timbul sejak 2 minggu yang lalu. Keluhan disertai dengan sering buang angin, perut tidak enak,kembung dan mencret-mencret.Menurut ibunya anaknya sering bermain dipasir dan tanah.Padapemeriksaanfeses ditemukan telurcacing.Jeniscacing apakah yangmenyebabkankeluhandiatas?","options":["Ascarislumbricoides","Ankilostoma caninum","Trichuris trichiura","Wucheria bancrofti","Oxyuris vermicularis Jarwaban:g"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-107","number":107,"package":"Paket 1","topic":"Kesehatan Masyarakat","title":"Soal 107 · Seorang karyawan perempuan sebuah toko berusia 19…","page":59,"stem":"Seorang karyawan perempuan sebuah toko berusia 19 tahun diantar Oleh temant-y-a puskesmas karena tiba-tiba ia berteriak-teriak dan meronta-ronta saat sedang Pasien bersuara seperti suara kakek tua yang mengaku sebagai penunggu toko Karyawan tersebut tidak ada riwayat gangguan jiwa, namun dalam kesehariannya cemas dan pendiam. Diagnosis yang tepat pada pasien ini adalatu","options":["Konversi histeria","Gangguan depersonalisasi","Trans disosiasi","Fugue disosiasi","Amnesia disosiasi"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-108","number":108,"package":"Paket 1","topic":"Neurologi","title":"Soal 108 · Seorang laki-laki berusia 30 tahun dibawa ke…","page":59,"stem":"Seorang laki-laki berusia 30 tahun dibawa ke IGD dengan penurunan kesadaran set*' kecelakaan lalu lintas. Pada pemeriksaan tanda vital didapatkan TD 80/60, nadi menit, RR 32x/menit, suhu 37 C. Pada abdomen kiri tampak jejas disertai abdomen tegang. Pasien akan dilakukan resusitasi dan rencana operasi. Keadaan pasien ini American Society ofAnesthesioIogist tergolong dalam?","options":["ASAI","ASAIIE","ASA Ill E","ASAIVE","ASAV"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-109","number":109,"package":"Paket 1","topic":"Mata","title":"Soal 109 · Seorang laki-laki berusia 50 tahun datang dengan…","page":60,"stem":"Seorang laki-laki berusia 50 tahun datang dengan keluhan penglihatan menurun mendadak pada mata kiri. Mata kiri terasa nyeri yang sangat hebat, pasien merasa seperti melihat pelangi. Keluhan disertai nyeri kepala, mual dan muntah. Pada pemeriksaan mata didapatkan konjungtiva hiperemis dan pada palpasi terasa lebih keras. Diagnosis yang tepat pada pasien ini","options":["Glaukoma","Ulkus kornea","Panoftalmitis","Endoftalmitis","Buftalmos"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Endoftalmitis merupakan inflamasi pada rongga intraocular (aqueous/vitrous humor). Tanda/gejala: a. Mata merah, nyeri, bengkak, visus turun, riwayat operasi katarak. b. Kelopak merah dan bengkak, hipopion, vitreitis, chemosis, edema kornea, sekret purulen. c. Pasien tidak memakai obat mata dengan patuh.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-110","number":110,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 110 · Seorang pasien perempuan berusia 40 tahun datang…","page":60,"stem":"Seorang pasien perempuan berusia 40 tahun datang ke poliklinik dengan keluhan menstruasi yang banyak dan tidak teratur serta tidak nyeri.Keluhan tersebut sudah dirasakan sejak 3 bulan. Pada pemeriksaan fisik ditemukan massa pada abdomen setinggi umur kehamilan 14-18 minggu. Vital sign dalam batas normal. Kemungkinan diagnosis pada kasus di atas adalahm","options":["Ca endometrium","Mioma uteri","Tumor ovarium","Mola hidatidosa","Ca ovarium"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Mioma uteri adalah tumor jinak miometrium uterus dengan konsistensi padat, kenyal, batas jelas, mempunyai pseudokapsul, tidak nyeri, dapat soliter atau multiple. Gejala timbul tergantung Ietak mioma berada, diantaranya perdarahan abnormal (hipermenore, menoragi, metroragi). Nyeri dapat timbul karena gangguan sirkulasi darah pada sarang mioma. Penekanan pada kandung kemih dapat menyebabkan poliuri, retensio urin, hidroureter dan hidronedrosis., penekanan rectum menyebabkan obstipasi dan tenesmus, pada pembuluh darah dan limfe dipanggul dapat menyebabkan edema tungkai dan nyeri panggul. Infertilitas dapat terjadi jika menekan pars intersisialis dan mioma submukosum juga dapat menyebabkan abortus karena distorsi rongga uterus.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-111","number":111,"package":"Paket 1","topic":"Neurologi","title":"Soal 111 · Seorang perempuan berusia 60 tahun datang dengan…","page":61,"stem":"Seorang perempuan berusia 60 tahun datang dengan keluhan menjadi pelupa. Pasien mengeluh Iupa menaruh barang. Pasien kadang merasa kesemutan di anggota gerak sebelah kanannya. Pasien tidak memiliki riwayat trauma atau jatuh sebelumnya. Pada pemeriksaan fisik kesadaran kompos mentis, tanda vital dalam batas normal. Hasil CT scan ditemukan adanya infark multiple. Diagnosis yang tepat pada pasien ini","options":["Demensia vascular","Dementia with lewy bodies","Tremor esensial","Parkinson","Penyakit alzeimer"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Anamnesis khas pada dementia vascular yaitu adanya gangguan kognitif akut/subakut setelah sebuah serangan neurologis akut yang semakin hari semakin memberat. Konfirmasi etiologi vaskular dengan CT atau MRI. Pada CT scan didapatkan adanya infark multiple. Penatalaksanaan pada dementia vascular : — Antiplatelet (aspirin) untuk mencegah stroke. - Pentoxifylinne untuk meningkatkan aliran darah ke otak.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-112","number":112,"package":"Paket 1","topic":"Kulit","title":"Soal 112 · Seorang laki-laki berusia 45 tahun datang dengan…","page":61,"stem":"Seorang laki-laki berusia 45 tahun datang dengan keluhan sering sakit kepala sejak 3 bulan terakhir. Keluhan sakit kepala disertai dengan telinga mendenging, mudah lelah' penglihatan kadang kabur, serta gatal-gatal di kulit. Pemeriksaan vital sign didapatkan tekanan darah 160/100 mmHg, denyut nadi 85 kali/menit, frekuensi nafas 20 kali/menit' suhu 36,70C. Pemeriksaan fisik didapatkan perkusi ruang traube speace pekak. Saturasi oksigen arteri sebesar 97%. Hasil pemeriksaan laboratorium menunjukkan trombOSlt 480.000/mL, leukosit 155000/mL Diagnosis yang tepat pada pasien tersebut","options":["Otitis media akut","Leukemia mielositik akut","Demam dengue","Malaria","Polisitemia vera"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"polisitemia vera adalah proliferasi berlebihan sel eritroid disertai dengan seri myeloid dan megakariosit. Umumnya mengenai usia tua dengan gejala sakit kepala, seak nafas, penglihatan kabur, dan keringat malam sering disertai gejala epigastrial distress, gatal, kesemutan, rasa terbakar pada tungkai, muka kemerahan, splenomegali, perdarahan, gejala thrombosis arterial, thrombosis vena, hipertensi, arthritis gout karena hiperurisemia. Kriteria diagnosis menurut Polycythemia Vera Study Group sebagai berikut: Kriteria mayor (A): a. Meningkatnya sel darah merah diukurdengan Cr51 (pria > 36 mL/kg, wanita > 32 mL/ kg) b. Saturasi oksigen arteri arterial > 9296 c. Splenomegali Kriteria minor (B) : a. Trombosit > 400.000/mm b. Leukosit> 12.000/mm3 c. Skor neutrofil alkalin fosfatase (neutrophil alkaline phospatase, NAP) meningkat> 100 (tanpa adanya panas atau infeksi), kadar vitamin B12 > 900 pg/mL dan atau UB12BC dalam serum > 2200 pg/L Diagnosis polisitemia vera dapat ditegakkan jika memenuhi criteria AI+A2+A3 atau A1 +A2+2 kategori B.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-113","number":113,"package":"Paket 1","topic":"THT","title":"Soal 113 · Seorang wanita berusia 30 tahun datang dengan…","page":62,"stem":"Seorang wanita berusia 30 tahun datang dengan keluhan pusing berputar, telinga berdenging dan pendengaran menurun.KeIuhan sudah dirasakan sejak 2 minggu yang lalu. Pemeriksaan vital sign dalam batas normal. Diagnosis yang tepat pada pasien ini adalah„.","options":["Labirinitis","Neuritis vestibularis","Meniere disease","Vertigo perifer","Vertigo sentral"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Meniere disease merupakan peningkatan tekanan datam system endolimfatik telinga dalam. Gejala dan tanda : adanya gangguan pendengaran yang hilang timbul kronik. Vertigo episodik kronik, tinitus, elinga terasa penuh. Penatalaksanaan: • Saat serangan: diazepam • Setelah serangan: diuretlk (HCT) + steroid","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-114","number":114,"package":"Paket 1","topic":"Campuran","title":"Soal 114 · Seorang perempuan berusia 50 tahun, mengalaml patah…","page":63,"stem":"Seorang perempuan berusia 50 tahun, mengalaml patah tulang akibat penipisan tulang trabekula. Pasien tersebut telah mengalaml menopause sejak 2 tahun yang lalu. Kadar kalsium dan fosfor dalam batas normal. Diagnosis yang tepat pada pasien tersebut adalah„.","options":["Osteoporosis","Artritis gout","Rheumatoid artritis","Mialgia","Osteokondroma"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Osteoporosis merupakan penyakit tulang sistemik yang ditandai dengan penurunan densitas massa tulang dan perburukan mikroarsitektur tulang sehingga menjadi rapuh dan mudah patah. Beberapa faktor resiko menopause meliputi umur, lamanya menopause dan kadar esterogen yang rendah. Dari anamnesis kadang keluhan utama dapat mengarah pada diagnosis seperti fraktur kolum femur. Kalsium dan fosfor dapat menurun pada pemeriksaan biokimia. Pada gambaran radiologik terdapat penipisan korteks dan daerah yang lebih lusen.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-115","number":115,"package":"Paket 1","topic":"Campuran","title":"Soal 115 · Seorang laki-laki berusia 35 tahun datang dengan…","page":63,"stem":"Seorang laki-laki berusia 35 tahun datang dengan keluhan kaku pada punggung dan leher. Sebelumnya pasien tertusuk paku saat sedang bekerja di sawah. Terdapat Iuka pada telapak kai kiri yang tampak mongering. Pada pemeriksaan fisik ditemukan trismus (+), kaku leher (+), tanda vital : TD 130/80 mmHg, nadi 98 x/menit, RR 28x/menit, suhu 37.5 C. Diagnosis yang tepat pada pasien tersebut adalah.„","options":["Meningoencepalitis","Malaria cerebral","Tetanus","Meningitis","Epilepsi"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala tetanus : Kaku otot dan kejang otot akibat toksin clostridium tetani, gejala mulai muncul dari hari ke-2 setelah infeksi, paling sering trismus, nadi dan frekuensi nafas meningkat. Penatalalaksanaan: a. Antibakteri : metronidazole b. Mengikat toksin bebas : tetanus immune globulin c. Simtomatis : diazepam d. Profilaksis : tetanus toxoid (penyakit tetanus tidak membuat imun)","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-116","number":116,"package":"Paket 1","topic":"Neurologi","title":"Soal 116 · Seorang laki-laki berusia 55 tahun berobat ke…","page":64,"stem":"Seorang laki-laki berusia 55 tahun berobat ke pollkllnlk dengan keluhan cering buang air kecil terutama malam harl, nafsu makan dan minum meningkat, tetapi berat badan mengalami penurunan. Berat badan paslen turun 5 kg dalarn I bulan ini. Perneriksaan vital sign didapatkan tekanan darah 150/100 mmHg, frekuensi nadi 86 kali/rnenit, Jaju napas 20 kali/menlt, dan suhu 37,50C. Hasil pemerlksaan gula darah %ewaktu 375 rng/dL Efek mikroangiopati yang dapat timbul pada pasien ini adalah..,","options":["Angina pectoris","Gagal ginjal","Nefropati diabetik","Miokardlopati","Stroke perdarahan"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada diabetes mellitus terdapat beberapa penyulit yaitu : Penyulit akut Pen ullt menahun a. Ketoasidosis diabetik a, Makroangiopati : b. Hiperosmolar nonketotik Pembuluh darah jantung: Angina c. Hipoglikemi Pembuluh darah tepi : penyakit arteri, intermitten claudicatio, ulkus iskemik kaki) Pembuluh darah otak : stroke b. Mikroangiopati : Retinopati diabetik Nefropati diabetik c. Neuropati","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-117","number":117,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 117 · Seorang perempuan berusia 30 tahun datang dengan…","page":64,"stem":"Seorang perempuan berusia 30 tahun datang dengan keluhan terasa berdebar-debar, sering berkeringat dan nafsu makan meningkat namun berat badan pasien cenderung turun drastis. Awalnya berat badan pasien 60 kg, turun menjadi 50 kg selama 4 minggu. Pada pemeriksaan fisik terdapat eksoftalmus. Pemeriksaan hormon tiroid menunjukkan TSH O,03T4 174. Diagnosis yang tepat pada pasien ini adalah...","options":["Adenoma toksik","Keganasan tiroid","Tiroiditis hashimoto","Tiroiditis sub-akut","Graves disease"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Klasifikasi penyakit tiroid yaitu a. Pembesaran tiroid semata : 1. Defisiensi yodium (struma difusa nontoksik/goiter endemik), Bisa berkembang menjadi struma nodular nontoksik. 2. Goiter sporadik (jarang) b. Hipotiroidisme 1. Defisiensi yodiurn yang lebih berat 2. Tiroiditis Hashimoto, tiroiditis subakut (awal hipertiroid namun berkembang menjadi hipotiroid 3. Iatrogenik 4. Lain-Iain (misalkan. obat, kongenital, hipopituitarisme, kelainan hipotalamus) c. Hipertiroidisme 1. Penyakit Graves 2. Struma nodular nontoksik yang menjadi toksik 3. Adenoma toksik 4. Lain-Iain (mis. tiroiditis destruktif, hormone tiroid ekstratiroidal, tumor hipofisis) d. Neoplasma : Pada pemeriksaan dapat ditemukan massa terfiksir, cepat membesar. e. Tiroiditis subakut (pada tipe Subacute granulomatous thyroiditis ) : dapat ditemukan keluhan demam, nyeri pada kelenjar.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-118","number":118,"package":"Paket 1","topic":"Anak","title":"Soal 118 · Seorang anak berusia 3 tahun dibawa Oleh…","page":65,"stem":"Seorang anak berusia 3 tahun dibawa Oleh ibunya dengan keluhan terdapat adanya flek putih pada mata. Pemeriksaan fisik dalam batas normal. Pada pemeriksaan mata didapatkan adanya ulkus kornea pada 2/3 permukaan kornea. Pasien belum pernah diimunisasi sebelumnya. Pemberian terapi yang sesuai dengan program pemerintah ialah?","options":["Pemberian vit A 50.000 UI pada usia 6-11 bulan dihari pertama, kedua dan 2 minggu kemudian","Pemberian vit A 50.000 UI pada usia 12-59 bulan dihari pertama, kedua dan 2 minggu kemudian","Pemberian vit A 100.000 UI pada usia kurang dari 5 bulan di hari pertama, kedua dan 2 minggu kemudian","Pemberian vit A 200.000 UI pada usia 12-59 bulan dihari pertama, kedua dan 2 minggu kemudian","Pemberian vitA 100.000 UI pada usia 12-59 bulan di hari pertama, kedua dan 2 minggu kemudian"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pemberian vitamin pada xerofthalmia: USIA bulan Vitamin A 50.000 IU pada hari ke 1,2 dan 14 6-12 bulan Vitamin A 100.000 IU pada hari ke 1, 2 dan 14 > 12 bulan-59 bulan Vitamin A 200.000 IU pada hari ke I, 2 dan 14","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-119","number":119,"package":"Paket 1","topic":"Campuran","title":"Soal 119 · Seorang anak perempuan berusia 4 tahun dibawa…","page":66,"stem":"Seorang anak perempuan berusia 4 tahun dibawa ibunya ke dokter dengan keluhan terdapat benjolan di ujung alis yang timbul seJak Jahir. Sejak 3 minggu terakhir benjolan tersebut baru mulai membesar, tidak nyeri, tidak merah, kistik, dan mobile. Pemeriksaan vital sign dalam batas normal. Diagnosis pasien ini adalah...","options":["Miliaria","Lipoma","Ateroma","Kista aterom","Kista dermoid"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kista dermoid adalah kista kongenital yang berasal dari kelainan pertumbuhan kulit pada masa embrio. Gambaran klinisnya bulat pada lapisan subkutan dengan ukuran bervariasi hingga IO cm. Terdiri atas kelenjar sebasea, folikel rambut yang rudimenter, dan elemen kelenjar keringat yang dekat pada garis epitelial. Predileksinya di Sisi lateral alis mata, sepanjang akar hidung, leher, sublingual, daerah sternal, perineal, skrotum, dan sakral. Biasanya tepas, tak melekat pada kulit di atasnya. Tetapi, sering melekat pada periosteum sehingga tidak lepas dari dasarnya. Dapat menjadi ganas jika sering terjadi infeksi (terutama di daerah sacrum), perforasi spontan, atau sering timbul fistula yang sulit sembuh.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-120","number":120,"package":"Paket 1","topic":"Campuran","title":"Soal 120 · Seorang Iaki-laki berusia 65 tahun dibawa Oleh…","page":66,"stem":"Seorang Iaki-laki berusia 65 tahun dibawa Oleh keluarganya ke IGD karena ditemukan dalam keadaan pingsan. Menurut keluarganya pasien mempunyai riwayat penyakit gula dan saat ini sedang mengkonsumsi obat gula. Dilakukan pemeriksaan GDS pasien dan didapatkan hasil 30. Pemeriksaan vital sign dalam batas normal. Setelah diberikan bolus dekstrosa kondisi pasien membaik, gula darah menjadi 137 mg/dL Obat-obatan DM yang sering menimbulkan kondisi ini adalahm","options":["Metformin","Tiazolidindion","Penghambat alfa-glukosidase","Midglitol","Sulfonilurea"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Efek samping obat antidiabetes : Jenis Obat Efek Samping Obat Penghambat alfa glukosidase Acarbose Perut kembung Miglitol Nyeri perut, diare Biguanid Metformin Mual, diare, perut kembung Hipoglikemi secretagogues Chlorpropamid Insulin Peningkatan berat badan Glimepirid (sulfonylurea) Glipzide Glyburide Peningkatan berat Pioglitazone Tiazolidindion retensi cairan Rosiglitazone","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-121","number":121,"package":"Paket 1","topic":"Neurologi","title":"Soal 121 · Seorang perempuan berusia 32 tahun dibawa Oleh…","page":67,"stem":"Seorang perempuan berusia 32 tahun dibawa Oleh keluarganya ke IGD karena kejang jam yang lalu. Pasien mengalami demam tinggi mendadak sejak 12 jam sebelum ke IGD. Pasien sering merasa badan sering terasa panas, berkeringat, berdebar.debat berat badan menurun. Pasien satu tahun terakhir sedang dalam pengobatan, 3 bulan terakhir tidak lagi kontrol dan mengkonsumsi obat. Pada pemeriksaan fisikdl bagian anterior leher ditemukan massa lunak yang ikut bergerak ketika pasien menelan Pemeriksaan laboratorium yang kemungkinan ditemukan pada pasien tersebut adalatL","options":["TSH meningkat,T4 menurun","TSH menurun,T4 meningkat","TSH menurun,T4 menurun","TSH normal, T4 meningkat","TSH meningkat, T4 normal"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-122","number":122,"package":"Paket 1","topic":"Campuran","title":"Soal 122 · Seorang perempuan berusia 40 tahun, datang ke…","page":67,"stem":"Seorang perempuan berusia 40 tahun, datang ke RS dengan keluhan nyeri perut sejak3 bulan yang lalu yang dirasakan kumat-kumatan. Frekuensi BAB 2-3 kali/hari, dan keluhan nyeri perut berkurang setelah BAB, serta hilang timbul. Pasien mengaku berat badannya normal tldak mengalaml penurunan. Hasil pemerlksaan darah samar (-), kolonoskopi dan endoskopi dengan blopsl menunjukkan hasll normal, serta kultur tinja (-). Pasien bekerja sebagal sekretarls sebuah perusahaan. Diagnosis yang tepat pada pasien tersebut adalah.„","options":["Ulkus gaster","Ulkus duodenum","Irritable bowel syndrome","Inflammatory bowel disease","Duodenitis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-123","number":123,"package":"Paket 1","topic":"Neurologi","title":"Soal 123 · Seorang pasien Iaki-laki berusia 27 tahun datang…","page":68,"stem":"Seorang pasien Iaki-laki berusia 27 tahun datang dengan penurunan kesadaran karena mengalami kecelakaan lalu lintas. Dilakukan pemeriksaan CT scan dan didapatkan gambaran lesi hiperdens di area paretooksipital berbentuk bulan sabit. Diagnosis yang tepat pada pasien ini","options":["Perdarahan epidural","Perdarahan subdural","Perdarahan subarachnoid","Perdarahan intraserebral","Perdarahan intraventrikuler"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"SDH : kesadaran menurun akutatau progresif, pada CT scan gambaran hiperdens bentuk sabit (konkaf). EDH : ada lucid interval, pada CT Scan gambaran hiperdens bikonveks.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-124","number":124,"package":"Paket 1","topic":"Kulit","title":"Soal 124 · Seorang perempuan berusia 30 tahun datang dengan…","page":68,"stem":"Seorang perempuan berusia 30 tahun datang dengan keluhan gatal pada kedua telapak tangan sejak mencuci baju dengan detergen 1 minggu yang lalu. Pada pemeriksaan lokalis kedua palmar dan jari tangan terlihat eritema difus, skuama kasar, fissure dan sedikit erosi. Pada pemeriksaan lab lgE dalam batas normal. Diagnosis yang tepat pada pasien ini adalah„.","options":["Dermatitis kontak alergi","Dermatitis kontak iritan","Tinea manus","Neurodermatitis","Dermatitis atopi"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Membedakan dermatitis kontak alergi dan iritan : DKI DKA Menyerang orang tertentu yang memiliki riwayatalergi Menyerang semua orang Timbul hanya bagian yang teririta., Dapat timbul di seluruh tubuh Batas lesi lebih jelas, monomorf Batas lesi tidakjelas, polimorf. patch test : lesi tidak meluas Patch test : lesi meluas langsung Didahului proses sensitisasi sebelumnya Zat kimia iritan Hapten","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-125","number":125,"package":"Paket 1","topic":"Campuran","title":"Soal 125 · Seorang perempuan berusia 17 tahun datang ke…","page":69,"stem":"Seorang perempuan berusia 17 tahun datang ke dokter dengan keluhan timbul benjolan pada payudara kanan. Pasien baru menyadari adanya benjolan selama 3 minggu ini karena sebelumnya tidak merasakan nyeri. Pemeriksaan vital sign dalam batas normal. pada pemeriksaan fisik ditemukan massa padat kenyal di payudara dan mudah digerakkan. Tidak ada pembesaran kelenjar getah bening. Diagnosis yang tepat pada pasien ini adalah...","options":["Ca mammae","Abses payudara","Fibroadenoma","Galactocele","Cystoma piloides"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Fibroadenoma merupakan neoplasma jinak yang utamanya terdapat pada wanita muda. Teraba sebagai benjolan bulat atau berbenjol-benjol dengan simpai licin dan konsistensi kenyal padat. Tumor ini amat mudah digerakkan. Biasanya tidak nyeri, tetapi kadang dirasakan nyeri bila ditekan. Pada massa adolesens, fbroadenoma bisa dalam ukuran besar. Pertumbuhan bisa cepat sekali selama kehamilan dan laktasi, atau menjelang menopause (saat rangsangan estrogen meninggi). Fibroadenoma harus diekstirpasi karena akan membesar terus menerus.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-126","number":126,"package":"Paket 1","topic":"Anak","title":"Soal 126 · Bayi perempuan lahir spontan usia kehamilan 31…","page":69,"stem":"Bayi perempuan lahir spontan usia kehamilan 31 minggu, ketuban jernih, apgar score 7-8-9, dan dirawat di incubator. Setelah 2 jam bayi merintih, sesak napas dan Sianosis frekuensi jantung 125 x/menit, bising jantung (-), temperature 37,40C. Diagnosis pada","options":["Aspirasi mekonium","Asfiksia perinatal","Penyakit Membran Hyalin","Pneumonia neonatal","Transient tacypnea of newborn"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hyalin membrane disease merupakan penyakit distress nafas yang terjadi pada bayi kurang bulan segera atau beberapa saat setelah lahir dan menetap selama 48-96 jam pertama kehidupan yang terjadi karena kekurangan surfaktan. Gambaran klinis terjadi pada bayi kurang bulan atau dengan faktor risiko seperti : a.Sectio Cesarea d.Korioamnionitis b.Familial e.Ibu dengan DM C.Asfiksia perinatal f.Hydrops fetalis Pemeriksaan fisik didapatkan kesulitan bernafas, takipneu, grunting saat ekspirasi, nafas cuping hidung, retraksi dinding dada, sianosis.Foto thoraks terdapat gambaran retikulogranula (ground-glass appearance) atau airbronchogram periferparu.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-127","number":127,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 127 · Seorang wanita GIPoAo berusia 23 tahun datang…","page":70,"stem":"Seorang wanita GIPoAo berusia 23 tahun datang untuk kontrol kehamilan. Dari anamnesis didapatkan siklus haid 28 hari. Hari pertama haid terakhir 20 April 2013. Menurut rumus neagle kapan takiran persalinan yang tepat?","options":["27 Desember 2013","23 Januari 2014","27 Januari 2014","23 Februari 2014","27 Februari 2014"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hukum Neagle berlaku jika siklus haid 28-30 Hari Rumus NEAGLE: Hari +7, Bulan -3, Tahun +1","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-128","number":128,"package":"Paket 1","topic":"Psikiatri","title":"Soal 128 · Seorang wanita berusia 28 tahun datang diantar…","page":70,"stem":"Seorang wanita berusia 28 tahun datang diantar keluarganya karena sering melamun dan tiba-tiba menangis setelah melahirkan sejak 2 minggu yang lalu, nafsu makan menurun. Apakah kemungkinan diagnosis pasien tersebut?","options":["Psikotik post partum","Depresi post partum","Baby blues syndrome","Gangguan cemas","Skizofrenia"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Baby blues syndrome merupakan mood depresifyang terjadi 14 hari pasca persalinan","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-129","number":129,"package":"Paket 1","topic":"Anak","title":"Soal 129 · Seorang anak laki-laki berusia 3 tahun datang…","page":70,"stem":"Seorang anak laki-laki berusia 3 tahun datang diantar ibunya dengan keluhan demam sejak 3 hari yang lalu. Demam disertai munculnya lenting-lenting di dada dan perut. Pada pemeriksaan fisik didapatkan TD 110/70 mmHg, N 90 x/menit, RR 25 x/menit dan suhu 38 C. Terdapat papula, vesikel, macula pada dada dan perut. Kapan sebaiknya imunisasi penyakit ini dilakukan?","options":["1 bulan","2 bulan","6 bulan","9 bulan","12 bulan"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-130","number":130,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 130 · Seorang perempuan berusia 38 tahun datang dengan…","page":71,"stem":"Seorang perempuan berusia 38 tahun datang dengan keluhan batuk sejak3 mingguj?c lalu. Keluhan disertai dengan keringat dingin pada malam hari dan berat badan Dokter mendiagnosis TB paru aktif dan akan memberikan OAT, vit BI dan tablet sedang mengkonsumsi kontrasepsi oral. Obat apakah yang dapat memberiizn terhadap alat kontrasepsi oral yang digunakan pasien?","options":["INH","Rifampisin","VitB1","Tablet Fe","Etambutol"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-131","number":131,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 131 · Seorang laki-laki berusia 55 tahun mengalami perdarahan…","page":72,"stem":"Seorang laki-laki berusia 55 tahun mengalami perdarahan saat mencabut giginya sekitar 1 jam yang lalu. Pasien merupakan penderita jantung koroner dan mengkonsurnsi aspirin 100 mg selama beberapa tahun ini. Penyebab perdarahan pada pasien di atas adalah..,","options":["Defisiensi factor IX","Hemofilia","Defisiensi trombosit","Gangguan fungsi trombosit","Defisiensi vitamin K"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada pasien ini mengkonsumsi aspirin, aspirin mengurangi aktivasi trombosit dengan menghambat kerja siklooksigenase, sehingga sintesa prostaglandin dan tromboksan A2 menjadi terhambat.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-132","number":132,"package":"Paket 1","topic":"Bedah","title":"Soal 132 · Seorang perempuan berusia 37 tahun datang ke…","page":72,"stem":"Seorang perempuan berusia 37 tahun datang ke IGD dengan keluhan nyeri perut mendadak sejak 1 jam yang lalu. Nyeri perut dirasakan di ulu hati dan menembus ke belakang. Nyeri akan bertambah jika pasien tidur terlentang. Keluhan juga disertai dengan muntah. Vital sign dalam batas normal. Pemeriksaan fisik ditemukan Kehr'5 sign dan Gray turner. Diagnosis yang tepat pada pasien ini adalah...","options":["Apendisitis","Kolelitiasis","Pankreatitis","Kolesistitis","Ruptur limpa"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus di atas terdapat manifestasi klinis berupa nyeri perut di epigastrium yang menembus ke belakang, akan bertambah jika posisi terlentang, terdapat muntahan, serta ditemukan Gray-Turner dan Kehr's sign merupakan gejala pankreatitis.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-133","number":133,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 133 · Dalam sebuah penelitian case control untuk mempelajari…","page":72,"stem":"Dalam sebuah penelitian case control untuk mempelajari angka kejadian hipertensi dengan faktor risiko obesitas tahun 2012 dalam suatu populasi. Didapatkan hasil sebagai berikut: Hipertensi Tidak hipertensi Obesitas 16 8 Tidakobesitas 384 392 Jumlah 400 400 Odd ratio yang diperoleh dari data di atas adalah","options":["16x384/8x392","8x392/16x384","16×392/8x384","16 x400/8x400","8 8x400/16x400"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hipertensi Tidak Hipertensi 16(a) 8(b) Obesitas 384(c) 392(d) Tidak obesitas Jumlah 400 400 Oddratio:ad/bc=16x392/8x384 t34. Seorang laki-laki berusia 25 tahun datang dengan keluhan demam. Demam dirasakan sejak 2 minggu yang lalu, disertai menggigil. Sebelumnya pasien bepergian ke Papua. Fada pemeriksaan fisik didapatkan TD 110/70 mmHg, nadi 88x/menit, RR 16x/menit, suhu38.s C.Pada pemeriksaan apusan darah tebal didapatkan kesan eritrosit membesar, terdapat cincin biru pada eritrosit berbentuk accole.Jenis parasit apa yang menginfeksi pasien tersebut? a.Flasmodiumfalciparum d.Plasmodiumknowlesi .Plasmodium ovale e.Plasmodiumvivax c.Flasmodium malariae Jawaban:A Pembahasan: Gambaran accole adalahgambaran trofozoit padamalaria falciparum. P.falsiparum P.vivax P.ovale P.malariae Penyakit Malaria Malaria Malaria Malaria falsiparum/tropika/ vivax/tersiana ovale malariae/kuartana tersiana maligna Bentuk Cincin,marginal, Cincin (1/3 Bulat/oval Band/pita, trofozoit accole(1/6eritrosit) eritrosit) (1/3 basket/keranjang, intra eritrosit) rossete,bulat eritrosit Bentuk Pisang Bulat/lonjong Bulat Bulat gametosit Pigmen Hitam Kuning tengguli Tengguli tua Tengguli hitam wama Titik-titik di Maurer Schuffner Schuffner enitrosit Ziemann Eritrosit (James) Muda,normosit, Retikulosit, yang Retikulosit, Normosit Tua normosit normosit dihinggapi Vektor muda Anopheles sp Hipnozoit + Daur Tiap 48 jam Tiap 48 jam Tiap48jam Tiap 72 jam eritrosit sejak3hai yang laKelhannyer diraakanmenjalardari pinan sami aha kanannya. Keluhan bertambah berat sat pasien kelelahan Pasien bekerja mengangkat barang di pasar. Pemeriksaan apa yang tepat dlakukan pada pasien ini? a.Tanda Patrick d.Tanda Kernig b.Tes Laseque e.Manuver Phalen c.Tanda Bragard Jawaban:B Pembahasan: Tanda Lasegue : Pasien berbaring, lalu tungkai diangkat ke atas dalam keadaan hutut ekstensi. Jika nyeri, maka kemungkinan ada herniasi diskus. Tes Patrick : Fleksi, abduksi, dan rotasi eksternal tungkai. Bila nyeri ipsilateral anterior, berartiada gangguan sendi panggul ipsilateral. Bila nyeri kontralateral posterior disendi sakroiliaka,berartiada gangguan di sendi tersebut. Tanda Bragard : Dilakukan jika tes Lasegue positif. Tungkai diturunkan satu inci dari posisi yang nyeri saat tesLasegue,kemudiankaki didorsifleksikansecarapasif.Bilatetap nyeri,berartipositif. Tanda Kernig:Fleksikan paha 90° (baik di lutut maupun panggul), kemudian ekstensikan lutut.Bila nyeri (ada resistensi), maka ada iritasi meningens. Manuver Phalen : Pasien diminta untuk memfleksikan penuh pergelangan tangannya selama 30-60 detik. Bila nyeri, maka curiga CTS.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-134","number":134,"package":"Paket 1","topic":"Parasitologi","title":"Soal 134 · Seerang laki-laki berusia 25 tahun datang dengan…","page":73,"stem":"Seerang laki-laki berusia 25 tahun datang dengan keluhan demam. Demam dirasakan sejak 2 minggu yang lalu, disertai menggigil. Sebelumnya pasien bepergian ke Papua. Pada pemeriksaan fisik didapatkan TD 110/70 mmHg, nadi 88x/menit, RR 16x/menit, suhu 3S,S0 C. Pada pemeriksaan apusan darah tebal didapatkan kesan eritrosit membesar, terdapat cincin biru pada eritrosit berbentuk accole. Jenis parasit apa yang menginfeksi gesien tersebut?","options":["Plasmodium falciparum","Plasmodium ovale","Plasmodium malariae","Plasmodium knowlesi","Plasmodium vivax"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gambaran accole adalah gambaran trofozoit pada malaria falciparum. P.falsiparum P.vivax P.ovale P.malariae Fer-yakit Malaria Malaria Malaria Malaria falsiparum/tropika/ vivax/tersiana ovale malariae/kuartana tersiana maligna Eenruk Cincin, marginal, Cincin (1/3 Bulat/oval Band/pita, t±zcit accole (1/6 eritrosit) eritrosit) (1/3 basket/keranjang, eritrosit) rossete, bulat Pisang Bulat/lonjong Bulat Bulat Figmen Hitam Kuning tengguli Tengguli tua Tengguli hitam Ttik-ätik di Maurer Schuffner Schuffner Ziemann ?itasit (James) Muda, normosit, Retikulosit, Tua Retikulosit, Normosit normosit normosit dihirggapi muda Anopheles sp Hipnozoit Daur Tiap 48 jam Tiap 48 jam Tiap 4B jam jot\" eritrosit","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-135","number":135,"package":"Paket 1","topic":"Campuran","title":"Soal 135 · seorang wanita berusia 45 tahun datang ke…","page":74,"stem":"seorang wanita berusia 45 tahun datang ke polikljnik dengan keluhan nyeri sejak 3 hari yang lalu. Keluhan nyeri dirasakan menjalar dari pinggang kanannya. Keluhan bertambah berat saat pasien kelelahan. Pasien bekerjd barang di pasar. Pemeriksaan apa yang tepat dllakukan pada pasien ini?","options":["Tanda Patrick","Tes Lasegue","Tanda Bragard","Tanda Kernig","Manuver Phalen"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-136","number":136,"package":"Paket 1","topic":"Kesehatan Masyarakat","title":"Soal 136 · Sebanyak 50 orang dilarikan ke Puskesmas karena…","page":74,"stem":"Sebanyak 50 orang dilarikan ke Puskesmas karena demam muntah, dan mencret. Keluhan ini timbul setelah mereka makan makanan yang disajikan di acara pernikahan salah satu warga. Pada pemeriksaan feses didapatkan bakteri E.coli Termasuk penyakit apakah kasus di atas? a.Louse borne d.Food borne b.Tick borne e.Vehicleborne CMilkborne disease Jawaban :D Pembahasan: Pada kasus di atas menunjukkan adanya kontaminasi mikroorganisme pada makanan. bakteri laamrikaanfePenyakit-enakit yangdaat ditlarkn makanan disebut sebagai food borne disease. adanyaeritmatateas,edemabulaalpasangat daye tkaeran","options":["Eritrasma","Impetigo kontangiosa bulosa","Erisipelas","Ektima","Selulitis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus erisipelas efouresensi berupa makula eritematosa numular hingga plakat, berbatas tegas, edematosa, panas pada perabaan, nyeri tekan. Penyebabnya adalah streptokokus Bhemolltycus.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-139","number":139,"package":"Paket 1","topic":"Kulit","title":"Soal 139 · Seorang laki•lakl berusla 33 tahun 1 minggu…","page":75,"stem":"Seorang laki•lakl berusla 33 tahun 1 minggu yang lalu berobat ke dokter dengan keluhan utama tungkai bawah kiri bengkak, merah dan nyeri. Kelalnan kulit yang terlihat adalnh adanya erltem, batas tegas, edema, bula, palpasi hangat dan nyerl tekan, Pomeriksaan gram dltemukan streptococcus (+). Diagnosis yang tepat pada kasus dl atas adalah","options":["Eritrasma","Impetigo kontangiosa bulosa","Erislpelas","Ektima","Selulltis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"pada kasus erislpelas eflouresensi berupa makula eritematosa numular hingga plakat, berbatas tegas, edematosa, panas pada perabaan, nyeri tekan. Penyebabnya adalah streptokokus B hemolltycus.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-140","number":140,"package":"Paket 1","topic":"Neurologi","title":"Soal 140 · Seorang laki-laki berusia 50 tahun datang ke…","page":75,"stem":"Seorang laki-laki berusia 50 tahun datang ke puskesmas dengan keluhan nyeri pada pinggang dan menJalar kelutut kiri sejak kurang lebih 3 bulan yang lalu. Keluhan disertai rasa baal dan kesemutan. Pada pemeriksaan fisik kesadaran compos mentis, TD 110/80, nadi 88x/menit, RR 20x/menit, suhu 36 C. Pemeriksaan motorik didapatkan kekuatan motorik ekstremitas superior 5555/5555 dan inferior 5555/5555 ,refieks fisiologls dalam batas normal, reflex patologis tidak ada. Pemeriksaan sensoris : parestesi di L2 dan hiporefleks di lutut kiri bawah. Diagnosis yang paling tepat adalah...","options":["Hernia nucleus Pulposus","Multiple sclerosis","Siringomlelia","Spondilitis TB","Tumor medulla spinalis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hernia Nukleus Pulposus, manifestasi klinis : a) Nyeri plnggang, menjalar ke lutut b) Disertai kelemahan otot, parestesia, dan perubahan reflex Slrlngomlella adalah munculnya kista di dalam medulla spinalis, yang dapat membesar dan merusak medula spinalis. Manifestasi klinis : menyebabkan kelemahan lengan dan tungkai yang kronik progresif, serta pegal atau nyeri kronik di punggung, bahu, lengan, dan tungkai. Multiple sclerosis : Penyakit autoimun yang menyerang mielin di otak dan medula spinalis. Bisa menyebabkan hampir seluruh jenis gejala dan tanda neurologis.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-141","number":141,"package":"Paket 1","topic":"Bedah","title":"Soal 141 · Seorang pemuda berusia 19 tahun terlibat tawuran…","page":75,"stem":"Seorang pemuda berusia 19 tahun terlibat tawuran dan meninggal. Pada saat diotopsi, dokter menemukan luka tembak masuk dengan kelim jelaga di bagian dada kiri. Berapa jarak senjata dengan korban?","options":["15 cm","25-30cm","50-60 cm","100-150cm","200 cm"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Luka tembak: a.LTtempel:terdapat jejaslaras b. LT sangat dekat (maksimal 15 m): terentuk akibat anak peluru, mesiu, jelaga dan panas/api (kelim api) C. LT dekat : terbentuk akibat anak peluru dan mesiu, kelim jelaga (maksimal 30 cm). kelim tato (maksimal 60 cm) d. LT jauh (> 60 cm) : terbentuk akibat komponen anak peluru, kelim kesat dan kelim lecet","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-142","number":142,"package":"Paket 1","topic":"Campuran","title":"Soal 142 · Seorang laki-laki berusia 40 tahun dengan HIV…","page":76,"stem":"Seorang laki-laki berusia 40 tahun dengan HIV (+) datang ke dokter dengan keluhan sariawan. Kemudian, dilakukan pemeriksaan KOH. Hasil apa yang dapat terlihat pada pemeriksaan tersebut?","options":["Pseudohifa","Gram positif","Hifa panjang bersekat","Hifa pendek dinding tebal","Spagheti dan meatball"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien telah didiagnosis dengan candidiasis oral. Candidiasis, moniliasis, atau kandidosis merupakan penyakit jamur yang disebabkan Oleh spesies Candida dan dapat mengenai mulut, vagina, kulit, kuku, bronki, atau paru. Kadang —kadang, dapat menyebabkan septikemia, endokarditis, atau meningitis. Pemeriksaan KOH 10% yang dilakukan akan terlihat sel ragi, blastospora, atau hifa semu.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-143","number":143,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 143 · Seorang laki-laki berusia 40 tahun terdiagnosis hipertensi…","page":76,"stem":"Seorang laki-laki berusia 40 tahun terdiagnosis hipertensi pertama kali. Pada pemeriksaan vital sign TD 160/100 mmHg, Nadi 88x/menit, RR 20x/menit, suhu 36 C. pemeriksan fisik Iain dalam batas normal. Pengobatan hipertensi menurut JNC 7 yang tepat pada pasien ini adalah„.","options":["Diuretik","ACE inhibitor","ACE inhibitor+diuretik","ACE inhibitor+beta blocker","ACE inhibitor+CCB+ARB"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tekanan darah 160/100 mmHg merupakan hipertensi stadium 2 Algaritma penanganan hipertensi menurut JNC 7 Modihkasl gaya hldup Belum mencapal target TD <140/90mmHg Untuk paslen DWGGK < 130/80 mmHg Tanpa indikasl compelling Dengan indikasi compelling Hipertensi stadium I : Hlpertensi stadium 2 : Diuretik thiazld secara umum komblnasi 2 obat (biasanya diuretik Dapat dipertlmbangkan ACE-I, tlpe thiazid dan ACE-I atau ARB atau BB ARB, BB, CCB atau komblnasl atau CCB Tldak mencapal target tekanan darah Naikkan dosis atau tambahkan obat komblnasl hingga mencapai target TD Pertimbangkan untuk konsultasi spesialis","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-144","number":144,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 144 · Seorang pria berumur 54 tahun datang ke…","page":77,"stem":"Seorang pria berumur 54 tahun datang ke dokter umum untuk kontrol penyakit hipertensi. Pasien mengeluh sering merasa lemas dan berdebar-debar. Diketahui pasien rutin mendapatkan obat yang membuat papsien jadi sering kencing. Dari hasil rontgen didapatkan gambaran kardiomegali dan ada kelainan di pemeriksaan EKG. Tekanan darah pasien sekarang adalah 170/100 mmHg. Apa efek samping dari obat yang dkonsumsi Oleh pasien?","options":["Hipokalsemi","Hipomagsenemi","Hiponatremi","Hipokalemia","Defisiensi asam folat"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Informasi yang cukup penting pada kasus tersebut adalah pasien sering mengkonsum„i Obat perangsang kencing. Terdapat riwayat hipertensi. Efek obat menimbulkan jantung Eerdebar dan otot lemas. Obat yang dapat merangsang BAK adalah diuretik. Penggunaan diuretik tiazid, furosemide, dapat menyebabkan hipokalemi. Hipokalemia merupakan samping yang dapat meningkatkan risiko aritmia jantung. Gangguan lainnya kelemahan otot. pusing, dan muntah.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-145","number":145,"package":"Paket 1","topic":"Campuran","title":"Soal 145 · Seorang pemuda berusia 19 tahun sering mencuri…","page":78,"stem":"Seorang pemuda berusia 19 tahun sering mencuri pakaian dalam Wanita rnilik tetangganya. Gangguan jiwa apakah yang dialami Oleh pemuda tersebut?","options":["Ekshibisionisme","Kleptomania","Piromania","Nekromania","Fetihisme"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Fetihisme adalah gangguan kejiwaan berupa penggunaan secara berulang SUatu benda mati sebagai cara yang lebih disenangi untuk mendapatkan kepuasan seksual.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-146","number":146,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 146 · Seorang wanita berusia 35 tahun G7PsAc hamil…","page":78,"stem":"Seorang wanita berusia 35 tahun G7PsAc hamil 39 minggu datang dengan keluhan sesak nafas dan pucat. Menurut keluarga, pasien sempat ditolong Oleh dukun untuk bersalin namun persalinan macet dan dukun mendorong perut pasien. Pada pemeriksaan fisik tekanan darah 70/palpasi, nadi 140x/menit, RR 26x/menit, suhu 37 C. Terdapat perdarahan pervaginam, nyeri pada suprasimpisis dan bagian janin teraba. Diagnosis yang tepat pada pasien ini","options":["Partus macet","Solutio placenta","Inversion uteri","Rupture uteri","Plasenta previa"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala pada rupture uteri yaitu nyeri abdomen, pendarahan pervaginam, tanda syok, fetal bradikardia, bagian janin teraba dari kulit. penyebab : a. Kelemahan pd dinding uterus, misalkan riwayat SC dan myomektomi, grande multipara, makrosomia, gemeli. b. Intervensi saat persalinan: induksi, mendorong fundus terlalu kuat, ekstraksi forcepS•","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-147","number":147,"package":"Paket 1","topic":"THT","title":"Soal 147 · Seorang Iaki-laki berusia 24 tahun datang dengan…","page":78,"stem":"Seorang Iaki-laki berusia 24 tahun datang dengan keluhan sering mimisan. Kadang disertai hidung tersumbat namun tidak batuk dan demam. Pada pemeriksaan tanda vital didapatkan Tekanan darah 120/80 mmHg, Nadi 80x/menit, RR 18x/menit, suhu 36,5. pada pemeriksaan rhinoskopi anterior ditemukan massa merah muda dihidung dan mudah berdarah. Diagnosis yang tepat pada pasien ini","options":["Angifibroma nasofaring","Ca nasofaring","Papiloma laring","Polip hidung","Septum deviasi"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Angiofibroma nasofaring terdapat gejala hidung tersumbat yang progresif dan epitaksis berulang yang masif. Obstruksi hidung memudahkan terjadinya penimbunan secret sehingga timbul rinorea kronis yang diikuti gangguan penghidu. Oklusi tuba eusthacius akan menimbulkan pendengaran menurun, adanya cefalgia menunjukan tumor sudah meluas ke intracranial. Pada pemeriksaan fisik rhinoskopi posterior akan terlihat massa tumor yang konsistensinya kenyal dan wama dapat merah muda sampai abu-abu, mukosa akan mengalami hipervaskularisasi namun jarang terjadi adanya ulserasi.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-148","number":148,"package":"Paket 1","topic":"Campuran","title":"Soal 148 · Seorang anak perempuan berusia 5 bulan dibawa…","page":79,"stem":"Seorang anak perempuan berusia 5 bulan dibawa ke rumah sakit dengan anemia gravis, pucat, ubun-ubun lebar, lien hepar membesar. Dilakukan pemeriksaan GDT dan didapatkan hasil : eritrosit ukuran sama dengan inti limfosit kecil, daerah pucat < h diameter eritrobasophilic stipling, target cell, ear drop dan howel jelly bodies. Penyebab anemia dari kasus di atas","options":["Thalasemia","Defisiensi Fe-hipokrom mikrositer","Anemia hemolitik","Defisiensi folat-makrositer","Defisiensi BI 2-makrositer"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Ditemukannya target cell, ear drop, dan howel jelly bodies merupakan patologi klinis untuk penyakit thalasemia.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-149","number":149,"package":"Paket 1","topic":"Neurologi","title":"Soal 149 · Seorang laki-laki berusia 23 tahun dibawa ke…","page":79,"stem":"Seorang laki-laki berusia 23 tahun dibawa ke IGD karena kecelakaan sepeda motor. Terdapat patah tulang terbuka pada tungkai kiri, darah terus mengalir. Pasien mengalami Penurunan kesadaran dan mendengkur seperti suara berkumur. Pada pemeriksaan didapatkan arteri radialis cepat dan lemah, serta ujung jari dingin. Tindakan pertama yang dilakukan","options":["Membebaskan jalan nafas dan mengatur posisi kepala","Mengangkat kedua tungkai lalu badan diberi alas papan keras","Pasang infus line cairan koloid dan vasopresor","Pasang bidai pada kedua tungkai","Memberi nafas buatan dari mulut ke mulut"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Prinsip penanganan kegawatdaruratan yang ditetapkan menurut Advanced Trauma Life SUPPOrt(ATlS) adalah dengan survei primer ABC. Hal yang pertama dilakukan adalah penilaian airways dengan proteksi cervical, meliputi pemeriksaan adanya obstruksi jalan nafas dengan melindungi vertebra servikal. Langkah kedua breathing, dengan menjaga oksigenasi kemudian menjaga sirkulasi dan kontrol perdarahan.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-150","number":150,"package":"Paket 1","topic":"Mata","title":"Soal 150 · Seorang wanita berusia 26 tahun datang dengan…","page":80,"stem":"Seorang wanita berusia 26 tahun datang dengan keluhan lemah, lesu dan wajah pucat. Pada pemeriksaan fisik didapatkan konjungtiva anemis, tekanan darah 100/80 nadi IOOx/menit, RR 24x/menit, suhu 37 C. Pemeriksaan laboratorium didapatkan Hb 9.2 g/dl, leukosit 6400/mm3. Pemeriksaan apusan darah didapatkan anemia mikrositik hipokromik. Feses menggunakan direct smear dengan larutan garam fisiologs ditemukan gambaran oval dinding transparan bersih dengan segmented ovum. Terapi yang tepat pada pasien ini","options":["Pirantel pamoat","Albendazol","Niklosimid","Pirazikuantel","Dietil karbamazin"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gambaran oval dinding transparan bersih dengan segmented ovum merupakan gambaran telur cacing tambang (necator americanus dan ancylostoma duodenale). Terapi yang tepat albendazol dosis tunggal 400 mg atau mebendazole 2xI 00 mg selama 3 hari.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-151","number":151,"package":"Paket 1","topic":"Neurologi","title":"Soal 151 · Seorang perempuan berusia 16 tahun datang dengan…","page":80,"stem":"Seorang perempuan berusia 16 tahun datang dengan keluhan sering kejang. Pasien mengaku kejangnya sering berulang sejak ia berumur 12 tahun. Lama kejang sekitar 5 menit, kejang berulang dengan frekuensi lx/bulan dan terjadi menjelang haid• Pemeriksaan penunjang apa yang kita anjurkan kepada pasien untuk menunjang diagnosis?","options":["EEG","ENG","EMG","Evoked potensial","Somatosensorik evoked potensial"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"EEG: mendiagnosis epilepsi, koma, ensefalopati, mati otak, gangguan tidur Electronystagmography (ENG): menilai fungsi vestibuler (misalnya pada vertigo) Electromyography (EMG): menilai aktivitas otot rangka, membantu diagnosis penyakit• penyakit neuromuskular Evoked potential: menilai potensi listriksistem saraf, setelah sebelumnya diberi stimUlUS Somatosensory evoked potential: menilai Sistem somatosensoris","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-152","number":152,"package":"Paket 1","topic":"THT","title":"Soal 152 · seorang ibu membawa anak petempuannya berusia S…","page":81,"stem":"seorang ibu membawa anak petempuannya berusia S tahun ke dokter dengan keluhan rasa mengganjal ditenggorokan seak minggu yang lalu. Keluhan dirasakan hilang timbul . Pemeriksaan fisik didapatkan tonsil T3•T3. hiperemis permukaan berbenjol benjol dengan kripta melebar Otagnosis pada pasien ini adalah.„","options":["Tonsilitis folikularis","Tonsilitis parenkimatosa","Tonsilitis Iakunaris","Tonsilitis akut","Tonsilitis kronis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tonsilitis kronis terjadi akibat rangsangan menahun dari rokok. beberapa jenis makanan, higiene mulut yang buruk, pengaruh cuaca. kelelahan fisik. dan pengobatan tonsilitis akut yang tidak adekuat. Pada pemeriksaan tampak tonsil membesar dengan permukaan yang tidak rata, kripta melebar dan beberapa kripte terisi Oleh detritus. Pasien seringkali datang dengan keluhan rasa mengganjal di tenggorokan, tenggorokan dirasakan kering, dan napas berbau.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-153","number":153,"package":"Paket 1","topic":"THT","title":"Soal 153 · Seorang Iaki-laki berusia 19 tahun datang dengan…","page":81,"stem":"Seorang Iaki-laki berusia 19 tahun datang dengan keluhan sakit kepala hebat sejak 5 bulan yang lalu di daerah pipi. Keluhan disertai hidung tersumbat, batuk pilek, dan kadang demam. Pada pemeriksaan fisik ditemukan nyeri tekan pada sinus maksilaris. Pemeriksaan penunjang apa yang anda sarankan?","options":["CT scan","Foto polos kepala posisi waters","EEG","MRI Kepala","Foto polos cranium"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Foto polos kepala posisi waters merupakan gold standar untuk pemeriksaan sinusitis. Dengan foto ini akan dilihat Edänye perse\"ubungan atau gambaran air fluid level pada foto.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-154","number":154,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 154 · Seorang Iaki-laki berumur 55 Sengan riwayat DM…","page":81,"stem":"Seorang Iaki-laki berumur 55 Sengan riwayat DM tipe 2 datang ke poliklinik untuk kontrol. Pemeriksaan fisik didapaten tekanan darah 160/100 mmHg. Terapi hipertensi yang tepat pada pasien tersebvt","options":["Captopril","Amlodipine","Hidrokiorotiazid","Bisoprolol","Bisoprolal+ hidroklorotiazid"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pilihan terapi hipertenfil clcnq.'lti an dlrekomendaslkan Indikasi ACE Antag ARB CCB inhibitor aldost Gagal jantung Post-infark miokard Diabetes Mellitus Gagal Ginjal Kronik Pencegahan stroke berulan€* Risiko tinggi en akit kovoner","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-155","number":155,"package":"Paket 1","topic":"Mata","title":"Soal 155 · Seorang wanita berusla 30 tohun datanq (lokter…","page":82,"stem":"Seorang wanita berusla 30 tohun datanq (lokter (lenqan keluhan mata gatal, merah dan terdapat secret seperti susu sejak 3 yanq lalu. Pada pemeriksaan slit lamp ditemukan papilla pada konjungtiva tarsal super101' (Ian Inferior, Paslen menqaku dalam keluarganya mempunyai riwayat penyakit dermatitis atoplk clan asma bronchial. Diagnosis pada pasien ini adalah...","options":["Flictenularis conjungtivitis","Atopic conjungtivitis","Acute conjungtivitis","Follicle conjunqtivitis","Vernal conjungtivitis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Adanya riwayat keluarga dengan dermatitis atoplk clan asma bronkhial maka kemungkinan konjungtivitis yang terjadi pada paslen ini aclalah konJunqtivitis alergi. Konjungtivitis alergi meliputi konjungtivitis vernal, atoplk, dan tllkten. Gejala klinis pada umumnya sama yaitu mata gatal, merah ,dan bersekret. Perbedaannya terllhat pada pemeriksaan. Pada konjungtivitis vernal terdapat 2 bentuk klinls. Pada bentuk palpebra terutama mengenai konjungtiva tarsal superior terdapat papil yang besar (cobblestone) diliputi sekret yang mukoid. Sedangkan, pada bentuk limbus terutama mengenai daerah limbus berupa penonjolan abu-abu sepertl Illin (tantras dot),","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-156","number":156,"package":"Paket 1","topic":"Campuran","title":"Soal 156 · Seorang Iaki-laki berusia 24 tahun mendadak kedua…","page":82,"stem":"Seorang Iaki-laki berusia 24 tahun mendadak kedua tungkainya lemah, Kelemahan simetris disertai kesemutan dikedua telapak kaki. Beberapa Jam kemudian kedua lengannya ikut lemah. Sembilan hari sebelumnya pasien sakit diare selama 2 hari. Saat ini BAK dan BAB normal. Pemeriksaan generalis dalam batas normal. Pemeriksaan sensoris tangan dalam batas normal. Diagnosis yang tepat pada pasien Ini adalah...","options":["Guillan barre syndrome","Poliomyelitis","Multiple sclerosis","Miastenla gravis","Amyotrophic lateral sclerosis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Guillain Barre Syndrome : a. Keadaan dimana antibodi terhadap patogen tertentu (biasanya C. jejuni) bereak%i Silang terhadap mielin system saraf perifer. b. Klinis: kelemahan otot dan penurunan refleks yang dimulai dari tungkai, menjalar ke atas. Didahului beberapa minggu sebelumnya Oleh infeksi pemapasan atau GI.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-157","number":157,"package":"Paket 1","topic":"Parasitologi","title":"Soal 157 · Seorang anak laki-laki berusia 9 tahun dibawa…","page":83,"stem":"Seorang anak laki-laki berusia 9 tahun dibawa Oleh ibunya ke IGD dengan keluhan BAB encer 6x dan kadang berdarah. Pasien sering flatus dan perut kembung. Pada pemeriksaan tinja ditemukan feses pucat dan berminyak. Pemeriksaan parasitologi ditemukan parasit dengan kista inti 4, prabasal, axystole. Diagnosis yang tepat pada kasus tersebut","options":["Amoebiasis","Giardiasis","Shigelosis","Clonorchiasis","Schistosomiasis"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala dan tanda Giardiasis : a. Asimtomatik : tidak ada kelainan pada mukosa b. Simtomatikditemukan atrofi vili, hyperplasia kripta, kerusakansel epitel, infiltrasi PMN. Pada klinis didapatkan Diare, flatulence, steatorrhea, kram perut, mual, penurunan berat badan, anak dapat menjadi gagal tumbuh, Urtikaria, kolesistitis, pankreatitis, dispepsia. Morfologi : • Stadium trofozoit seperti buah jambu monyet yang bagian anterior memburat dan posteriornya meruncing. Permukaan dorsal cembung dan ventral pipih. Memiliki 4 pasang flagel yang berasal dari 4 blefaroplas. • Kista dinding tipis dan kuat. Sitoplasma berbutir dan terpisah dari dinding. Kista baru berinti 2, sedangkan dewasa berinti 4.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-158","number":158,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 158 · Seorang wanita berusia 40 tahun mengalami pembesaran…","page":83,"stem":"Seorang wanita berusia 40 tahun mengalami pembesaran uterus simetris tanpa disertai nodul atau massa. Pasien juga mengalami nyeri pelvis dan menorrhagia. Pemeriksaan vital sign tekanan darah 130/80 mmHg, nadi 86 x/menit, frekuensi nafas 20 x/menit dan suhu 36,8 oc. Tes kehamilan (+). Diagnosis yang paling tepat adalah...","options":["Endometritis kronis","Adenomiosis","Leimyoma","Hiperplasia endometrium","Endometriosis"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala yang dialami pasien berupa pembesaran uterus nodul/massa menorrhagia dan nyeri pelvis, serta tes kehamilan (+) mengarah ke hiperplasia endometrium. Dibagi menjadi 2 golongan : • Simple hyperplasia • Complex hyperplasia (memiliki 2 sub golongan: typical dan atypical hyperplasia ) Atypical hyperplasia merupakan potensi keganasan paling tinggi 20-30% tanpa pengobatan yang akan mengarah ke karsinoma endometrium","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-159","number":159,"package":"Paket 1","topic":"Anak","title":"Soal 159 · Seorang ibu membawa bayinya yang berumur 6…","page":84,"stem":"Seorang ibu membawa bayinya yang berumur 6 bulan ke Puskesmas karena bayinya belum dapat mengangkat kepaIa.Untuk mengukur apakah bayi tersebut memiliki perkembangan yang baik atau belum, alat ukur apa yang kita gunakan?","options":["Tes IQ","Tes EQ","Bailey","Denver II","Kurva pertumbuhan CDC"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Untuk mengetahui tumbuh kembang anak dapat digunakan tabel Denver ll.Melalui tabel tersebut, akan dapat diketahui perkembangan motorik kasar, bahasa, adaftif-motorik• halus, dan perkembangan personal anak.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-160","number":160,"package":"Paket 1","topic":"Kulit","title":"Soal 160 · Seorang perempuan berusia 24 tahun datang dengan…","page":84,"stem":"Seorang perempuan berusia 24 tahun datang dengan keluhan timbul bercak merah di dada, punggung, dan lengan atas disertai sedikit gatal jika berkeringat sejak 6 hari yang lalu. Bercak merah tersebut awalnya terdapat satu lesi di perut kemudian diikuti lesi Iain yang serupa namun lebih kecil. Pada pemeriksaan ditemukan lesi eritematOSa berbentuk oval dengan skuama halus kolaret tersebar dengan pola invented Christma; tree appearance. Diagnosis yang tepat pada pasien ini adalah.„","options":["Eritroderma","Ptiriasis rosea","Psoriasis vulgaris","Dermatitis atopik","Dermatitis seboroik"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Penyakit Kelainan dan Ciri Khas Eritroderma Eritema hampir seluruh tubuh, gatal (+), squama halus Ptiriasis Rosea Eritrosquamosa halus, gatal terutama jika berkeringat, predilek5i' dada, punggung, perut (pohon cemara terbalik/pakaian renang)'$ lesi awal besar diikuti lesi kecil-kecil Psoariasis Vulgaris Eritrosquamosa tebal, autspitz, tetesan Jilin, reaksi auto imun Dermatitis Atopik Riwayat atopi (+). Predileksi bayi di pipi/wajah. anak atau dewasa di flexura Dermatitis Seboroik Predileksi kulit berminyak (kepala, dahi, nasolabial), squama halus sampai tebal","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-161","number":161,"package":"Paket 1","topic":"Campuran","title":"Soal 161 · Seorang anak laki-laki berusia II tahun datang…","page":85,"stem":"Seorang anak laki-laki berusia II tahun datang ke klinik dengan keluhan BAK berwarna merah. Terdapat riwayat batuk, pilek dan demam sekitar 1 minggu yang lalu. Pada pemeriksaan fisik didapatkan Tekanan darah 130/70 mmHg dan edema. Pemeriksaan laboratorium urin makroskopik ditemukan hematuri minimal. Apakah diagnosis yang tepat pada pasien ini?","options":["Glomerulonefritis Akut Post Streptococcus","Glomerulonefritis Akut","Glomerulonefritis Kronik","Sindrom Nefrotik","Infeksi Saluran Kemih"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"GNAPS (Glomerulonefritis akut post streptococcus) merupakan salah satu sindrom nefritik yang ditandai Oleh timbulnya hematuria, edema, hipertensi dan penurunan fungsi ginjal. GNAPS didahului Oleh infeksi SBGA nefritogenik (tipe 4, 12, 16, 25, dan 49) di saluran napas atas. Reaksi Ag-Ab terjadi setelah infeksi saluran napas atas telah usai. Seorang bayi perempuan berusia IO tahun dibawa orang tuanya ke RS dengan keluhan keluar tinja dari vagina. Dari penjelasan orang tuanya didapatkan bayi lahir di bidan, cukup bulan dan langsung menangis. Pemeriksaan fisik didapatkan keadaan umum baik,","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-162","number":162,"package":"Paket 1","topic":"Bedah","title":"Soal 162 · Seorang perempuan berusia 35 tahun datang ke…","page":85,"stem":"Seorang perempuan berusia 35 tahun datang ke IGD dengan keluhan demam dan menggigil setelah kecelakaan dan mengalami patah tulang terbuka sekitar 3 hari yang lalu. Setelah kecelakaan pasien dijahit di Puskesmas dengan luka jahitan 25 cm. Pemeriksaan fsik didapatkan tekanan darah 80/palpasi, frekuensi nadi 120 x/menit dan tepat pada pasien di atas adalah...","options":["Tetanus","Osteomielitis","Sepsis","Artritis",". Mielitis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Sepsisserngtejdpdasietaumaaapatahtulangteruaseharusnadla debridement danmenutup otot kemudian membiarkannya terbuka karena bila ditutup akan menyebabkan infeksi. Rekonstruksi dapat dilakukan setelah luka tenang.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-163","number":163,"package":"Paket 1","topic":"Bedah","title":"Soal 163 · Seorang perempuan berusia 35 tahun datang ke…","page":85,"stem":"Seorang perempuan berusia 35 tahun datang ke IGD dengan keluhan demam dan menggigil setelah kecelakaan dan mengalami patah tulang terbuka sekitar 3 hari yang Lalu. Setelah kecelakaan pasien dijahit di Puskesmas dengan Iuka jahitan 25 cm. Pemenksaan fisik didapatkan tekanan darah 80/palpasi, frekuensi nadi 120 x/menit dan suhu 39,2 Hasil pemetiksaan laboratorium didapatkan Hb g/dl. Diagnosis yang tepat pada pasien di aes","options":["Tetanus","Osteomielitis","Sepsis","Artritis","Mielitis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-164","number":164,"package":"Paket 1","topic":"Anak","title":"Soal 164 · Seorang perempuan setusia 35 tahun PSA. datang…","page":86,"stem":"Seorang perempuan setusia 35 tahun PSA. datang dengan rujukan bidan dengan perdarahan per-vaginam setetah melahirkan 2 jam yang lalu. Berat janin 4200 gram. Plasenta Jahir lengkap 5 menit setelah bayi lahir. Dari pemeriksaan fisik didapatkan tekanan darah 120tSO mmHg, nadi 100x/menit. Pada jalan lahir tampak robekan hingga otot perineum. Serape derajat ruptur perineum pada pasien ini?","options":["Ruptur perineum derajat","Ruptur perineum derajat 2","Ruptur perineum derajät SA","Ruptur perineum derajat 3B","Ruptur perineum derajat4"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Derajat I: robekan pada mukosa & kulit vagina saja Derajat II: derajat I + robekan kulit perineum hingga otot dan fasia perineum (belum mengenai sfngter ani) Derajat Ill: derajEt II + robekan seluruh perineum sampai m. sfingter ani : Illa: robekan < ketebalan m. sfingter ani 111b: robekan > ketebalan m. sfingter ani IIIc hingga m. sfingter interna Derajat 4: sudah melibetkan mukosa rektum dan epitel anus (sudah bolong)","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-165","number":165,"package":"Paket 1","topic":"Neurologi","title":"Soal 165 · Seorang Jaki-Jaki berusia 50 tahun datang dengan…","page":86,"stem":"Seorang Jaki-Jaki berusia 50 tahun datang dengan keluhan suara parau sejak 7 hari yang lalu. Keluhan disertai dengansulit menelan dan berbicara. Tidak ada demam, selain itu juga terdapat kelemahan anggota gerak pada tungkai dan lengan yang semakin memberat• Pada pemeriksaan fisik didapatkan tetraparesis, ptosis, refleks fisiologis meningkat dan refleks patologis normal. Diagnosis yang tepat pada pasien ini adalah...","options":["Sindrom guillain barre","Miastenia gravis","Stroke iskemik","Tumor","Duchenne muscular dystrophy"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Miastenia Gravis merupakan penyakit autolmun dimana terbentuk antibodi terhadap reseptor asetllkolln nlkotlnik pascaslnaptlk di neuromuscularjunction otot rangka. GeJaIa dan tanda Kelemahan Otot dari waJah (terutama ptosis) yang kemudian menjalar ke ekstremitas Di pagi hari, kelemahan tidak terlalu berate Seiring berjalannya hari, kelemahan bertambah parah Kelemahan dlperberat Oleh aktlvitas dan membaik dengan istirahat • Kelemahan bertambah berat seiring berjalannya waktu","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-166","number":166,"package":"Paket 1","topic":"Campuran","title":"Soal 166 · Seorang laki-laki berusia 50 tahun datang dengan…","page":87,"stem":"Seorang laki-laki berusia 50 tahun datang dengan keluhan nyeri ulu hati, mual dan muntah selama 4 hari. Pasien memiliki kebiasaan merokok. dokter menyarankan mengontrol pola makan dan berhenti merokok. Upaya dokter memberikan saran termasuk dalam?","options":["Health promotion","Spesific protection","Early diagnose","Disability limitation","Rehabilitation"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pelayanan kesehatan berdasarkan tingkat pencegahan penyakit menurut leavell dan Clark sesuai dengan pemanfaatannya yaitu promosi kesehatan dilakukan tindakan umum untuk menjaga keseimbangan proses bibit peyakit-host-environment sehingga menguntungkan manusia dengan cara meningkatkan daya tahan manusia dan memperbaiki lingkungan. Contoh penyuluhan cara hidup sehat, olah raga, peningkatan gizi, kebiasaan hidup, perbaikan sanitasi, higienis dan sebagainya.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-167","number":167,"package":"Paket 1","topic":"Neurologi","title":"Soal 167 · Seorang anak perempuan berusia 3 tahun kejang…","page":87,"stem":"Seorang anak perempuan berusia 3 tahun kejang seluruh tubuh 1 jam sebelum masuk rumah sakit. Mata mendelik ke atas, tidak sadar selama kejang, durasi kejang I menit. Setelah kejang tidak sadar. Kejang berulang 5 menit. Pasien tetap tidak sadar. Sudah diberi suntikan diazepam 2x. Terapi lanjutan apa yang kita berikan pada pasien di atas?","options":["Asam valproat","Propofol","Fenitoin","Fenobarbital","Midazolam"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Bagan Penatalaksanaan Kejang DIAZEPAM(iv) KEJANG - MG (maks 20mg) atau DIAZEPAM(rektal) 5 mg (BB<I Okg) 1 omg (BB>10kg) 0.5 menit REJANG (-) KEJANG (+) (A) Diulang interval 3 menit 5- IO menit KEJANG (+) KEJANG (-) Fenitoin bolus IV 15-20 mg/kgBB Fenitoin: 1 2 jam kemudian Kecepatan: 25mg/menit 5 - 7 mg/kgbb REJANG (+) IO- 15 menit Fenobarbital IV / 1M KEJANG (-) IO- 20 mg/kgbb Fenobarbital 12 jam kemudian 3-4 mg/kgbb KEJANG(I) ICU Midazolam: 0,2 mg/kgbb Fenobarbital: 5 - IO mg/kgbb","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-168","number":168,"package":"Paket 1","topic":"Campuran","title":"Soal 168 · Seorang Iaki-laki berusia 26 tahun datang ke…","page":88,"stem":"Seorang Iaki-laki berusia 26 tahun datang ke IGD rumah sakit karena tersiram cairan kimia. Pada pemeriksaan fisik tampak vesikel setelah terkena cairan kimia. Vesikel bula dengan dasar eritema. Pemeriksaan tanda vital didapatkan tekanan darah 130/70 mmHg' nadi 80 x/menit, frekuensi nafas 18 x/menit dan suhu 37,1 oc. Diagnosis pada pasien ini adalah„.","options":["Dermatitis statis","Dermatitis numularis","Dermatitis alergi","DKI","DKA"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dermatitis kontak iritan akut biasanya karena kecelakaan.KuIit terasa pedih atau panas dengan eritema, vesikel, atau bula.Luas kelainan, umumnya sebatas daerah yang terkena, berbatas tegas.Pada umumnya kelainan kulit muncul segera, tetapi ada sejumlah bahan kimia yang menimbulkan reaksi akut lambat, misalnya pedofilin, antralin, dan asam fluorohidrogenat. Kelainan kulit baru terlihat 12-24 jam atau lebih. Pengobatannya adalah dengan menyingkirkan pajanan bahan iritan. Apabila diperlukan, dapat diberikan kortikosteroid topikal.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-169","number":169,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 169 · Seorang perempuan GIPoA0 berusia 20 tahun usia…","page":89,"stem":"Seorang perempuan GIPoA0 berusia 20 tahun usia kehamilan IO minggu dibawa ke rumah sakit karena mengalami perdarahan dari jalan lahir setelah jatuh dari kamar mandi I jam yang lalu. Pemeriksaan fisik didapatkan pucat, tekanan darah 90/70mmHg. Pemeriksaan dalam diperoleh perdarahan profuse, pembukaan cervix I cm. Apakah tindakan yang paling tepat dilakukan?","options":["Perbaikan keadaan umum","Kuretase","Histerektomi","Drip oksitosin","Pemberian tokolitik"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Diagnosis pada kasus di atas adalah abortus insipiens. Penatalaksanaan awal yang dapat dilakukan pada pasien tersebut adalah melakukan perbaikan keadaan umum terlebih dahulu. 170. Seorang laki-laki berusia 25 tahun datang dengan penurunan kesadaran setelah mengalami kecelakaan lalu lintas. Dari hasil pemeriksaan pasien membuka mata dengan rangsang nyeri, ekstremitas ekstensi abnormal dengan rangsang nyeri, dan pasien mengeluarkan suara melengking yang tidak dapat dihentikan. Berapakah score GCS pada pasien ini? Jawaban : B Pembahasan: GLASGOW COMA SCALE 4 Respon Mata (E) Spontan 3 Pada perintah ( verbal ) 2 Rangsang nyeri 1 Tanpa respon 6 Menurut perintah Respon Motorik (M) 5 Melokalisir nyeri 4 Menjauhi nyeri Flexi abnormal / Dekortikasi 3 Ekstensi abnormal / Deserebrasi 2 Tanpa respon Orientasi baik 5 Respon Bicara (V) Bingung (bicara kacau) 4 Berupa kata-kata 3 Berupa suku kata 2 Tanpa respon 1","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-170","number":170,"package":"Paket 1","topic":"Neurologi","title":"Soal 170 · Seorang laki-laki berusia 25 tahun datang dengan…","page":89,"stem":"Seorang laki-laki berusia 25 tahun datang dengan penurunan kesadaran setelah mengalamikecelakaanlalu lintas.Darihasil pemeriksaan pasie membuka mata dengan rangsang nyeri, ekstremitas ekstensi abnormal dengan rangsang nyeri, dan pasien mengeluarkan suara melengking yang tidak dapat dihentikan. Berapakah score GCS padapasienini?","options":["5","6","7","8","9"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"GLASGOWCOMASCALE 4 Respon Mata (E) Spontan 3 Pada perintah ( verbal) 2 Rangsang nyeri 1 Tanpa respon 6 Respon Motorik(M) Menurut perintah 5 Melokalisir nyeri 4 Menjauhi nyeri Flexi abnormal/Dekortikasi 3 Ekstensiabnormal/Deserebrasi 2 1 Tanpa respon Orientasi baik 5 Respon Bicara (V) Bingung (bicara kacau) 4 Berupa kata-kata 3 Berupa suku kata 2 Tanpa respon 1","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-171","number":171,"package":"Paket 1","topic":"Neurologi","title":"Soal 171 · Seorang anak perempuan berusia 5 tahun mengalami…","page":90,"stem":"Seorang anak perempuan berusia 5 tahun mengalami demam selama 2 minggu, nafsu makan menurun, tidak sesak dan tidak batuk. Pasien diasuh Oleh neneknya yang sedang batuk lama. Pada pemeriksaan fisik kesadaran Compos Mentis, tanda vital frekuensi nadi 100x/menit, nafas 28x/menit, suhu 37 oc dan ikterik (-). Pemeriksaan laboratorium didapatkan eritrosit menurun, proteinuria (-), leukosit 0-2 LP, hemoglobin 8 g/dl dan widal O/H 1/80. Mantoux indurasi, jantung dan paru dalam batas normal dan leher terdapat benjolan ukuran IxI,5 cm. Penyebab demam yang paling mungkin adalah...","options":["Limphadenitis TB","Limphangitis","Demam tifoid","Malaria","Demam dengue"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Perlu mencurigai nenek pasien menderita TB paru karena memiliki keluhan batuk lma Adanya indurasi mantoux memungkinkan anak terkena TB, dan didukung dengan pembengkakan pada kelenjar getah bening di leher.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-172","number":172,"package":"Paket 1","topic":"Mata","title":"Soal 172 · Seorang Iaki-laki berusia 37 tahun datang keRS…","page":90,"stem":"Seorang Iaki-laki berusia 37 tahun datang keRS dengan keluhan demam sejak4hariyang lalu yang disertai mual dan muntah. Pasien mengaku beberapa tahun yang lalu mengkonsumsi alkohol dan narkoba. Pemeriksaan fisik tampak konjungtiva ikteriL Pemeriksaan laboraturium didapatkan SGOT: 1 IO U/L, SGPT: 3450 U/L, Bilirubin mg/dL. Gambaran serologis yang terjadi pada pasien tersebut adalah„.","options":["HBsAg anti HBsAg+, IgM+","HBsAg +, anti HBsAg-, IgG+","HBsAg +, anti HbsAg-, IgM+","HBsAg -, anti HBsAg-, IgG+","HBsAg anti HbsAg+, IgG+"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Serologi dan virologi hepatitis Tanda Intepretasi Hepatitis A IgM HAV Infeksi akut IgG HAV Infeksi dimasa lalu Hepatitis B HBsAg Infeksi aktif/sedang berlangsung. Muncul sebelum gejala muncul HbeAg Bukti replikasi virus dan infektivitas IgM anti HBc Infeksi akut Window period HbsAg (-), anti HBS belum (+) Anti HBS Resolusi penyakit aktif Petanda imunitas (petanda tunggal pasca imunisasi) IgG anti HbC Infeksi HBV lampau HbsAg (-), kronis HbsAg (+) IgG anti Hbe Replikasi virus <<, infektivitas << HBV DNA Replikasi aktif virus di hepar Hepatitis C Anti HCV atau HCV RNA Sedang menderita hepatitis C","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-173","number":173,"package":"Paket 1","topic":"Kulit","title":"Soal 173 · Seorang anak perempuan berusia 8tahun dibawa ke…","page":91,"stem":"Seorang anak perempuan berusia 8tahun dibawa ke dokteroleh ibunya karena mengalami gatal-gatal di lubang dubur pada malam hari. Tidak ada demam. Vital sign dalam batas normal. Pada pemeriksaan apus anal ditemukan telur. Penyebab dari keluhan pasien di atas adalah... a.Oxyuris vermicularis d.Ancylostoma duodenale b. Trichuris trichiura e.Ascaris lumbricoides Trichuris strongyloides Jawaban:A Pembahasan: Manifestasi klinis dari oxyuriasis adalah adanya pruritus ani yang berat pada malam hari, anoreksia, badan menjadi kurus, tidur tidak nyenyak, dan anak jadi iritabel. Pada anak wanita dapat terjadi pruritus vulva dan vaginitis.","options":["Mempercepatkelahiran","Mempercepat pematangan paru darah","Mempercepat denyutjantung","Mencegah infeksi","Mencegah hkeluranyalendi"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Manifestasi klinis dari oxyuriasis adalah adanya pruritus ani yang berat pada malam hari, anoreksia, badan menjadi kurus, tidur tidak nyenyak, dan anak jadi irritabel. Pada anak Wanita dapat terjadi pruritus vulva dan vaginitis.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-174","number":174,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 174 · Seorang perempuan berusia 25 tahun G,PoAo dengan…","page":92,"stem":"Seorang perempuan berusia 25 tahun G,PoAo dengan usia kehamilan 34 minggu data dengan keluhan sudah mules-mules disertai keluarnya lendir dan darah. Kemudian ditangani Oleh dokter dan diberi prednisone. Apakah tujuan dari pemberian obat ini?","options":["Mempercepat kelahiran","Mempercepat pematangan paru darah","Mempercepat denyutjantung","Mencegah infeksi","Mencegah keluranya"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kortikosteroid berfungsi untuk pematangan paru janin. Glukokortikoid (prednison, betametason, deksametason) akan merangsang produksi surfaktan parujanin karena bayi prematur produksi surfaktan masih sedikit. Selain itu steroid juga menurunkan komplikasi perdarahan intraventricular, necrotising enterokolitis (diare pada bayi prematur) & ductus arteriosus (PDA).","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-175","number":175,"package":"Paket 1","topic":"Campuran","title":"Soal 175 · Seorang wanita berusia 25 tahun datang dengan…","page":92,"stem":"Seorang wanita berusia 25 tahun datang dengan keluhan nyeri kepala sebelah kanam Keluhan sudah berkali-kali, didahului dengan mual, muntah dan mata berkunang. kunang. Diagnosis pasien tersebut adalah„.","options":["Cluster headache","Tension type headache","Migraine headache","Secondary headache","Inflammatory headache"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tension type headache Migraine headache Cluster headache Kualitas Ditekan/diikat Berdenyut Menusuk Lokasi bilateral unilateral unilateral Mual Ada/tidak + Muntah + Fotofobia Ada/tidak + Gejala penyerta Lakrimasi, injeksi konjungtiva, rinorea, dan perspirasi wajah yang ipsilateral Aura","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-176","number":176,"package":"Paket 1","topic":"THT","title":"Soal 176 · Seorang pasien perempuan berusia 16 tahun, datang…","page":92,"stem":"Seorang pasien perempuan berusia 16 tahun, datang berobat dengan keluhan bersiry bersin, terutama pada pagi hari dan saat membereskan tumpukkan buku-buku lama Bersin disertai hidung tersumbat dan berair, gatal, pada mata dan hidung. Riwayat penggunaan obat pada hidung dan mata disangkal. Ayah pasien memiliki riwayat asma• Diagnosis yang tepat pada pasien ini adalah„.","options":["Rinitis vasomotor","Rinitis medikamentosa","Rinitis alergi","Rinitis akut","Rinitis atrofi"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Rinitis atrofi (Ozaena) Rinitis vasomotor Rinitis alergika Pengertlan Infeksi hidung kronik dengan Gangguan fisiologis tapisan Reaksi hipersensitivitas tipe atrofi progresif tulang dan mukosa karena peningkatan I di mukosa hidung mukosa konka saraf parasimpatis KentaL hijau.krusta hijau Sekret Bersin-bersin Encer dan banyak Gatal di mata Pasien mencium bau + dan Iakrimasi busuk Faktor risiko Ekonomti rendah.lingkungan Suhu ekstnmudara buruk lembab.asap rokok Faktor herediter, alergen, sering disertai asma, Rongga hidung Sangat lapang konka media Edem mukosa. konka merah urtikaria,atau eksim dan infenor hipotrofi atau dapat pula pucat Mukosa edem, pucat atau Irvid,sekret sangat encer, Allergic crease Komplikasi Sinusitis Poligotitis media, sinusitis","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-177","number":177,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 177 · Seorang wanita berusia 17 tahun datang dengan…","page":93,"stem":"Seorang wanita berusia 17 tahun datang dengan keluhan menstruasi tidak teratur sejak menstruasi pertama setahun yang lalu. Riwayat haid kadang banyak kadang sedikit, bahkan sampai dua minggu. Pemeriksaan VT didapatkan vulva vagina dalam batas normal dan fluksus (+). Tindakan yang tepat untuk menegakkan diagnosis adalah.„","options":["Tes kehamilan","Biopsi endometrial","USG pelvic","Kontrasepsi oral","Screening homeostatis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien pada kasus di atas datang dengan keluhan haid tidak teratur, pada pemeriksaan VT didapatkan vulva vagina tidak ada kelainan dan terdapat fluksus (+). Hal yang perlu dilakukan setelah menanyakan riwayat haid sebelumnya secara lengkap adalah melakukan tes kehamilan untuk menyingkirkan diagnosis hamil.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-178","number":178,"package":"Paket 1","topic":"Campuran","title":"Soal 178 · Seorang Iaki-laki berusia 30 tahun datang dengan…","page":94,"stem":"Seorang Iaki-laki berusia 30 tahun datang dengan keluhan rambut rontok sejak satu minggu yang lalu. Pada pemeriksaan lokalis ditemukan area tidak berambut, denga n batas tegas, berbentuk vocal atau bulat kecil-kecil. Diagnosis yang tepat pada kasus adalah...","options":["Alopesia totalis","Alopesia universalis","Alopesia areata","Alopesia androgenik","Traction alopecia"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Alopesia totalis: mengenai seluruh rambut kepala Alopesia universalis: mengenai seluruh rambut pada tubuh Alopesia areata: kebotakan setempat-setempat berbatas tegas. Alopesia androgenik: kebotakan yang muncul mulai dari verteks lalu secara bertahap memanjang ke belakang. Traction alopesia : suatu kondisi dimana rambut rontok yang terlokalisasi pada daerah yang kecil terjadi karena pencabutan akar rambut yang terus menerus.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-179","number":179,"package":"Paket 1","topic":"Anak","title":"Soal 179 · Seorang bayi perempuan berusia 1,5 tahun dibawa…","page":94,"stem":"Seorang bayi perempuan berusia 1,5 tahun dibawa ke rumah sakit dengan keluhan lebam-lebam pada tubuh. Pada pemeriksaan fisik didapatkan bengkak pada lutut dan lebam lengan bawah. Dari hasil pemeriksaan laboratorium darah ditemukan hemoglobin, leukosit dan trombosit normal. Hasil yang Iain didapatkan clotting time memanjang, bleeding time normal, APTT memanjang dan PT normal. Diagnosis pada pasien ini adalah...","options":["Tromboastenia","Von willebrand disease","Disfibrinogenemia","Syndrom Bernard Sollier","Hemofilia"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Manifestasi klinis yang terdapat pada pasien mengarah ke hemofilia yaitu bengkak pada lutut dan lebam lengan bawah. Dari hasil pemeriksaan laboratorium darah ditemukan hemoglobin, leukosit, dan trombosit normal, clotting time memanjang, bleeding time normal, aPTT memanjang, dan PT normal.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-180","number":180,"package":"Paket 1","topic":"Kulit","title":"Soal 180 · Seorang wanita usia 27 tahun mengalami Iuka…","page":95,"stem":"Seorang wanita usia 27 tahun mengalami Iuka bakar. Pada pemeriksaan fisik didapatkan kulit melepuh dan kemerahan, dijumpai pada seluruh lengan kanan, seluruh wajah dan seluruh dada. Berat badan pasien adalah 70 kg. bagaimana pemberian cairan pada pasien ini?","options":["2.520 ml pada 8 jam pertma, 2.520 ml pada 16jam berikutnya","3.150 ml pada4jam pertama, 3.150 ml pada 8jam berikutnya","3.150 ml pada 8jam pertama, 3.150 ml pada 16jam berikutnya","3.780 ml pada 4jam pertama, 3.780 ml pada 8jam berikutnya","3.780 ml pada 8jam pertama, 3.780 ml pada 16jam berikutnya"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Formula Baxter/Parkland 4 x persentase Iuka bakar derajat x BB(kg) 50% diberi dalam jam pertama, 5096 dalam 16 jam berikutnya 4 x 22,5 x 70 = 6300 ml 3.150 mL dalam 8 jam pertama 3.150 mL dalam 16 jam berikutnya","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-181","number":181,"package":"Paket 1","topic":"Kesehatan Masyarakat","title":"Soal 181 · Seorang laki-laki berusia 40tahun datang ke puskesmas…","page":95,"stem":"Seorang laki-laki berusia 40tahun datang ke puskesmas dengan keluhan batuk yang tidak kunjung sembuh sejak 2 bulan yang lalu. Batuk berdahak, kental berwarna putih, pasien mengeluh nafsu makan berkurang, badan lemas, demam ringan dan berkeringat pada malam hari. Pada pemeriksaan fisik didapatkan ronki basah halus di kedua apeks paru. Pada pemeriksaan sputum BTA SPS -/-/-. Tindakan apa yang akan dilakukan selanjutnya pada pasien ini?","options":["Melakukan uji tuberculin","Melakukan pengulangan pemeriksaan BTA","Memberikan OAT kategori 1 selama 2 bulan","Memberikan ampisilin 1-2minggu","Memberikan OAT kategori 1 selama 6 bulan"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"SuspekTB Paru Pemeriksaan dahak mikroskopik-Sewaktu, pagi, Sewaktu (SPS) Hasil BTA Hasil BTA Hasil BTA Antibiotik Non OAT Tidak ada Ada perbaika perbaikan Foto toraks dan Pemeriksaan dahak pertimbangan dokter mikroskopis Hasil BTA Hasil BTA Foto toraks dan pertimbangan dokter TB Bukan TB","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-182","number":182,"package":"Paket 1","topic":"THT","title":"Soal 182 · Seorang Iaki-laki berusia 65 tahun datang dengan…","page":96,"stem":"Seorang Iaki-laki berusia 65 tahun datang dengan keluhan mulut mencong ke kiri. Keluhan disertai dengan nyeri pada telinga. Nyeri bertambah saat daun telinga digerakkan dan keluar cairan kental kuning dari telinga. Pasien memiliki riwayat DM sejak 5 tahun yang lalu. Pada pemeriksaan vital sign didapatkan tekanan darah 120/80 mmHg, nadi 80 x/menit, frekuensi nafas 20 x/menit dan suhu 38 oc. Pemeriksaan telinga didapatkan pinna lunak, kanal auditory eksterna radang dan edema, leukosit dalam batas normal. Organisme penyebabnya adalah...","options":["Staphylococcus aureus","Moxarella cattarallis","Pseudomonas aeroginosa","Candida albicans","Haemophylus influenza"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Diagnosis pasien pada kasus ini adalah otitis eksterna maligna yaitu suatu tipe khustJS dari infeksi akut yang difus di telinga luar. Gejala diantaranya terdapat rasa gatal di liang telinga diikuti dengan nyeri, sekret yang banyak, pembengkakan liang telinga dan jaringan granulasi menutupi liang telinga. Saraf facial dapat terkena sehingga menimbulkan paresis. Kelainan patologik Iain adalah osteomielitis yang disebabkan infeksi Pseudomonsa aeroginosa.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-183","number":183,"package":"Paket 1","topic":"Neurologi","title":"Soal 183 · seorang laki-laki berusia 30 tahun mengeluh bruntus-bruntus…","page":97,"stem":"seorang laki-laki berusia 30 tahun mengeluh bruntus-bruntus di atas dada kiri, nyeri, dan sebelumnya terkena varicella. Pemeriksaan fisik vesikel dan pustul bergerombol unilateral. Komplikasi apa yang dapat terjadi pada kasus di atas?","options":["Neuralgia pascaherpetik","Hemiparesis","Glomerulonefritis","Osteomyelitis","Pneumonia"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Varisela adalah infeksi akut primer virus varisela zooster. Reaktivasi virus setelah penderita mendapat varisela disebut herpes zooster. Daerah yang paling sering terkena adalah daerah torakal, walaupun daerah-daerah lain tidakjarang. Gejala prodromal lokal antara lain, nyeri otot-tulang, gatal, pegal, dan sebagainya. Setelah itu, timbul eritema yang dalam waktu singkat mejadi vesikel yang berkelompok dengan dasar kulit yang eritematosa dan edema. Lokalisasi penyakit ini adalah unilateral dan bersifat dermatomal sesuai dengan tempat persarafan. Komplikasi yang dapat timbul adalah neuralgia pascaherpetik.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-184","number":184,"package":"Paket 1","topic":"Campuran","title":"Soal 184 · Pada sebuah klinik, seorang dokter memiliki kebiasaan…","page":97,"stem":"Pada sebuah klinik, seorang dokter memiliki kebiasaan memeriksa pasien dalam jumlah banyak di waktu yang bersamaan karena pasien antri panjang. Kaidah dasar moral yang dilanggar Oleh dokter tersebut adalah...","options":["Beneficence","Non maleficence","Autonomy","Justice","Prima facie"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Prinsip autonomy adalah menghargai pilihan pasien dan menghargai privasi pasien","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-185","number":185,"package":"Paket 1","topic":"Neurologi","title":"Soal 185 · Seorang laki-laki berusia 45 tahun datang dengan…","page":97,"stem":"Seorang laki-laki berusia 45 tahun datang dengan penurunan kesadaran dan tidak bernafas. Sebelumnya pasien mengeluh nyeri dada. Dari pemeriksaan EKG didapatkan : Tindakan yang dilakukan pada pasien tersebut adalah...","options":["Melakukan shock dengan kekuatan 200 joule bifasik","Melakukan shock dengan kekuatan 360 joule bifasik","Memasang IV line dan memberikan epinephrine IV","Melakukan intubasi dan memberikan epinephrine melalui ETT","Melakukan CPR"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"transkripsi","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pembahasan buku menyebut gambaran VT, dengan shock 200 J bifasik atau 360 J monofasik. Ini transkripsi pembahasan lama, belum diverifikasi ulang; tidak dijadikan kunci otomatis.","answerPage":null,"transcriptionIssues":["Sumber memuat gambar EKG yang tidak disertakan. Pembahasan buku menyebut gambaran VT; kunci huruf tidak tercetak jelas. Soal ini belum dapat digunakan sebagai latihan interpretasi EKG lengkap."],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-186","number":186,"package":"Paket 1","topic":"Anak","title":"Soal 186 · Seorang ibu berusia 26 tahun melahirkan bayi…","page":99,"stem":"Seorang ibu berusia 26 tahun melahirkan bayi kurang bulan. Bayi mengalami asfiksia berat 6 jam kemudian. Pada pemeriksaan terlihat retraksi suprasternal dan intercostalis. pemeriksaan foto dada menunjukkan gambaran granular, reticular dan air bronkogram. Kondisi apa yang sedang dialami Oleh bayi tersebut?","options":["Pneumothoraks","Sudden infant death syndrome","Displasia bronkus","Pneumonia","Hyalin membrane disease"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Penyakit membran hialin terjadi pada bayi dengan berat 1000-2000 gram atau masa gestasi < 36 minggu.Jarang terjadi pada bayi lebih dari 2500 gram. Tanda-tanda gangguan napas (asfiksia) biasanya muncul 6-8 jam pertama setelah Jahir dan gejala karakteristik tampak pada umur 24-72 jam. Terdapat dispnu, hiperpnu, sianosis, retraksi suprasternal, interkostal, epigastrium, dan respirasi grunting serta bunyi napas melemah. Kemudian, pada pemeriksaan radiologi, terbagi atas: Grade I Gambaran bintik retikulograbular. Grade II : Gambaran bintik retikulograbular disertai air bronkogram. Grade III : Gambaran grade II disertai hilangnya batas jantung. Grade IV : Gambaran white lung.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-187","number":187,"package":"Paket 1","topic":"Campuran","title":"Soal 187 · Seorang laki-laki berusia 56 tahun datang dengan…","page":99,"stem":"Seorang laki-laki berusia 56 tahun datang dengan keluhan demam sejak 5 hari yang lalu. Selain itu pasien juga mengeluh batuk berdahak kental kuning dan sesak nafas. Pada pemeriksaan fisik didapatkan tekanan darah 120/80 mmHg, nadi 88x/menit, pernafasan 30x/menit dan suhu 39,1 oc. Pemeriksaan paru didapatkan ronki basah kasar di kedua basal paru. Pada pemeriksaan penunjang didapatkan leukosit 13000/mm3. Pemeriksaan penunjang apakah yang dapat menegakkan diagnosis pada pasien ini?","options":["CT scan thoraks","BTA","Kultur darah","Kultur sputum","Foto thoraks PA"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Diagnosis pada pasien ini adalah pneumonia. Pemeriksaan penunjang untukmendiagnosis pasien ini adalah foto thorax PA/AP yang digunakan untuk mencari adanya gambaran infiltrat atau perselubungan.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-188","number":188,"package":"Paket 1","topic":"Campuran","title":"Soal 188 · Seorang perempuan berusia 25 tahun datang ke…","page":99,"stem":"Seorang perempuan berusia 25 tahun datang ke poliklinik dengan keluhan selalu merasa cemas. Dia memiliki seorang adik dan merasa terganggu kemudian dia melukai adiknya. Kemudian pasien merasa bersalah setelah melakukan hal tersebut. Dia merasa tidak baik memiliki perasaan seperti itu, namun perasaan tersebut sering muncul di pikirannya t;arnpai tidak bisa tidur, pusing, gernetaran dan sulit konsentrasi. Terapi yang diberikan adalah...","options":["Clorprornazine","Haloperidol","Diazeparn","Estazolam","SSRI"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"anti anxietas yaitu: a. Benzodiazepin diazepam, chlordiazepoxide, lorazepam, clobbazam, bromazepan. oxazolam, alprazolam,dan prazepam. b, Non benzodiazepine :sulpiride, buspirone, dan hidroxyzine","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-189","number":189,"package":"Paket 1","topic":"Campuran","title":"Soal 189 · Seorang wanita berusia 18 tahun datang dengan…","page":100,"stem":"Seorang wanita berusia 18 tahun datang dengan keluhan belum pernah haid. meminum obat untuk merangsang haidnya namun tidak berhasiL Pertumbuhan ketiak dan pubis sesuai dengan usianya. Diagnosis yang tepat pada pasien terse± adalah...","options":["Amenore primer","Amenore sekunder","Pubertas prekoks","Oligomenore","Menometroragi"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Amenore primer Belum pernah terjadi menstruasi sebelumnya, padahal sudah usia pubertas (pada pasie tanda-tanda pubertas lainnya sudah muncul). Amenore sekunder Sudah pernah menstruasi, akan tetapi sudah > 3 bulan berturut-turut tidak tergi menstruasi.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-190","number":190,"package":"Paket 1","topic":"Penyakit Dalam","title":"Soal 190 · Seorang Iaki-laki berusia 17 tahun datang ke…","page":100,"stem":"Seorang Iaki-laki berusia 17 tahun datang ke poliklinik dengan keluhan kencing sejak 1 minggu yang lalu. Keluhan ini disertai bengkak pada kelopak mata. Dua kemudian timbul pula bengkak pada tungkai dan perut. Pada vital sign didapatk2' tekanan darah 110/70 mmHg, nadi 84 x/menit, pernafasan 18 x/menit dan suhu Dari pemeriksaan laboratorium ditemukan protein urine 4+ dan eritrosit. Diagnosis FN tepat pada pasien ini adalahm","options":["Sindrom nefrotik","Sindrom Nefritis Akut","Gagal jantung","Sirosis Hepatis","Gaga! Ginjal Kronik"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Sindrorn nefrotik ditandai Oleh proteinuria fjij)0öIbuminemja, edema, dan hiperlipidcmia. Manifestæ,i kJinir, ditandai ditandaj dengan influenza, bengkak periorbital, dan oliguria, hari, edema sernakin jelas dan menJadi anasarka. Keluhan jarang scJain ringan dan nyeri perut, Selain proteinuria masif, sedimen urine biae„ant/kj normal, P,ilö terJ;jdi hematuria mikro%kopik eritrosit/LPB) dicurigai adanya leroi glomerular, Alburnin plasma rendah dan lipid meningkat. IgM dapat meningkat, sedangk;jn IgG turun.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-191","number":191,"package":"Paket 1","topic":"Parasitologi","title":"Soal 191 · Seorang wanita berusia 25 tahun datang degrjgan…","page":101,"stem":"Seorang wanita berusia 25 tahun datang degrjgan keluhan diare, tinja Jernbek tetapi tidak disertai darah. Pasion Juga mengeluh nyeri ruerut muntah, seluruh badan gatal, clan penurunan nafsu makarj, Pada pemerikl,aan fj%ik kesadaran compos mentis, tekanan darah 100/70 mmHg, tyl ggz/rnenit, 20//rnenit, suhu 37 diternukan pembesaran hepar. Pada pemeriksaan feeoeo diternukan telur cacing dengan duri di bagian lateralnya. Parasit yang menyebabkan keluhan pada pavoien ini adalah„.","options":["Strongyloides","Taenia","Ascaris","Schistosoma","Necator"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gambaran telur cacing dengan duri di bagian lateralnya adalah Schistosoma","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-192","number":192,"package":"Paket 1","topic":"Mata","title":"Soal 192 · Seorang perempuan berusia 30 tahun datang dengan…","page":101,"stem":"Seorang perempuan berusia 30 tahun datang dengan keluhan penurunan penglihatan sejak 3 hari yang lalu disertai nyeri, mata merah dan berair. Pada pemeriksaan fisik didapatkan tekanan darah 120/80 mmHg, nadi 84 x/menit, pernapasan 20 x/menit dan suhu 36,6 oc. Dokter mendiagnosis pasien tersebut sebagai pasien TB. Pemeriksaan mata didapatkan injeksi silier, flare bilik mata depan (+) dan keratic presipitat (+). Diagnosis yang tepat pada pasien ini adalah...","options":["Pars planitis","Endophtalmitis","Uveitis","Uveitis akut","Choroiditis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Manifestasi klinis pada uveitis diantaranya mata merah, nyeri, fotofobia, penurunan penglihatan dan Iakrimasi pada keadaan akut. Pemeriksaan mata didapatkan injeksi silier, flare bilik mata depan (+) dan keratik presipitat Terapi yang harus dilakukan segera untuk mencegah kebutaan adalah diberikan steroid tetes mata pada Siang hari dan salep pada malam hari. Dapat dipakai deksametasone, betametasone dan prednisolon 1 tetes selama 5 menit dan diturunkan hingga perhari.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-193","number":193,"package":"Paket 1","topic":"Kesehatan Masyarakat","title":"Soal 193 · Seorang anak laki-laki berusia 7 tahun dibawa…","page":102,"stem":"Seorang anak laki-laki berusia 7 tahun dibawa ibunya ke puskesmas dengan keluhan terdapat koreng pada kedua tungkai bawah sejak 2 minggu yang lalu. Sebelumnya terdapat gelembung. Pada pemeriksaan fisik kedua tungkai bawah ditemukan lesi tersebar berupa krusta yang dibawahnya terdapat ulkus kotor. Apa diagnosis yang tepat pada pasien tersebut?","options":["ektima","ulkus tropikum","impetigo krustosa","impetigo bochkart","impetigo vesikobulosa"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"'Penyakit Ciri Khas Ektima Predileksi di tungkai bawah, biasanya karena trauma, ulkus dang yang ditutupi krusta, Oleh Streptococcus B-Hemoliticus Ulkus tropikum Luka kecil papul vesikel -Y ulkus infeksi kuman meluas Impetigo krustosa Bula kendur, mudah pecah krusta Honeycomb app, menyerang bayi daerah pipi/wajah Impetigo bockhart Folikulitis superficialis, papulopustul pada dekat muara rambut Impetigovesikobulosa vesikel dan bula hipopion (tegang), predileksi daerah lipatan badan, anak dan dewasa","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-194","number":194,"package":"Paket 1","topic":"Campuran","title":"Soal 194 · Seorang laki-laki berusia 30 tahun datang dengan…","page":102,"stem":"Seorang laki-laki berusia 30 tahun datang dengan keluhan pilek yang disertai dengan ingus berbau, pipi bengkak, nyeri dan terasa panas sejak 4 hari yang lalu.Terdapat lubang pada gigi geraham atas sejak 2 bulan yang lalu. Pemeriksaan tanda vital didapatkan tekanan darah 120/70 mmHg, nadi 80 x/menit, nafas 20 x/menit dan suhu 387 Pemeriksaan penunjang apakah yang dilakukan untuk mendiagnosis pasien tersebUt?","options":["Lateral foto polos cranium","CT scan","Foto servical","MRI","Waters photo"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala paapaie tersebt erua pil ingus bau,ppengkak, yi dn dmam serta terdapat lubang pada gigi geraham atas mengarah pada sinusitis. Pemerikaan penunjang yang dilakukanadalah pemeriksan radiologidengan posisi waters,P dn lateral. Hasilnya akan tampak perselubungan atau penebalan mukosa batas cairan-udara (air fluid level) pada sinus yang sakit.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-195","number":195,"package":"Paket 1","topic":"Campuran","title":"Soal 195 · Seorang Iaki-laki berusia 35 tahun datang ke…","page":103,"stem":"Seorang Iaki-laki berusia 35 tahun datang ke IGD RS dengan keluhan lectusuk (li kaki kanan ketika berjalan di pekarangan rumah yang sedang dilakulcan berkarat telah dikeluarkan sendiri dan diberi antiseptic. Keluhannya (Ijqertai rasa nyeri. Satu tahun yang lalu pasien pernah diberi ATS sebanyak 2 x. Pertama kejadian dan kedua kalinya satu bulan berikutnya setelah kejadian. Tindakan apa yaji0 sebaiknya kita Iakukan pada pasien tersebut?","options":["BeriTT","Beri ATS","Beri ATSdanTT","TidakdiberiTT","Tidak diberi ATS"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Padafase awal terapi,mencakup pembersihan luka dengan debridemen dan antibiotik, serta pemberian anti tetanus serum. Tindakan segera saat itu adalah pemberian ATS setelahpembersihan luka. Imunisasi toksoid lengkap diberikan untuk mencegah serangantetanus. Indikasi pemberian imunisasi pada tetanus: 1.Jika riwayat imunisasi sebelumnya tidak ada atau tidak pasti maka pada luka bersih diberikan seri lengkap toksoid tetanus (TT).Sedangkan,pada luka kotor diberikan seri lengkap TT dan ATS. 2. Jika telah mendapat 1 kali imunisasi difteri-tetanus (DT) atau difteri-tetanus-pertusis (DPT) maka pada luka bersih diberikan seri lengkap toksoid tetanus (TD) sedangkan, padalukakotordiberikanserilengkapTTdanATS. 3. Jika telah mendapat 2 kali imunisasi difteri tetatus (DT) atau difteri-tetanus-per-tusis (DPT) maka pada luka bersih diberikan seri tengkap toksoid tetanus (TT) sedangkan, padalukakotor diberikanseri lengkapTT danATS. Jika telah mendapat 3 kali imunisasi difteri tetatus (DT) atau difteri-tetanus-pertusis (DPT) atau lebih maka pada luka bersih tidak mendapat TT kecuali booster yang terakhir sudah 10 tahun yang lalu atau lebih. Sedangkan, pada luka kotor tidak diberikan TT kecuali booster yang lalu sudah lima tahun yang lalu atau lebih. adalah.... d.Breast feeding jaundice a.Belum sempuma fungsi hati e.DefisiensiG6PD b.Rhesus Inkompatibiltas c.ABOD Inkompatibiitas Jawaban:A Pembahasan: Penyebab ikterus neonatorum berdasarkan waktu kejadian: a.Harike!: Inkompabilitas darah (Rh, ABO) Infeksi intrauterine (TORCH) Anemia hemolitik non sferositosis (G6PD) Sferositosis b. Harike 2: Infeksi Keadaanseperti hari1 tetapi baru timbul Fisiologis C. Hari3-5: Fisiologis(KUbaikmau minum,BBnaik,hepar-liendalambatasnormal,kadar bilirubin total,15 mg/dl,menghilang pada hari ke 10). d.>5 hari atau menetap sampai dengan 10 hari Galaktosemia obat-obatan Ikterus obstruktif Penyakit gilbert Kistik fibrosis sindrom lucey-driscoll Hipotiroidisme Minum ASI Anemia hemolitik Infeksi bakteri/virus","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-196","number":196,"package":"Paket 1","topic":"Campuran","title":"Soal 196 · Seorang S 3000 gram, spontan, normal, diberikan…","page":104,"stem":"Seorang S 3000 gram, spontan, normal, diberikan ASI sejak lahir. Sejak berusia 4 menga)ami kuning Kramer II. Penyebab dari kondisi di atas","options":["Betum sempuna fungsi hati","Rhesus Inkompatibütä-s","ABOD","Breast feeding jaundice","Defisiensi G6PD"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Penyebäb ikterus neonatorum Eerdasarkan waktu kejadian : a. Harikel: Inkompabititas (Rho ABO) Infeksi intrautetine FORCH) Anemia hemelitik non sierositosis (G6PD) Sferositosis b. Hari ke2: - Infeksi Keadzan sepetti hari tetapi baru timbul Esiologis c. Hari 3-5 : fisiologis mau minum, SB naik, hepar-lien dalam batas normal, kadar bilirubin total , IS menghilang pada hari ke IO). d. > 5 hari atau menetap sempai dengan IO hari Galaktosemia obat-obään Ikterus obstrukff Penyakit gilbert Kistik fibrosis sindrom lucey-driscoll Hipotircidisme Minum ASI Anemia hemolitik Infeksi bakteri&irus","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-197","number":197,"package":"Paket 1","topic":"Obstetri & Ginekologi","title":"Soal 197 · Seorang perempuan Serusia 26 tahun GtPcA. hamil…","page":104,"stem":"Seorang perempuan Serusia 26 tahun GtPcA. hamil 27 minggu datang dengan tanda- tanda persalinan. His dari pemeriksaan dalam teraba pembukaan 9 cm dan teraba bagianjanin yaitu hidung dan mulutdengan dagu bagian anterior. penatalaksanaan yang tepat untuk pasien ini adalah—","options":["Persalinan pervaginam","Per abdominal","Ekstraksi forcep","Ekstraksi vakum","Perasat mcRobert"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Sekitar 60-70% persalinan dengan presentasi wajah lahir dengan persalinan pervaginam dan dengan perabdominal. Persalinan perabdominal meningkat bila posisi mentum dilateral atau posterior dibanding anterior.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-198","number":198,"package":"Paket 1","topic":"Campuran","title":"Soal 198 · Seorang wanita berusia 45 tahun datang ke…","page":105,"stem":"Seorang wanita berusia 45 tahun datang ke praktik dokterdengan keluhan dada berdebar- debar sejak 5 hari yang lalu. Rasa berdebar-debar disertai berat pada dada, tertekan, nyeri dada kiri dan takut mati. Pada pemeriksaan fisik didapatkan tekanan darah 130/80 mmHg, nadi 86 x/menit, frekuensi nafas 20 x/menit dan suhu 37,5 oc. Diagnosis pada pasien ini adalah.„","options":["Pneumotorak","AMI","Anxietas","Perikarditis","Katatonik"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Anxietas dicetuskan Oleh adanya situasi atau objek yang jelas (dari luar individu itu sendiri) yang sebenarnya pada saat kejadian ini tidak membahayakan. Sebagai akibatnya, objek atau situasi tersebut dihindari dengan rasa terancam. Hasil pemeriksaan fisik yang dilakukan pada pasien semuanya normal. Keluhan yang ada adalah akibat gangguan cemas (cemas akut).","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-199","number":199,"package":"Paket 1","topic":"Campuran","title":"Soal 199 · Seorang perempuan berusia 45 tahun datang dengan…","page":105,"stem":"Seorang perempuan berusia 45 tahun datang dengan keluhan nyeri hebat pada lutut kanan dan bengkak muncul mendadak. Pada pemeriksaan fisik didapatkan tanda-tanda peradangan pada lutut serta bengkak, nyeri gerak dan nyeri sentuh pada kaki kanan. Saat ini pasien sedang menjalani pengobatan OAT aktif. Hasil pemeriksaan laboratorium didapatkan asam urat I I mg/dl. Obat apa yang menyebabkan keluhan pasien di atas?","options":["Etambutol","Isoniazid","Rifampisin","Pirazinamid","Streptomisin"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tabel efek samping ringan OAT Efek Samping Penyebab Penatalaksanaan Tidak ada nafsu makan, mual, Rifampisin Semua OAT diminum malam sebelum sakit perut tidur Nyeri sendi Pirazinamid Beri Aspirin Kesemutan sld rasa terbakar INH Beri vitamin B6 (piridoxin) 100 mg per di kaki hari Warna kemerahan pada air seni Streptomisin Tidak perlu diberi apa-apa, tapi perlu (urine) penjelasan kepada pasien","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p1-200","number":200,"package":"Paket 1","topic":"Kulit","title":"Soal 200 · Seorang wanita berusia 20 tahun datang ke…","page":106,"stem":"Seorang wanita berusia 20 tahun datang ke praktik dokter dengan keluhan gatal pada keduajempol kaki dan di antarajari kaki kiri. Pada pemeriksaan diambil specimen tampak hifa. Diagnosis yang paling tepat adalah...","options":["Tinea corporis","Candidiasis","Tinea nigra","Tinea cruris","Tinea pedis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada pemeriksaan specimen ditemukan hifa menunjukkan adanya penyakit jamur. Keluhan pada pasien menunjukkan tanda-tanda dari tinea pedis yaitu dermatofitosis pada kaki terutama di sela-sela jari dan telapak kaki.","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-001","number":1,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 001 · Usaha pencegahan diabetes mellitus paling baik adalah.,.…","page":107,"stem":"Usaha pencegahan diabetes mellitus paling baik adalah.,.","options":["Pemberian inhibitor a glukosidase","Diberi sulfonylurea","Diet dan aktivitas fisik teratur","Berhenti merokok","Pemberian metformin"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Patofisiologi diabetesmellitus adalah Diabetes Melitus dibedakan menjadi 2 yaitu : 1. DM tipe 1 yang disebabkan oleh proses autoimun yang merusak sel beta pancreas. Hal ini disebabkan oleh faktor genetik dan lingkungan. 2. DM tipe 2 disebabkan oleh beberapa faktor yaitu : a. Glukogenesis (produksi glukosa di hati) yang berlebihan. Insulin daapat menekan proses glukogenesis di hati tetapi karena terjadi resistensi insulin di hati, maka insulin tidakdapat secara efektifmenekan prosesglukogenesistersebut, akibatnye terjadi produksi glukosa yang berlebihan. b.F Resistensi insulin yang disebabkan oleh factor genetic dan obesitas C. Berkurangnya sekresi insulin yang berkurang (awalnya untuk mengkompensasi resistensi insulin sehingga terjadi kenaikan sekresi insulin, kemudian sekresi insulin akan semakin berkurang seiring dengan perjalanan penyakit DM), namun penyebabnya belum diketahui secara pasti. Dari factor di atas yang dapat dikendalikan adalah obesitas. Diet yang baik dan melakukan aktivitas fisik secara teratur dapat mencegah obesitas, sehingga dapat mengurangi kemungkinan terjadinya DM. Aktivitas fisik juga dapat meningkatkan sensitivitassel tubuhterhadapinsulin.","answerPage":150,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-002","number":2,"package":"Paket 2","topic":"Psikiatri","title":"Soal 002 · Seorang wanita usia 34 tahun dibawa ke…","page":107,"stem":"Seorang wanita usia 34 tahun dibawa ke puskesmas Oleh keluarganya karena keluarganya kewalahan dengan perilaku pasien yang membagikan barang-barang di toko milik keluarganya kepada orang lewat. Pasien ini dandan berlebihan dengan pakaian ketat dan terbuka, sangat gembira, bicara cepat dan sulit dimengerti. Wanita ini beranggapan bahwa ia sangat kaya. Gangguan ini sudah sering terjadi. Diagnosis yang tepat untuk pasien ini adalah„.","options":["Gangguan siklotimik","Gangguan afektif bipolar","Skizofrenia","Gangguan skizoafektif Gangguan skizoafektif","Gangguan waharn menetap"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gangguan afektif bipolar memiliki episode berulang (sekurang-kurangnya dua episode) diamana afekpasien dantingkataktivitasnya jelasterganggu.Padasaat tertentu terdini dari peningkatan afek disertai penambahan energy dan aktivitas (manicatau hipomania). pada saatlain berupa penurunan afek disertai pengurangan energy danaktivitas(depresi). Yang khas biasanya ada penyembuhan sempurna antarepisode.Pada pasien tersebut dalam episode manic,tampakgejala afek meningkat disertai denganpeningkatandalam jumlah dan kecepatan aktivitas fisik dan mental.","answerPage":150,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-003","number":3,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 003 · Seorang wanita usia 23 tahun datang ke…","page":107,"stem":"Seorang wanita usia 23 tahun datang ke IGD dengan keluhan nyeri perut hebat dan disertai perdarahan pervaginam. Pasien terlihat pucat dan tidak haid selama dua bulan. Pada pemeriksaan fisik didapatkan TD 80/60 mmHg dan denyut nadi yang teraba lemah. Pemeriksaan abdomen pada palpasi ditemukan abdomen tegang dan nyeri bagian bawah. Selain itu didapatkan kavum douglas menonjol. Diagnosis pada pasien ini adalah...","options":["Abortus iminens","Rupture tuba","Peritonitis appendiks","Peritonitis umurn","Salphingitas akut"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Berdasarkan gejala klinis dan hasil pemeriksaan dapat disimpulkan pada kasus ini pasien mengalami kehamilan ektopik terganggu. Hal ini dapat terjadi karena adanya kehamilan dalam tuba. Sebagian besar kehamilan ektopik berlokasi di tuba. Karena tuba bukan tempat untuk pertumbuhan hasil konsepsi janin tidak akan tumbuh secarautuhseperti dalam uterus. Sebagian besar kehamilan tuba terganggu pada umur kehamilan antara 6-10 minggu yaitu hasil konsepsi mati dini dan direabsorbsi, abortus ke dalam lumen tuba ataupun terjadi ruptur tuba.","answerPage":150,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-004","number":4,"package":"Paket 2","topic":"Bedah","title":"Soal 004 · Seorang Iaki-laki usia 20 tahun mengalami kecelakaan…","page":107,"stem":"Seorang Iaki-laki usia 20 tahun mengalami kecelakaan Jalu lintas dan terdapat Iuka terbuka pada kaki kiri dan mengalami perdarahan. Perdarahan sulit dihentikan dan ditemukan Iuka memar pada kepala dan tangan. Pasien memiliki riwayat pada saat anak- anak mengalami Iuka kecil yang masa penyembuhannya lebih lama. Pemeriksaan fi5ik didapatkan tekanan darah 120/80 mmHg, denyut nai 80x/menit, frekuensi nafas 20%/ menit dan temperature 37 OCC. Berdasarkan hasil di atas pada pemeriksaan laboratorium akan didapatkan?","options":["Masa protombin (P T) meman)ang","Masa pembekuan (CT) memanjang","FaktorVlll dan Xl normal","Masa tromboplastin partial teraktivasl (aPTT) normal","Masa plasma protombin (PTT) memanjang"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien ditemukan keluhan perdarahan berkelanjutan yang merupakan tanda kinis khas dari hemophila. Dikenal dua macam hemophilia yang diturunkan secara sexlinked recessive yaitu: a. Hemoflia A (hemophili klasik) akibat defsiensi factor pembekuan Vll(F Vlic) b. Hemofilia B (Christmas disease) akibat defisiensi factor IX (F Christmas) Laboratorium pada hemophilia A dan hemophilia B : HemofliaA Hemofilia B Jumlahtrombosit N N Waktuperdarahan N N PT N N CT Memanjang Memanjang PPT N N aPTT Memanjang Memanjang FVIlIC Rendah N FVIll ag N N FIX N Rendah Tes ristosetin N N","answerPage":151,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-005","number":5,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 005 · Kadar glukosa darah 2 jam setelah makan…","page":108,"stem":"Kadar glukosa darah 2 jam setelah makan sebesar 450 njg/cll Oleh...","options":["Glikogenesis, lipogenesis, dan glikoli5i5 terhambat","Terlalu banyak makan","Masuknya glukosa ke dalam hepatosis terhambat","Ginjal tidak mampu mensekresi glukosa clarah","Glikogenesis dan glukoneogenesis menlngkat"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kadar gula darah memicu sekresi insulin oleh sel beta pancreas. Pada kadar gula darah yang rendah(saat puasa),kadarinsulin rendah, sehingga glukogenesis hati dan glikogenolisis meningkat hal ini bertujuan untuk mengkompensasi kurangnya asupan glukosa dari makanan. Kadar glukosa darah meningkat setelah makan karena mendapat suplai glukosa dari makanan tersebut. Kadar gula yang tinggi memicu sekresi insulin. Insulinakanmemasukkanglukosa dari darahkejaringansehinggakadarguladarah postpandrial tidak terlalu tinggi.Pada penderita DM, terjadi resistensi insulin (DM tipe 2). Hal ini mengakibatkan terjadinya gangguan pemasukkan glukosa dari darah ke jaringan atau sel tubuh, sehingga kadar gula darah postpandrial meningkat.","answerPage":151,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-006","number":6,"package":"Paket 2","topic":"Campuran","title":"Soal 006 · Seorang wanita usia 23 tahun mengeluh nyeri…","page":108,"stem":"Seorang wanita usia 23 tahun mengeluh nyeri sendi pada Jarl kedua tangan dan kedua lutut dengan tanda bengkak dan panas. Terdapat bercak merah seperti kupu-kupu pada kedua pipi dan dahi yang bertambah jelas bila terkena mataharl. Penatalaksanaan yang tepat untuk pasien ini adalah.„","options":["Terapi dengan OAINS, pemeriksaan laboratorium meliputi sel LE, tes DNA dan RF","Terapi dengan kortikosteroid saja tidak perlu konfirmasi diagnosis Jagj","Tidak perlu terapi, cukup observasi saja","Terapi dengan OAINS dan siklofosfamid tidak perlu pemeriksaan laboratorium","Terapi dengan OAINS dan pemeriksaan foto sinar X sendi saJa"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kriteria diagnosis untuk SLE, jika terdapat 4 kriteria maka diagnosis SLE dapat ditegakkan: a. Malar rash, eritema yang fxed datar dan meninggi, letaknya pada malar biasanya tidak mengenai lipatan nasolabial Discid rash lesi erythematous yang meninggi dengan skuama keratotik b. C.Fotosensitivitas d. Ukus oral ulserasidimulut ataunasofaring biasanya tidak nyeri Arthritis arthritis non erosive melibatkan 2 sendi atau lebih sendi perifer ditandai e. dengan nyeri, bengkak dan efusi Serosts pada peuritis didapatan riayat nyeri leral, leuralfrictionrub, usi f. pleura.Pada perikarditis tampak pada EKG, gesekan perikard efusi perikard Gangguan ginjal, proteinuria>05 g/hari atau>3+atau ceuer cast berupa eritrosit, g. hemoglobin granular, tubular dan campuran h. Kelainan neurologis, psikosis, kejng (tanpa sebabyanglas) Kelainan hematologis, anemia hemolitik, leukopeni (<4000), limfopeni (<1500), 1. trombositopenia(<100.000) Kelainan imunologis, anti ds-DNA, anti-Sm (antibody terhadap antigen otot polos), j. antibody antifosfolipid, STS positif palsu k.Antibody antinuclear, tes ANA positif","answerPage":151,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-007","number":7,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 007 · Seorang Jaki-Jaki usia 30 tahun dibawa keluarganya…","page":108,"stem":"Seorang Jaki-Jaki usia 30 tahun dibawa keluarganya post kecelakaan lalu lintas. Pada pemeriksaan fisik didapatkan nadi teraba lemah, nafas lemah. Dokter melakukan penanganan pertama. Resusitasi yang dilakukan adalah.„","options":["Nafas 2x, kompresi jantung 30x","Nafas lx, kompresi jantung 15x","Kompresi jantung 30x, nafas lx","Nafas kompresi jantung 151","Kompresi jantung 15x, nafas2x"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Resusitasijantung paruyang dilakukan pada pasien iniadalah dengan pemberian ventilasi buatan dan oksigenasi serta kompresi jantung. Ventilasi dapat dari mulut ke mulut, mulut ke hidung, mulut ke trakea. RJP dilakukan dengan Nafas 2x, kompresi jantung 30x","answerPage":152,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-008","number":8,"package":"Paket 2","topic":"THT","title":"Soal 008 · Seorang Iaki-laki usia 34 tahun datang dengan…","page":108,"stem":"Seorang Iaki-laki usia 34 tahun datang dengan keluhan keluar darah dari hidung setelah kecelakaan lalu lintas. Pada pemeriksaan vital sign didapatkan TD 130/80 mmHg, nadi 88x/menit, RR 20x/menit, suhu 36,50C. Pemeriksaan fisik didapatkan hidung edema (+1 hiperemis (+), cavum nasi hiperemis (+), bekuan darah (+), dan perdarahan aktif pada nasofaring. Terapi yang diberikan pada pasien ini adalah.„","options":["Tampon anterior 4 hari","Tampon anterior 5 hari","Tampon anterior dan posterior","Tampon belloq 2-4 hari","Tampon belloq 4 hari"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien ini mengalami perdarahan aktif pada nasofaring sehingga perlu penatalaksanaan perdarahan dari bagian posterior. Untuk pemasangan perdarahan posterior dilakukan pemasangan tampon posterior yang disebut tampon belloq. Tampon ini harus menutup koana yang harus dilepas 2-3 hari.","answerPage":152,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-009","number":9,"package":"Paket 2","topic":"Campuran","title":"Soal 009 · g/dl Pada apusan arah tepi menunjukkan sel-sel…","page":109,"stem":"g/dl Pada apusan arah tepi menunjukkan sel-sel eritrosit normositer normokromik, hematokrit 28% danMCV94 Penyebabkondisipasientersbut adala.","options":["Perdarahan akut","Leukimia limfositik kronik","Defisiensi erythropoietin","Defisiensi enzim eritrosit","Anemia sideroblastik"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Anemia normokromik normositer ditemukan pada: a.Anemia pasca perdarahan akut e. Anemia pada gagal ginjal kronik b.Anemia aplastik f.Anemia pada sindrom mielodisplastik C.Anemia hemolitik didapat g. Anemia pada keganasan hematologik d.anemia akibat penyakit kronik Anemia pada penyakit kronik ditandai dengan memperpendek masa hidup eritrosit dan gangguan produksi eritrosit akibat tidak efektifnya rangsangan eritropoetin.","answerPage":152,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-010","number":10,"package":"Paket 2","topic":"Psikiatri","title":"Soal 010 · seorang wanita usia 59 tahun tinggal bersama…","page":109,"stem":"seorang wanita usia 59 tahun tinggal bersama suaminya sejak beberapa tahun ini mengalami kepikunan yang semakin lama semakin memberat, tidak mampu makan ataupun berpakaian sendiri dan memerlukan bantuan pembantu. Pada kegiatan sehari-hari ia tidak berbuat apa-apa, kadang marah tanpa sebab. Tidak mamu bergaul dengan siapapun padahal sebelumnya adalah seorang yang aktif, komunikasi terbatas. Secara fisik tidak ada kelainan. Setiap pertanyaan dari suaminya selalu ia jawab dengan tersenyum tetapi jawabnya tidak benar. Kemampuan member alasan tidak logis walaupun berpakaian masih sopan. Kada ia merasa seperti ada seseorang di dalam kamar padahal kenyataannya tidak ada. Kasus tersebut pasien mengalami:","options":["Demensia","Psikosa","Ansietas","Skizofrenia","Mild cognitive impairment"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Padpasintersbtngalamigejlaitikwahalsinasinerensil katatonia). Pasien tersebut mengalami halusinasi (merasakan seperti ada seseorang dikamarnya), dan dijumpai deteriorasi yaitu kemampuanmengurus diri dan socialyang berkurang (berpakaiandibantuolh orang lain,kmunikasi sangat tebatas)ehingga diagnosisnya adalah skizofrenia.","answerPage":153,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-011","number":11,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 011 · Beberapawargadatangkepuskesmaskurang lebih100orang dengankeluhanmencret danmuntahsertademam.Keluhaninimunculsetelahmerekamakan-makandisebuah hajatan.Padapemeriksaanfeses didapatkan bakteri…","page":109,"stem":"Beberapawargadatangkepuskesmaskurang lebih100orang dengankeluhanmencret danmuntahsertademam.Keluhaninimunculsetelahmerekamakan-makandisebuah hajatan.Padapemeriksaanfeses didapatkan bakteri E.coli.Akan tetapi yang tidak ikut makan-makantidaksakit.Penyakittersebutadalah..","options":["Milkborne disease","Food borne disease","Tickborne disease","Vehicle borne disease","Louseborne disease"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus ini menunjukan adanya kontaminasi mikroorganisme pada makanan. Hal initerlihat munculnyakeluhan setelah makan bersama danditemukannya bakteri E.Coli pada feses. Penyakit yang ditularkan melalui makanan disebut food borne disease.","answerPage":153,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-012","number":12,"package":"Paket 2","topic":"Neurologi","title":"Soal 012 · Seorang laki-laki usia 50 tahun dating kelGDdengan…","page":109,"stem":"Seorang laki-laki usia 50 tahun dating kelGDdengan penurunan kesadaran. Pemeriksaan fisik diapatkan tekanan darah 80/60 mmHg, nadi teraba lemah dan cepat dan kedua akral dingin. Perneriksaan laboratorium didapatkan hemoglobin 13,8 g/dl, leukosit 4200/mm3, hematokrit 38% dan trombosit 222.000/mm3. Kemudian diketahui bahwa pasien ada riwayat pemberian suntikan penisilin 30 menit sebelumnya. Bagaimana mekanismenya","options":["Terjadi reaksi anafilatik akibat reaksi antigen dengan lgE yang terbentuk","Terjadinya reaksi sitotaksi karena terbentuknya IgM/lgG Oleh antigen","Terjadinya reaksi kompleks imunitas","Terjadinya respons system imunitas humoral","Terjadi respon selTyang telah disensitasi Oleh antigen tertentu"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pemberian obat penisilin rentan terjadinya reaksi hipersensitivitas tipe L Biasanya terjadi 30 menit setelah pemberian obat. Pada reaksi hipersensitivitas tipe I terjadi manifestasi klinis renjatan anaflatik yang merupakan efek mediator kimia akibat reaksi antigen denganIgEyang telah terbentuk.Gejalanya adalah: a.Sesak nafas akibat kejang bronkus ataupun kejang laring b.Urtikaria C.Angioedema d.Pingsandan hipotensi","answerPage":153,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-013","number":13,"package":"Paket 2","topic":"Campuran","title":"Soal 013 · Seorang anak perempuan usia 22 bulan dengan…","page":110,"stem":"Seorang anak perempuan usia 22 bulan dengan berat badan 6 kg dan tinggi badan 77 cm dibawa ibunya ke dokter karena terlalu kurus. Pada pemeriksaan fisik terlihat sayu, otot hipotrofi, jaringan subkutannya sedikit, serta terdapat edema pada dorsum pedis. Jika diberi makan anak tersebut muntah. Diagnosisnya adalah...","options":["KEP II","KEP marasmus","KEP Ill","KEP campuran","KEP kwashiorkor"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kekuranganenergyproteinberat dibagi menjadi3yaitu: a.Tipemarasmik;kekurangan energy tanpa disertai dengan kekuranganprotein. Ditemukanpenyusutanmassaototsecaramenyeluruhdantidakadanyalemak subkutansehingga tampak tinggal tulang terbalutkulit tanpa disertaiedem,rambut tipisdankering.mudahdicabuttanpa disertairasasakit. b. .Tipe kwarshiorkor:kekurangan energy disertai protein.Gejala klinis yang dominan adalahedemajaringanlunakyangbersifatpittingtanparasasakitbiasanyaterjadi pada tungkai dan kaki yang meluas ke perineum, ekstremitas atas dan wajah pada kasusyang berat.Rambut kering danmudah dicabut tanpa rasa sakit.Terdapat anoreksia,mual,muntah setelah makan serta diare.Abdomen biasanya distended, peristaltic lambat dan tidak teratur.Kekuatan dan tonus otot berkurang. Tipemarasmik kwashiorkor(campuran):pada klinis ditemukan kombinasikwashiorkor dan marasmik. Gejala utama berupa edema dari kwashiorkor dengan atau tanpa lesi kulit serta terjadi penyusutan otot dan penurunan lemak subkutan dari marasmus.","answerPage":153,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-014","number":14,"package":"Paket 2","topic":"THT","title":"Soal 014 · Seorang anak perempuan usia 9 tahun datang…","page":110,"stem":"Seorang anak perempuan usia 9 tahun datang dengan keluhan BAK berwarna gelan Wajahnya juga sembab, pasien mengeluh demam, nyeri saat menelan serta tenggorokan terasa nyeri sejak 2 minggu yang lalu. Namun sekarang gejala tersebut sudah menghilang. Pemeriksaan fisik didapatkan TD 150/90 mmHg, Nadi 90x/menit, RR 20x/menit, suhu 37 oc. Terdapat edema pada kedua tungkai. Hasil pemeriksaan laboratorium menunjukkan adanya peningkatan kreatinin dan ureum darah serta penurunan albumin plasma. Pemeriksaan urin didapatkan proteinuria dan gross hematuria. Patogenesis dasar dari penyakit ini adalah.„","options":["Aterosklerosis","Autoimun","Keganasan","Gangguan metabolism","Neuropati"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Glomerulonefritis tipe ploriferatif trjadi melalu mekanisme inflamasi yang diperantarai imun. Jenis yang paling sering adalah glomerulonefritis akut pasca streptococus. Reaksi imunologis terhadap bakteri diperantarai oleh aktivasi terhadap komplemen dan juga terjadi deposisi antibodi dalam glomerulus. Imunitas seluler juga berperan dalam pathogenesis glomerulonefritis yang diperantarai antibodi dengan cara memodulasi produksi antibodi danmelalui sitotoksisitas sel.","answerPage":154,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-015","number":15,"package":"Paket 2","topic":"Kulit","title":"Soal 015 · Seorang laki-laki usia 35 tahun datang dengan…","page":110,"stem":"Seorang laki-laki usia 35 tahun datang dengan keluhan diare sebanyak 10k Dokter mengatakan ia mengalami dehidrasi sehingga harus dirawat. Gejala dan tanda apa yang dapat ditemukan pada pasien ini?","options":["BAK berkurang","Banyak keringat","Turgor meningkat","Lidah basah","Kulit lembab"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Beberapa gejala pada dehidrasi : a.BAK berkurang b.Turgormenurun C. tidakberkeringat d. Lidahdankulitkering e. air mata kering f. mata cekung g.suara serak Gejala yang timbul tergantung dengan derajat dehidrasi yang terjadi.","answerPage":154,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-016","number":16,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 016 · Seorang wanita usia 55 tahun datang dengan…","page":110,"stem":"Seorang wanita usia 55 tahun datang dengan keluhan sulit tidur, nafsu makan menurun' jantung berdebar-debar, nafas terasa berat dan sesak, lernah dan mudah tersinggung• Suaminya sering dinas diluarkota sejak4 bulan yang lalu dan hanya pulang I bulan sekali• Semua anaknya telah menikah dan tinggal di rumah masing-masing. Pemeriksaan fisik dalam batas normal dan pemeriksaan laboratorium tidak menunjukkan adanya kelainan•","options":["Gaga! jantung","Gangguan bipolar","Depresi","Psikosomatik","Cemas menyeluruh"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gangguan cemas menyeluruh merupakan suatu kekhawatiran yang berlebihan dan dihayati disertai berbagai gejala somatic yang menyebabkan gangguan bermakna dalam fungsi social atau pekerjaan atau penderitaan yang jelas bagi pasien. Gejala utamanya adalahkecemasan motorik(gemetar,gelisah dan nyeri kepala),hiperaktivitas otonom (sesak nafas, keringat berlebihan, palpitasi dan gejala gastrointestinal), gejala lainnya kewaspadaan kognitif yaitu mudah tersinggung dan mudah dikejutkan.Pasien seringkali datang ke dokter umum atau penyakit dalam dengan keluhan somatik spesifik.","answerPage":154,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-017","number":17,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 017 · Seorangwanita usia25tahun datang kepuskesmas dengan keluhan demam…","page":110,"stem":"Seorangwanita usia25tahun datang kepuskesmas dengan keluhan demam sejak3hari yang lalu. Pemeriksaan vital sign TD 110/80, nadi 80 x/menit, RR 30x/menit, suhu 385 •C. Pada pemeriksaan laboratorium hasil diagnosisnya adalah tifoid. salah satu factor determinan yang menyebabkan penyakit ini adalah..","options":["Psikologis","Lingkungan social","Imunitas","Gaya hidup","Pelayanan kesehatan"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Penyebab tifoid secara klinis hamper selalu yang beradaptasi pada manusia, penyebab yang paling dekat adalah air atau makanan yang terkontaminasi. Di Amerika perbaikan sanitasi lingkungan menyebabkan insidensi tifoid telah menurun.","answerPage":154,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-018","number":18,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 018 · Seorang Iaki-laki usia 40 tahun dating dengan…","page":111,"stem":"Seorang Iaki-laki usia 40 tahun dating dengan keluhan jantung berdebar-debar. Keluhan ini dirasakan setelah minum obat sesak yang diberikan Oleh dokter 3 hari lalu. Pasien didiagnosiS mengidap asma bronchial. Pemeriksaan fisik ditemukan takikardi dan tensi darah 160/90 mmHg. Obat mana yang paling mungkin menyebabkan keluhan di atas?","options":["Salbutamol","Terbutalin","Efedrin","Fenilpropanolamin","Ritodrin"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Salah satu obat antiasma adalah agonis beta 2 (fenoterol, salbutamol,terbulin, prokaterol) merupakan obat terpilih untuk gejala asma akut serta bila diberikan sebelum kegiatan","answerPage":154,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-019","number":19,"package":"Paket 2","topic":"Campuran","title":"Soal 019 · Penyebaran penyakit dengan perantara hewan peliharaan adalah...…","page":111,"stem":"Penyebaran penyakit dengan perantara hewan peliharaan adalah...","options":["Campak","Pneumonia","Diare","Leptospirosis","Toksoplasmosis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"peliharaan) Leptospirosis disebabkan oleh ptospira dengan perantara tius,racoon, serigala Pneumonia, diare dan campak penularannya tanpa melalui perantara.","answerPage":155,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-020","number":20,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 020 · Seorang laki-laki usia 55 tahun dating denga…","page":111,"stem":"Seorang laki-laki usia 55 tahun dating denga keluhan sesak nafas dan bengkak dikedua tungkai sejak 2 hari yang lalu. Pasien memiliki riwayat minum obat hipertensi sejak 5 tahun yang lalu. Sehari yang lalu pasien mengeluh urine berwarna agak merah an sedikit. Pemeriksaan penunjang yang mendukung pemeriksaan kearah iagnosis adalah...","options":["SGPT","Kreatinin","Clearance creatinin","CKMB","Ureum"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Adanya keluhan urine berwarma merah dan sedikit dapat dipikirkan untuk memeriksa adanya kelainan pada fungsi ginjal. Apakah fungsi ginjal masih baik atau telah mengalami gagal ginjal. Pemeriksaan penunjang yang dapat dilakukan adalah clearance creatinin.","answerPage":155,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-021","number":21,"package":"Paket 2","topic":"Neurologi","title":"Soal 021 · Seorang anak laki-laki usia4tahun datang dibawa ibunya…","page":111,"stem":"Seorang anak laki-laki usia4tahun datang dibawa ibunya dengan keluhan kejang, demam selama 5 hari, penurunan kesadaran dan batuk pilek. Untuk menegakkan diagnosis keadaan ini perlu dilakukan pemeriksaan:","options":["Gas darah","Elektrolit","Cairan otak","Cairan Iambung","Trombosit"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Apabila ada pasien datang dengan keluhan kejang maka perlu dipikirkan apakah kejang tersebut disertai demam atau tidak, perlu dipikirkan pula apakah kejang tersebut disebabkan kelainan primer di otak (system saraf pusat) ataukan diluar otak.Pada pasien ini kejang disertai dengan demam dan terdapat penurunan kesadaran. Hal ini mengarah kepada meningitis atau meningoencepalitis,tergantung apakah adakelainan saraf disentralatauperifer.Namunadanyariwayatdemam5harikemungkinandisebabkan olehinfeksipadasaluranpernafasan(yang ditandaidengankeluhanbatukdanpilek) juga mengarah ke proses kejang demam. Oleh karena itu untuk menyingkirkan diagnosis meningitis maka perlu dilakukan pemeriksaan cairan serebrospinal (pungsi lumbal). Kejang juga dapat disebabkan oleh gangguan elektrolit dan metabolic sehingga dapat dilakukan pemeriksaan gas darahdan elektrolit. Namun, berdasarkan tanda dan gejala pada pasien ini yang lebih tepat adalah pemeriksaan cairan cerebrospinal. Pemeriksaan trombosit dan cairan lambung tidak bersifat spesifik.","answerPage":155,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-022","number":22,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 022 · Seorang wanita usia 24 tahun GI POAO…","page":111,"stem":"Seorang wanita usia 24 tahun GI POAO datang untuk memeriksa kehamilannya pada tanggal 13 Januari 2013 dan HPHT 18 Mei 2012. Pemeriksaan tanda vital didapatkan tekanan darah 120/80 mmHg, nadi 78x/menit, frekuensi nafas 24x/menit dan suhu 36,8 OC.Janin tunggal dan hidup dengan djj 120x/menit. Pemeriksaan fisik didapatkan janin tunggal hidup presentasi kepala, kepala belum masuk PAP, punggung kiri, belum inpartu. Letak punggung kiri didapatkan dari pemeriksaan?","options":["Leopold I","Leopold II","Leopold Ill","Leopold IV","VT"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Cara pemeriksaan obsetrik terdapat 4 tahap yaitu : a. Leopold I : menentukan tinggi fundus uteri, sehingga usia kehamilan dapat diketahui dan bagian janin yang terletak difundus uteri bila kepala akan teraba bulat keras b. Leopold I: Menentukan batas samping uterus dan punggung janin yang membujur dari ataske bawah menghubungkan bokong dengan kepala.Padaletaklintang dapat ditentukan kepala janin. C.Leopold Ill: Untuk menentukan bagian yang terletak di sebelah bawah telah masuk ke dalam pintu atas panggul.","answerPage":155,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-023","number":23,"package":"Paket 2","topic":"Neurologi","title":"Soal 023 · Seorang wanita usia 19 tahun dibawa ke…","page":112,"stem":"Seorang wanita usia 19 tahun dibawa ke IGD rumah sakit dalam keadaan tidak I setelah berusaha bunuh diri dengan minum baygon (organofosfat) 1 jam yang lalu. Dokter IGD segera memberiksan injeksi atropine sampai terjadi atropinisasi. Yang merupakan parameter terjadinya atropinisasi adalah...","options":["Midriasis maksimal","Denyut jantung menurun","Bronkokonstriksi","Kejang","Hipersalivasi"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Atropin berfungsi sebagai antidotum pada keracunan insektisida golongan organofosfat. Atropine bekerja sebagai pemblokade/penyekat reseptor muskarinikyang memiliki efek sikiopedia pada pupil. Pupil yang melebar (midriasis) merupakan parameter untuk mengetahui efek kerja atropine.","answerPage":156,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-024","number":24,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 024 · Seorang wanita hamil aterm G2PIAO datang dengan…","page":112,"stem":"Seorang wanita hamil aterm G2PIAO datang dengan keluhan terasa kenceng-kenceng 24. dan mules sejak dua jam yang lalu. Untuk memantau his dimana posisi tangan saat","options":["fundus uteri","atas simpisis","pinggang janin","sekitar pusat ibu","Sisi perut ibu"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"His atau kontraksiuterus terjadikarena otot-ototrahim bekerja dengan baikdan sempurna dengan sifat kontraksi simetris, fundus dominan kemudian dan dikuti relaksasi. Pusat koordinasi his berada pada uterus disudut tuba, dimana gelombang his berasal. His yang sempurna mempunyai kekuatan paling tinggi di fundus uterus. Pada pemeriksan untuk memantau his, tangan pemeriksa diletakkan pada daerah yang memiliki jaringan longgar disekitarpusat dekan denganfundusuteri.","answerPage":156,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-025","number":25,"package":"Paket 2","topic":"Psikiatri","title":"Soal 025 · Seorang wanita usia 20 tahun datang ke…","page":112,"stem":"Seorang wanita usia 20 tahun datang ke tempat prakterk dokter karena mengeluh setiap 25. melihat darah merasa ketakutan. Bahkan melihat sedikit darah pun sangat takut. Terapi apakah yang tepat untuk pasien ini?","options":["Terapi psikodinamika","Terapi paparan","Terapi antipsikotik","Terapi kelompok","Terapi fuoksetin"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien ini mengeluh mengalami ketakutan terhadap suatu objek yang jelas (darah) yang sebenarnyaobjektersebuttidakmembahayakan,sehinggadiagnoisisnyaadalahfobia. Penatalaksanaan fobia adalah dengan terapi paparan, pasien dipaparkan dengan objek yang membuatnya takut. Terapi ini dimulai dengan paparan ringan (misalnya: gambar darah).Bila sudah tidaktakutbisadinaikkanpaparannya sehinggapasien tidaktakut dengan darah.","answerPage":156,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-026","number":26,"package":"Paket 2","topic":"Campuran","title":"Soal 026 · Seorang wanita usia 17 tahun datang dengan…","page":112,"stem":"Seorang wanita usia 17 tahun datang dengan keluhan keluarcairan berwarna kuningyang keluar dari vagina. Pada pemeriksaan fisik didapatkan serviks eritematosa. Pemeriksaan makroskopik didapatkan adanya discharge viscous sebaran leukosit. Apakah diagnosis yang mungkin pada pasien ini?","options":["Candida albicans","Bacterial vaginosis","Ureaplasma ureulyticum","Neischerisia gonorrhea","Clamidya trachomatis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Discharge(duh tubuh ataucairan)yangkeluarpadavagina antara laindisebabkan oleh candida albicans,bacterial vaginosis,trichomoniasis,foreign body,dan senile charge. Padacandidaalbicansdantrichomoniasis,duhtubuhataucairanberwarnakekuningan sedangkanbacterialvaginosisditemukanduhtubuhvaginaberwarnaabu-abu, homogeny dan berbau.","answerPage":156,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-027","number":27,"package":"Paket 2","topic":"Anak","title":"Soal 027 · Seorang bayi berumur 3 bulan dibawa Oleh…","page":112,"stem":"Seorang bayi berumur 3 bulan dibawa Oleh ibunya ke RS dengan keluhan saat BAK le;uar dari tempat yang tidak semestiya. Pada pemeriksaan tanda vital dalam batas normal Status lokalis didapatkan adanya pembesaran klitoris seperti labia mayora dan muara AUE di perineum. Diagnosis pasien ini adalah...","options":["Biseks","Interseks","Hermafrodit","Transeks","Transgender"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Interseks merupakan istilah yang menunjukkan secara umum gangguan diferensiasi kelainan. Disebabkan karena kelainan produksi hormone dan gangguan fal hormone serta kelainan kromosom. Terdapat beberapa kelainan khas seperti hermafrodit, sindrom turner, sindrom klineferter dl Sedangkan pada hermafrodit menunjukkan istilah adanya kedua jenis kelamin yang secara bersamaan akibat kelainan kromosom. Hal ini dengan ditemukannya gonad laki-laki dan perempuan dalam tubuh yang sama. Biseks menunjukan perilaku homoseksual dan heteroseksual yang ditunjukan dengan ketertarikan pada dua jenis kelamin.","answerPage":156,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-028","number":28,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 028 · Seorang Iaki-laki usia 50 tahun datang ke…","page":112,"stem":"Seorang Iaki-laki usia 50 tahun datang ke dokter dengan keluhan jantung berdebar- debar. Keluhan ini dirasakan setelah minum obat sesak nafas yang diberiksan Oleh dokter sekitar 2 hari yang lalu. Saat itu dokter mendiagnosis pasien mengidap asma bronchial Dari pemeriksaan fisik clitemukan TD 160/90 mmHg dan takikardi. Obat mana yang paling mungkin menyebabkan keluhan di atas?","options":["Efedrin","Salbutamol","Terbutalin","Ritodrin","Fenilpropanolamin"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Salah satu obat antiasma adalah agonis beta 2 (fenoterol, salbutamol, terbulin, prokaterol) merupakan obat terpilih untuk gejala asma akut serta bila diberikan sebelum kegiatan jasmani dapat mencegah serangan asma karena kegiatan jasmani. Salbutamol memiliki efek samping takikardi dan peningkatan tekanan darah karena itu tidak dianjurkan diberikan pada pasien yang memiliki riwayat hipertensi.","answerPage":157,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-029","number":29,"package":"Paket 2","topic":"THT","title":"Soal 029 · Seorang laki-laki usia 24 tahun datang dengan…","page":113,"stem":"Seorang laki-laki usia 24 tahun datang dengan keluhan sering mimisan. Keluhan tidak disertai batuk dan demam. Pasien sering merasa hidungnya tersumbat. Pada pemeriksaan vital sign didapatkan TD 120/80 mmHg, nadi 80x/menit, RR 18x/menit dan suhu 36,5 oc. pemeriksaan rinoskopi anterior ditemukan massa merah muda di hidung dan mudah berdarah. Diagnosis pasien ini adalah...","options":["Ca nasofaring","Septum deviasi","Angiofibroma nasofaring","Polip hidung","Papiloma laring"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Diagnosis angiofbroma nasofaring biasanya hanya ditegakkan berdasarkan gejala klinis. Gejalayang paling sering ditemukan adalah hidung tersumbatyang progresif dan epitaksis berulang masif. Adanya obstruksi hidung memudahkan terjadinya penimbunan secret sehingga timbul rinorea kronis yang dikuti oleh gangguan penciuman. Okulasi pada tuba eusthacius akan menimbulkanketulian atau otalgia.Sefalgia hebat menunjukkan tumor sudah meluaskeintracranial.Pada pemeriksaanfisik secara rinoskopi posterior akan terlihat massa tumor yangkonsistensikenyal dan warnanya bervariasi dari merahmuda sampai abu-abu.Mukosanya mengalami hipervaskularisasi dan tidak jarang ditemukan adanya ulserasi.","answerPage":157,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-030","number":30,"package":"Paket 2","topic":"Campuran","title":"Soal 030 · Yang merupakan penyakit akibat kekurangan iodium, kecuali…","page":113,"stem":"Yang merupakan penyakit akibat kekurangan iodium, kecuali :","options":["Kerdil","Bisu-tuli","Mata juling","Gigantisme","Kecerdasan rendah"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada defisiensi iodium manifestasi klinispada anak dapat terjadi pembesarankelenjar gondok, gangguan fungsi mental dan perkembangan fisik.Pada daerah gondok endemic dijumpai kreatinisme endemic. Kelainan ini terjadi saat bayi masih berada dalam kandungan atau tidaklama setelah dilahirkan dan terjadikerusakan pada saraf pusat dan hipotiroidisme.Kerusakan saraf pusat secara klinis bermanifestasi sebagai berikut: a.Retardasimental b. Gangguan pendengaran sampai bisu-tuli C. Gangguan neuromotor:gangguan biacara,cara berjalanyang aneh d.Hipotiroidisme dengan gejala: Miksedemapadahipotiroidismeberat Tinggi badan yang kurang, cebol/kerdil dan osifikasi yang terlambat","answerPage":157,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-031","number":31,"package":"Paket 2","topic":"Anak","title":"Soal 031 · Seorang bayi perempuan usia 2 hari dibawa…","page":113,"stem":"Seorang bayi perempuan usia 2 hari dibawa ke IGD Oleh orang tuanya dengan keluhan muntah-muntah berwarna hijau dan sudah 2 hari belum buang air besar. Pemeriksaan tanda vital dalam batas normal. Pemeriksaan fisik ditemukan anus normal, perut tampak distensi dan peristaltic meningkat. Pemeriksaan colok dubur didapatkan pergerakan meconium melambat dan obtipasi berulang. Penanganan yang tepat","options":["NGT dapat mengurangi distensi abdomen","Rectal biopsy dapat dilakukan pada keadaan akut","Rectal biopsy harus dilakukan secepatnya untuk diagnosis pasti","abdominal x-ray dan barium enema harus dilakukan setelah kondisi akut ditangani","Pemeriksaan yang tepat untuk diagnosis pasti adalah CT scan abdomen"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Prinsip penanganan pada pasien ini adalah: a.Mengatasi obstruksi b.Membuang segmen aganglionik C.Mengembalikankontinuitas d.Mencegah terjadinyaenterokolitis Tindakan pertamayang dilakukanadalah untuk mengatasiobsruksidengan pemasangan NGT sehingga dapat mengurangi distensi abdomen.","answerPage":158,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-032","number":32,"package":"Paket 2","topic":"Kulit","title":"Soal 032 · Seorang wanita usia 23 tahun datang dengan…","page":113,"stem":"Seorang wanita usia 23 tahun datang dengan keluhan keluar cairan dari vagina, tidak terlalu gatal tetapi berbau amis. Pasien tidak memiliki factor risiko infeksi menular seksual. Diagnosis yang paling tepat adalah...","options":["Vaginits candida","Vaginosis bacterial","Trikomonas vaginalis","Servisitis gonorea","Servisitis bacterial"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien dengan vaginosis bacterial akan mengeluh adanya cairan dari vagina yang ringan atau sedang dan berbau tidak enak (amis).Dapat ditemukan iritasi daerah vagina atau seki- tar vagina (gatal dan terasa terbakar). Lebih ringan daripada yang disebabkan trichomonas vaginalis atau candida albicans.","answerPage":158,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-033","number":33,"package":"Paket 2","topic":"Psikiatri","title":"Soal 033 · Seorang laki-lakiusia34tahun datang dengankeluhan takuttidurkarenadiamerasaakan meninggalsat tertiaieserng…","page":113,"stem":"Seorang laki-lakiusia34tahun datang dengankeluhan takuttidurkarenadiamerasaakan meninggalsat tertiaieserng mencucitangannyaerkal-kalsetiapmeegang bendasejaksatubulanyang laluSebelumnya iaadalah orangyang sangattertibterhadap peraturan. Diagnosis pasien ini adalah..","options":["Reaksi disosiasi","Psikotik somatic","Reaksi konversi","Obsesif kompulsif","Neuritis somatic"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Obesif kompulsif didiagnosis jika terdapat gejala obsesif atau kompulsif atau keduanya, harus ada setiap hari selama sedikitnya dua minggu berturut-turut. Hal tersebut merupakan sumber distress atau mengganggu aktivitas penderita.","answerPage":158,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-034","number":34,"package":"Paket 2","topic":"Campuran","title":"Soal 034 · Penyakit yang disebabkan oleh kekurangan vitamin A…","page":114,"stem":"Penyakit yang disebabkan oleh kekurangan vitamin A adalah..","options":["Rabun dekat","Rabun jauh","Rabun pagi","Rabun senja","Rabun malam"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kekurangan vitamin Apada mata disebut sebagai xeroftalmia,dengan criteria menurut WHO sebagaiberikut: a.Buta senja yaitu bila anak sering jatuh atau salah tangkap benda yang diberikan saat senja b.Bercak bitot,berupabercak berwarna putih berbuih terdiri dari penimbunan selepitel C. Kekeringan pada konjungtivitis merupakan proses perubahan bulbus yaitu kering, tebal,keriput dan terjadi penimbunan pigmen d. Ulkus kornea ≥ 1/3 permukaan e.Jaringanparutpada kornea Xeroftalmiafunfus g. Kekeringan pada kornea (keratomalasia) < 1/3 permukaan akibat keringnya epitel sehingga kejernihan kornea berkurang","answerPage":158,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-035","number":35,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 035 · Seorangwanita dengan Keluhan tunqkai kanannya bengkaksejak2 tahun…","page":114,"stem":"Seorangwanita dengan Keluhan tunqkai kanannya bengkaksejak2 tahun yang lalu. Awalnya timbul edem pitting. belakanqan ini menjadi edema non pitting dan tidak terasa nyeri. Diagnosis pasien ini adalah.„","options":["Edema statis","Thrombosis vena dalam","Gaga! ginjal akut","Litnfedema","Gagal ginjal kronik"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Penegakkandiagnosislfeema adalh berjalannya waktu limfangitis dan selulitis","answerPage":159,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-036","number":36,"package":"Paket 2","topic":"Campuran","title":"Soal 036 · Seorang laki-laki usia 23 tahun senang mengintip…","page":114,"stem":"Seorang laki-laki usia 23 tahun senang mengintip wanita yang sedang mandi untuk mencapai orgasme. Selain itu dia juga senang menonton video porno setiap hari untuk mencapai kepuasan. Kelainan pada pasien ini adalah...","options":["Masokisme","Skopofilia","Fetihisme","Froteurisme","Nekrofilia"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Skopoflia sinonim dengan voyeurism adalah suatu keadaan dimana seseorang harus mengamati tindakan seksual atau ketelanjangan (orang lain) untuk memperoleh rangsangan dan pemuasanseksual.Sering terjadipadalaki-lakidibandingkanperempuan.","answerPage":159,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-037","number":37,"package":"Paket 2","topic":"Campuran","title":"Soal 037 · Seorang Iaki-laki usia 30 tahun datang ke…","page":114,"stem":"Seorang Iaki-laki usia 30 tahun datang ke klinik dokter dengan keluhan pusing berputar. Keluhan ini disertai mual dan penurunan fungsi seksual. Sebelumnya pasien mengkonsumsi obat untuk mengatasi neurosis. Pembicaraan pasien tidak jelas dan tampak bingung serta tidak konsentrasi. Obat yang mungkin menyebabkan kelainan timbul adalah...","options":["Lithium","Haloperidol","Diazepam","Karbamazepin","Klordiazepoksid"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Lithium memiliki efek samping nyeri kepala, kadang bicara tidak jelas, bingung, mual, muntah, diare, tremor kasar, ataxia berat, delirium, kejang dan koma.","answerPage":159,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-038","number":38,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 038 · Seorang anak perempuan usia 8 tahun dibawa…","page":114,"stem":"Seorang anak perempuan usia 8 tahun dibawa Oleh ibunya dengan keluhan sudah mengalami menstruasi lebih awal dibandingkan dengan teman sekolahnya, kuncup payudara juga sudah terbentuk. Wajah berjerawat, rambut pubis dan aksila juga sudah tumbuh. Pada pemeriksaan LH dan FSH meningkat. Diagnosis keadaan ini adalah„.","options":["Tumor adrenal","Tumor hipofisis","Tumor payudara","Pubertas prekoks","Normal"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada perempuan, pubertas diakatakan mengalami prekoks jika kuncup payudara terbentuksebelum usia8 tahun atau jikamenarche terjadi sebelum usia9 tahun.Jika perkembangan ciri kelamin sekunder sama dengan jenis kelamin genetic, yaitu feminisasi pada anakperempuan atauvirilisasipada laki-lakimaka disebutprekoksisoseksual dan sebaliknya jikatidaksesuai maka disebutprekoksheteroseksual. Pubertasprekoksdibedakanmenjadi3yaitu: 1.Pubertasprekokssejaticiri-cirinyaadalahterdapatperkembangancirikelaminsekunder yang terlalu awal,namunurutanperkembangan tersebutseperti perkembangan pubertas normal.Perkembangankuncuppayudara dikuti perkembangan rambut pubiskemudian rambut aksila,kulminasi daripubertas pada perempuan adalah terjadinya siklus menstruasi yang teratur. Pada pubertas ini terjadi aktivasi sekresi gonadotropin pada usia yang terlalu dini. Pada pemeriksaan profil sekresi hormone LH dan FSH meningkat jika dibandingkan dengan anak normal seusianya. Penyebab pada penyakit ini sebagian besar belum diketahui, penyebab lainnya karena penyakit pada otak (tumor, radang, infeksi, dll) yang memicu aktivasi sekresi gonadotropin. 2. Pseudopubertas prekoks terjadi pada anak perempuan yang mengalami feninisasi (pertumbuhan payudara, rambut pubis, dl tanpa mengalami siklus menstruasi yang teratur. Pada anak laki-laki untuk membedakan dengan pubertas prekoks sejatidilakukan pemeriksaan hormone. Penyebab kelainan ini adalah tumor yang mensekresi esterogen atau androgen (pada wanita akhirnya juga akan diubah oleh tubuh menjadi esterogen) misalnya tumorovarium,tumor adrenal, medikasidengan preparat esterogen, dll Bila gonadotropin diperiksa kadarnya akan rendah karena tertekan oleh esterogen atau androgen tersebut. 3. Pubertas prekoks inkomplet, perkembangan pubertas hanya pada satu bagian saja tidak semuanya misalnya hanya mengalami perkembangan payudara saja atau hanya mengalami perkembangan rambut pubis saja atau hanya mengalami perkembangan rambut aksila saja. Penyebabnya adalah peningkatan sekresi esterogen atau peningkatan sensitivitas terhadap esterogen yang sifatnya sementara.","answerPage":159,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-039","number":39,"package":"Paket 2","topic":"Campuran","title":"Soal 039 · Seorang anak Iaki-taki usia4 tahun dibawa ibunya…","page":114,"stem":"Seorang anak Iaki-taki usia4 tahun dibawa ibunya karena mengeluh pada senja hari tidak","options":["dapat melihat dan jika menangkap benda selalu Jatuh. Dokter mendiagnosis pasien ini karena kekurangan vitamin A. Dosis pemberian vitamin A untuk usia 1-5 tahun","100.000 Sl","150.000 Sl","200.000","250.000 Sl"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dosis cara pemberian kapsul vitamin A dosis tinggi: Dosis Pemberian (kali/ Keterangan KelompokSasaran tahun) 200.000SI 2 Februari Anak balita 200.000SI 1 Agustus Ibu nifas","answerPage":160,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-040","number":40,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 040 · seorang wanita usia 25 tahun sedang menyusui…","page":115,"stem":"seorang wanita usia 25 tahun sedang menyusui ingin memasang alat kontrasepsi, Pasien belum pernah menstruasi setelah melahirkan 3 bulan yang lalu dan ingin memberikan ASI eksklusif. Metode kontrasepsi yang tepat adalah„.","options":["Suntikan selama 1 bulan","Patch esterogen+progesterone","Pil esterogen","Lactation amenorrhea method (LAM) sampai dengan bayi berumu 6 butan","Pil esterogen+progesterone"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien hendak melanjutkan ASl eksklusif sehingga dapat dilakukan metode kontrasepsi alami.","answerPage":160,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-041","number":41,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 041 · Seorang wanita usia 25 tahun GI POAO…","page":115,"stem":"Seorang wanita usia 25 tahun GI POAO usia kehamilan 8 minggu mengeluh mual sejak4 minggu yang lalu dan muntah hebat sejak 2 hari yang lalu. la muntah bercampur darah segar 4 jam yang lalu dan merasa nyeri pada ulu hati. Pemeriksaan vital sign didapatkan TD 100/70, nadi 98x/menit, RR 24 x/menit. Pemeriksaan abdomen didapatkan nyeri tekan pada epigastrium. Pemeriksaan darah lengkap didapatkan Hb 10,1 mg/dl, leukosit 13.000/mm, trombosit 219.000/mm, SGOT 43, SGPT 39. Diagnosis pasien ini adalahm","options":["Ruptur varises esophagus","Angiodisplasia","Gastritis erosive","Ulkus peptikum","Hiperemis gravidarum dengan Mallory-Weiss tear"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala dan tanda hiperemesis gravidarum: Batasan antara mual yang masih fisiologik dalam kehamilan dengan hiperemesis gravidarum tidak ada, tetapi bila keadaan umum penderita terpengaruh sebaiknya dianggap hiperemesis gravidarum. Terdapat 3 tingkatan yaitu : a. Tingkat I: Muntah terus menerus, lemah, nafsu makan berkurang, berat badan turun dan nyeri epigastrium, takikardi, tekanan darah menurun, turgor kulit berkurang, lidahmongering dan matacekung b. Tingkat Il : lemah dan apatis, turgor kulit lebih berkurang, lidah mongering dan tampak kotor, denyut nadi kecil dan cepat, suhu kadang naik dan tampak ikterik,berat badan turun dan mata cekung, tekanan darah turun, hemokonsentrasi, oliguria dan konstipasi, aseton tercium dalam pernafasan dan urin Tingkat Ill : Keadaan umum lebih parah, muntah berhenti, kesadaran menurun dari somnolen sampai koma, denyut nadi kecil dan cepat, suhu badan meningkat, tekanan darah menurun. Komplikasi fatal terjadi pada SSP : encefalopati wernicke (nistagmus, diplopia dan perubahan mental). Pada pasien initerdapat keluhanmuntah darahkarena terjadirobekan padaselaputlendir esophagus dan lambung (sindrom Mallory-weiss), yang mengakibatkan perdarahan gastrointestinal. Umumnya robekan ringan dan perdarahan berhenti sendiri.","answerPage":160,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-042","number":42,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 042 · Seorang wanita usia 34 tahun G3PIAI usia…","page":115,"stem":"Seorang wanita usia 34 tahun G3PIAI usia kehamilan 38 minggu datang dengan keluhan merasa mulas sejak tiga jam yang lalu. Dokter akan melakukan pemantauan kontraksi uterus. Di manakah posisi tangan saat diletakan pada perut ibu untuk memantau kontraksi uterus?","options":["Atas simfisis","Funfus uteri","Sisi perut ibu","Sekitar pusat ibu","Pinggang janin"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kontraksi uterus (his) karena otot-otot rahim bekerja dengan baik dan sempurna dengan sifat kontraksi simetris, fundus dominan kemudian, dan dikuti relaksasi. Pusat koordinasi his berada pada uterus di sudut tuba, dimana gelombang his berasal. His yang sempurna mempunyai kekuatan paling tinggi di fundus uterus. Untuk memantau his, tangan diletakkan pada daerah yang memiliki jaringan longgar di sekitar pusar, dekat fundus uteri.","answerPage":161,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-043","number":43,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 043 · Seorang wanita usia 28 tahun dating dengan…","page":115,"stem":"Seorang wanita usia 28 tahun dating dengan keluhan terdapat benjolan pada leher bagian depan. Pasien tidak mengeluh sering berkeringat dan jantung tidak berdebar- debar.Sekitar 1 minggu yang lalu pasien menderita nyeridandemam Pada pemeriksaan vital sign dalam batas normal. Pemeriksaan lokalis terdapat massa bulat kenyal. mudah digerakan ukuran 3 x3 x 2 cm, pada saat menelan ikut bergerak. Pemeriksaan laboratorium didapatkan leukositosis, LED meningkat, T3 dan T4 meningkat. Diagnosis yang tepat pada pasien ini adalah...","options":["Goiter nodosa toksik","Goiter nodosa non toksik","Goiter difusa toksik","Tiroiditis akut","Karsinona tiroid"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tiroiditis akut ditandai dengan gejala yang menonjol yaitu nyeri pada tiroid seringkali menjalar hingga tenggorokan dan telinga. Pasien mengalami nyeri telan, juga dapat ditemukan kemerahan di kulit di atas kelenjar tiroid. Terdapat gejala sistemik demam dan limfadenopati.Tiroiditis akut sebagianbesar disebabkan olehinfeksi supurasi pada kelenjar tiroid.Pada anak dan dewasa muda disebabkan karena adanya sinus piriformis (sisa “fourth branchial pouch\") yang menjadi jalan masuk berbagai kuman yang dapat menginfeksi kelenjar tiroid. Pada lanjut usia factor risiko terjadinya penyakit ini adalah goiter (pembesaran kelenjar tiroid) yang berlangsung lama dan keganasan tiroid.","answerPage":161,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-044","number":44,"package":"Paket 2","topic":"Campuran","title":"Soal 044 · Seorang wanita usia 24 tahun post partum…","page":116,"stem":"Seorang wanita usia 24 tahun post partum 2 minggu yang lalu datang dengan terdapat pembengkakan pada payudara kanan sejak 5 hari yang lalu. Pada pemeriEaan terdapat demam dan payudara bengkak, merah dan nyeri. Diagnosisnya adalah„.","options":["FAM (fibroadenoma mammae)","Abses payudara kanan","Filoides","Fibroki5tik","Ca Mammae"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Abses payudara umum terjadi pada wanita hamil primigravida dan terjadi pada saat menyusui yang terjadi akibat trauma pada putting susu dan dikuti oleh infeksi organism (Staphylococcus aureus, S.epidermidis) dari hidung bayi ke payudara ibu.Biasanya terjadi 1 minggu atau lebih setelah melahirkan. Sering hanya satu payudara yang terkena dengan gejala nyeri, kemerahan, bengkak dan teraba panas. Pasien akan mengeluh demam dan kelihatan kesakitan. Pada pemeriksaan laboratorium didapatkan leukositosis. Penanganannya perlu insisi drainase serta pemberian antibiotik (kloksasilin, dkloksasilin, nafsilin, sefalosporin). Untuk sementara menyusui dihentikan pada payudara dengan abses, tetapi ASl harus tetap dipompa.","answerPage":161,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-045","number":45,"package":"Paket 2","topic":"Mata","title":"Soal 045 · Seorang Iaki-laki usia 34 tahun datang dengan…","page":116,"stem":"Seorang Iaki-laki usia 34 tahun datang dengan keluhan penglihatan kabur mendadak, lensa tiba-tiba menjadi putih dengan cepat dan mata merah. Pada pemeriksaan slit lamp setelah diteteskan midriatik terlihat lensa posterior berbentuk bintang. Pasien adalah seorang pekerja industry. Diagnosis apa yang mungkin terjadi pada pasien ini?","options":["Uveitis","Katarak traumatic","Katarak senilis","Skleritis","Dislokasi lensa"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Uveitisbentuk nongranulomata memiiki gejala klinis yang khasdengan rasa sakit injeksi, fotofobiadan penglihatan kaburyang onsetnyaakut Terdapat kemerahan sirkumkorneal yang disebabkan dilatasi pembuluh darah daerah limbus. Deposit putih halus (presipit keratik) pada permukaan posterior kornea dapat dilihat dengan slitlamp. Pupilnya kecil dan mungkin terdapat kumpulan fbrin dengan sel pada kamera anterior Jjika terdapat sinekia posterior bentuk pupil tidak teratur (mirip seperti bintang) maka gejala pada pasienmengarahkediagnosisuveitis.","answerPage":162,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-046","number":46,"package":"Paket 2","topic":"Kulit","title":"Soal 046 · Seorang wanita usia45 tahun menderita diabetes mellitus…","page":116,"stem":"Seorang wanita usia45 tahun menderita diabetes mellitus sejak5 tahun yang lalu, datang dengan keluhan keputihan dan terasa gatal sejak 2 bulan yang lalu. Pada pemeriksaan didapatkan mukosa vulva dan vagina hiperemis, maserasi, serviks edema, hiperemis dan erosi serta fluor albus berwarna putih kental seperti susu. Diagnosis klinis pada pasien ini adalah.„","options":["Vulvovaginitis candida","Vulvovaginitis trikomonas","Servisitis bacterial","Servisitis klamidial","Servisitis gonorrhea"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Keluhan utama pada vulvovaginits candida adalah gatal di daerah vulva. Pada keadaan berat dapat terjadi rasa paans dan nyeri sesudah buang air kecil juga nyeri saat berhubungan seksual.Vulvovaginitiscandida biasanya ditemukan pada penderita dengan sistem kekebalan tubuh yang menurun,yaitu pada penderita diabetes melitus, defisiensi imun dan wanita hamil. Pada pemeriksaan tampak hiperemis di labia minora, introitus vagina terutama sepertiga vagina bagian luar. Kelainan yang khas adalah terdapat bercak putih kekuningan. Pada kelainan berat terdapat edema pada labia minora dan ulkus yang dangkal pada labia minora dan sekitar introitus vagina. Tanda khas pada fluor albus berwarna kekuningan disertai gumpalan seperti susu. Gumpalan tersebut berasal dari massa yang terlepas dari dinding vulva atau vagina yang terdiri dari bahan nekrotik, sel epitel dan jamur.","answerPage":162,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-047","number":47,"package":"Paket 2","topic":"Campuran","title":"Soal 047 · Paket 2","page":116,"stem":"Hormon yang menyebabkan folikel terisi cairan","options":["LH","FSH","Esterogen","Progesteron","Oksitosin"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"FSH merupakan hormonyang dihasilkan oleh hipofisis anterioryang bertanggungjawab untukmaturasiawalfolikelovarium.","answerPage":162,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-048","number":48,"package":"Paket 2","topic":"Psikiatri","title":"Soal 048 · Seorang wanita usia 35 tahun dating dengan…","page":116,"stem":"Seorang wanita usia 35 tahun dating dengan keluhan sulit tidur, nafsu makan berkurang' jantung berdebar-debar, nafas terasa berat dan sesak, lemah dan mudah tersinggung. Dia tinggal bersama 2 anaknya, suaminya sering pergi keluar kota dan hanya pulang setiap I bulan sekali. Pada pemeriksaan fisik dan laboratorium semuanya menunjukkan hasil yang normal. Diagnosis apa yang paling mungkin?","options":["Depresi","Cemas menyeluruh","Fobia sosial","Gangguan bipolar","Psikosomatik"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gangguan cemas menyeluruh adalah suatu kekhawatiran secara berlebihan dan dihayati yang disertai berbagai gejala somatik yang menyebabkan gangguan bermakna dalam fungsi sosial atau pekerjaan atau penderitaan yang jelas bagi pasien. Gejalanya adalah kecemasan motorik (Sesak nafas, keringat berlebih, palpitasi, gejala gastrointestinal), hiperaktivitas otonom, dan kewaspadaankognitif.","answerPage":162,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-049","number":49,"package":"Paket 2","topic":"Campuran","title":"Soal 049 · seorang wanita usia 23 tahun datang dengan…","page":117,"stem":"seorang wanita usia 23 tahun datang dengan keluhan terdapat benjolan pada kuadran lateral bawah payudara kanan sejak 3 bulan yang lalu. Pada pemeriksaan vital sign TD 110/70, nadi 80x/menit, RR 20x/menit, suhu 360C. Pemeriksaan lokalis terdapat massa berdiameter 2 cm, berbentuk oval, padat halus dan mobile pada payudara tersebut. Tidak terdapat pembesaran kelenjar gentah bening aksila. Jika biopsy eksisi dilakukan pada benjolan tersebut maka kemungkinan besar akan menunjukkan tanda-tanda penyakit?","options":["Fibroadenoma","Nekrosis lemak","Kelainan fibrokistik payudara","Papiloma intraductal","Karsinoma intraductal"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Fibroadenoma Mammae (FAM) sering terjadi pada wanita muda, sekitar usia 20an. Pada pemeriksaan fisik terdapat benjolan bulat, berbatas tegas, dan relatif mobile, tidak nyeri dengan diameter 1-5 cm.Tumor ini berhubungan dengan kadar hormon wanita dalam darah, dapat soliter maupun multiple, gampang digerakkan, sama sekali bebas dari jaringan di sekitarnyadanbesarnya tidakberubah,dengansiklusmenstruasi dan putig susu tidak memerlihatkan adanya perubahan.Pengobatan terbaik adalahbiopsi dan eksisi. Sering dijumpai penyakit kistik simultan dengan terjadinya FAM karena keduanya sama-sama dipengaruhi estrogen.","answerPage":162,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-050","number":50,"package":"Paket 2","topic":"Campuran","title":"Soal 050 · Seorang laki-laki usia 55 tahun dating dengan…","page":117,"stem":"Seorang laki-laki usia 55 tahun dating dengan keluhanadanya tumor pada paha kanannya yang sudah diderita selama 3 bulan. Pada pemeriksaan tampak tumor berdiameter 10 cm, konsistensi padat kenyal, dan fixed. Pada pemeriksaan foto rontgen tampak gambaran tumor mesenkimal setempat yang sudah menimbulkan erosi pada tulang paha. Pemeriksaan biopsy tampak gambaran sei-sel fibroblastic yang pleomorfik yang tersusun storiform. Diagnosis mana yang paling tepat?","options":["Fibrosarcoma","Liposarcoma","Malignant fibrous histiocytoma","Ewing's sarcoma","Alveolar rhabdomyosarcoma"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Histiositoma fbrous malignan adalah salah satu sarcoma yang paling sering terjadi pada usia dewasa, merujuk pada suatu grup tumor jaringan lunak yang heterogen dan agresif yang ditandai dengan adanya gambaran sel yang pleomorfk, adanya sel bizzare multinucleated, membentuk arsitektur storiform dan terdapat stoma kolagen yang meradang dan kadang tampak makrofag dengan sitoplasma bervakuola.","answerPage":163,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-051","number":51,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 051 · Seorang Iaki-laki usia 23 tahun datang ke…","page":117,"stem":"Seorang Iaki-laki usia 23 tahun datang ke puskesmas dengan keluhan badan panas sejak 4 hari yang lalu. Pemeriksaan laboratorium menunjukkan pasien ini terkena DBD (demam berdarah dengue). Dokter kemudian memeriksa seluruh keluarganya yang mengeluh demam. Tindakan dokter puskesmas ini termasuk dalam...","options":["Promp treatment","Deteksi dini","Disability limitation","Pencegahan primer","Pencegahan tersier"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus ini dokter memeriksa seluruh keluarga pasien yang mengeluh demam untuk mengetahui sedini mungkin apakah terkena DBD atau tidak. Tindakan pencegahan sekunder meliputi: a.Deteksi dini b. General check up rutin c.Selective survei d.Keteraturan pengobatanuntukpenyakit kronik e.Terapiadekuatuntukkasusawal Pencegahansekunderberperandalammendeteksipenyakitpadasaatawalpenyakit tersebutmasihasimptomatikdanpadasaatterapiawalagardapatmencegahprogresivitas penyakit.Selain itujuga berfungsi sebagaiskrining untuk mengidentifkasipenyakit atau adanyafaktorrisikosuatupenyakit.","answerPage":163,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-052","number":52,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 052 · Seorang Iaki-laki usia 50 tahun 3 bulan…","page":117,"stem":"Seorang Iaki-laki usia 50 tahun 3 bulan lalu terserang infark miokard. Hasil pemeriksaan laboratorium menunjukkan adanya LDL 176 mg/dl, HDL 45 mg/dl, kolesterol total 267 mg/dl dan trigliserid 153 mg/dl. Manakan terapi yang tepat untuk pasien ini?","options":["Fibrat","Statin","Asam nikotinat","Kolestiramin","Asam lemak omega 3"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"a.Golongan statin mengurangi produksi kolesterol di hati, menurunkan kadar LDL hingga 35% dan menaikkan kadar HDL. Golongan ini digunakan untuk pencegahan sekunder terhadap infark miokard dan menurunkan mortalitas karena infark. b. Golongan fibrat menurunkan kadar LDL sebesar 10-15%, menurunkan kadar trigliserida hingga 40% dan menaikkan kadar HDL sebesar 15-20%. Asam nikotinat mengurangi produksi VLDL, LDL, dan menaikkan kadar HDL. C. Kolestiramin menurunkan kadar LDL sebesar 15-25%, namun tidak berefek pada kadar HDL dan cenderung menaikkan trigliserida d.Asam lemak omega 3 tidak digunakan untuk terapi menurunkan lemak","answerPage":163,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-053","number":53,"package":"Paket 2","topic":"Mata","title":"Soal 053 · Diagnosis yang paling mungkin jika terdapat ulkus…","page":117,"stem":"Diagnosis yang paling mungkin jika terdapat ulkus kornea peripheral adalah„.","options":["Ulkus moraxela","Ulkus fungi","Ulkus mooren","Ulkus geografian","Ulkus karena trauma"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Ulkus kornea berdasarkan letaknya dibedakan menjadi 2 yaitu : a. Ulkus sentral : etiologi Staphylococcus aureus, Streptococcus, Pneumococcus, Pseudomonas,danMoxarella b. Ulkus marginal atau peripheral : bisa terjadi pada ulkus bacterial yang disebabkan oleh Staphylococcus atau pada ulkus mooren (karena autoimun)","answerPage":164,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-054","number":54,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 054 · Seorang wanita usia 55 tahun dengan obesitas…","page":118,"stem":"Seorang wanita usia 55 tahun dengan obesitas memiliki riwayat dirawat I yang lalu karena infark miokard. sejak itu menjalani diet rendah lemak secara terdapat riwayat hipertensi dan DM. Pemeriksaan laboratorium menunjukkan total 230 mg/dl, trigliserida 160 mg/dl, HDL 52 mg/dl dan LDL 140 mg/dl. saran pasien ini","options":["Memberikan obat golongan statin","Meneruskan diet tanpa tambahan obat","Memberikan derivate asana fibrat, seperti gemfibrozil","Memberikan kombinasi statin dan gemfibrozil","Memberikan niasin/asam nikotinat"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Golongan statin mengurangi produksi kolesteroldihati, menurunkan kadar LDLhingga 35% dan menaikkan kadar HDL. Golongan ini digunakan untuk menstabilkan plak, pencegahan sekunderterhadap infark miokard dan menurunkan mortalitas karena infark.","answerPage":164,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-055","number":55,"package":"Paket 2","topic":"THT","title":"Soal 055 · Seorang wanita usia 34 tahun datang dengan…","page":118,"stem":"Seorang wanita usia 34 tahun datang dengan keluhan telinga terasa nyeri yang sejak3 hari yang lalu, tidak terdapat keluhan penurunan pendengaran. Pada otoskopi tidak ditemukan perforasi. Diagnosis yang tepat pada pasien ini","options":["Otitis eksterna difus","Otitis eksterna sirkumskripta","Perikondritis","Otitis media serosa akut","Otitis media supurativa kronik"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada otitis eksterna sirkumskripta terdapat gejala rasa nyeri yang hebat (tidak sesuai dengan besarnya furunkel yang terbentuk), karena kulit tiang telinga tidak mengandung jaringan longgar dibawahnya sehingga rasa nyeri timbul pada penekanan perikondrium. Gangguan pendengaran terjadi bila furunkel yang terbentuk besar dan menyumbat liang telinga.","answerPage":164,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-056","number":56,"package":"Paket 2","topic":"Campuran","title":"Soal 056 · Seorang Iaki-laki usia 30 tahun diantar ke…","page":118,"stem":"Seorang Iaki-laki usia 30 tahun diantar ke IGD Rumah sakit setelah tertusuk Pisau di bagian dada sebelah payudara kiri. pada pemeriksaan vital sign TD 70/50 mmHg. Vena leher tampak melebar, suara vesicular normal pada kedua paru. Tindakan berikutnya yang paling tepat adalah.„","options":["EKG","Foto rontgen thoraks","Intubasi endotrakeal","Insersi tabung pada kavum thoraks sebelah kiri","Perikardiosentesis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Diagnosis kasus ini adalah efusipericardial atau temponadekordis yang menyebabkan low input failurekarena jantungpada saatdiastolictidak dapatmengembangsecara maksimal.Tindakan pertama yang dilakukan adalah perikardiosentesis.","answerPage":164,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-057","number":57,"package":"Paket 2","topic":"THT","title":"Soal 057 · Seorang anak perempuan usia 6 tahun datang…","page":118,"stem":"Seorang anak perempuan usia 6 tahun datang dengan keluhan nyeri pada telinga kanan, lemah, nafsu makan menurun. Pemeriksaan vital sign nadi 98x/menit, RR 18x/menit dan suhu 38 'C. Pemeriksaan otoskopi didapatkan membrane timpani merah menonjol, tidak ditemukan perforasi. Diagnosis kelainan ini adalah...","options":["Otitis media kronik","Otitis media serosa akut","Furunkel","Miringitis","Otitis media serosa"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Stadium Otitis media supuratif : a. Stadium hiperemis (seluruh membrane timpani tampak hiperemis dan edema), b. Stadium supurasi (terbentuk eksudat purulen sehingga membrana timpani tampak menonjol), C. Stadium perforasi (membrana timpani ruptur dan pus keluar).Pada stadium ini telinga akanterasasangatnyeri,nadidansuhumeningkat. d. Stadium resolusi (sekret berkurang, membrana timpani menjadi normal, perforasi menutup)","answerPage":164,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-058","number":58,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 058 · Seorang bayi Iaki-laki baru Jahir mengalami labiognatopalatoskisis.…","page":118,"stem":"Seorang bayi Iaki-laki baru Jahir mengalami labiognatopalatoskisis. Berat badan bayi 3500 gr, tidak terdapat kelainan bawaan Iain. Kedua orang tuanya sehat, tidak memiliki riwayat cacat bawaan. Yang paling mungkin menjadi factor kelainan bawaan tersebut kecuali•-","options":["Faktor genetik","Kekurangan zat besi","Trauma pada kehamilan","Penggunaan fenitoin","Terjadi radiasi sinar X pada kehamilan ibunya"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Faktor risiko terjadinya labiognatopalatoskis atara lain genetik (abnormalitas pada dan kekurangan nutrien (asam folat).","answerPage":165,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-059","number":59,"package":"Paket 2","topic":"Mata","title":"Soal 059 · Q. Seorang laki-laki 25 tahun datang dengan…","page":119,"stem":"Q. Seorang laki-laki 25 tahun datang dengan keluhan kedua matanya merah sejak kurang i; lebih 3 hari yang lalu, saat bangun pagi matanya sulit dibuka karena lengket dan terdapat kotoran putih yang lengket. Sebelumnya pasien menggunakan tetes mata yang ia beli diwarung 3x1 tetes/hari. Pada pemeriksaan visus didapatkan ODS 5/5, pemeriksaan fisik mata palpebra edem, konjungtiva kemosis berat, dan kornea jernih. Pemeriksaan Iain dalam batas normal. Kemungkinan penyebab penyakit ini","options":["Virus","Bakteri Terpapar bahan toksis","DM","Alergi","Jamur"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Semua faktor risiko yang ada pada kasus ini berperan terhadap penyakit jantung koroner. Namun, faktor risiko tertinggi adalah LDL.","answerPage":165,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-060","number":60,"package":"Paket 2","topic":"Mata","title":"Soal 060 · seorang laki-laki 25 tahun datang dengan keluhan…","page":119,"stem":"seorang laki-laki 25 tahun datang dengan keluhan kedua matanya merah sejak kurang lebih 3 hari yang lalu, saat bangun pagi matanya sulit dibuka karena lengket dan terdapat kotoran putih yang lengket. Sebelumnya pasien menggunakan tetes mata yang ia beli diwarung 3x1 tetes/hari. Pada pemeriksaan visus didapatkan ODS 5/5, pemeriksaan fisik mata palpebra edem, konjungtiva kemosis berat, dan kornea jernih. Pemeriksaan Iain dalam batas normal. Kemungkinan penyebab penyakit ini","options":["Virus","Bakteri","Terpapar bahan toksis","Alergi","Jamur"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus ini pasien mengeluh mata merah, visus tidak turun, sekresi mukopurulen sat bangun tidur terasa lengket pada pemeriksan fisik mata terdapat edem palpebra dan konjungtiva hiperemis sehingga mengarah pada diagnosis konjungtivitis bacterial.","answerPage":165,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-061","number":61,"package":"Paket 2","topic":"Campuran","title":"Soal 061 · Seorang anak perempuan usia 7 tahun datang…","page":119,"stem":"Seorang anak perempuan usia 7 tahun datang ke IGD dibawa ibunya dengan keluhan demam tinggi sejak lima hari yang lalu.Pasien juga mengeluh tidak mau makan dan minum.Pemeriksaanvital signdidapatkanNadi88x/menit,RR20x/menit,suhu38,6°℃. Pemeriksaan fisik didapatkan gejala dehidrasiberat.Hasil pemeriksaan laboratorium urine didapatkan bakteri penuh dan leukosit 100.000/mm. Penatalaksanaan yang sebaiknya diberikan adalah...","options":["Berikan amoxicillin dan mulai rehidrasi oral","Antibiotik","Pasang infuse untuk antibiotik IV dan rehidrasi","Ceftriaxon IM, besok control kembali","Ceftriaxone IV, besok control kembali"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus ini pasien mengalami dehidrasi dan infeksi pada saluran kemih. Ini dibuktikan dengan ditemukannya bakteri penuh dan leukosit 100.000/mm? pada urine. Penatalaksanaan yang dilakukan adalah pemasangan IV line untuk terapi dehidrasi dan untuk memasukkan antibiotik.","answerPage":165,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-062","number":62,"package":"Paket 2","topic":"Campuran","title":"Soal 062 · Seorang Iaki-laki usia 27 tahun telah terdiagnosis…","page":119,"stem":"Seorang Iaki-laki usia 27 tahun telah terdiagnosis Oleh dokter terkena HIV (+), CD4 250, 5 minggu yang lalu mendapat terapi inhibitor reserve transcriptase dan reverse protease. Pasien mengeluh lemas dan mudah lelah. Pada pemeriksaan laboratorium Hb awal 12 turun menjadi 8. Yang paling mungkin menyebakan anemia","options":["Menurunnya produksi eritrosit","Meningkatnya antibodi eritrosit","Meningkatnya fragilitas eritrosit","Defisiensi folat","Menurunnnya antibodi eritrosit"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Efek samping terapi dengan inhibitor reserve transcriptase pada penderita Hiv/AIDS antara lain nyeri kepala,lemah,intoleransi saluran cerna,insomnia,anemia,neutropenia serta penekanan sumsum tulang yang tergantung dosis miopati, peningkatan enzim keratin fosfokinase (creatine phospokinase, CPK), hepatitis,kardiomiopati, dan perubahan warna kuku.Pada pasien ini anemia disebabkan oleh penekanan sumsum tulang.","answerPage":165,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-063","number":63,"package":"Paket 2","topic":"Mata","title":"Soal 063 · wanita usia 60 tahun datang ke tempat…","page":120,"stem":"wanita usia 60 tahun datang ke tempat praktik dokter dengan penqlihatan terasa kabur pada mata kanannya.Terasa nyeri, seperti melihat Pelangi, clan muntah, Sebelumnya mata kanan normal visus 2/60, tekanan N+3, hiperernis, edema pupil midriasis, dan bilik dangkal. Diagnosis pasien ini adalah...","options":["Glaucoma sudut tertutup akut","Glaucoma sudut terbuka","Glaucoma absolut","Glaucoma sekunder Glaucoma suclut tertutup akut","Glaucoma maligna"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Keluhan mata nyeri dan pandangan kabur, seperti melihat pelangi disertai mual muntah merupakan gejala glaucoma akut. Pada pemeriksaan mata yang terkena visus akan sangat turun karena kekeruhan kornea (edema kornea), injeksi perikorneal, COA dangkal dan pupil midriasis, serta pemeriksaan Ti0 N+3 (meningkat) mendukung diagnosis glaukoma akut sudut tertutup.","answerPage":165,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-064","number":64,"package":"Paket 2","topic":"Campuran","title":"Soal 064 · Seorang laki-laki usia 40 tahun dibawa istrinya…","page":120,"stem":"Seorang laki-laki usia 40 tahun dibawa istrinya ke IGD rumah sakit dengan keluhan memasukan kawat ke dalam alat kelaminnya. Saat kawat dikeluarkan timbul rasa sakit dan kawat tidak dapat dikeluarkan. Penderita sudah sering melakukan hal ini karena menimbulkan rasa nikmat. Menurut laporan isterinya sejak 1 tahun yang lalu suaminya sering mengikat penisnya dengan tali dan menusuk penisnya dengan kawat hingga berclarah. Penderita merasa nikmat jika melakukan hal tersebut. Gangguan apa yang dialami pasien ini?","options":["Fetishime","Masokisme","Pedofilia","Ekshibionisme","Disfungsi orgasme"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Masokisme adalahkesenangan yang diperoleh dar rasa nyeri fsik atau psikologi yabg dibuat oleh dirinya sendiri atau orang lain terhadap dirinya.","answerPage":166,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-065","number":65,"package":"Paket 2","topic":"Neurologi","title":"Soal 065 · Berikut ini yang benar mengenai delirium adalah...…","page":120,"stem":"Berikut ini yang benar mengenai delirium adalah...","options":["Terdapat fluktuasi kesadaran","Gejala lebih hebat pada Siang hari","Penderita dapat berorientasi dengan waktu","Gejala mereda pada malam hari","Tidak satupun pernyataan di atas yang benar"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Delirium merupakan keadaan akut yang reversible disebabkan karena gangguan fungsi otak, merupakan sindrom otak organic akut dengan gejala utama kesadaran menurun, gelisah, kebingungan,lusi halusinasi, dan waham serta sering juga terdapat emosi yang labil dengankecemasan dan agitasi.","answerPage":166,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-066","number":66,"package":"Paket 2","topic":"Anak","title":"Soal 066 · Seorang ibu membawa bayinya ke rumah sakit…","page":120,"stem":"Seorang ibu membawa bayinya ke rumah sakit dengan Ciri bentuk kepala lebih kecil dari anak seusianya, facies mongoloid, terdapat garis simian yang jelas pada telapak tangan, Iidah menonjol keluar. Diagnosis yang tepat untuk pasien ini adalah„.","options":["Sindrom turner","Sindrom Jacob","Sindrom klinefelter","Sindrom patau","Sindrom down"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tanda-tandasindromdown: a.Bentuk kepala yang relatif lebih kecil dari normal (mikrosefali) b.Adanya bentuk wajah yang khas (facies mongoloid) C. Adanya garis melintang pada telapak tangan (simian crease) d. Sela hidung yang datar, mulut kecil dan lidah menonjol keluar (makroglosia) e Mata sipit dengan sudut bagian tengah membentuk lipatan (epichantal fold) f. Tangan yang pendek termasuk ruas jari-jarinya dan jarak antara jari ke 1 dan ke 2 melebar, baik pada tangan dan kaki g.Lapisan kulit tampak keriput (dermatogliphic) h. Tinggi badan relatif pendek, mulut mengecil dan hidung mendatar menyerupai orang Mongolia(faciesmongoloid)","answerPage":166,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-067","number":67,"package":"Paket 2","topic":"Neurologi","title":"Soal 067 · Seorang anak Iaki-laki usia 2 tahun dibawa…","page":120,"stem":"Seorang anak Iaki-laki usia 2 tahun dibawa ibunya karena kejang selama 15 menit• Kemudian berulang dalam 1 jam kemudian. Selama batas kejang, anak sadar. pemeriksaan fisik Nadi 90x/menit, RR 20x/menit, suhu 400C. Diagnosis pasien ini adalah...","options":["Kejang demam simplek","Kejang demam yang tidak biasa","Kejang demam kompleks","Kejang dengan demam","Epilepsi"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Ciri-ciri kejang demamkompleks sebagai berikut: a. Kejang lama > 15 menit, kejang berulang lebih dari 2 kali. Pada saat kejang pasien tidak sadar.Kejang lama terjadi pada 8 % kejang demam. b. Kejang fokal atau parsial satu sisi atau kejang umum didahului kejang parsial .Kejang berulang atau lebih dari satu kali dalam 24 jam. Kejang berulang adalah kejang 2 kali atau lebih dari 1 kali(diantara 2 bangkitan kejang anak sadar. Kejang berulang terjadi pada 16% diantara anak yang mengalami kejang demam.","answerPage":166,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-068","number":68,"package":"Paket 2","topic":"Campuran","title":"Soal 068 · Wanita 18 tahun datang dengan benjolan di…","page":121,"stem":"Wanita 18 tahun datang dengan benjolan di perut bagian kiri. Pemeriksaan patologi anatomi dari biopsi menunjukkan adanya tulang, tulang rawan, sel glioma otak, dan ependimoma. Apakah diagnosis pasien?","options":["Teratoma ganas","Teratoma jinak","Tumor yolk sac","Tumor sel granulose","Teratoma campuran"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Teratoma ganas berukuran besar dan memiliki permukaan luar yang halus. Pada pembelahan memiliki struktur yang padat, terdapat area nekrosis dan hemoragik. Dapat ditemukan rambt,tlang rwan, dankalsikasiemeriksan mikroskopik mengandung sejumlah jaringan matuyang erdifensiasimenjad kailao,kelenjar, tlang t, saraf dan yang lainnya. Sering terjadi padausia prapubertas danwanitamuda rataata usia 18 tahun.","answerPage":166,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-069","number":69,"package":"Paket 2","topic":"THT","title":"Soal 069 · setelah peristiwa tersebut Ia mengeluh keluar cairan…","page":121,"stem":"setelah peristiwa tersebut Ia mengeluh keluar cairan dari hidungnya secara terus menerus, cairan tersebut kemungkinan besar berasal darl? Cavum cranii d. Sinus frontalis b. Sinus maksilaris e. Sinus sfenoidalis Sekresi mukosa hidung c. 5eorang laki-laki usia 30 tahun datang ke puskesmas dengan keluhan terdapat benjolan 10. di leher, tidak nyeri, kenyal dan berdlameter IXI cm. pemeriksaan vital sign TD 110/80 mmHg, Nadi 88x/menit, RR 20x/menit, suhu 37 oc. Pada pemeriksaan laboratorium Hb 13.5 g/dJ, leukosit 13.800/mmJ. Perlu dlketahui pasien ini sering makan daging sate setengah matang. Yang paling mungkin diderita Oleh pasien ini adalah...","options":["Infeksi HIV","Limfoma","Toksoplasmosis","Tuberculosis","Infeksi banal"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Sinus paranasalberisiudara sedangkan yang keluar darihidung adalahcairan sehingga tidak mungkin berasal dari sinus paranasal. Cairan yang keluar dari rongga hidung akibat trauma pada wajah dapat berupa darah atau liquor cerebrospinal. Perdarahan (epistaksis) dapat dibagi menjadi epistaksis anterior (dari pleksus kiesslbach) ataupun posterior (daria.etmoidalis posterior). Pada trauma wajah fraktur os nasal sering disertai fraktur pada bagian cranium lainnya. Cairan jernih yang mengalir dari hidung mungkin menunjukan kebocoran cairan serebrospinal karena fraktur basis crani. Fraktur basis crani yang disertai robekan duramater dan arakhnoid dapat menyebabkan cairan otak keluar melalui kedua lubang hidung.","answerPage":167,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-070","number":70,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 070 · eorang laki-laki usia 30 tahun datang ke…","page":121,"stem":"eorang laki-laki usia 30 tahun datang ke puskesmas dengan keluhan terdapat benjolan 10. di leher, tidak nyeri, kenyal dan berdlameter IXI cm. pemeriksaan vital sign TD 110/80 mmHg, Nadi 88x/menit, RR 20x/menit, suhu 37 oc. Pada pemeriksaan laboratorium Hb 13.5 g/dJ, leukosit 13.800/mmJ. Perlu dlketahui pasien ini sering makan daging sate setengah matang. Yang paling mungkin diderita Oleh pasien ini adalah...","options":["Infeksi HIV","Limfoma","Toksoplasmosis","Tuberculosis","Infeksi banal"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Toksoplasmosis pada pasien imunokompeten dapat memberikan gambaran pembesaran limfonodi servikal yang khas, biasanya tidak nyeri dan nodusnya berdiameter kurang dari 3 cm. Didapatkan tanda-tanda infeksi seperti peningkatan angka leukosit. Salah satu penyebab infeksi toksoplasmosis adalah ingesti makanan atau daging yang mengandung kista jaringan (bradizoit) atau oosit yang terdapat pada feses kucing. Daging yang dimasak kurang matang dapat mengandung kista jaringan, pada daging babi sekitar 5-35 %, daging kambing/domba 9-60% dan daging sapi 0-9%.","answerPage":167,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-071","number":71,"package":"Paket 2","topic":"Campuran","title":"Soal 071 · Seorang wanita usia 35 tahun terdiagnosis Oleh…","page":121,"stem":"Seorang wanita usia 35 tahun terdiagnosis Oleh dokter terdapat struma. Kemudian akan dilakukan strumadektomi, untuk menurunkan kadar T4 diberikan terapi?","options":["Metimazol","Kortikosteroid","Bromokriptin","PTU (propiltiourasil)","Lugo!"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Sebelumdilakukan operasi strumadektomi dapat digunakansolution luggol selama 10- 21hari untuk mengurangi vaskularisasi glandula tiroid,mengurangi tingkat aliran darah danmencegahkehilangan darah secara berlebihan saat operasi.","answerPage":167,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-072","number":72,"package":"Paket 2","topic":"Mata","title":"Soal 072 · Seorang anak Iaki-laki usia 5 tahun dibawa…","page":121,"stem":"Seorang anak Iaki-laki usia 5 tahun dibawa Oleh ayahnya ke poli mata dengan keluhan mata merah sejak 3 hari yang lalu. Gatal, berair sehingga sering digosok-gosok. Keluhan bertambah berat saat berada dibawah sinar matahari. Awalnya keluhan ini sering terjadi sejak kecil namun hilang timbul dan memberat pada 3 hari terkahir. Pada pemeriksaan visus ODS 5/5, injeksi konjungtiva dan terdapat bintik kecoklatan, secret mukoid dan tampilan cobblestone pada konjungtiva palpebra superior. Diagnosis yang tepat pada anak ini adalah.„.","options":["Konjungtivitis bacterial","Konjungtivitis viral","Konjungtivitis vernal","Kongjungtivitis jamur","Konjungtivitis gonorea"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Ciri khas konjungtivitis vernal adalah terdapat gejala mata merah, gatal, berair hilang timbul (ada pemicu) dengan riwayat atopi. Pada pemeriksaan ditemukan hambatan reaksi papilar yang besar (tampilan cobblestone), secret mukoid.","answerPage":167,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-073","number":73,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 073 · Seorang wanita usia 26 tahun GIPOAO dengan…","page":122,"stem":"Seorang wanita usia 26 tahun GIPOAO dengan usia kehamllan 32 sehat datang ke IGD dengan keluhan sesak naclas dlsertal men la merasakan keluhan ini setiap bulan sejak kehamilann gi I Jam ya. Pemerlksaan fislk wheezing dan ekspirasi memanjang. Dokter menqatakan akan terJndl","options":["Deksametason","Prednisone","Metal prednisolon","Atropine","Hidrokortison"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien inimengalami kehamilanpretem yaituusiakehamilankurang dari37minggu. Penggunaan kortikosteroid untuk mempercepat maturasi paru harus dipertimbangkan pada gestasi 24-34 minggu. Walaupun ada beberapa pendapat yang mengatakan dengan pemberian kortikosteroid dapat meningkatkan risiko infeksi namun data lain mengatakan kortikosteroid menurunkan morbiditas dan mortalitas neonatal seperti menurunkan respiratory distress syndrome, nerotizing enterocolitis dan perdarahan intraventrikular. Yang bisa digunakan adalah betametason 12 mg IM 2kali dalam 24 jam atau deksametason 6 mg setiap 12 jam diberikan 4 kali.","answerPage":168,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-074","number":74,"package":"Paket 2","topic":"Campuran","title":"Soal 074 · Seorang laki-laki usia 40 tahun melakukan pemeriksaan…","page":122,"stem":"Seorang laki-laki usia 40 tahun melakukan pemeriksaan laboratorium dan menunjukkan 19M HBV (4). Setelah digali lebih Ianjut kakanya meninqgal karena hepatis dan kakeknya meninggal Karena kanker hati. Untuk mengetahui replikasl sei","options":["HbcAg","HBeAg","Anti HBs","Anti HBc","HbsAg"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Adanya IgM HBV (+) menunjukkan bahwa pasien terkena infeksi hepatitis B. Parameter untuk mengukur replika virus hepatitis B adalah HBeAg dan anti Hbe serta kadar DNA virus hepatitis B.","answerPage":168,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-075","number":75,"package":"Paket 2","topic":"Mata","title":"Soal 075 · Seorang wanita usia 45 tahun datang ke…","page":122,"stem":"Seorang wanita usia 45 tahun datang ke poli mata dengan keluhan mata kirinya terasa 75. nyeri sejak 3 hari yang lalu dan penglihatannya kabur. Pasien juga mengeluh mual dan muntah. Sebelumnya pasien tidak pernah mengalami hal ini. Pada pemeriksaan visus didapatkan OD 5/5, OS 1/60. Pada OS didapatkan injeksi perikorneal, edema korma, bilik mata depan dangkal dan iris bombans serta tekanan interaokular (TIO) 59 mmHg. Diagnosis pasien ini adalah„.","options":["Glaukoma kronik sudut tertutup","Glaucoma kronik sudut terbuka","Glaucoma akut sudut tertutup","Glaucoma akut sudut terbuka","Suspek galukoma"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Keluhan mata nyeri dan penglihatan kabur sejak 2 hari (akut) disertai mual dan muntah meupakan gejala glaucoma. Pada pemeriksan mata yang terkena, didapatkan visus turun karena kekeruhan kornea (edema kornea), injeksi perikorneal, COA dangkal dan iris bombans (sudah terjadi blok pupil). Pada pemeriksaan diperoleh TIO > 21 mmHg, yang mendukung diagnosis glaucoma akut sudut tertutup.","answerPage":168,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-076","number":76,"package":"Paket 2","topic":"Neurologi","title":"Soal 076 · Seorang laki-laki usia 54 tahun terdiagnosis Oleh…","page":122,"stem":"Seorang laki-laki usia 54 tahun terdiagnosis Oleh dokter inkontinensia alvi. Pasien mengaku 1 bulan yang lalu menjalani eksisi abses pada anus. Kemungkinan penyebab inkontinensia tersebut adalah...","options":["Kerusakan sfingter ani interna interior","Kerusakan sfingter ani eksterna rectum","Kerusakan aliran darah menuju anus","Kerusakan nervus rektalis","Kerusakan tunika sirkularis"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kelainanyang disertaidengan gangguansensibilitasrectum dan anus,faal otot anorektal dapat menyebabkan inkontinensia alvi.Penyebabnya ada 2 yaitu: a.Inkontinensia traumatic atau iatrogenic sfingter ani rusak. Defek di sfingter biasanya dapat diraba dan dilihat karena gambaran pengerutan kulit di sekitar anus juga hilang. Fungsi otot anorektum dapat ditentukan dan diukur dengan manometri di dalamanusdanrectum b.Inkontinensia karena neurologic","answerPage":168,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-077","number":77,"package":"Paket 2","topic":"Bedah","title":"Soal 077 · Sorang wanita usia 40 tahun datang ke…","page":122,"stem":"Sorang wanita usia 40 tahun datang ke tempat praktek dengan keluhan dada tengah terasa seperti terbakar. Keluhan ini timbul sejak 5 tahun yang lalu, namun hilang timbul. pemeriksaan vital sign TD 110/80 nadi 88x/menit RR 18x/menit suhu 360C. Dokter melakukan pemeriksaan abdomen, elektrokardiografi dan foto thoraks PA menunjukkan hasil yang normal, kemudian dilakukan pemeriksaan gastroduodenografi. Kelainan yang paling mungkin didapatkan dari pemeriksaan ini","options":["Sliding hernia","Gastritis atrofikans","Esofagitis","Akalasia","Duodenitis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Keluhan rasa nyeri seperti terbakar pada substernal/retrosternal/dada sering dikenal sebagai heart burn. Rasa tidak enak pada retrosternal ini mirip dengan keluhan angina pectoris. Keluhan heart burn merupakan gejala yang mengarah pada diagnosis esofagitis. Pada pasien ini pemeriksaan elektrokardiograf tidak dijumpai adanya kelainan sehingga kecurigaan kea rah angina pectoris dapat disingkirkan. Hasil pemeriksaan USG abdomen dan foto thoraks PA dalam batas normal sehingga menyingkirkan diagnosis akalasia dan sliding hernia. Pemeriksaan radiologis foto polos pada akalasia menunjukkan garmbaran kontur ganda di atas mediastinum bagian kanan seperti mediastinum melebar dan adanya gambaran batas cairan udara. Pemeriksaan gastroduodenograf diharapkan keadaan mukosa esophagus dapat teramati meskipun pemeriksaan ini kurang peka dan seringkali tidak menunjukan kelainan terutama pada kasus esofagitis ringan.","answerPage":168,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-078","number":78,"package":"Paket 2","topic":"Campuran","title":"Soal 078 · seorang anak laki-laki usia 23 bulan dibawa…","page":123,"stem":"seorang anak laki-laki usia 23 bulan dibawa ibunya karena berat badannya hanya kg dan tinggi badannya 78 cm. pada pemeriksaan fisik didapatkan anak cengeng, terlihat sayu, otot hipotrofi,jaringan subkutannya sedikit dan terdapat edema pada dorsum pedis. Setiap makanan yang dimakan selalu ia muntahkan. Dokter mendiagnosis KEP campuran (marasmik-kwashiorkor). Berapa kalori yang dibutuhkan untuk fase inisial pada pasien ini?","options":["350 kal/hari","450 kal/hari","550 kal/hari","650 kal/hari","750 kal/hari"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada fase inisial terapi MEP secara aman dapat dimulai pada 20% di atas standar asupan sebelumnya. Namun jika tidak ada estimasi asupan kalori sebelumnya, maka dapat diberikan 50-70% dari kebutuhan energi normal. Pada kasus ini tidak terdapat estimasi asupan kalori sebelumnya. Adapun kebutuhan energi normal anak untuk pertumbuhan adalah sebagai berikut: Usia Energi (kkal/kgBB/hari) 10hari-1bulan 120 1-2bulan 115 2-3bulan 105 3-4bulan 95 4-6bulan 95 6-12bulan 90 1-2tahun 90 2-3 tahun 90 3 -5 tahun 90 Jadi kebutuhan energi inisial pada pasien ini adalah: 90 x6,1kg x(50-70%)= 274,5 -284,3 kkal/hari Pilihanjawaban yang termasuk dalamkisaran adalah350kkal/hari Selanjutnya terapi nutrisi dapat ditingkatkan 10-20% setiap hari, sambil dilakukan pemantauan keseimbangan elektrolit, fungsi jantung,edema dan intoleransi makanan.","answerPage":169,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-079","number":79,"package":"Paket 2","topic":"Campuran","title":"Soal 079 · Seorang laki-laki usia 45 tahun datang dengan…","page":123,"stem":"Seorang laki-laki usia 45 tahun datang dengan keluhan terdapat benjolan pada submandibular dekstra. Setelah dilakukan pemeriksaan dokter mendiagnosis sebagai tumor parotis yang paling ganas. Diagnosis pasien ini adalahm","options":["Kistadenoma","Adenokarsinoma","Tumor acinic","Karsinoma mucoepidermoid","Mixed type cell carcinoma"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tipe tumor parotis yaitu: a.Adenokarsinoma pleomorfik:tumor mikstus jinak b. Tumor warthin (adenolimfoma) : jinak C. Tumor mukoepidermoid : keganasan berhubungan dengan peningkatan proporsi sel intermediet dan sel skuamosa dengan lebih sedikit sel-sel mucus d. d.Adenoid kistik karsinoma : keganasan yang terdiri dari sel-sel epiteliel kecil yang menyusun pulau-pulau yang menunjukkan perubahan mikrositik. Tumor ini memiliki kecenderungan menyebar perineural dan sulit dieradikasi secara bedah.","answerPage":169,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-080","number":80,"package":"Paket 2","topic":"Mata","title":"Soal 080 · Seorang wanita usia 65 tahun datang bersama…","page":123,"stem":"Seorang wanita usia 65 tahun datang bersama anaknya ke puskesmas dengan keluhan penglihatan kedua mata menjadi kabur sejak 2 tahun ini secara perlahan-lahan. Mata tidak merah dan tidak terasa nyeri. Pasien ini memiliki riwayat diabetes mellitus sejak 8 tahun yang lalu dan menderita hipertensi sejak 12 tahun yang lalu. Pasien tidak pernah control ke rumah sakit. Pada pemeriksaan visus didapatkan OD 6/20 dan OS 6/40. Segmen anterior dalam batas normal, lensa keruh tidak merata. Pemeriksaan lapang pandang didapatkan gambaran depresi umum. Tekanan bola mata dalam batas normal. Pemeriksaan funduskopi didapatkan gambaran cup disc rasio ODS yaitu 0,3/0,4, degenerasi trigoid, silver wire, tidak terdapat mikroaneurisme maupun eksudat. Diagnosis pada pasien ini adalah.„","options":["Katarak","Retinopati hipertensi","Retinopati diabetic","Glaucoma","Uveitis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus ini pasien mengeluh pandangan matanya kabur secara kronik progressive yang dapat terjadi pada katarak, glaucoma kronik, maupun presbiopia. Pada glaucoma kronik mata terasa pegal dan nyeri. Pemeriksan fsik ditemukan penurunan visus dan lensa keruh tidak meratasehinga mendukung kearah katarak. Pemeriksaanfunduskopi cup disc ratio dan tekanan bola mata dalam batas normal, sehingga menyingkirkan diagnosis glaucoma. Pada retina tidak ditemukan mikroaneurisma, silver wire, maupun eksudat sehingga menyingkirkan diagnosis retinopati.","answerPage":170,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-081","number":81,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 081 · Derajat kesehatan seseorang selalu berubah-ubah disebabkan beberapa…","page":123,"stem":"Derajat kesehatan seseorang selalu berubah-ubah disebabkan beberapa factor yang mempengaruhi kesehatan seseorang atau suatu populasi. Salah satu factor derajat kesehatan adalahm","options":["Angka kesakitan","Angka dependensi ratio","Angka kecukupan gizi","Angka kesempatan kerja","Angka persiapan sekolah"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Buku sistem kesehatan nasional (SKN) menyebutkan derajat kesehatan masyarakat dipengaruhi olehbeberapa factoryaitu: a.s Statushygiene dan sanitasi b.Angka kematian kasar c. Status gizi d. Angka kesakitan e. Angkakematianbayidanbalita Usia untuk mencapai harapan hidup","answerPage":170,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-082","number":82,"package":"Paket 2","topic":"Kulit","title":"Soal 082 · $3. Seorang wanita usia 50 tahun datang…","page":124,"stem":"$3. Seorang wanita usia 50 tahun datang dengan keluhan gatal pada lipat paha sejak I minggu yang lalu yang ticlak kunjung sembuh. Pada pemerlksaan didapatkan lesi eritema di inguinal kanan dan kiri, nodul satelit (T), tidak terdapat erosi. Sediaan yang tepat untuk pengobatan pasien ini adalah...","options":["Puyer","Krim","Salep","Bedak","Lotion"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada saat pasien datang dengan keluhan dan masalahnya sebaiknya yang dilakukan dokter adalah memberikan konseling individu. Pasien diberikan edukasi tentang risiko perbuatan dari segi hukum dan medis.Dokter menganjurkan untuk mempertahankan kandungannya.","answerPage":170,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-083","number":83,"package":"Paket 2","topic":"Bedah","title":"Soal 083 · SO, Seorang wanita usia 60 tahun mengalami…","page":124,"stem":"SO, Seorang wanita usia 60 tahun mengalami fraktur akibat penipisan tulang trabekula. pada pemeriksaan kalsium dan fosfor dalam batas normal. Diagnosis yang mungkin pada pasien ini adalah","options":["Osteogenesis infecta","Osteomyelitis","Osteomalasia","Osteotetrosis","Osteoporosis"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kandidosis kutis intertriginosa terdapat lesi di daerah lipat paha,kulit ketiak, intergluteal, lipat payudara, sela jari tangan dan kaki, gland penis dan umbilicus. Lesi berupa bercak yang berbatas tegas, bersisik, basah dan eritematosa. Lesi dikelilingi oleh lesi satelit berupa vesikel dan pustule kecil atau bula yang bila pecah meninggalkan daerah yang erosive dengan pinggir yang kasar dan berkembang seperti lesi primer. Terapi: 1.Menghindarifaktorpredisposisi 2. Topical: Larutan ungu gentian % - 1 % untuk selaput lender, 1 β 2% dioleskan pada kulit 2 kalisehariselama3hari Golongan azole : mikonazole 25 berupa krim atau bedak, klotrimazole 1% berupa bedak, larutan dan krim, tiokonazole, bufonazole, isokonazole, antimikotik spectrumluas Dibandingkan bedak kemampuan krim lebih baik untuk terserap ke kulit.","answerPage":170,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-084","number":84,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 084 · SSS Seorang laki-laki usia 40 tahun datang…","page":124,"stem":"SSS Seorang laki-laki usia 40 tahun datang ke puskesmas dengan keluhan terjadi pembengkakan pada skrotum. Pasien tidak mengeluh nyerui serta tidak ada gangguan seksual. Pada pemeriksaan status lokalis skrotum terlihat membesar, teraba lunak tetapi tidak teraba adanya massa tumor. Tidak didapatkan pembesaran kelenjar limfe inguinal. Hasil pemeriksaan transiluminasi (+). Diagnosis pasien ini adalah...","options":["Varikokel","Hidrokel","Orkitis","Hernia scrotalis","Seminoma"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Keluhan utama pada pasien ini berupa fraktur kolum femur mengarah pada diagnosis osteoporosis. Pada pemeriksan kalsium dan fosfor dapat menurun atau normal. Gambaran khas radiologik pada osteoporosis adalah penipisan korteks dan daerah yang lebih lusen.Haliniakan tampak pada tulang-tulang vertebra yang memberikan gambaran picture-frame vertebra.","answerPage":171,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-085","number":85,"package":"Paket 2","topic":"Campuran","title":"Soal 085 · Sé- Seorang anak laki-laki usia 4 tahun…","page":124,"stem":"Sé- Seorang anak laki-laki usia 4 tahun dibawa Oleh ibunya karena terdapat benjolan pada mandibula, submandibula dan maksila. Pemeriksaan vital sign nadi 90x/menit, RR 18x/ menit, suhu 36,6 oc. Pemeriksaan lain ditemukan adanya gambaran starry sky, limfosit ukuran sedang dan mitosis cukup. Diagnosis yang paling mungkin pada anak ini adalah","options":["Mioma","Ameloblastoma c- Neuroblastoma tahun dibawa keluarganya karena penurunan Dari pasien sering diravvat di rumah sakit dengan gejafa yang Sarna. Pasien tidak todi pagi. sebelum sadar malamnya pasien mengadakan anak clan ia hanyak sekali yang pada keadaan biasa ia tidak rnakan. clidapatkan Skela ikterik, perut ascites, tangarj dan tungkai kurw, edem pada kaki dan terdapat fetorex core. Ada gambaran di abdomen. Keadaan tidak sadar pada pasien ini disebabkan Oleh? Kelclahan","Keracunan ammonia","Limfoma burkit Keracunan makanan","Limfoma Hodgkin Kebanyakan minum alcohol"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hidrokel adalah penumpukan cairan berlebihan diantara lamina parietal dan lamina visceral tunika vaginalis. Kondisi ini menyebabkan scrotum membesar yang berisi cairan. Pasien mengeluh adanya benjolan di kantong skrotum yang tiak terasa nyeri. Pada pemeriksan fisik didapatkan adanya benjolan di kantong skrotum dengan konsistensi kistus dan pada pemeriksaan transiluminasi menunjukkan hasil (+). Varikokel : dilatasi abnormal vena-vena pada pleksus pampiniformis akibat gangguan aliran balik vena spermatika interna yang menimbulkan gambaran seperti cacing pada bagianatasskrotum. Orkitis : peradangan pada testis yang paling sering terjadi akibat infeksi bakteri. Viral orkitis juga dapat terjadi akibat infeksi mumps. Orkitis terjadi pada sekitar 30% laki-laki pubertasyangmengalamiparotitis. Seminoma:salah satujenis tumortestis dengan gejala klinis yang timbul berupa adanya massa testis atau skrotumyang tidak nyeri.Sebanyak 30-40%pasien mengalami nyeri tumpul atausensasi terasaberatpadadaerahperutbagianbawah,anal atauskrotum. Pada pemeriksaan transiluminasi menunjukkan hasil negative.Tumor ini merupakan jenis yangpaling sering terjadi(60%kasus).","answerPage":171,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-086","number":86,"package":"Paket 2","topic":"Bedah","title":"Soal 086 · sebagai petugas laboratorium. Pemeriksaan vital sign TD…","page":125,"stem":"sebagai petugas laboratorium. Pemeriksaan vital sign TD 120/80 mmHg, nadi 80 x/mcnit, RR 20x/menit, suhu 36.6 oc. Pemeriksaan fisik terdapat lesi Bula berisi cairan benlng. Diagnosis pasien ini adalah","options":["Luka bakar","Dermatitis kontak iritan","Liken simplek","Allergic drug eruption","Dermatitis kontak alergi"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Benjolan di mandibula, submandibula, dan maksila pada anak-anak kemungkinan berasal darilimfonodi baik berupa tumor maupun peradangan. Gambaran starry sky (sel- sel limfoid berukuran medium diselingi dengan makrofag fagositik) khas untuk limfoma burkit. Penyakit ini banyak terjadi pada anak-anak dan remaja berhubungan dengan infeksi virus Epstein barr dan malaria, melibatkan lokasi ekstranodal terutama daerah rahang,traktus gastrointestinal dan gonad.","answerPage":171,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-087","number":87,"package":"Paket 2","topic":"Campuran","title":"Soal 087 · tahun dibawa keluarganya karena penurunan Dari pasien…","page":125,"stem":"tahun dibawa keluarganya karena penurunan Dari pasien sering diravvat di rumah sakit dengan gejafa yang Sarna. Pasien tidak todi pagi. sebelum sadar malamnya pasien mengadakan anak clan ia hanyak sekali yang pada keadaan biasa ia tidak rnakan. clidapatkan Skela ikterik, perut ascites, tangarj dan tungkai kurw, edem pada kaki dan terdapat fetorex core. Ada gambaran di abdomen. Keadaan tidak sadar pada pasien ini disebabkan Oleh?","options":["Keracunan urea","Kelclahan","Keracunan ammonia","Keracunan makanan","Kebanyakan minum alcohol"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"mengarah pada adanya ganguan system saraf sentral yang berhubungan dengan mengidap penyakit hati yang berat dan berlangsung menahun yang mengkonsumsi mengandung nitrogen dariusus sehingga akan mengakibatkan terjadinya kenaikan kadar ammonia yang tajam yang erat hubungannya dengan gejala gangguan saraf sentral.Jika sumber pembentukan ammonia dapat dikurangi atau dihilangkan maka kadar ammonia dalam darah akan kembali normal dan penderita akan terbangun dari koma.","answerPage":172,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-088","number":88,"package":"Paket 2","topic":"Bedah","title":"Soal 088 · x/mcnit, RR 20x/menit, suhu 36.6 oc. Pemeriksaan…","page":125,"stem":"x/mcnit, RR 20x/menit, suhu 36.6 oc. Pemeriksaan fisik terdapat lesi Bula berisi cairan benlng. Diagnosis pasien ini adalah","options":["Luka bakar","Dermatitis kontak iritan","Liken simplek","Allergic drug eruption","Dermatitis kontak alergi"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dermatitis kontak iritan akut biasanya terjadi karena kecelakaan. Gejalanya berupa kulit perih, panas dengan eritem, vesikel atau bula. Luas kelainan umumnya sebatas daerah yang terkena dan berbatas tegas. Kelainan kulit umumnya timbul segera. Beberapa zat kimia yang menimbulkan reaksi akut timbul lambat yaitu podoflin, antralin dan asam fluorohidrogenat.","answerPage":172,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-089","number":89,"package":"Paket 2","topic":"Campuran","title":"Soal 089 · Seorang wanita usia 15 tahun dibawa ke…","page":125,"stem":"Seorang wanita usia 15 tahun dibawa ke IGD RS dengan keluhan kaki dan tangan terasa dingin selama satu jam. Pasien juga mengeluh demam tinggi terus menerus sejak 4 hari yang lalu. Tidak ada keluhan batuk dan pilek. Pasien tidak mau makan, mual dan muntah kehitaman. BAK dan BAB dalam batas normal. Selama 3 jam mengeluhy sakit perut dan gelisah. Pada pemeriksaan fisik anemis (-), akral dingin +/+ trombosit 25.CCO/rnrrP, CR > 2. Bentuk pencegahan yang dilakukan adalah","options":["Vaksinasi","Isolasi pasien","Pemberantasan sarang nyamuk","Immunoglobulin","Kortikosteroid"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pembasahan: Tindakan preventif yang dapat dilakukan adalah promosi kesehatan (health promotion). Pada tingkat ini dilakukan tindakan ini dilakukan tindakan umum untuk menjaga keseimbangan proses bibit penyakit-penjamu-lingkungan sehingga menguntungkan manusia dengan cara meningkatkan daya tahan manusia dan memperbaiki lingkungan. Tindakan ini dilakukanpada orang sehat.Contohnya penyuluhan cara hidup sehat dan kesehatan olahraga.","answerPage":172,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-090","number":90,"package":"Paket 2","topic":"Campuran","title":"Soal 090 · Seorang wanita usia 45 tahun datang dengan…","page":125,"stem":"Seorang wanita usia 45 tahun datang dengan keluhan rasa tidaknyaman pada bagian ulu hati yang timbul setelah makan. Selain itu pasien juga mengeluh perut kembung, terasa panas di dalam perut dan mual. Pemeriksaan lokalis terdapat nyeri tekan pada ulu hati. Pemeriksaan endoskopi ditemukan massa dengan permukaan yang tidak beraturaan. Hasil biopsy menunjukkan adenokarsinoma esophagus. Apakah yang merupakan awal terjadinya keadaan ini?","options":["Esofagitis akut","Esofagitits kronik","Esofagitis barrett","Esofagitis erosive","Esofagitis ulseratif"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Esofagitis barett merupakan keadaan pramaligna untuk adenokarsinoma esophagus. Keadaan pramalignaini disertai esophaguskronik refluks,tidakterbukti ada kaitannya dengan alcohol dan rokok seperti pada squamous cell carcinoma pada esophagus. Perbedaan epidemiologis lainnya adalah adenokarsinoma jarang ditemukan pada ras kulit hitam.Sebagian besartumor initerdapat dekatesophagogastricjunction,cenderung massif daninvasifsertamenyebarkekelenjarregional,jarangbermetastasiskehati.","answerPage":172,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-091","number":91,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 091 · Seorang wanita usia 34 tahun G3POAO dengan…","page":126,"stem":"Seorang wanita usia 34 tahun G3POAO dengan usia kehamilan 32 minggu datang denga h 91. keluhan nyeri pada bagian perut bawah dan tidak buang air kecil selama 48 jam. pemeriksaan fisik didapatkan suhu badan 39 oc. Hasil pemeriksaan urin menunjukkan bakteri (+), glukosa (-), protein Kemudian dilakukan kultur, sambil menunggu hasil kultur antibiotic yang dapat diberikan sebagai pilihan adalah...","options":["PenisilinV generasi l)","Kotrimoksazol","Seftriakson (sefalosporin generasi Ill)","Sefadroksil (sefalosporin","Tetrasiklin"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada pasien ini terdapat tanda dan gejala sistitis akut. Hal yang perlu diperhatikan adalah pasien sedang hamil trisemeste Il. Wanita hamil yang mengalami sititis akut direkomendasikan untuk mendapat teapi antibiotik dengan pivnesilinam (turunan penisilin) selama 7 hari Berikut daftar efek antibiotik terhadap kehamilan: Obat Efek samping perkembangan janin Sulfonamide Kernikterus Trimetoprim Mengganggu perkembangan tabung saraf Tetrasiklin Dysplasia dan perubahan warna gigi dan tulang HemolisisdandefisiensiG6PD Nitrofurantoin Kerusakan saraf Aminoglikosida Mengganggupembentukankartilago Fluorokuinolon Aman Penisilin Aman Sefalosporin Aman Inhibitorbeta-laktamase Aman Monobaktam Aman Fosfomisintrometamol","answerPage":173,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-092","number":92,"package":"Paket 2","topic":"Campuran","title":"Soal 092 · Seorang wanita usia 40 tahun datang dengan…","page":126,"stem":"Seorang wanita usia 40 tahun datang dengan keluhan keluar darah melalui clubur sejak 2 bulan yang lalu. Pasien juga mengeluh nyeri kepala dan kedua kakinya kesemutan. Pada pemeriksaan vital sign TD 120/80 mmHg, ndai 88x/menit, RR 18x/menit, suhu 37t pada pemeriksaan lokalis dengan rectal toucher didapatkan benjolan dan terasa nyeri. Pemeriksaan laboratorium didapatkan kadar Hb 7,8 g%, hematokrit 24%, MCV 60 n, 18. MCHC 70. Apakah penyebab keluhan pada pasien ini?","options":["Anemia defisiensi besi","Anemia defisiensi asam folat","Anemia hemolitik","Anemia sideroblastik","Anemia defisiensi B12"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kehilangan darahpadapasienhemoroid menyebabkan anemia defisiensi besi.Menurut etiologinya anemia defisiensi besi disebabkan oleh: a.Gangguan absorpsi besi:gastrektomi,tropical sprue b.Factor nutrisi:kurangnya zat besi dalam makanan C. Kehilangan besi sebagai akibat perdarahan kronis : tukak peptic, kanker lambung, kankerkolon,hemoroid,infeksi cacing tambang,menoragia,hematuria,hemoptoe d.Factor nutrisi : kurangnya zat besi dalam makanan e.Kebutuhan besi yang meningkat :prematuritas, kehamilan,anak dalam masa pertumbuhan Pemeriksaan laboratorium pada anemia defisiensi besi : Nilainormal ADB Pria14-18wanita12-16 Ringan-berat Derajat anemia 82-97 Menurun MCV 27-33 Menurun MCH 0.5-1,5% Meningkat Retikulosit Menurun<30 Besiserum P300-400W250-300 Meningkat> 360 TIBC Menurun<15% Saturasi transferin Besisumsum tulang Negative Protoporfrineritrosit Meningkat Feritinserum Menurun<20 ElektroforesisHb normal","answerPage":173,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-093","number":93,"package":"Paket 2","topic":"Kulit","title":"Soal 093 · Seorang wanita usia 45 tahun datang dengan…","page":126,"stem":"Seorang wanita usia 45 tahun datang dengan keluhan gatal pada telapak tangannya setelah mencuci pakaian. Hasil pemeriksaan menunjukkan lgE normal dan uji temple normal. Diag. nosis kelainan ini adalahm","options":["Dermatitis kantarides","Dermatitis kontak alergi","Dermatitis kontak iritan","Dermatitis numularis","Dermatitis seboroik"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dermatitis kontak iritan dapat diderita oleh semua orang dari berbagai golongan, ras dan kelamin. Penyebab munculnya DKI adalah dari bahan yang bersifat iritan misalnya bahan pelarut, detergen, minyak pelumas, asam, alkali dan serbuk kayu. Pada kasus ini merupakan DKl akut karena kelainan kuilit muncul segera setelah terpapar zat iritan dan diperkuat dengan hasil lgE yang normal sehingga kemungkinan dermatitis atopic dapat disingkirkan.","answerPage":174,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-094","number":94,"package":"Paket 2","topic":"Bedah","title":"Soal 094 · Seorang laki-laki usia 25 tahun mengalami kecelakaan…","page":126,"stem":"Seorang laki-laki usia 25 tahun mengalami kecelakaan lalu lintas, dadanya terbentur stank sepeda motor. Sampai di IGD RS nafas tersengal-sengal, mengorok, tidak bereaksi saat dicubit, nadi teraba kecil dan lemah, akral dingin, suara nafas dada kiri menurun, pergerakan dada kiri tertinggal dan perkusi dada kiri hipersonor. Tindakan apa yang harus dilakukan terlebih dahulu?","options":["Pasang iv line darah","Periksa jalan nafas","Pasang EKG","Pemeriksaan laboratorium","Pemberian oksigen"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Berdasarkan anamnesis danpemeriksaan fisikdisimpulkan ada sumbatanpadajalan nafas yang ditandai dengan nafas tersengal-sengal dan mengorok. Berdasarkan penanganan ACLS yang harus dibebaskan pertama kali adalah airways, denganjalan memeriksa jalan nafasuntukkemudian dibebaskanjalannafas.","answerPage":174,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-095","number":95,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 095 · Seorang wanitausia27tahunG1POA0hamilusia35 minggudatang dengankeluhannyeri pada kemaluan, terdapat…","page":126,"stem":"Seorang wanitausia27tahunG1POA0hamilusia35 minggudatang dengankeluhannyeri pada kemaluan, terdapat erosi, vesikel, krusta di labia mayora dan minora serta vagina Hasil tzanc test ditemukan sel datia berinti banyak Terapi yang sebaiknya diberian kepadapasien adalah...","options":["Asiklovir topical Fenilalanin","Glutamate","Asiklovir oral 5x800 mg 5-10 hari Hidroksilisin","Cotrimoksazole Lisin","Vamsiklovir1x500mg Triptofan"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Manifestasi klinis yang ditemukan pada pasien sesuai herpes zoster. Pengobatan yang diberikan adalah obat antiviral yang sebaiknya diberikan dalam tiga hari pertama sejak lesimuncul.Antiviral yang dianjurkan adalah asiklovir5x800mgsehar diberikanselama 7hari atauvasasiklovir3x1000mg sehari.Jika lesi barumasih tetap timbul obat tersebut masih dapat diteruskan dan dihentikansesudah duahari sejaklesi baru tidak timbul lagi.","answerPage":174,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-096","number":96,"package":"Paket 2","topic":"Campuran","title":"Soal 096 · seorang anak laki-laki usia 2 tahun mengalami…","page":127,"stem":"seorang anak laki-laki usia 2 tahun mengalami retardasi mental. Pada waktu ditest IQ anak ini 55. pada pemeriksaan urin hasil fenil piruvat positif dan anak ini mengalami inborn error of metabolism. Asam amino yang terganggu adalah...","options":["Fenilalanin","Glutamate","Hidroksilisin","Lisin","Triptofan"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"motorik sangat menonjol pada umumnya penderitabaru dapat beralan pada usia ebih dari 2tahun.Retardasi mental mulai nyata menjelang usia 14 bulan dan menjadisemakon lebihjelasManifestai retardasimentalbisaberupautism daniritabilitas Epilepsy dapat melengkapi penyakit metabolic herediter ini. Factor genetiknya adalah resesif autosomal.","answerPage":175,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-097","number":97,"package":"Paket 2","topic":"Kulit","title":"Soal 097 · seorang wanita usia 35 tahun datang ke…","page":127,"stem":"seorang wanita usia 35 tahun datang ke puskesmas dengan keluhan keputihan sejak 1 minggU yang lalu. Pasien juga mengeluh gatal pada vulva, vagina lecet karena sering digaruk. Pada pemeriksaan fisik vagina keluar cairan seperti bulir-bulir nasi atau susu bubuk. Pemeriksaan selanjutnya yang harus dilakukan adalah...","options":["Darah","Pap smear","Vaginal swab","Urin","IVA test"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Anamnesis pada pasien ini mengarah ke kandidosis vaginalis yaitu keluhan gatal pada daerah vulva. Pada derajat yang berat dapat disertai rasa panas, nyeri sesudah miksi dan dispareunia. Pemeriksaan fisik didapatkan hiperemis pada lania minora, introitus vagina dan vagian terutama 1/3 bawah. Sering pula terdapat kelainan yang khas yaitu bercak- bercak putih kekuningan. Fluor albus pada kandidosis vaginalis berwarna kekuningan dan tanda khas yaitu disertai gumpalan seperti kepala susu berwarna putih kekuningan, untuk membantu diagnosis dilakukan kerokan kulit atau usapan mukokutan serta pemeriksaan biakan.","answerPage":175,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-098","number":98,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 098 · Seorang wanita usia 60 tahun datang ke…","page":127,"stem":"Seorang wanita usia 60 tahun datang ke puskesma dengan keluhan sesak nafas dan bengkak pada kedua tungkai sejak 3 hari yang lalu. Pasien memiliki riwayat minum obat hipertensi sejak 8 tahun yang lalu. Satu hari yang lalu pasien mengeluh urine berwarna agak merah dan sedikit. Pemeriksaan penunjang yang mendukung pemeriksaan ke arah diagnosis adalah...","options":["Ureum","Kreatinin","SGPT","CK/CKMB","Clearance creatinin"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien mengeluh urine berwarna merah dan BAK sedikit dapat dipikirkan untuk memeriksan adakah kelainan pada fungsi ginjal. Untuk mengetahui apakah ada kelainan pada fungsi ginjal maka pemeriksaan penunjang yang dilakukan adalah clearance creatinin.","answerPage":175,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-099","number":99,"package":"Paket 2","topic":"Campuran","title":"Soal 099 · Seorang anak Iaki-laki usia 11 tahun datang…","page":127,"stem":"Seorang anak Iaki-laki usia 11 tahun datang dengan keluhan demam sejak I minggu yang lalu. Pasien juga mengeluh batuk dan pilek. Kurang lebih IO hari kemudian terdapat pembengkakan pada lutut kiri disertai nyeri dan mobilitas terbatas. Dokter melakukan foto rontgen, hasilnya tampak focus titik dikelilingi tepi yang sklerotik pada korteks distal femur. Diagnosis yang tepat pada pasien ini adalah...","options":["Osteomielitis akut piogenik","Osteomielitis tuberkulosa","Osteogenik sarcoma","Osteoarthritis","Arthritis supuratif"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Osteomielitis akut piogenik merupakan infeksi tulang dan sumsum tulang akut yang disebabkan oleh bakteri piogenik, dimana mikroorganisme berasal dari focus di tempat lain dan beredar melalui sirkulasi darah.Infeksi ini terutama mengenai anak-anak dan bayi. Lokasi biasanya di daerah metafisis. Trauma dan hematoma pada metafisis merupakan salah satu faktor predisposisi. Factor predisposisilainnya adalah nutrisi, lingkunganm dan imunitasyang buruk serta adanya focusinfeksisebelumnya.Pada kasus ini pembengkakan di lutut kiri dan mobilitas terbatas. Foto rontgen yang menunjukkan focus litik dikelilingi tepi yang sklerotik mengarahkan pada diagnosis osteomielitis akut piogenik.","answerPage":175,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-100","number":100,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 100 · Seorang wanita usia 25 tahun GI POAO…","page":127,"stem":"Seorang wanita usia 25 tahun GI POAO usia kehamilan 24 minggu datang dengan keluhan gatal pada sela-sela jari tangan sejak 2 hari yang lalu. Dokter mendiagnosis wanita ini terkena scabies. Obat scabies yang paling aman untuk ibu hamil adalah„.","options":["Malation","Benzyl benzoate","Permetrin","Sulfur percipitatum","Karbaril"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Obat scabies paling aman untuk ibu hamil adalah belerang endap (sulfur precipitatum) yang berbentuk salep atau krim dimana preparat ini tidak efektif untuk stadium telur sehingga pemakaiannya tidak boleh kurang dari 3 hari.","answerPage":176,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-101","number":101,"package":"Paket 2","topic":"Parasitologi","title":"Soal 101 · Seorang anak laki-laki usia 5 tahun datang…","page":128,"stem":"Seorang anak laki-laki usia 5 tahun datang dengan keluhan BAB cair >5 kali/hari dan fesesnya mengandung darah. Dari hasil anamnesis ibunya anak ini habis bermain di pasir. Cacing yang menyebabkan penyakit ini adalah...","options":["Giardia lambia","Necator americanus","Strongyloides stercolaris","Wuchereria brancofti","Enterobius vermicularis"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Cacing yang sering terdapat pada tanah berpasir adalah cacing tambang (Necator americanus dan Ancylostoma duodenale). Kedua cacing jenis ini memerlukan tanah berpasir yang gemburuntuk hidup tercampur humus dan terlindung sinar mataharijuga terdapat bintik larva flariform dari Strongyloides stercoralis yang banyak terdapat di tanah pasir. Cacing initidak menyebabkan diare tetapi lesi serpiginosa di kulit.","answerPage":176,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-102","number":102,"package":"Paket 2","topic":"Campuran","title":"Soal 102 · Seorang kepal puskesma Sukamaju menekankan kepada staf…","page":128,"stem":"Seorang kepal puskesma Sukamaju menekankan kepada staf untuk memberikan vitamin A pada anak yang terkena malnutrisi di daerahnya. Penyakit yang paling mungkin dicegah adalah.„","options":["Diare","Tifoid","DHF","Malaria","Measles"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Penatalaksanaan morbili dengan pemberian vitamin A : Usia<1 tahun: 100.000 1U hari ke 1,2 dan 14 Usia>1tahun:200.000IU harike1,2 dan14","answerPage":176,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-103","number":103,"package":"Paket 2","topic":"Neurologi","title":"Soal 103 · Seorang wanita usia 25 tahun datang dengan…","page":128,"stem":"Seorang wanita usia 25 tahun datang dengan penurunan kesadaran. 1 minggu yang pasien masih bisa dibangunkan dengan panggilan tetapi sekarang tidak bisa. Pasien sedang menjalani pengobatan TB secara 6 bulan namun berhenti karena merasa sudah enak. Pada pemeriksaan fisik didapatkan kaku kuduk (+), kaki kiri lebih lemah daripada kaki kanan, babynski test (+) pada kaki kiri. Diagnosis pasien ini","options":["Stroke emboli","Stroke perdarahan intraserebral","Tumor serebri","Meningitis TB","Meningitis bacterial akut"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Meningitis tuberkulosa adalah radang selaput otak akibat komplikasi tunerkulosis primer. Yang membedakan dengan meningitis bakterial akut adalah perjalanan penyakit pada meningitis tuberkulosa lebih lama, kelainan dalam cairan serebrospinal tidak begitu terlihat dan pasien biasanya datang dengan keluhan utama panas dan penurunan kesadaran. Berdasarkan gambaran klinis pasien ini yaitu berupa rangsang meningeal terlihat nyata, seluruh tubuh dapat menjadi kaku dan terdapat tanda-tanda peningkatan intracranial termasuk pada stadium ll. Kesadaran menurun dan dapat terjadi defisit neurologis seperti hemiparesis karena infark otak dan rigiditas deserebrasi. Stroke emboli dan troke perdarahan intraserebral dapat disingkirkan karena pada kedua kondisijarang ditemukan kaku kuduk. Diagnosis tumor serebri dapat disingkirkan karena pada kondisi tersebut gejalaklinis bersifat kronis dan progresif.","answerPage":176,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-104","number":104,"package":"Paket 2","topic":"Campuran","title":"Soal 104 · Seorang laki-laki usia 34 tahun datang ke…","page":128,"stem":"Seorang laki-laki usia 34 tahun datang ke IGD rumah sakit dengan keluhan nyeri kepala berdenyut dengan intensitas berat. Keluhan disertai mual, muntah dan fotopobia. Dalam I tahun terakhir keluhan ini dirasakan sebanyak 6 kali. Diagnosis yang tepat untuk pasien ini adalahm","options":["Tension type headache chronic","Cluster headache","Tension type headache episodic","Classic migraine","Common migraine"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Deskripsi migrain adalah nyeri kepala berdenyut baik dengan intensitas sedang maupun berat. Pada kasus ini gejala nyeri kepala tidak disertai dengan aura sehingga masuk dalam kelompok common migraine. Beberapa kriteria diagnostik common migraine yaitu : a.Sekurang-kurangnya terjadi 5 serangan yang memenuhi kriteria 2-4 diobati) 1. Lokasi unilateral 2） Kualitas berdenyut 3. Intensitas nyeri sedang sarmpai berat 4.Keadan bertambah beratoleh aktivitas fsikatau penderita menghindariativitas fisik rutin d. Selama nyeri kepala disertai salah satu gejala dibawah ini : 1. Mual dan/muntah e.Tidakberkaitan dengankelainan lain 2.Fotopobia dan fonofobia","answerPage":176,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-105","number":105,"package":"Paket 2","topic":"Kulit","title":"Soal 105 · Seorang anak laki-laki usia 5 tahun datang…","page":128,"stem":"Seorang anak laki-laki usia 5 tahun datang dibawa ibunya karena tidak dapat menahan kencing, sering mengompol. Selain itu pasienjuga mengeluh sering gatal pada anus terutama pada malam hari. Usulan pemeriksaan yang dilakukan adalah..","options":["Harada mori","Urin","Tinja langsung","Tinja endapan","Garam scoth adhesive tape"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Infeksi akibat Enterobius vermicularis dicurigai pada anak yang menunjukkan rasa gataldi sekitar anus terutama pada malam hari. Diagnosis ditegakkan dengan menemukan telur dan cacing dewasa. Telur cacing dapat diambil dengan alat anal swab yang ditempelkan di sekitar anus pada pagi hari sebelum anak BAB dan cebok. Anal swab adalah suatu alat dari batang gelas atau spatel lidah yang pada ujungnya dilekatkan Scoth adhesive tape, yang bila ditempelkan didaerah anus telur cacing akan menempel pada perekatnya. Kemudian scoth adhesive tape diratakan pada kaca objek dan dibubuhi tuluol untuk pemeriksaan mikroskopik. Pemeriksaan sebaiknya dilakukan berturut-turut.","answerPage":177,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-106","number":106,"package":"Paket 2","topic":"Psikiatri","title":"Soal 106 · seorang laki-laki usia 40 tahun datang dengan…","page":129,"stem":"seorang laki-laki usia 40 tahun datang dengan keluhan gelisah, bicara ngiantur, sering mondar-mandirtidakjelas. diantarolehtetangganyadengan tangandiikat.sebelumnya bekerja sebagai petani dengan pendidikan tidak SD. Pada pemeriksaan lebih lanjut tidak ditemukan kelainan organic, tetapi ditemukan waham dan halusinasi dengar. Gejala ini dialami penderita sejak 1 minggu yang lalu dan sebelumnya tidak pernah sakit seperti ini. Gangguan yang dialami pasien ini adalah„.","options":["Skizofrenia","Gangguan waham sementara","Gangguan afektif","Demensia","Gangguan psikotik akut"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gangguanpsikotikakutsementara: a.Awal yang akut(dalam 2minggu ataukurang)merupakan jangkawaktu gejala psikotikmenjadi nyata danmengganggu sedikitnyabeberapa aspek kehidupan dan pekerjaansehari-hari,tidaktermasukgejalaprodromalyanggejalanya tidakjelas D. Waham dan halusinasipolimorfik C. Gangguanafektifdanemosi d. Perubahan yang cepat dari jenis dan intensitas dari gejala psikotik e.Tidak ada bukti yang disebabkan oleh organik atau substansi psikoaktif","answerPage":177,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-107","number":107,"package":"Paket 2","topic":"Campuran","title":"Soal 107 · seorang laki-laki usia 34 tahun senang menggosokkan…","page":129,"stem":"seorang laki-laki usia 34 tahun senang menggosokkan alat kelamin pada pantat seorang Wanita yang berpakaian lengkap untuk mencapai orgasme. Selain itu pasien juga senang menggunakan tangannya untuk meraba korban. Tindakan ini biasa terjadi ditempat ramai, terutama di tempat umum seperti pasar, bus dan kereta. Gangguan apa yang dialami Oleh pasien?","options":["Nekrofilia","Masokisme","Fetihisme","Froteurisme","Voyeurisme"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Froteurisme dikarakteristikan pada laki-laki yang senang menggosokkan penisnya pada pantat atau bagian tubuh wanita yang berpakaian lengkap untuk mencapai orgasme. Perbuatan ini dilakukan ditempat yang padat.","answerPage":177,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-108","number":108,"package":"Paket 2","topic":"Campuran","title":"Soal 108 · Seorang Iaki-laki usia 40 tahun dengan berat…","page":129,"stem":"Seorang Iaki-laki usia 40 tahun dengan berat badan 100 kg datang dengan keluhan nyeri pada kedua lututnya yang dirasakan jika berdiri lama. Nyeri semakin memberat dengan aktivitas fisik. Pasien menyangkal adanya kaku di pagi hari. Pada pemeriksaan kedua lutut tidak ditemukan adanya deformitas, didapatkan efusi ringan dan krepitasi. Diagnosis yang paling mungkin adalah.„","options":["Arthritis gout","Osteoarthritis","Arthritis rematoid","Kondromalasia patella","Arthritis psoriatic"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien bertubuh gemuk merupakan salah satu factor risiko OA. Pemeriksaan fsik didapatkan krepitasi pada kedua lutut, fusl ringan serta nyeri pada kedua lutut yang memberat dengan aktivitas isik, sehingga mengarah diagnosis pada OA.","answerPage":178,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-109","number":109,"package":"Paket 2","topic":"Campuran","title":"Soal 109 · Seorang wanita usia 17 tahun datang dengan…","page":129,"stem":"Seorang wanita usia 17 tahun datang dengan keluhan terdapat benjolan di lehernya sejak 6 bulan terakhir. Tidak terdapat gangguan menelan terutama saat makan dan minum. Pada pemeriksaan vital sign didapatkan TD 110/80 mmHg, nadi 90x/menit, RR 18x/menit, suhu 380C. Pemeriksaan fisik didapatkan teraba kelenjar simetris, tidak nyeri, mobile dan ikut bergerak saat menelan. Kemungkinan diagnosis pasien ini adalah„.","options":["Limfadenopati","Struma nodusa","Struma difus","Penyakit graves","Tumor non spesifik"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Benjolan dileher yang terletak di anteriorleher dan gerakannya naik turun saat menelan menunjukkan adanya pembengkakan tiroid. Pada usia muda < 30 tahun kelainan pembengkakan tiroid terbanyak adalah struma difus berupa hiperplastika maupun difus. Kelainan ini disebabkan oleh defisiensi iodine (absolute maupun relative) dan peningkatan kebutuhan tiroksin karena fisiologis (misalnya pada masa pubertas laktasi, kehamilan,stressdanlain-lain)","answerPage":178,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-110","number":110,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 110 · Seorang wanita usia 65 tahun datang dengan…","page":130,"stem":"Seorang wanita usia 65 tahun datang dengan keluhan sesak nafas yang terasa berat, tetapi tidak ada riwayat sakit ginjal. Dari pemeriksaan rontgen thoraks pembesaranjantung. Pemeriksaan fisik ditemukan tekanan darah 160/90 mmHg, nadi 100 kali/menit, RR 24 x/menit. Suara nafas tambahan (-), edema G). Pemeriksaan tarnbaha untuk menegakkan diagnose","options":["EKG","Ureum, kreatini, elektrolit","Rontgen thoraks","AGD, tes fungsi paru","Darah dan urine rutin"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Keluhan sesak dapat diakibatkan oleh organ paru, jantung, hati dan ginjal. Kemungkinan ginjal tersingkirkan.Adanya pembesaran jantung pada pemeriksan foto thoraks member kemungkinan diagnosis kearah kelainanjantung Untuk mengetahui lebih spesink kelainan jantung apa yang diderita, dan pembesaran bagian jantung mana, dapat diketahui dengan pemeriksaan penunjang EKG.","answerPage":178,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-111","number":111,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 111 · 11. Seorang wanita usia 34tahundatang ke puskesmas…","page":130,"stem":"11. Seorang wanita usia 34tahundatang ke puskesmas karena mengeluhjari kedua tangannya terasa kaku terutama di pagi hari. Nyeri berkurang saat beraktivitas. Pada pemeriksaan fisik didapatkan arthritis pada sendi metakarpofalang dan interfalang proksimal kedua tangan. Diagnosis yang paling mungkin","options":["Artritis rematoid","Osteoarthritis","Arthritis reaktif","Arthritis gout","Arthritis psoriatic"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kriteria diagnostik RA adalah a. Kaku sendi di pagi hari sekurang-kurangnya 1 jam b. Arthritispada3persendian ataulebih C. Arthritis simetris d. Arthritispadapersendian tangan e. Nodulrheumatoid f. Faktorrheumatoid serumpositif g. . Perubahan gambaran radiologis menunjukkan adanya erosi dan dekalsifkasi tulang","answerPage":178,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-112","number":112,"package":"Paket 2","topic":"Campuran","title":"Soal 112 · Seorang wanita usia 35 tahun datang dengan…","page":130,"stem":"Seorang wanita usia 35 tahun datang dengan keluhan sering keputihan yang sangat berbau. Pasien mengaku menikah sejak usia 16 tahun sebanyak 3 kali sampai saat ini dan memiliki 5 orang anak. Pada pemeriksaan vital sign TD 120/80 mmHg, nadi 88x/menit RR 20x/menit, suhu 36,70C. Pemeriksaan VT didapatkan keputihan (+), portio licin (+1 Diagnosis pasien ini","options":["Ca Cervik","Bartolinitis","Cervicitis","Vaginitis","Endometriosis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala pada ca servik diantaranya adalah keputihan yang berbau semakin lama berbau busuk akibat infeksi dan nekrosis jaringan. Kejadiannya mempunyai hubungan erat dengan faktor diantaranya aktivitasseksualyang berganti-gantipasangan,koitus pertama yang dialami pada usia muda (< 16 tahun). Insidensi meningkat dengan tingginya paritas.","answerPage":178,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-113","number":113,"package":"Paket 2","topic":"Anak","title":"Soal 113 · Seorang bayi laki-laki usia 3 bulan datang…","page":130,"stem":"Seorang bayi laki-laki usia 3 bulan datang dibawa ibunya karenaterlihat pucat. Pada pemeriksaan fisik ubun-ubun lebar, lien dan hati melebar. Hasil pemeriksaan laboratorium didapatkan anemia gravis, eritrosit berukuran sama dengan inti limfosit kecilm daerah pucat < h diameter, basophilic stippling, sel target, ear drop, Howel-jelly bodies Penyebabnya adalalu","options":["Talasemia","Anemia hemolitik","Anemia defisiensi asam folat","Anemia defisiensi besi","Defisiensi vitamin B12"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"a. Anemia berat dengan kadar Hb3-7 g/dL b. Hepatosplenomegali massif c. Kemunduran tumbuh kembang d. Defomitastulang tulngwajngenmals Pada pemeriksaan darah tepiditemukan: a. MCV dan MCH rendah, pada talasemia mayor terdapata anisositosisekstrem b. Hitung darah putih biasanya meningkat pada talasemia mayor, halini disebabkan kesalahan dalam perhitungan dimana eritrosit berinti dianggap sebagai leukosit c. Hitung trombosit biasanya normal kecualijika pembesaran lien sangat mencolok d. Morfologidarah tepi menunjukan mikrositik hipokromik, seltarget, berinti,basophilic stippling dan leukosit imatur","answerPage":179,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-114","number":114,"package":"Paket 2","topic":"Campuran","title":"Soal 114 · seorang laki-laki usia 35 tahun d atang…","page":131,"stem":"seorang laki-laki usia 35 tahun d atang dengan keluhan diare sudah 2 bulan namun","options":["tidak sembuh-sembuh. Dokter melakukan pemeriksaan kolonoskopi dan haslinya menunjukkan tampilan cobblestone. Diagnosis yang tepat untuk pasien ini adalahm colitis TB","Colitis ulseratif Kanker colon","Kanker colon","Amoebiasis intestinal","Penyakit crohn"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Inflammatory bowel disease (IBD) adalah penyakit inflamasi yang melibatkan saluran cerna dengan penyebab pastinya hingga saat ini belum diketahui secara jelas. IBD dibagi menjadi 3 jenis yaitu : a.colitis ulseratif b. penyakit crohn c. intermediate colitis (bila sulit dibedakan antara colitis ulseratif dan penyakit crohn) GambaranlesiendoskopiIBD: Colitisulseratif Penyakit crohn Lesi inflamasi (hiperemis, ulserasi) Bersifat kontinu dan terdapat +++ skip area (adanya mukosa normal diantara lesi) Terdapatketerlibatanrectum +++ + Lesi mudah berdarah +++ + Tampilan cobblestone/ + +++ pseudopolip Sifat ulkus Terdapat pada mukosa yang +++ mengalamiinflamasi ++++ Terdapatketerlibatan ileum + +++ Lesiulkusbersifatdiskrit Bentukulkus + +++ Diameter>1cm + +++ Dalam +++ Berbentuklinier + ++++ Aphtoid","answerPage":179,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-115","number":115,"package":"Paket 2","topic":"Neurologi","title":"Soal 115 · seorang wanita usia 40 tahun datang dibawa…","page":131,"stem":"seorang wanita usia 40 tahun datang dibawa keluarganya ke IGD Rumah sakit dengan penurunan kesadaran. Pada pemeriksaan fisik TD 80/60 mmHg, nadi teraba lemah dan cepat, kedua akral dingin. Pemeriksaan laboratorium didapatkan Hb 13,8 g/dl, leukosit 4200/mm3, hematokrit 38 % dan trombosit 222.000/mm3. Sebelumnya pasien diberi suntikan penisilin sekitar 30 menit yang lalu. Bagaimana mekanisme dalam keadaan tersebut?","options":["Terjadi reaksi sitotaksi karena terbentuknya IgM/IgG Oleh antigen","Terjadinya reaksi kompleks imunitas","Terjadi respon selTyang telah disensitasi Oleh antigen tertentu","Terjadinya reaksi anafilatik akibat reaksi antigen dengan IgE yang terbentuk","Terjadi respon system imunitas humoral"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pemberian obat penisiin rentan terjadi reaski hipersensitivitas tipe l. biasanya terjadi dalam 30 menit setelah pemberian obat Pada hipersensitivitas tipeIterjadi manifestasi klinis renjatan anaflatik yang merupakan efek mediator kimia akibat reaksi antigen denganlgE yang telahterbentuk.Gejalanyaadalah sebagaiberikut: a. Sesak nafas akibat kejang bronkus ataupun kejang laring b.Urtikaria C. Angioedema d.Pingsan dan hipotensi","answerPage":180,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-116","number":116,"package":"Paket 2","topic":"Kulit","title":"Soal 116 · Seorang wanita usia 25 tahun datang dengan…","page":131,"stem":"Seorang wanita usia 25 tahun datang dengan keluhan BAB cair berbau sebanyak IOX dalam sehari tanpa disertai lender darah. Dokter mengatakan bahwa ia mengalami dehidrasi sehingga harus dirawat. Apa gejala atau tanda yang dapat ditemukan pada pasien ini?","options":["Turgor meningkat","BAK berkurang","Lidah basah","Kulit lembab","Banyak keringat"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala dehidrasi adalah BAK berkurang, turgor menurun, tidak berkeringat, lidah dan kulit kering, air mata kering, mata cekung dan suara serak. Gejala yang timbul tergantung derajat dehidrasi.","answerPage":180,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-117","number":117,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 117 · Seorang wanita usia 28 tahun GI POAO…","page":131,"stem":"Seorang wanita usia 28 tahun GI POAO hamil 32 minggu datang ke IGD RS dengan keluhan sesak nafas disertai mengi sejak satu jam yang lalu. Pasien merasakan keluhan ini setiap bulan sejak kehamilannya. Pada pemeriksaan fisik didapatkan wheezing dan ekspirasi memanjang. Diperkirakan akan terjadi persalinan dini. Obat apa yang diberiksan untuk mencegah efek buruk dari persalinan dini tersebut?","options":["Prednisone","Dexametasone","Hidrokortison","Betametason","Metal prednisolon"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien memiliki keluhan sesak nafas disertai mengi. Pada pemeriksaan fisik didapatkan wheezing dan ekspirasi memanjang. Diagnosis kasus ini adalah asma bronchial, sehingga obat yang paling aman adalah dexametason.","answerPage":180,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-118","number":118,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 118 · Sorang laki-lakiusia45 tahun datang kepuskesmasmengeluhbadanterasalemassekali setelah beberapa…","page":131,"stem":"Sorang laki-lakiusia45 tahun datang kepuskesmasmengeluhbadanterasalemassekali setelah beberapa jam yang lalu nyeri kepala diobati sendiri dengan obat aspirin. Pasien ini mempunyai riwayat DM tipe ll sejak 10 tahun yang lalu dan mengkonsumsi obat klorpropamid untuk diabetes melitus yang disandangnya. Apakah efek interaksi dari kedua jenis obat tersebut?","options":["Hiperglikemi","Hipoglikemi","Emboli","Ulkus peptikum","Perdarahan"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Klorpropamid adalah obat antidiabetes gologngan sulfonylurea generasi pertama yang seringkali menyebabkan efek samping hipoglikemia. Hal ini terjadi terutama bila cara pemberian kurang tepat. Pemberian sulfonylurea bersamaan dengan OAINS (aspirin) akan meningkatkan efek hipoglikemia dari sulfonylurea.","answerPage":180,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-119","number":119,"package":"Paket 2","topic":"Campuran","title":"Soal 119 · Seorang wanita usia 40 tahun mengalami sesak…","page":132,"stem":"Seorang wanita usia 40 tahun mengalami sesak nafas dan merasa seperti tercekik disuntik antibiotic IV. Terapi yang tepat diberikan kepada pasien adalah","options":["Adrenalin","Atropine","Lidokain","Kortikosteroid","Salbutamol"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada syok anafilatik terapi yang tepat digunakan adalah adrenalin 1:1000 sejumlah 0,3- 0.5 mL yang diberikan secara subkutan atau intramuscular pada lengan atau paha.","answerPage":180,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-120","number":120,"package":"Paket 2","topic":"Mata","title":"Soal 120 · Seorang wanita usia 25 tahun sedang menjalani…","page":132,"stem":"Seorang wanita usia 25 tahun sedang menjalani program diet untuk menurunkan berat badan. Ia tidak mau makan apapun, sehingga merasa lemas. Pada pemeriksaan fiSik didapatkan konjungtiva anemis. Dilakukan pemeriksaan laboratorium hasilnya Hb 10 mg/dl. Pemeriksaan darah tepi menunjukkan anemia normokromik makrositik. pasien mengalami defisiensi.„","options":["Besi","Vitamin Bl","Vitamin B 12","Vitamin K","Vitamin A"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":181,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-121","number":121,"package":"Paket 2","topic":"Neurologi","title":"Soal 121 · Seorang wanita usia 30 tahun datang dengan…","page":132,"stem":"Seorang wanita usia 30 tahun datang dengan keluhan nyeri kepala seperti diikat sejak2 bulan yang lalu. Pasien juga mengeluh ketika berjalan terasa melayang, sering berdebar. debar dan keringat dingin. Nyeri kepala ini hamper terjadi setiap hari, kumat-kumatan disertai mual tanpa muntah dan tidak bisa tidur. Pada pemeriksaan vital sign didapatkan TD 120/80 mmHg, nadi 80x/menit, RR 18x/menit, suhu 36 oc. Pemeriksaan fisik tidak ditemukan deficit neurologis. Diagnosis pasien ini adalah...","options":["Migraine klasik","Stroke infark","Trigeminal neuralgia","Cluster headache","Tension headache"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala khas pada tension headache yaitu nyeri seperti tersengat listrik) b. Nyeri kepala hamper terjadi setiap hari (migraine: nyeri bersifat episodic dengan interval serangan bervariasi, cluster headache : serangan berlangsung selama periode waktu tertentu, yaitu beberapa hari dan diantara periode serangan terdapat periode bebas gejala sedangkan trigeminal neuralgia nyeri bersifat tiba-tiba dan dicetuskan oleh factor pencetus tertentu seperti merokok, bicara, gosok gigi) c. Disertai adanya sindrom anxietas (kecemasan) seperti dada berdebar, keringat dingin dan sulit tidur.","answerPage":181,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-122","number":122,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 122 · Seorang dokter puskesmas menuliskan resep sebagai berikut:…","page":132,"stem":"Seorang dokter puskesmas menuliskan resep sebagai berikut: R/ Paracetamol 100 mg DMP 250 mg Mfpulv dtd no X 3 dd pulv I Berapa dosis paracetamol untuk 1 hari?","options":["100 mg","200 mg","300 mg","600 mg","800 mg"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dalam satu pulvis mengandung paracetamol 100 mg, dalam satu hari terapi diberikan 3 kali. Maka dosis paracetamol 100mg x 3 = 300 mg","answerPage":181,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-123","number":123,"package":"Paket 2","topic":"Neurologi","title":"Soal 123 · Seorang wanita usia 75 tahun dibawa keluarganya…","page":132,"stem":"Seorang wanita usia 75 tahun dibawa keluarganya dengan keluhan sulit menggerakkan anggota tubuhnya baik sebelah kanan maupun kiri. Tangan kanannya terlihat tremor orang sedang menghitung uang. Wajahnya terlihat kaku seperti topeng. Jalannya seperti terlihat kaku, langkahnya kecil-kecil. Kesadaran tidak menurun. Terapi yang tepat untuk pasien ini adalah...","options":["Karbamazepin","Difenilhidantion","Difenilhidantion","Luminal","Levodopa"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala dan tandapasienParkinson adalah a.Tremor yang terlihat jelas saat istirahat dan meningkat saat timbul stress emosional. Umunya dimulai padalengan dan tungkai,berupa gerakan ritmis fleksi-ekstensi dari jari,tangan dankaki. b. Rigiditas merupakan resistensi terhadap gerakan. Otot terus menerus berkontraksi secara bersamaan sehingga penderita merasa kaku dan lemah C. Akinesia/hipokinesia merupakan perlambatan pada gerakan volunteer atau gerakan spontan seperti mengayunkan tangan ketika berjalan d. Postural instability yaitu cara berjalan dan postur yang abnormal","answerPage":181,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-124","number":124,"package":"Paket 2","topic":"Campuran","title":"Soal 124 · seorang laki-laki usia 24 tahun sedang mengikuti…","page":133,"stem":"seorang laki-laki usia 24 tahun sedang mengikuti panjatgunung.Tiba-tiba mengeluh mual dan sakit kepala hebat. Pemeriksaan fisik didapatkan TD 120/80 mmHg, nadi 80x/menit, RR 20x/menit dan suhu 36,5 oc. Pada pemeriksaan laboratorium didapatkan hemoglobin g/dl, leukosit 7000/mm3 dan trombosit 250.000/mm3. Penyebab terjadinya keadaan ini adalah.„","options":["Hematokrit meningkat bdarah otak Tekanan pulmonal turun jaringan otak","Tekanan pulmonal turun jaringan otak","Viskositas darah menurun","Vasodilatasi local pembuluh","Menurunnya aliran 02 di"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada daratan tinggi, kandungan oksigen dalam udara menjadi berkurang. Sehingga ada mekanisme dalam tubuh untuk mendapatkan oksigen lebih banyak. Hemoglobin diperlukan pada transportasi oksigen dalam darah. Untuk transportasi yang optimal, diperlukan konsentrasi hemoglobin yang normal, bukan hematokrit. Peningkatan tekanan pulmonal pada edema paru akan mengganggu pertukaran gas dalam paru. Gejala menurunnya pasokan oksigen dalam jaringan otak akan memberikan gejala penurunan kesadaran. Pada kasus ini tidak ditemukan gejala penurunan kesadaran. Sehingga terjadinya vasodilatasi lokal pembuluh darah otak merupakan jawaban yang tepat.","answerPage":181,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-125","number":125,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 125 · Seorang wanita usia 30 tahun G2P1A0 hamil…","page":133,"stem":"Seorang wanita usia 30 tahun G2P1A0 hamil usia 12 minggu datang untuk ANC teratur. Riwayat kehamilan anak pertama lahir spontan, berat badan normal dan cukup bulan. Anamnesis tambahan untuk risiko anemia pada ibu adalah...","options":["Riwayat minum obat-obatan sebelum dan selama kehamilan ini","Apakah anak yang hidup anemia","Menanyakan kebiasan dietnya","Jenis kontrasepsi yang digunakan sebelum kehamilan","Riwayat anemia defisiensi Zn saat kehamilan yang lalu"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Anamnesis tambahan untuk menanyakan adakah risiko anemia pada ibu adalah dengan menanyakan asupan makananya selama kehamilan apakah sesuai dengan kebutuhan pada ibu hamil. Apa yang biasa ibu makan sesuai dengan kecukupan gizi pada kehamilannyaatautidak.","answerPage":182,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-126","number":126,"package":"Paket 2","topic":"Campuran","title":"Soal 126 · Seorang laki-laki usia 20 tahun datang ke…","page":133,"stem":"Seorang laki-laki usia 20 tahun datang ke klinik praktik anda dengan membawa resep yang mengandung codein. Kemudian ia meminta dibuatkan resep lagi kepada anda. Ada iwayat penggunaan opiate. Tindakan anda adalah...","options":["Rujukke panti rehab","Rujuk psikiater","Rujuk dokter Iain","Kembali ke dokter lama","Buat resep baru tanpa opiate"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus initerdapat riwayat pengguanan opiate dan resepsebelumnya mengandung codein sehingga untuk menghindari penyimpangan dalam praktik kedokteran dan dalam pemberian terapi lanjutan akan lebih baik jika pasien dikembalikan ke dokter sebelumnya.","answerPage":182,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-127","number":127,"package":"Paket 2","topic":"Kulit","title":"Soal 127 · Seorang pelajar SMA datang ke puskesmas dengan…","page":133,"stem":"Seorang pelajar SMA datang ke puskesmas dengan keluhan gatal pada kedua jempol kaki dan diantara jari kaki kanan. Pada pemeriksaan diambil specimen tampak hifa. Diagnosis yang mungkin adalah...","options":["Tinea nigra Sulfas atropine","Tinea cruris C Tinea pedis tepat adalah... Natriumklorida","Fenobarbital","Tinea korporis Adrenalin","Candidiasis Natrium bicarbonate"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada kasus ini ditemukan hifa pada pemeriksaan specimen sehingga menunjukkan adanya jamur. Keluhan pada pasien menunjukkan tanda tinea pedis yaitu dermatofitosis pada kaki, terutama pada sela-sela jari dan telapakkaki.","answerPage":182,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-128","number":128,"package":"Paket 2","topic":"Campuran","title":"Soal 128 · Seorang wanita usia 30 tahun datang ke…","page":134,"stem":"Seorang wanita usia 30 tahun datang ke IGD RS dengan keluhan nyeri pinggang kencing berwarna merah bercampur darah. Sebelumnya pasien mengaku makan jengkol terlalu banyak. Pada pemeriksaan vital sign dalam batas normal. Antidotum yan9","options":["Sulfas atropine","Natrium klorida","Fenobarbital","Adrenalin","Natrium bicarbonate"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Intoksikasi asam jengkolat : konsumsi terlalu banyak jengkol, tersaturasi berlebih (karena asam jengkolat sulit diekskresi oleh ginjal dan bila sudah tersekresi direabsorpsi kembali oleh lengkung henle) kemudian akan terbentuk Kristal asam jengkolat yang tajam sehingga akan merusak glomerulus, terjadi glomerulonefritis dan akan timbul keluhan nyeri pinggang dan hematuria. Penatalaksanaan:antidotum natrium bicarbonate dan rehidrasi","answerPage":182,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-129","number":129,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 129 · Seorang koass sedang mengikuti operasi section caesaria,…","page":134,"stem":"Seorang koass sedang mengikuti operasi section caesaria, pada saat operasi matanya terciprat darah pasien yang terkena hepatitis B. Koass tersebut pernah mendapatkan booster hepatitis B sekitar I tahun yang lalu pada saat sebelum koass. Yang dilakukan koass tersebut","options":["Tak perlu profilaksis","Meminta suntikan HBIg","Meminta suntikan HBIg dan hepatitis B","Meminta suntikan vaksin hepatitisB","Periksa anti-HBs"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Booster imunisasi hepatitis B secara rutin tidak direkomendasikan kecuali pada orang imunosupresi yang tidak terdeteksi anti-HBs. Dosis booster direkomendasikan ketika anti-HBslevel<10mlU/mL.","answerPage":182,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-130","number":130,"package":"Paket 2","topic":"Campuran","title":"Soal 130 · Seorang anak perempuan usia I I tahun…","page":134,"stem":"Seorang anak perempuan usia I I tahun dibawa Oleh ibunya ke klinik tempat anda praktek karena keluar tinja dari vaginanya. Tidak ada keluhan lain. Pemeriksaan vital sign nadi 88x/menit, RR 16x/menit, suhu 36 oc. Diagnosis pasien ini adalah","options":["Fistula rektovagina","Fistula urethrovagina","Atresia ani","Atresia vagina","Fistula rektourethra"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":183,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-131","number":131,"package":"Paket 2","topic":"Neurologi","title":"Soal 131 · Seorang wanita usia 60 tahun datang dibawa…","page":134,"stem":"Seorang wanita usia 60 tahun datang dibawa keluarganya ke RS dengan keluhan sesak nafas sejak 30 menit yang lalu. Dari keluarganya didapatkan informasi, pasien sedang makan kemudian tersedak dan muntah dan tiba-tiba sesak nafas. Pasien memiliki riwayat stroke, sulit menelan dan lemah anggota gerak (hemiparese) sejak I tahun yang lalu. Pemeriksaan vital sign TD 160/90 mmHg, nadi 112x/menit, RR 40x/menit cepat dan dangkal, suhu 37 oc. Pemeriksaan fisik paru didapatkan ronki basah dan kedua kaki sianosis. Diagnosis pada pasien ini adalah.„","options":["Pneumosia atipik","Bronchitis akut","Bronkiektasis","Asma bronkiale","Pneumonia aspirasi"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"; Pada pasienididapatkanadanyaiwayat sat makan teredak dnmutahKmudin pasien tibataeaafejlanikadaeniirasiasienniaf karena aspirasi makanan yang ditunjang dengan adanya frekuensi nafas 40x/menit cepat dan dangkal dan ditemukan ronki basah pada paru.","answerPage":183,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-132","number":132,"package":"Paket 2","topic":"Campuran","title":"Soal 132 · Seorang wanita usia 30 tahun datang dengan…","page":134,"stem":"Seorang wanita usia 30 tahun datang dengan keluhan keluar nanah dari saluran kencingnya. Pasien memiliki riwayat kontak seksual sekitar 3 hari yang lalu. pemeriksaan vital sign TD 120/80 mmHg, nadi 88 x/menit, RR 20 x/menit, suhu 38 oc. Pemeriksaan fisik didapatkan orifisium uretra eksterna berwarna kemerahan, bengkak dan terasa nyeri• Diagnosis pasien ini adalah","options":["Herpes zooster","Ulkus mole","Sifilis","Limfogranuloma venerum","Gonorea"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada anamnesis dan gejala pasien ini mengarah pada gonorea dimana gambaran klinis dan perjalanan penyakit pada wanita berbeda dengan pria. Mulanya hanya serviks uteri yang terkena infeksi. Secret tubuh yang mukopurulen dan banyak mengandung gonokokus mengali keluar dan menyerang uretra, duktus parauretra, kelenjar bartoloni, rectum dan dapat naik sampai kandung telur. Pada uretritis gonorea gejala utama adalah disuria, kadang poliuria. Pada pemeriksaan tampak OUE merah, edematosa dan ada sekret mukopurulen. Sedangkan siflis, limfagranuloma venerum dan ulkus mole tidak didapatkanadanyasekretmukopurulen.","answerPage":183,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-133","number":133,"package":"Paket 2","topic":"Anak","title":"Soal 133 · bayi ditemukan meninggal dalam keadaan Iuka lecet…","page":135,"stem":"bayi ditemukan meninggal dalam keadaan Iuka lecet di leher serta tampak di mulut.Tes apung paru (+). Penyebab kematian bayi adalah","options":["Abortus","Kematian wajar","Infantisid","Mati karena kelainan paru","Penelantaran bayi"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada variselapengobatanbersifat simtomatikdengan analgesicdanantipiretikdan untuk menghilangkan rasa gatal diberikan sedative.Terapi local dengan pemberian bedak yang ditambahdenganzatantigataluntukmencegahpecahnyavesikelsecaradini,serta menghilangkanrasa gatal.Jika timbul infeksi sekundermaka diberikan antibioticsalep dan oral. Dapat pula diberikan obat antivirus.","answerPage":183,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-134","number":134,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 134 · seorang mahasiswa kedokteran sedang mendapat tugas untuk…","page":135,"stem":"seorang mahasiswa kedokteran sedang mendapat tugas untuk melakukan penelitian yang di!akukan kepada ibu merokok selama hamil dan berpengaruh terhadap kecerdasan ibu Iupa berapa batang rokok perhari yang dikonsumsi. Bias yang terjadi disebut","options":["Berkson bias","Neyman bias","Volunteer bias","Recall bias","Misclassification bias"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hasiltes apung paru yang positif menunjukkan adanya udara di dalam paru sehingga dapat disimpulkan bahwa bayi pernah hidup sebelumnya atau lahir hidup. Luka yang ditemukan pada bayi dapat dikaitkan dengan penyebab kematiannya. Cara yang paling banyakdjumpai untuk melakukan tindakan pembunuhan adalah menimbulkan keadan matilemas(asfiksia) sepertienjeratan,pencekikan,pembekapan, sertamembenanman ke air. Pada kasus ini ditemukan lebam di mulut dan luka lecet. Pemeriksan tersebut termasuk pembunuhan anak (infantisid).","answerPage":183,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-135","number":135,"package":"Paket 2","topic":"Campuran","title":"Soal 135 · Seorang wanita usia 30 tahun datang ke…","page":135,"stem":"Seorang wanita usia 30 tahun datang ke klinik anda dengan membawa hasil biopsy dari rumah sakit. Ternyata pasien ini terdiagnosis ca cerviks stadium 4. Kemudian ia bertanya •apa benar saya sakit seperti ini?apa tidak salah dok?\" Sikap anda sebagai dokter adalah...","options":["Menangis","Simpati","Empati","Marah","Perhatian"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Recall bias merupakan bias informasi, individu diminta untuk mengingat tentang apa yang pernah dialaminya terpapar factor risiko pada masa lampau.","answerPage":184,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-136","number":136,"package":"Paket 2","topic":"Campuran","title":"Soal 136 · Seorang wanita usia 30 tahun datang ke…","page":135,"stem":"Seorang wanita usia 30 tahun datang ke klinik anda dengan membawa hasil biopsy dari rumah sakit. Ternyata pasien ini terdiagnosis ca cerviks stadium 4. Kemudian ia bertanya \"apa benar saya sakit seperti ini?apa tidak salah dok?\" Sikap anda sebagai dokter adalah..","options":["Menangis","Simpati","Empati","Marah","Perhatian"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Empati merupakan kesadaran emosionaldan intelektualdan pengertian terhadap pikiran, perasaan dan perilaku orang lain. Empati menekankan pada pengertian akan perasaan dan perilaku orang lain. Sedangkan simpati menekankan turut berbagi perasan dan pengalaman orang lain.","answerPage":184,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-137","number":137,"package":"Paket 2","topic":"Bedah","title":"Soal 137 · Seorang Iaki-laki usia 34 tahun mengalami kecelakaan…","page":135,"stem":"Seorang Iaki-laki usia 34 tahun mengalami kecelakaan lalu lintas, setelah diperiksa ternyata ia mabuk dan baru putus dengan pacarnya. Dia meminta anda agar tidak menulis di rekam medis karena takut karirnya terancam sebagai tenaga medis. Yang sebaiknya anda Iakukan adalah","options":["Tetap menuliskan di rekam medis","Tidak menuliskan karena rahasia kedokteran","Meminta peravvat lain menuliskan","Meminta dokter jaga Iain menuliskan","Meminta pasien menulis sendiri karena dia adalah tenaga medis"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dalam permenkes no 749a tahun 1989 rekam medis adalah berkas yang berisi catatan dokumen tentang identitas pasien, pemeriksan, pengobatan, tindakan dan pelayanan lain kepada pasien pada sarana pelayanan kesehatan. Untuk itu hasil pemeriksan yang didapatkan pasien dituliskan dalam rekam medis sesuai pemeriksan yang ada.","answerPage":184,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-138","number":138,"package":"Paket 2","topic":"Kulit","title":"Soal 138 · Seorang wanita usia 45 tahun datang dengan…","page":135,"stem":"Seorang wanita usia 45 tahun datang dengan keluhan lepuh kulit di kepala, wajah, badan dan ekstremitas sejak dua bulan yang lalu. Pemeriksaan dermatotoksik tampak vesikel dan bula generalisata berdinding tebal di atas kulit yang eritematosa dan edematosa. Pada Pemeriksaan hispatologik menunjukkan vesikel subepidermis, sementara pemeriksaan imunofluoresensi langsung memperlihatkan endapan IgG di membrane basal Diagnosis pasien ini adalah","options":["Pemfigus vulgaris","Pemfigus bulosa","Dermatitis herpetiform","Lupus eritematous","Sindrom steven jhonson"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pemfigus vulgaris memiliki gejala khas yaitu : b.Keadaan umum penderita biasanya buruk c.Pembentukan bula kendur pada kulit mudah pecah lesi generalisata d.Padapenekaananbula tersebutmeluas e.Akantolisis selalu positif Adanya antibody IgG terhadap antigen interseluler di epidermis dan dapat ditemukan dalamserummaupun terikat diepidermis.","answerPage":184,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-139","number":139,"package":"Paket 2","topic":"Mata","title":"Soal 139 · Seorang laki-laki usia 60 tahun datang dengan…","page":136,"stem":"Seorang laki-laki usia 60 tahun datang dengan keluhan pandangan buram terutama ketika membaca dekat sejak dua bulan terakhir. Menurut pasien, ia sudah mengidap diabetes mellitus sejak 5 tahun yang lalu. Pemeriksaan funduskopi didapatkan lesi intralateral terutama daerah polus posterior berupa mikroorganeurisma, perdarahan bintik dan bercak, hard and soft exudat, oedema, neovaskularisasi dan perdarahan vitreous. findakan yang tepat untuk pasien ini adalah","options":["Vitrektomi","Konsul spesialis penyakit dalam","Fotokoagulasi laser","Obat empiris seperti vitamin E, enico dan antioksidan Iain","Edukasi control gula darah dengan ketat"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Fotokoagulasi panretina laser argon biasanya dindikasikan untuk retinopati diabetes proliferative. Pasien berisiko paling besar mengalami penurunan penglihatan bermakna jika terdapat perdarahan praretina atau korpus vitrum atau neovaskularisasi diskus. Pada pasien ini fotokoagulasi panretina dapat secara bermakna menurunkan kemungkinan perdarahan massif korpus vitreum dan pelepasan retina dengan menimbulkan regresi dan hilangnyapembuluh-pembuluhbaru tersebut.","answerPage":184,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-140","number":140,"package":"Paket 2","topic":"Bedah","title":"Soal 140 · Seorang laki-laki usia 20 tahun datang ke…","page":136,"stem":"Seorang laki-laki usia 20 tahun datang ke praktik dokter dengan membawa hasil foto rontgen. Dari foto tersebut terlihat pembengkakan jaringan lunak, reaksi periosteal (+), terdapat proses osteolitik dan osteosklerotik, serta garis fraktur (+). Diagnosis yang mungkin pada pasien ini adalah","options":["Osteoma","Giant cell tumor","Sarcoma ewing","Osteosarkoma","Kondroblastoma"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Osteosarkoma merupakan tumor ganas primer tulang yang paling sering dengan prognosis buruk. Pada gambaran radiologi tampak tanda-tanda destruksi tulang yang","answerPage":184,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-141","number":141,"package":"Paket 2","topic":"Campuran","title":"Soal 141 · Seorang anak laki-laki usia 9 tahun datang…","page":136,"stem":"Seorang anak laki-laki usia 9 tahun datang dengan alopesia di kepala, diameter 3 cm, terdapat titik hitam ditengah dan KOH menunjukkan hifa sejati dari batang rambut Penatalaksanaan keadaan ini adalah","options":["Sampo bifonazole","Krim mikonazole","Tablet ketokonazole","Tablet amfoterisin B","Tablet griseosulvin"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"sulde vidneinataamangengandgeriva alm dua kali seminggu dapat mencegah penularan dan perluasan infeksi serta bermanfat mempercepat kultur negatif.","answerPage":185,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-142","number":142,"package":"Paket 2","topic":"Campuran","title":"Soal 142 · Anak perempuan 9 tahun dengan berat badan…","page":136,"stem":"Anak perempuan 9 tahun dengan berat badan 25 kg mengalami demam selama 3 hari. Diberikan parasetamol 10 mg/kg berat badan per dosis, dalam sediaan tablet 500 mg, untuk 4 hari. Berapa jumlah tablet yang diberikan?","options":["VI","VIII","IV","XX","X"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dosis paracetamol sehari= 25kg x 10 mg/kgBB = 250 x3 = 750 mg Dibutuhkan untuk 4 hari = 4 x 750 mg = 3000 mg Kaplet yang diberikan untuk 4 hari = 3000/500 = 6 tablet","answerPage":185,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-143","number":143,"package":"Paket 2","topic":"Campuran","title":"Soal 143 · Perempuan 40 tahun mengeluhkan benjolan payudara sejak…","page":137,"stem":"Perempuan 40 tahun mengeluhkan benjolan payudara sejak 1,5 tahun, tidak nyeri, berdiameter 1,5 cm, dapat digerakkan, dan berkonsistensi kenyal. Tekanan darah 120/80 mmHg, nadi 80 kali/menit, napas 20 kali/menit, suhu 36 °C. Apakah penatalaksanaan selanjutnya?","options":["Biopsy insisi","USG payudara","Mammografi","Pengangkatan benjolan","Pengangkatan payudara"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pemeriksaan penunjang denganmammografi dapat ditemukan benjolanyang kecil sekalipun pada pemeriksaan tidak teraba.Bila mammograf positif dan secara klinis tidak teraba tumor, pemeriksaan harus dialnjutkan dengan pungsi atau biopsy di tempat yang ditunjukkanolehfototersebut.UsGbergunaterutamauntukmenentukanadanyakista. Akdangtampakkistasebesar1-2cm.","answerPage":185,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-144","number":144,"package":"Paket 2","topic":"THT","title":"Soal 144 · seorang anak laki-laki usia 17 tahun dib…","page":137,"stem":"seorang anak laki-laki usia 17 tahun dib awa ke IGD dalam keadaan tidak sadar setelah kecelakaan lalu lintas sekitar 1 jam yang lalu. Pasien diketahui terlempar dari sepeda motor dan kepalanya membentur aspal. Pada pemeriksaan fisik TD 120/80 mmHg, nadi 80 x/menit, RR 20x/menit, suhu 36,5 oc. tidak terdapat perdarahan hidung dan telinga. Hasil pemeriksaan CT scan ditemukan perdarahan dengan gambaran berbentuk bikonkaf. Terapi yang diberikan untuk pasien ini adalah","options":["Masuk ICU","Antitrombolitik","Burr hole","Resusitasi cairan","Pembedahan terbuka"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien ini menderita hematom epidural, penatalaksanaan yang harus dilakukan segera adalah dengan cara trepanasi yaitu tindakan bedah dengan menggunakan trepan (sejenis bor). Tujuannya untuk melakukan evaluasi hematom dan menghentikan perdarahan.","answerPage":185,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-145","number":145,"package":"Paket 2","topic":"Neurologi","title":"Soal 145 · seorang Iaki-laki usia 40 tahun dibawa ke…","page":137,"stem":"seorang Iaki-laki usia 40 tahun dibawa ke IGD RS dengan keluhan lemah pada kedua tungkai dan lengan secara tiba-tiba. Pasien tidak memiliki riwayat hipertensi. Sekitar dua minggu sebelumnya pasien batuk dan pilek kemudian sembuh. Pada pemeriksaan vital sign didapatkan tekanan darah 120/80 mmHg, nadi 80 x/menit, RR 20x/menit, suhu 36.50C, hand and glove parestesi. Diagnosis yang mungkin adalah","options":["Myelitis","Miopati","Stroke hemmoragic","Poliomyelitis","Guillan bare syndrome"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kerusakan pada radiks ventralis dan dorsalis yang reversible serta menyeluruh dapat teriadin Keadan itu dikenal dengan indrom guillan bare SGB). Manifestasi klinisnya adalah sebelum kelumpuhan terjadi terdapat infeksi traktus respiratorius bagjian atas Kelumpuhan timbul pada keempat ekstremitas dan umumnya bermula di bagian distal tungkai dan meluas ke bagian proksimal. Pada tahap permulaan gannguan miksi dan defekasijuga dapatterjadi.","answerPage":185,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-146","number":146,"package":"Paket 2","topic":"Campuran","title":"Soal 146 · Seorang laki-laki usia 55 tahun terdiagnosis Oleh…","page":137,"stem":"Seorang laki-laki usia 55 tahun terdiagnosis Oleh dokter terkena sirosis hepatis. Pasien ini datang dengan keluhan muntah darah. Terdapat riwayat distensi abdomen, dilatasi vena dari dinding abdomen anterior dan hemoroid interna selama 2 bulan. Vena manakah yang menjadi sumber dari hematemesis tersebut?","options":["Vena gastric sinistra","Vena rectal superior","Vena mesenterika inferior","Vena periumbilikalis","Vena cava superior"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Jika terjadi obstruksi tekanan vena porta akan meningkat dan jalur kolateral antara system vena porta dan sistemik akan terbuka.Komunikasi jalur kolateral yaitu : a. Antara cabang esophageal vena gastric sinistra dan vena esophageal system azigosis (varisesesophageal danhematemesisberat) b. Antara cabang rectal superior vena mesenteric inferior dan vena rectal inferior yang drainase ke vena iliaka interna melalui pudendal interna (hemoroid) C. Antara cabang portal di mesenteric dan mesokolon dan vena retroperitoneal d.Antara cabang portal di liver dan vena dinding abdomen via vena yang melintasi ligament falsiform dari umbilicus (caput medusa) e.Antara cabang porta di liver dan vena diafragma","answerPage":186,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-147","number":147,"package":"Paket 2","topic":"Anak","title":"Soal 147 · Criteria nafas cepat pada bayi usia <…","page":137,"stem":"Criteria nafas cepat pada bayi usia < 2 bulan adalah","options":["> 20 x/menit","230 x/menit","240 x/menit","2 50 x/menit","2 60 x/menit"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Menurut MTBSkriteria nafascepatberdasarkanumuranakadalahsebagai berikut: <2bulan :≥60x/menit 2bulan-12 bulan:≥50x/menit 12bulan-5tahun:≥40x/menit","answerPage":186,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-148","number":148,"package":"Paket 2","topic":"Kulit","title":"Soal 148 · Seorang anak Iaki-laki usia tohun (libawa Ilouny,\"…","page":138,"stem":"Seorang anak Iaki-laki usia tohun (libawa Ilouny,\" ke dengan keluhan pada sela Jari tangan dan tungkal. Paslen memjllkl yang ticlak higienjs. sebangkunya juga mengeluh hal yang sama, Pernerilc;aan lokalis diclapatkan eritema, papul, pustule dan vesikula. yang paling mungkln pada","options":["Herpes simpleks","Herpes zoster","Dermatitis atopi","Skabies","Varisela"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Scabies adalah penyakit yang disebabkan karena infestasi dan sensitisasi terhadap Sarcoptesscabei.Faktor penunjang perkembangan penyakit ini antara lain kondisi sosioekonomi yang rendah, hygiene yang buruk, hubungan seksual yang sifatnya promiskuitas serta perkembangan demografik dan ekologik. Gejala klinis scabies adalah pruritus nokturna (gatal pada malam hari karena aktivitas tungau yang lebih tinggi pada malam hari), biasanya menyerang secara berkelompok, adanya terowongan (kanikulus) pada tempat predileksi yang berwarna putih atau keabu-abuan.Pada ujung terowongan ditemukan papula dan vesikel. Jika timbul infeksi sekunder, ruam kulit menjadi polimorf (pustule, ekskoriasi, dll).Tempat predileksi biasanya merupakan tempat dengan stratum korneumyang tipisyaitu sela-sela jari tangan,pergelangan tanganbagianvolar,siku bagianluar,lipatketiakbagiandepan,areola mammae,umbilicus,bokong,genitalia eksterna dan perutbagianbawah.Pada dermatitis atopi dan varisela,faktor utamabukan karenahigieneyangrendahdantempatpredileksijuga berbeda.","answerPage":186,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-149","number":149,"package":"Paket 2","topic":"Campuran","title":"Soal 149 · Seorang wanita usia 35 tahun datang dengan…","page":138,"stem":"Seorang wanita usia 35 tahun datang dengan keluhan sesak nafas, Hasil pemeriksaan laboratorium SGPT dan SGOT dalam batas normal, foto thoraks menunjukan cairan di basal paru. USG abdomen menunjukkan tumor ovarium clekstra dan ascites Diagnosis pasien ini adalah...","options":["Edema paru","Sindrom meigs","Sindrom kartagener","Sindrom eisenmenger","Sindrom nefrotik"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Sekitar 40 % dari kasus fibroma ovariditemukan asites dan hidrotoraks dikenal dengan sindromeigsCairandarronggatoraksberasaldrcairandalamonggapertAdany cairan di hidrotoraks menyebabkan pasien sesak. Sindrom meigs perlu dibedakan dari ascites dengan atau tanpahidrotoraks yang ditemukan pada tumor ganas. Dalam hal ini ditemukan sel-sel ganas dalam sedimen cairan.","answerPage":187,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-150","number":150,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 150 · Seorang ibu membawa anak Iaki-lakinya usia 2…","page":138,"stem":"Seorang ibu membawa anak Iaki-lakinya usia 2 bulan ke puskesmas karena bibir sumbing. Keadaan umum pasien baik, tidak batuk dan tidak pilek. Berat badannya 4,5 kg. didapatkan labiognatopalatoskisis unilateral sinistra komplit. Hasil pemeriksaan laboratorium Hb II g/dl. Tidak didapatkan kelainan Iain. USia pasien yang tepat untuk melakukan labioplasti adalah...","options":["IO tahun","20 bulan","IO minggu","IO hari","20 jam"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kelainan labiopalatoskisis sebaiknya secepat mungkin diperbaiki karena akan mengganggu pada saat menyusuidanakan mempengaruhipertumbuhannormalrahang serta perkembangan bicara. Koreksinya dapat dilakukan bertahap atau sekaligus. Saat melaksanakan tindakan koreksi digunakan hukum sepuluh yaitu berat badan minimal4,5 kg (10 pon), kadar hb 10 g% dan usia sekurang-kurangnya 10 minggu.","answerPage":187,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-151","number":151,"package":"Paket 2","topic":"Campuran","title":"Soal 151 · Seorang Iaki-laki berusia 20 tahun, datang dengan…","page":138,"stem":"Seorang Iaki-laki berusia 20 tahun, datang dengan keluhan sesak yang dialaminya sejak I minggu yang lalu. Sejak satu bulan yang lalu, pasien mengalami demam dan batuk Saat ini keluhan demam bertambah berat. Pada pemeriksaan foto thoraks dan ditemukan terdapat lesi radiopak milier. Apakah penyebab lesi tersebut?","options":["Lesi akibat penyebaran melalui cairan pleura","Lesi akibat penyebaran melalui lesi primer","Lesi akibat penyebaran limfatik","Lesi akibat penyebaran hematogen","Lesi melalui bronkus"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Diagnosis yang paling mungkin pada pasien ini adalah TB milier yang merupakan salah satu bentuk TB ektra paru yang terjadi akibat penyebaran hematogen dari basil tuberkel. Lesimilierbiasanya berupa granuloma kekuningan berdiameter 1-2 mm yang menyerupai biji millet (sejenis padi-padian, sehingga disebut milier).","answerPage":187,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-152","number":152,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 152 · Data penyakit di Puskesmas Karangjambu bulan agustus-september…","page":138,"stem":"Data penyakit di Puskesmas Karangjambu bulan agustus-september 2013 Penyakit agustus September ISPA 3367 3397 Hipertensi 1330 2009 DBD 2 680 12 Diare Flue burung 0 802","options":["ISPA","Hipertensi","DBD","Diare","Flu burung"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kriteria tentang KejadianLuar Biasa mengacu pada Keputusan DirjenNo.451/91,tentang PedomanPenyelidikandanPenanggulanganKejadianLuarBiasa: 1.Timbulnyasuatupenyakitmenularyang sebelumnya tidakada atau tidakdikenal 2.Peningkatankejadianpenyakit/kematian terus-menerus selama3kurunwaktu berturut-turut menurut jenis penyakitnya (jam,hari, minggu) 3.Peningkatankejadian penyakit/kematian 2 kali lipat atau lebih dibandingkan dengan periode sebelumnya (jam, hari, minggu, bulan, tahun). 4. Jumlah penderita baru dalam satu bulan menunjukkan kenaikan 2 kali lipat atau lebih bila dibandingkan dengan angka rata-rata perbulan dalam tahun sebelumnya. 5. Timbulnya lagi suatu penyakit yang sudah lama tiada.","answerPage":187,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-153","number":153,"package":"Paket 2","topic":"Campuran","title":"Soal 153 · seorang perempuan berusia 18 tahun datang dengan…","page":139,"stem":"seorang perempuan berusia 18 tahun datang dengan keluhan sulit tidur sejak seminggu yang lalu. pasien mengeluh mudah terbangun dimalam hari dan sulit untuk tidur kembali. pasien juga kehilangan minat untuk beraktivitas, nafsu makan menurun, mudah lelah dan hilang energi. Apa jenis gangguan ticlur pada pasien tersebut?","options":["Parasomnia","Somnabulisme","Early insomnia","Middle insomnia","Late insomnia"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Early insomnia:Sulit mulai tidur, sering berhubungan dengan gangguan cemas Middle insomnia: sulit untuk tetap tidur, sering terbangun. Berhubungan dengan penyakit somatis, nyeri, atau depresi. Late insomnia:bangun terlalu cepat,sering berhubungan dengan depresi mayor Somnambulisme:tidur sambil berjalan. buruk, sleep terror, dan somnambulisme termasuk dalam parasomnia.","answerPage":187,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-154","number":154,"package":"Paket 2","topic":"Anak","title":"Soal 154 · seorang bayi Iaki-laki umur 3 bulan dibawa…","page":139,"stem":"seorang bayi Iaki-laki umur 3 bulan dibawa ke puskesmas dengan keluhan terdapat benjolan kebiruan di temporal kanan. Benjolan muncul pada usia 1 minggu dan semakin membesar secara perlahan. Bayi tampak tidak terganggu. Kadang benjolan membesar saat pasien menangis. Saat ini diameter benjoJan 3,5 cm. Penanganan apakah yang paling tepat?","options":["Observasi","Eksisi massa","Ekstirpasi","Injeksi sklerosan","Injeksi kortikosteroid"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejalaklinisyangdtudahadanabeolankebiruanditmoralkananandt membesar sat pasien menangis. Hemangioma kavernosum dari luar tampak sebagai tumor kebiruan yang dapat dikempeskan dengan penekanan,tetapi menonjol kembali setelah tekanan dilepaskan. Hemangioma buah arbei sebaiknya dibiarkan mengalami regresi spontan. Jenis flameus ditanggulangi dengan eksisi, kalau perlu ditambah dengan cangkok kulit. Untuk hemangioma kavernosa satu-satunya terapiadalah dengan ektirpasi.","answerPage":188,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-155","number":155,"package":"Paket 2","topic":"Kulit","title":"Soal 155 · Seorang anak Iaki-laki berusia 6 tahun datang…","page":139,"stem":"Seorang anak Iaki-laki berusia 6 tahun datang dengan keluhan gatal pada seluruh tubuh setelah makan udang. Pada pemeriksaan fisik terdapat kulit eritema dan edema setempat yang berbatas tegas, bagian tengah tampak pucat membentuk plakat seperti pulau. Apa 1. diagnosis yang tepat pada pasien ini?","options":["Urtikaria","Angioedem","Sindrom steven johnson","Fixed drug eruption","Nekrolitis epidermolisis toksik"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Urtikaria : Eritema dan edema setempat berbatas tegas, bagian tengah tampak pucat, gatal, riwayat makan makanan laut. Penatalaksanaan: Difenhidramin 25 mg IV atau 50 mg IM/PO pada masa akut. Setelah itu, gunakan antihistamin oral.","answerPage":188,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-156","number":156,"package":"Paket 2","topic":"Kulit","title":"Soal 156 · Seorang wanita berusia 19 tahun datang ke…","page":139,"stem":"Seorang wanita berusia 19 tahun datang ke klinik dengan keluhan keluar cairan berwarna kuning dari vagina dan kadang disertai gatal. Dari pemeriksaan tanda vital didapatkan tekanan darah 110/70 mmHg, nadi 80 x/menit, frekuensi nafas 20x/menit dan suhu 36,5 Pada pemeriksaan mikroskopik ditemukan serbukan leukosit. Penyebab keluhan pada pasien ini adalah...","options":["N. gonore","Candida albicans","Chlamydia trachomatis","U ureolitikum","G. vaginalis"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejala yang timbul pada pasien ini seperti keluar cairan berwarna kuning dari vagina dan kadang disertai gatal, pemeriksan mikroskopik ditemukan serbukan leukosit mengarah pada infeksi genital nonspesifk yang disebabkan Chlamidia Trachomatis. Pada N. gonore didapatkan diplokokus gram (-), sedangkan candida albicans akan ditemukan hifa semu pada pemeriksaan KOH.","answerPage":188,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-157","number":157,"package":"Paket 2","topic":"Mata","title":"Soal 157 · Seorang pria berusia 35 tahun datang ke…","page":140,"stem":"Seorang pria berusia 35 tahun datang ke ternpat praktek dokter dengan penglihatan menjadi ganda sejak beberapa minggu yang lalu, Keluhan disertai mata menjadi berat terutama pada Siang hari setelah beraktivitas. pada pemeriksaan sign didapatkan tekanan darah 120/80 mmHg, nadi 80x/rnenit, frekuensi nafas dan temperature 36,8 oc. Dari pemeriksaan fi3ik terdapat ptosi% kanan dan kedua bol mata tidak dapat bergerak ke nasal. Diagnosis yang tepat pada pasien ini adalah.","options":["Krisis kolinergik","Neuropati","Syndrom guillan barre","Hipokalemia","Myastenia gravis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Miastenia gravis ditandai oleh kelemahan abnormal otot-otot serat lintang setelah kontraksi berulang. Membaik setelah istirahat dan sering pertama kali bermanifestasi sebagai kelemahan otot-otot ekstraokuler. Ptosis unilateral karena kelelahan otot sering merupakan tanda awal dikuti oleh keterlibatan otot-otot ekstraokuler bilateral sehingga gejala awalsering berupa diplopia.Gejala matalainyangtidaklazim mungkin miripdengan gangguan melihat, oftalmoplegia antarnukleus, nistagmus vertikal, dan oftalmiplegia eksternal progresif.Pada kasusyang tidak diobati dapat segera timbul kelemahan umum lengan dan tungkai serta kesulitan bernapas. Kelemahan ini memperlihatkan variasi diurnal dan sering memburuk seiring perjalanan hari, tetapi dapat membaik setelah tidur siang.Tidakterjadigangguansensorik.","answerPage":188,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-158","number":158,"package":"Paket 2","topic":"Mata","title":"Soal 158 · Seorang 'aki-laki berusia 25 tahun datang dengan…","page":140,"stem":"Seorang 'aki-laki berusia 25 tahun datang dengan keluhan mata mengganjal sejak I buJan yang lalu. Selain itu, pasienjuga sering mengeluhkan mata merah yg hilang tirnbul Pasien merupakan supir angkutan umum. pada pemeriksaan mata didapatkan selaput berbentuk segitiga dengan puncak 2 mm dari kornea, belum sampai pupil. pemeriksaan tes sondase didapatkan sondase tidak dapat masuk. Diagnosis pada pasien ini","options":["Pterigium","Pseudopterigium","Pinguekulitis","Skleritis","Hematom subkonjungtiva"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Beberapa penyakit pada mata merah dengan visus normal adalah : Mata merah,visus normal pterigium pinguekula Hematom Episklertitis. subkonjuntiva skelritis Pterigium Pinguekula Hematom episkleritis pseudopterigium subconjuntiva Radang:merah, Radang:merah astigmatisme akibat pembuluh Mataterasa Perlekatan darah ygmelebar kering,menganjal, konjuntiva dg Letakcelah letakdicelah nyeriringan kornea kelopakbag kelopakmata Benjolan setempat letak Tidak harus nasal/temporal dgbatastegas, pd celahkelopak bagian nasal warnamerahungu yang meluaske ataufisura dibawah konjuntiva,dapat kornea konjuntiva, diselipkan sonde dibawahnya Iritsi kronisoleh Seringterpapar Keadaan Umumnya satu udara yg panas, udara ygpanas, pembuluh darah mata,pdwanita cahaya,debu cahaya,debu rapuh Usia,HT, usia pertengahan trauma dgbawanrematik Tidakperlukarena Tidak perlu Tdk perlu Vasokonstriktor: seringrekuren, pengobatan pengobatan, fenil efrin 2,5%, jika meradang: kecualiada diserap spontan1- berat; steroidatau peradangan 3mgg kortikosteroid dekongestantetes mata","answerPage":189,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-159","number":159,"package":"Paket 2","topic":"Campuran","title":"Soal 159 · Seorang Jaki-Jaki berusia 35 tahun datang dengan…","page":140,"stem":"Seorang Jaki-Jaki berusia 35 tahun datang dengan keluhan nyeri hebat pada pinggang Hal ini terjadi setelah pasien mengkonsumsi jengkol. Urine sedikit dan berwarna merah. Obat yang tepat untuk mengatasi hal ini adalah...","options":["Magnesium klorida","Magnesium hidroksida","Natrium bicarbonate","Bisokodil","Karbon aktif"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Antidotum jengkol yang tepat padakasus tersebut adalahnatriumbicarbonate 4x 2 gram/hari.","answerPage":189,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-160","number":160,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 160 · Seorang wanita berusia 45 tahun datang ke…","page":140,"stem":"Seorang wanita berusia 45 tahun datang ke dokter dengan keluhan Iuka di kaki kanan yang tidak kunjung sembuh. Keluhan ini telah berlangsung sejak 5 bulan yang lalu. Pasien merupakan seorang karyawan swasta, menikah, memiliki 5 orang anak dan memakai kontrasepsi oral. Dari pemeriksaan fisik didapatkan tinggi badan 155 cm, berat badan 80 kg, ditemukan ulkus supratroklear medial dekstra, basah dan kulit sekitar kehitaman. Diagnosis yang tepat pada pasien ini adalah...","options":["Ulkus diabetikum","Ulkus kronik e.c sumbatan aorta","Ulkus e.c thrombosis vena","Ulkus varikosum","Ulkus e.c lupus"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien memiliki riwayat memakai kontrasepsi oral. Pada kontrasepsi ini biasanya terdiri atas komponen estrogen dan progesteron, atau salah satu dari komponen tersebut. Efek samping berat yang dikhawatirkan dari otak adalah trombo emboli, termasuk tromboflebitis, emboli paru, dan trombosis otak. Kemungkinan terjadi tromboemboli pada wanita yang memakai kontrasepsi pil akanlebih besarapabila ada faktor predisposisi, seperti merokok, hipertensi, diabetes mellitus, dan obesitas.","answerPage":189,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-161","number":161,"package":"Paket 2","topic":"Anak","title":"Soal 161 · Seorang bayi berusia 3 hari dibawa Oleh…","page":140,"stem":"Seorang bayi berusia 3 hari dibawa Oleh orangtuanya ke IGD dengan keluhan selalu terlihat pucat dan biru. Kemudian dokter melakukan pemeriksaan foto thoraks, didapatkan gambaran boot shaped heart. Diagnosis yang tepat pada pasien ini adalah...","options":["ASD","VSD","Tetralogi fallot","Stenosis katup mitral","PDA"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tetralogi fallt adalahkelainanjantung bawaan siantik yang ediri atasdefek septum ventrikel, pulmonal stenosis, hipertropi ventrikel kanan dan overiding aorta. Pada pemeriksaanfot thoraksdidapatkangambaranbootshapedheart dancorakanvascular paru yang menurun.","answerPage":190,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-162","number":162,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 162 · seorang Jaki-Jaki berusia 38 tahun datang dengan…","page":141,"stem":"seorang Jaki-Jaki berusia 38 tahun datang dengan keluhan sering sakit kepala dan leher kencang. Dari pemeriksaan tekanan darah 150/90 rnrnHg, Dokter mendiagnosis hipertensi. Namun pasien memiliki riwayat asrna. Obat hipertensi yang kontraindikasi pada pasien ini adalah... Captopril","options":["Metildopa","Metildopa propanolol","Propanolol","Nifedipin","Furosemid"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kontraindikasi tidak Kontraindikasi mutlak Obat Indikasi mutlak Penyakit pembuluh Betablocker Angina pectoris Asma darah perifer (propanolol) Pasca infark PPOK Intoleransi glukosa Miokardium Blok A-V (derajat 2-3) Pasien yang aktif fisik Gagal jantung kongestif Kehamilan takiaritmia","answerPage":190,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-163","number":163,"package":"Paket 2","topic":"Psikiatri","title":"Soal 163 · seorang perempuan berusia 26 tahun sering melamun,…","page":141,"stem":"seorang perempuan berusia 26 tahun sering melamun, mengoceh sendiri dan jika ada teman mengobrol didekatnya merasa curiga bahwa ternan-temannya sedang 1. membicarakan dia. Pasien mengeluh seperti ini setelah dipindahtugaskan ke bagian operator. Gangguan kejiwaan pada pasien ini","options":["Halusinasi auditorik","Flight of ideas","Obsesif kompulsif","Waham paranoid","Episode maniak"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Waham paranoid adalah waham menetap berupa kecurigaan terhadap orang yang beradadisekitarnyaataudidekatnya.","answerPage":190,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-164","number":164,"package":"Paket 2","topic":"Mata","title":"Soal 164 · seorang anak perempuan berumur 8 tahun dibawa…","page":141,"stem":"seorang anak perempuan berumur 8 tahun dibawa ke dokter umum dengan keluhan penglihatan kabur. Bila sedang dikelas, ia duduk dibelakang. Namun karena tidak dapat melihat tulisan di papan tulis ia selalu dipindahkan gurunya agar duduk di depan. Anak tersebut mengeluh kaburjika melihat jauh. Diagnosis yang tepat pada anak ini adalah...","options":["Katarak congenital","Hipermetropi","Presbiopi","Astigmatisme","Miopi"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien tidak dapat melihat jauh sehingga selalu duduk di depan. Gejala ini merupakan gejala miopi. Pada miopi, sinar-sinar berjalan sejajar dengan sumbu mata tanpa akomodasi di bias depan retina.Terapi yang dberikan adalah lensa negatif (S-) agar tanpa akomodasi dapat melihat denganbaik.Hipermetropi merupakankelainan tidak dapat melihat jarak dekat. Biasanya, terdapat keluhan lelah dan sakit kepala. Jika pungtum proksimum letaknya jauh darijarakbaca seseorang dinamakanprebiopi.Astigmatismus dengan gejala subjektif tidak dapat melihat sinar atau garis sejajar.","answerPage":190,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-165","number":165,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 165 · Seorang wanita berusia 26 tahun datang untuk…","page":141,"stem":"Seorang wanita berusia 26 tahun datang untuk berkonsultasi ke dokter ingin menggunakan alat kontrasepsi, namun pasien ini memiliki riwayat hipertensi sejak 5 tahun ini. Suaminya menolak untuk memakai kondom. Pasien masih ingin memiliki anak sekitar 3 atau 4 tahun mendatang. Kontrasepsi yang tepat pada pasien ini adalah.„","options":["Kalender","Pil esterogen","Pil kombinasi","Implant","AKDR"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"AKDR merupakan kontrasepsi pilihan utama pada kasus ini. AKDR memiliki keunggulan antara lain: a.Tidakmenimbulkanefeksistemik b.Reversible C. Efektifitas cukup tinggi d.Ekonomis dan hanya memerlukan satukalipemasangan Pil kontrasepsi hormonal merupakan kontraindikasi relative pada pasien hipertensi.","answerPage":190,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-166","number":166,"package":"Paket 2","topic":"Bedah","title":"Soal 166 · Seorang laki-laki berusia 50 tahun datang dengan…","page":141,"stem":"Seorang laki-laki berusia 50 tahun datang dengan keluhan terdapat benjolan pada Iipat paha kanan yang muncul saat pasien mengejan dan batuk. Keluhan hilang pada saat berbaring. Tidak ada keluhan mual, muntah dan nyeri. Diagnosis yang tepat pada pasien ini adalah...","options":["Hernia inguinalis","Hernia scrotalis","Hernia femoralis","Hernia umbilikalis","Hernia hiatal"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":191,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-167","number":167,"package":"Paket 2","topic":"Kesehatan Masyarakat","title":"Soal 167 · Seorang peneliti ingin melakukan penelitian case control…","page":142,"stem":"Seorang peneliti ingin melakukan penelitian case control untuk melihat hubungan asfiksia dengan gangguan belajar. Data diperoleh hanya dari ingatan ibunya Saja. Hal tersebut akan menimbulkan bias?","options":["Recall bias","Surveillance bias","Detection bias","Compliance bias","Procedural bias"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"biassemakinbesajikapaparan terjadiberlangsungbertahn-tahunyang lampauatau menyangkut sejumlah faktorlin yang mirip dengan faktor penelitian.","answerPage":191,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-168","number":168,"package":"Paket 2","topic":"Campuran","title":"Soal 168 · Seorang anak perempuan berusia I tahun dibawa…","page":142,"stem":"Seorang anak perempuan berusia I tahun dibawa Oleh orang tuanya ketempat praktik dokter dengan keluhan mencret sejak 2 minggu yang lalu. Selain itu berat badan juga semakin menurun. Pada pemeriksaan fisik ditemukan adanya hepatomegali dan ascites. Pemeriksaan laboratorium didapatkan Hb 6 g/dl, protein total 4,4 mg/dl dan albumin 2.6 mg/dl. Penyebab edema anasarka pada pasien tersebut adalah...","options":["Kurang asam amino esensial albumin","Tekanan onkotik vaskuler rendah","Tekanan hidrostatik vaskuler rendah","Kegagalan hepar sintesis","Prekursornya menurun"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Edema merupakan keadaan dimana terjadi penumpukan cairan interstisial yang berlebihan. Edema dibedakan menjadi 2 yaitu edema yang terlokalisir dan edema generalisata. Penyebabnya selalu berkaitan dengan perubahan kekuatan pada hukum starling yang mengatur distribusi cairan antara kapiler dan ruang interstisial sehingga edema dapat disebabkan oleh tekanan hidrostatik kapiler yang meningkat, tekanan osmotik koloid yang menurun, permeabilitas kapiler yang meningkat atau obstruksi aliran limfatik.","answerPage":191,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-169","number":169,"package":"Paket 2","topic":"Bedah","title":"Soal 169 · Seorang laki-laki berusia 24 tahun datang dengan…","page":142,"stem":"Seorang laki-laki berusia 24 tahun datang dengan Iuka bacok setelah dirampok. Terdapat beberapa Iuka bacok pada lengan kanannya. Setelah perawatan Iuka pasien dianjurkan untuk rawat inap. Setelah 5 hari pasien diperbolehkan pulang dan kontrol kembali ke poli. Jenis visum apakah yang diberikan?","options":["VER psikiatrik","VER sementara","VER Ianjutan","VER pemeriksaan luar","VER definitif"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Macam-macamVisumetRepertum: 1. VeR hidup a.Definitif:dibuatseketika,dimanakorbantidakmemerlukanperawatandanpemeriksaan lanjutan sehingga tidak menghalangi pekerjaan korban. Kualifkasi luka ditulis derajat I. b.Sementara:dibuat sementara waktu karena korban memerlukan perawatan dan pemeriksaan lanjutan sehingga menghalangi pekerjaan korban. Kualifikasi luka tidak ditulis. c. Lanjutan: yaitu VeR yang dibuat saat luka korban telah sembuh atau pindah rumah sakit atau pindah dokter atau pulang paksa. Kualifikasi luka ditulis. 2. VeR jenazah dilakukan terhadap korban yang sudah meninggal.","answerPage":191,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-170","number":170,"package":"Paket 2","topic":"Campuran","title":"Soal 170 · Seorang laki-laki berusia 24 tahun datang ke…","page":142,"stem":"Seorang laki-laki berusia 24 tahun datang ke klinik 24 jam dengan keluhan utama keluar cairan kental seperti nanah dari kemaluannya. Tidak ada nyeri didaerah prostat. Pasien merupakan sopir antarprovinsi. Pada pemeriksaan tanda vital didapatkan tekanan darah 120/80 mmHg, nadi 88x/menit, suhu 37,3 oc. Pemeriksaan mikroskopis pada discharge ditemukan banyak leukosit dan neutrofil tapi tidak ditemukan bakteri. Diagnosis apa yang paling mungkin pada kasus tersebut?","options":["Sistitis interstisialis","Sistitis acute","Prostatitits acute","Uretritis gonococcal","Nongonococcal uretritis"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Gejalaklinikdariuretritis Rasa gatal, panas di bagian distal uretra di sekitar orifsium uretra eksternum. Disuria,polikisuria. Keluar duh tubuh dari ujung uretra yang kadang-kadang disertai darah. Nyeri saat ereksi. Pada pemeriksaan tampak orifsium uretra eksternum eritematosa, edematosa,dan ektopion. Tampak duh tubuh yang mukopurulen. ·Dapatterjadi pembesarankelenjar getah bening inguinal unilateralataubilateral. Uretritisyang disebabkanoleh gonore dikenal dengannama uretritis gonoccalDiagnosis ditunjang dengan ditemukannya gonococus gram negatifada pemeriksan duh tubuh Jika tidak ditemukan maka disebut nongonococal uretritis.","answerPage":192,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-171","number":171,"package":"Paket 2","topic":"THT","title":"Soal 171 · Seorang laki-laki berusia 20 tahun datang dengan…","page":142,"stem":"Seorang laki-laki berusia 20 tahun datang dengan keluhan nyeri pada saat menelan sejak 5 hari yang lalu. Keluhan semakin bertambah berat sejak 1 hari yang lalu dan sulit membuka mulut. Vital sign dalam batas normal. Diagnosis yang paling mungkin pada kasus ini adalah.„","options":["Abses submandibula","Abses parafaring","Abses retrofaring","Abses peritonsil","Angina ludovici"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"a. Absessubmandibuladitemukangejalaberupanyeripadaleherdisertaipembengkakan dibawah mandibula dan atau dibawah lidah mungkin berfluktuasi b. Absesparafaringditemukangejalaberupaadanyatrismus,indurasiataupembengkakan disekitar angulus mandibula, disertai demam tinggi dan pembengkakan dinding lateralfaring Abses retrofaring, gejala berupa nyeri dan sukar menelan, terdapat demam, leher kaku dan nyeri, kadang sesak karena terjadi sumbatan jalan nafas. Jika peradangan mencapai laring akan menimbulkan stridor. d.Abses peritonsil, terdapat tanda dan gejala tonsillitis akut, terdapat neyri menelan yang hebat, biasanya pada sisi yang sama dengan keluhan nyeri telinga, muntah, mulut berbau,banyak ludah,suara sengau dan sukarmembuka mulut.Terdapat nyeri tekan dan pembengkakan pada kelenjar submandibula. e.Angina ludovici, terdapat nyeritenggorok dan leher disertai pembengkakan di daerah submandibula yang tampak hiperemis dan keras pada perabaan.Pada dasar mulut membengkak, dapat mendorong lidah keatas belakang sehingga menimbulkan sumbatan jalan nafas.","answerPage":192,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-172","number":172,"package":"Paket 2","topic":"Kulit","title":"Soal 172 · seorang Iaki-laki berusia 25 tahun datang dengan…","page":143,"stem":"seorang Iaki-laki berusia 25 tahun datang dengan keluhan terdapat bcnjolan kecil disekitar kelamin. Sebulan yang lalu menurut pasien, terdapat Iuka di yanq nyeri dan sembuh sendiri. Pasien bekerja sebagai pelaut dan pulanq. Pada pemeriksaan fisikTekanan darah 120/70, Nadi 88x/menit, 20x/menit, suhu 38,2 C. Pada status dermatologis terdapat lesi kondilomatosa di perineum, limfadenopati inguinal dan ruam makulopapular tidak gatal di telapak tangan dan kaki. Pemeriksaan penunjang","options":["Tes TPHA/VDRL","Biopsi jaringan","Pap smear","I-litung CD4","Kultur clarah"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Lesi kondilomatosa di perineum, limfadenopati inguinal dan ruam makulopapular merupakan tanda-tanda siflis sekunder. Pemeriksaan penunjang yang dilakukan pada sifilis adalah: 1. Pemeriksaan dengan mikroskop lapangan gelap 2.Pemeriksaan serologis: VDRL, RPR (nontreponemal/tidak spesifk tapi sensitif). VDRL juga dipakai untuk follow-upterapi. TPHA (treponemal/spesifik tapl tidak sensitif).","answerPage":192,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-173","number":173,"package":"Paket 2","topic":"Campuran","title":"Soal 173 · seorang pria berusia 42 tahun datang kedokter…","page":143,"stem":"seorang pria berusia 42 tahun datang kedokter dengan keluhan selama 2 minggu m erasakan kaki kirinya sangat nyeri saat tidur. Sebenarnya dirasakan sakit sejak setahun belakangan. Namun hanya dirasakan bila berjalan. Penderita mengeluh jarak tempuh makin lama makin pendek dan sering berhenti karena nyeri. Bila istirahat rasa nyeri hilang. Penderita seorang perokok berat. Pemeriksaan fisik secara umum normal. Pada ekstremitas inferior sinistra, tidak teraba pulsasi a. dorsalis pedis dan tibialis posterior. pemeriksaan laboratorium normal. Diagnosis yang paling tepat adalah...","options":["Diabetic arteriopathy","Chronic arterial thrombosis","Acute arterial occlusion","Thromboangitis obliterans","Atherosclerotic peripheral arterial occlusive disease"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"1. Klaudikasio yang melibatkan ektremitas. 2. Fenomena Raynaud. 3. Tromboplebitis vena superisial yang berpindah-pindah Kaudikasio biasanya terjadi pada betis dan kaki atau pada lengan bawah dan tangan. Sebab, terutama memang mengenai pembuluh darah daerah distal. Berupa iskemik digitalyangberat, perubahan kuku, ukus yang nyeri dan gangren pada ujung jri atau tumit. Pada pemeriksan klinis, arteri brakialis dan poplitea normal. Tetapi, nadi dapat berkurang atau hilang pada arteri radlialis, ulnaris, dan tibialis. Lalu, pada pemeriksan ultrasonograf duplex dan arteriograf, berupa gambaran khas perubahan lesi segmental pembuluh darah dari yang normal bertahap menjadi halus pembuluh darah distal. Tidak ada pengobatan spesifik, kecuali pasien berhenti merokok.prognosis memburuk jika tidak berhenti merokok. Operasi pintas arteri dari pembuluh darah yang lebih besar mungkin ada gunanya pada keadaan tertentu.","answerPage":193,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-174","number":174,"package":"Paket 2","topic":"Bedah","title":"Soal 174 · Seorang Iaki-laki berusia 29 tahun diantar polisi…","page":143,"stem":"Seorang Iaki-laki berusia 29 tahun diantar polisi post kecelakaan lalu lintas dengan penurunan kesadaran. Pada pemeriksaan tanda vital didapatkan tekanan darah 80/ palpasi, nadi tidak teraba, RR 32x/menit. Pemeriksaan dada ditemukan trauma dada, sesak nafas dan ngorok. Perkusi dada kiri hipersonor. Pada saat nafas, dada kiri tertinggal, akral dingin. Bagian yang ditusuk jarum pada pasien yang mengalami kecelakaan dan sesak nafas tersebut adalah...","options":["SIC II Sisi bawah costa 2","SIC II Sisi tengah atas costa 2","SIC II Sisi di atas costa 3","SIC II Sisi dibawah costa 3","SIC II di atas costa 4"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dekompresi dilakukan pada sela iga dua garis midclavicula pada hemithoraks yang terkena.Insersijarum diatascosta3bertujuan untukmenghindari vasa dan nervus.","answerPage":193,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-175","number":175,"package":"Paket 2","topic":"Obstetri & Ginekologi","title":"Soal 175 · Seorang wanita berusia 25 tahun GI PoAo…","page":143,"stem":"Seorang wanita berusia 25 tahun GI PoAo tidak ingat kapan terakhir haid. Pada pemeriksaan fisik didapatkan fundus uteri setinggi pertengahan simfisis-pusat. Denyut jantung sudah teraba dengan Doppler. Berapa perkiraan usai kehamilannya?","options":["8-10 minggu","10-12 minggu","12-14 minggu","16-18 minggu","20-22 minggu"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"minggu xyphold 36 Perumbuhan 32dan40 setiap2minggu 28 klra-kira1lebarjari 24 umbllikus 20 18 Pertumbuhan .16 setiap2minggu .... ·14 kira-kira2lebarjarl 12 simfisis","answerPage":193,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-176","number":176,"package":"Paket 2","topic":"Campuran","title":"Soal 176 · Seorang perempuan berusia 24 tahun datang dengan…","page":144,"stem":"Seorang perempuan berusia 24 tahun datang dengan keluhan terdapat benjolan pada kelopak mata kiri sejak 2 bulan yang lalu. Benjolan tidak terasa nyeri, sudah antibiotik dan kompres air hangat namun tidak ada perubahan. pada pemeriksaan fiSik didapatkan benjolan sebesar biji kacang hijau pada kelopak mata kiri, tidak hiperemi$ mudah digerakkan dan tidak nyeri tekan. Diagnosis pada kasus ini adalah...","options":["Hordeolum internum","Hordeolum eksternum","Chalazion","Karsinoma kelenjar sebasea","Disfungsi kelenjar meibom"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Tanda dan gejala : Chalazion: pembengkakan sebesar kacang,tidak ada keluhan,rabaan keras, melekat padatarsus,akantetapilepasdarikulit. Hordeolum: infeksi akut dari kelenjar palpebra yg disebabkan oleh staflokokus/ streptokokus Padahordeolum,palpebra bengkak,merah,sakit, dan tonjolan di palpebra.","answerPage":194,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-177","number":177,"package":"Paket 2","topic":"Campuran","title":"Soal 177 · Seorang perempuan berusia 24 tahun dibawa keluarganya…","page":144,"stem":"Seorang perempuan berusia 24 tahun dibawa keluarganya karena sangat gembira dan bercerita panjang lebar bahwa dia bahagia karena berteman dengan seorang pejabat. Lalu ia akan dibelikan rumah mewah karena karirnya meningkat. Pasien berubah menjadi ceria semenjak dipecat dari pekerjaannya. Saat bercerita, pasien beberapa kali selalu menggeser kaki kanannya ke arah depan. Menurut keluarganya, di rumah pasien gemar membongkar lemari pakaian dan menyusunnya kembali. Kelainan apakah yang dialami Oleh pasien tersebut?","options":["Stereotipik gerak","Kompulsi","Eupraksi","Hiperaktivitas","Afitas psikomotor"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Kompulsi adalah suatuperbuatan yang disadari dan diketahi olh individu, tetapi seolah-olah dilakukan di luar kekuasannya meskipun yang bersangkutan tahu dan mengakui perbuatannya adalah tidak rasional. Kompulsif biasanya menjadi akibat suatu obsesi.","answerPage":194,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-178","number":178,"package":"Paket 2","topic":"Campuran","title":"Soal 178 · Seorang perempuan berusia 24 tahun datang dengan…","page":144,"stem":"Seorang perempuan berusia 24 tahun datang dengan keluhan demam tinggi, mual, muntah. Dari pemeriksaan fisik ditemukan kaku kuduk (+). Setelah dilakukan pemeriksaan lumbal pungsi, hasil CSF tampak keruh. Kemungkinan apa yang ditemukan?","options":["Protein normal, glukosa normal, PMN meningkat","Protein turun, glukosa normal, PMN menurun","Protein naik, glukosa turun, PMN meningkat","Protein menurun, glukosa naik, PMN meningkat","Protein naik, glukosa turun, PMN normal"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pada infeksibakteriditemukan CSF yang keruh.Protein akan naik, glukosa turun karena dikonsumsi oleh bakteri danPMN akan meningkat.","answerPage":194,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-179","number":179,"package":"Paket 2","topic":"Kulit","title":"Soal 179 · Seorang wanita berusia 35 tahun datang dengan…","page":144,"stem":"Seorang wanita berusia 35 tahun datang dengan keluhan keputihan seperti susu kental sejak 2 hari yang lalu. Gatal pada kemaluan secara berulang. Pasien juga mempunyai riwayat penyakit gula. Pada pemeriksaan fisik didapatkan tekanan darah 1 10/70 mmHg, nadi 84 x/menit, frekuensi nafas 18 x/menit dan suhu badan 36,5 oc. Status lokalis region vagina dan perineum hiperemis terdapat bercak-bercak putih serta flour albus putih kental. Pemeriksaan apakah yang disarankan untuk penegakkan diagnosis?","options":["USG","Serologi","Biomolekuler","Sediaan basah usap vagina","Biopsi"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Berdasarkan gejala klinisnya, pasien ini kemungkinan mengidap vaginosis. Untuk memastikan diagnosis, perlu dilakukan pemeriksaan !aboratorium dengan mengambil sediaanbasah usapvagina,kemudian dilakukan pewarnaan gram.","answerPage":194,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-180","number":180,"package":"Paket 2","topic":"Anak","title":"Soal 180 · Seorang pasien perempuan berusia 25 tahun baru…","page":145,"stem":"Seorang pasien perempuan berusia 25 tahun baru saja melahirkan di Puskesmas meminta kepada dokter untuk memberikan bawang putih pada baju bayinya. Dokter pun mengizinkan, bentuk penghargaan dokter kepada pasien adalah berdasarkan?","options":["Moral","Etika Nilai","Nilai","Norma","Adat"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Moral adalahsuatukumpulan ajaran tentangbagaimana manusia harushidup dan bertindak agar menjadi manusia yang baik Etika adalah ilmu yang membahas tentang bagaimana dan mengapa kita mengikuti suatu ajaranmoral tertentu Nilaiadalahkemampuan yang dipercayaiyang ada pada suatubenda untuk memuaskan manusia Norma adalah wujud konkrit dari nilai (misalnya berjabat tangan setelah sebuah pertandingan) Adat adalah aturan yang lazim dilakukan sejak dahulukala.","answerPage":194,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-181","number":181,"package":"Paket 2","topic":"Mata","title":"Soal 181 · seorang perempuan berusia 20 tahun datang dengan…","page":145,"stem":"seorang perempuan berusia 20 tahun datang dengan keluhan mata kiri terkena pembersih lantai saat sedang bersih-bersih rumahnya. Pada pemeriksaan visus mata kiri 6/6. pada inspeksi mata kiri didapatkan injeksi konjungtiva (+), tidak ada iskemik limbus, kornea jernih. Bagaimana penatalaksanaan yang tepat pada pasien ini?","options":["Irigasi bola mata dengan aquabidest dilanjutkan dengan steroid topical","Irigasi bola mata dengan aquabidest dilanjutkan dengan miotik topical","Irigasi bola mata dengan boorwater dilanjutkan dengan steroid topical","Irigasi bola mata dengan aquabidest dilanjutkan dengan miotik topical","Irigasi bola mata dengan aquabidest dilanjutkan dengan antibiotiktopical"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Deterjen/sabun/pembersih lantai bersifat basa sehingga penetrasinya kuat. Untuk menekan reaksi radang yang hebat, dapat diberikansteroid topical.Prinsip penanganan trauma kimia adalah irigasi dengan normal saline mengalir selama 15-30 menit, berikan siklopegik agar relaksasi dan midriasis, berikan steroid untuk meredakan peradangan. Sedangkan Boorwater adalah asam boric bersifat asam. Tidak boleh diberikan pada trauma kimia.","answerPage":194,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-182","number":182,"package":"Paket 2","topic":"Kulit","title":"Soal 182 · Seorang pelajar SMA berusia 15 tahun sedang…","page":145,"stem":"Seorang pelajar SMA berusia 15 tahun sedang melakukan praktikum dilaboratorium kimia datang dengan keluhan kulit melepuh pada jari telunjuk dan ibu jari. Kulit terasa perih dan panas. Pemeriksaan vital sign didapatkan tekanan darah 120/80 mmHg, nadi 80 x/menit, nafas 20 x/menit dan suhu 36,5 oc. Pada pemeriksaan fisik didapatkan kulit terdapat lesi vesikel-bula berisi cairan bening setelah terkena zat kimia di tempat kerjanya. Diagnosis pasien ini adalah„.","options":["Dermatitis kontak iritan","Dermatitis kontak alergi","Luka bakar","Liken simpleks","Allergic drug eruption"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Dermatitis kontak iritan akut biasanya terjadi karena kecelakaan, kulit terasa pedih atau panas dengan eritema, vesike atau bula, luas kelainan mumnya sebatas daerah yang terkena dan berbatas tegas. Kelainan kulit akan muncul segera, tetapi ada sejumlah bahan kimia yang menimbulkan reaksi akut lambat, misalnya podoflin, antralin dan asam fluorohidrogenat.","answerPage":195,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-183","number":183,"package":"Paket 2","topic":"Anak","title":"Soal 183 · Seorang bayi perempuan berusia 9 bulan datang…","page":145,"stem":"Seorang bayi perempuan berusia 9 bulan datang keklinik dengan keluhan sesak nafas sejak 2 hari yang lalu. Keluhan disertai demam dan batuk pilek. Pada pemeriksaan fisik pasien tampak sesak, RR 55x/menit, suhu 38,5 C. Tidak ada pembesaran KGB. Pada pemeriksaan paru ekspirasi memanjang dan terdapat mengi. Pemeriksaan laboratorium ditemukan leukosit 3.500 dan trombosit 140.000. Apa diagnosis yang paling mungkin pada pasien tersebut?","options":["Bronchitis akut","Bronkiolitis","Asma","Bronkopneumoni","Pneumoni aspirasi"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Bronkiolitis adalah inflamasi bronkiolus akut akibat infeksi virus (umumnya RSV, parainfluenza, adenovirus). Bronkiolitis sering terjadi pada anak usia <2 tahun, paling sering anak usia 6 bulan. Gejala Klinis : Diawali dengan demam subfebris danAURI Kemudian terjadi batuk, sesak, dan mengi Jarangmenjadiberat Pemeriksaan Fisik: demam, dyspnea (expiratory effort), ekspirasi memanjang, mengi, hipersonor(airtrapping) Pemeriksaan Penunjang: foto dada AP-lateral (air trapping),AGD:hiperkarbia,asidosis metabolik/respiratorik.","answerPage":195,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-184","number":184,"package":"Paket 2","topic":"Campuran","title":"Soal 184 · Seorang paienlailaiberusia5 tahpeneritaTparudatangkedoktedengan keluhannyer sendi pada pangkal…","page":145,"stem":"Seorang paienlailaiberusia5 tahpeneritaTparudatangkedoktedengan keluhannyer sendi pada pangkal jari kakidanmolkaki kiri sejak1mingguyang lalu. Pada pemeriksaan fsikditemukan peradangan pada sendi metatarsofalangeal dan interfalang I. Hasil pemeriksaan laboratorium menunjukan kadar asam urat 8,9 mg%.","options":["Streptomisin","PAS","INH","Rifampisin","Etambutol"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Obat TB dapat diklasifikasikan menjadi dua jenisresimen,yaitu obat lapis pertama dan lapis kedua. Obat lapis pertama terdiri atas isoniazid, rifampisin, pyrazinamid, etambutol, dan streptomisin.Obatlapis kedua mencakup rifabutin,etionamid, cycloserine,paraamino salicylic acid, clofazimine, aminoglicoside di luar streptomisin, dan quinolones. OAT yang memiliki efek samping hiperurisemia adalah pirazinamide dan PAs. Efek asing INH hepatitis dan neuropati perifer,rifampisin memiliki efek samping antara lain hepatitis, flu-like syndrome's, dan trombositopenia. Etambutol dapat menyebabkan efek samping neuritis optika, nefrotoksik dan dermatitis. Efek samping toksik streptomisin pada saraf kranial kedelapan yang menyebabkan disfungsi vestibular.","answerPage":195,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-185","number":185,"package":"Paket 2","topic":"Campuran","title":"Soal 185 · Seorang laki-laki berusia 65 tahun datang ke…","page":146,"stem":"Seorang laki-laki berusia 65 tahun datang ke IGD dengan keluhan nyeri mendadak di daerah perut atas dan pada kemaluan teraba kandung kemih penuh. Pada pemeriksaan fisik tekanan darah 120/80 mmHg, nadi 80 x/menit, frekuensi nafas 20 x/menit, suhu 36,5 oc. Tindakan segera yang harus dilakukan adalah...","options":["Pasang kateter uretra","Terapi analgetik","Pasang iv line","BNO","Pasang oksigen"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"dnretnsutleuanadapnangtidadat nig padahal kandung kemih penuh saat diraba yang disebabkan oleh sumbatanmekanis padaretraatau gangguanfungsional kandungkemihdnsngterna sehinggapu tindakan segerayangharus dlakukan adalahmemasang katetr retraagardat mengeluarkan urine dalamkandungkemih.","answerPage":196,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-186","number":186,"package":"Paket 2","topic":"Campuran","title":"Soal 186 · Seorang laki-laki berusia 25 tahun datang dengan…","page":146,"stem":"Seorang laki-laki berusia 25 tahun datang dengan keluhan nyeri kepala sejak 5 bulan yang lalu terutama pada daerah dahi. Nyeri bertambah berat saat pasien menunduk. Keluhan Iain berupa demam dan pilek. Apa diagnosis kerja pada pasien ini?","options":["Sinusitis sphenoidalis","Sinusitis frontalis","Sinusitis maxilaris","Sinusitis etmoidalis","Multisinusitis"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Sinusitis adalah radang mukosa sinus paranasal, bila mengenai beberapa sinus disebut multisinusitis, sedangkan bila mengenai semua sinus paranasal disebut pansinusitis. Sinusitis frontalis akut hampir selalu bersama-sama dengan infeksi sinus etmoidalis anterlor. Gejala subyektif terdapat nyeri kepala yang khas, nyeri berlokasi diatas alis mata, biasanya pada pagi hari dan memburuk menjelang tengah hari, kemudian perlahan- lahan mereda hingga menjelang malam. Frontalsinus Ethmoidsinus Aroasot locallzodpain Maxillarysinus Nasalcavity Nasaldischargefrom bothnontrilnthatmay boworseononoside","answerPage":196,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-187","number":187,"package":"Paket 2","topic":"Kulit","title":"Soal 187 · Seorang perempuan berusia 55 tahun dibawa ke…","page":146,"stem":"Seorang perempuan berusia 55 tahun dibawa ke IGD RS dalam keadaan tidak sadarkan diri. Pasien mempunyai riwayat DM sejak 20 tahun yang lalu. pada pemeriksaan fisik ditemukan tekanan darah 150/90 mmHg serta nafas cepat dan dalam ,temperature 37.40C, kulit kering dan ada bagian terinfeksi. Diagnosis yang paling tepat adalahm","options":["Ketoasidosis Diabetikum","Hiperosmolar Non Ketotik","Sepsis","Koma Diabetikum","Gagal jantung"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Sekitar 80% pasien Ketoasidosis Diabetikum adalah pasien DM yang sudah dikenal. Pada pasien KAD dijumpai pernapasan cepat dan dalam (kussmaul), berbagai derajat dehidrasi, dan kadang-kadang disertai hipovolemia sampai syok. Bau aseton dari hawa napas tidak terlalu mudah tercium. Derajat kesadaran pasien yang dijumpai, dapat kompos mentis sampai koma.","answerPage":196,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-188","number":188,"package":"Paket 2","topic":"THT","title":"Soal 188 · Seorang wanita berusia 43 tahun datang berobat…","page":146,"stem":"Seorang wanita berusia 43 tahun datang berobat ke dokter dengan keluhan sejak 10 tahun yang lalu keluar cairan dari telinga kanan. Cairan berwarna putih, kental, dan bau busuk. Keluhan disertai nyeri telinga dan demam (+). Pada vital sign didapatkan tekanan darah 120/70 mmHg, nadi 84 x/menit, frekuensi nafas 20 x/menit suhu 37,7 oc, mulut mencong kekiri dan CAE granulasi. Diagnosis yang tepat pada kasus ini","options":["Otitis eksterna maligna","Granuloma","OMSK","OMA","Kolesteatoma"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Otis media akut dengan perforasi membran timpani menjadi ottis medla supuratif kronis OMSK apabila prosesnyasudahlebihdari 2bulan.Kemudian yang disebut OMSK adalah infeksi kronis ditelinga tengah dengan perforasi membran tmpani dan seket yang keluadriteigatengahtermenerusatahilang mbulmlkaslMSKdpt menybakamatdileetsitisareisifiars,bse trombosis sinuslateralis, absessubdural, meningitisabsesotak, danhdrosefalusotts.","answerPage":197,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-189","number":189,"package":"Paket 2","topic":"Campuran","title":"Soal 189 · Seorang anak laki-laki berusia 4 tahun diantar…","page":146,"stem":"Seorang anak laki-laki berusia 4 tahun diantar oleh ibunya datang dengan keluhan batuk yang tidak sembuh-sembuh sejak 3 minggu yang lalu. Pasien juga mengeluh demam namun tidak terlalu tinggi terutama pada malam menjelang dini hari. Batuk bertambah sering setelah makan cokelat bu pasien khawatir karena pengasuh pasien mengalami batuk darah dan didiagnosis TBC. BB anak 19 kg. hasil uji tuberculin (+). Bagaimana","options":["Profilaksis primer","Proflaksis sekunder","Pengobatan OAT","Imunostimulator","Obat batuk"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"TB Anak - Klasifkasi (ATS/CDC) Class kontak Infeksi disease Manaqement 0 1 + 1\"proph 11 + + 2m proph 111 + + + OAT Keterangan: ·Kontak dinilai dengan adanya kontak dengan pasien TB di sekitar lingkungan ·Infeksi dinilaidenganuji Mantoux ·Disease dinilai dengan TBscoring menurut WHO","answerPage":197,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-190","number":190,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 190 · seorang laki-laki berusia 30 tahun datang dengan…","page":147,"stem":"seorang laki-laki berusia 30 tahun datang dengan keluhan demam dan nafsu makan menurun sejak 3 hari yang lalu. Dari pemeriksaan fisik didapatkan ikterus dan hepatomegali. Pasien pernah mendapat vaksin hepatitis B 3 tahun yang lalu. Hasil pemeriksaan serologis didapatkan IgM HAV negative, IgG HAV positif, HbsAg negatif, HbsAb positif, HbcAb negatif, dan HCV Ab positif. Kesimpulan pada pasien ini adalah„.","options":["pernah terinfeksi HAV dan HCV dimasa lalu, belum pernah terinfeksi HBV dan saat ini menderita Hepatitis C","Saat ini menderita Hepatitis A, belum pernah terinfeksi HBV dan menderita Hepatitis C di masa lalu","pernah terinfeksi HAV dan HCV di masa lalu, saat ini sedang terinfeksi Hepatitis B","Saat ini menderita Hepatitis A, pernah terinfeksi HBV dan HCV di masa lalu","pernah terinfeksi HAV di masa lalu, belum pernah terinfeksi HBV dan saat ini sedang mengalami Hepatitis C"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"HAV: ·IgM HAV negatif danIgGHAV positif ·InfeksiHAVlama HBV: ·HbsAgnegatif+HbsAb/antiHbspositif+HBcAb negatif ·Riwayatimunisasi HBV HCV: ·HCV Ab positif ·Kemungkinan terinfeksi Hepatitis C","answerPage":197,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-191","number":191,"package":"Paket 2","topic":"Neurologi","title":"Soal 191 · Seorang anak berusia 8 tahun sering melamun…","page":147,"stem":"Seorang anak berusia 8 tahun sering melamun dan tiba-tiba kejang. Tiap kali kejang, durasinya 5-10 detik. Hal ini seringkali terjadi di rumah tanpa disertai panas. Pemeriksaan fisik tidak ditemukan kelainan. Pemeriksaan penunjang yang dibutuhkan pada pasien ini adalah...","options":["CT scan","Rontgen kepala","MRI","EEG","EKG"],"bookKey":"D","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Padakasusdiatas, diagnosisdaripasien mengarah keepilepsi.Sebab,adanya bangkitan kejang tanpa demam. Pemeriksaan penunjang yang dapat menegakan epilepsi adalah EEG. Kelainan EEG yang sering dijumpai pada pasien epilepsi disebut epileptiform discharge atau epileptifrm activity. Gambaran yang terekam saat serangan maupun di luar serangan,berupa gelombang runcing, gelmbang pak,runcing lambat, dan paku lambat.","answerPage":197,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-192","number":192,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 192 · Seorang pria datang dengan keluhan merasa sakit…","page":147,"stem":"Seorang pria datang dengan keluhan merasa sakit jantung. Dari hasil pemeriksaan fisik dan laboratorium tidak ditemukan adanya kelainan. Akan tetapi pasien sangat yakin bahwa dia menderita penyakit jantung. Diagnosis yang tepat pada pasien ini","options":["Gangguan konversi","Hipokondriasis terinci","Gangguan somatisasi","Gangguan citra tubuh","• Gangguan somatoform tidak"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Hipokondriasis Kriteria diagnosis menurutPPDGJ IlI: a.Keyakinan yang menetap adanya sekurang-kurangnya satu penyait sik yang serius adanya alasan fsik yang memadai ataupun preokupasiyang menetap kemungkinan deformitas atau perubahan bentuk penampakan fsiknya (tidak sampai waham). b. Tdak mau menerima nasihatataudukungan penjelasandaribeberapadokterbahwa tidak ditemukan penyakit fisik yang melandasi kekurangannya.","answerPage":198,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-193","number":193,"package":"Paket 2","topic":"Bedah","title":"Soal 193 · Seorang perempuan berusia 24 tahun dibawa polisi…","page":147,"stem":"Seorang perempuan berusia 24 tahun dibawa polisi ke IGD setelah mengalami kecelakaan lalu lintas 30 menit yang lalu. Pada pemeriksaan fisik didapatkan kesadaran koma, saat dirangsang nyeri pada sternum mata memberikan respon, tangan terlihat ekstensi abnormal dan pasien mengerang. Pada telinga kiri mengalir darah merah segar. Kemungkinan diagnosis pada kasus ini","options":["Fraktur basis kranii anterior","Fraktur basis kranii posterior","Fraktur basis kranii media","Epidural hematom","Subdural hematom"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Frakturbasiskraniianterior: a.Rhinorrhea b.Raccoon eyes Fraktur basis kranii posterior:Battle sign Frakturbasiskraniimedia a.Otorrhea b. Biasanya fraktur media jarang terjadi sendiri, sering bersamaan dengan posterior","answerPage":198,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-194","number":194,"package":"Paket 2","topic":"Campuran","title":"Soal 194 · Seorang wanita berusia 65 tahun dirawat di…","page":148,"stem":"Seorang wanita berusia 65 tahun dirawat di RS sejak 3 hari yang lalu karena mengalami keluhan kedua kaki bengkak, perut terasa besar, dan padat. Pada pemeriksaan fisik didapatkan tes undulasi positif, hepar teraba 3 Jari di bawah arcus costae, edema 2 tungkai. Tekanan darah pasien 150/90 mmHg. Terapi simptomatik apakah yang paling cocok pada pasien tersebut?","options":["Loop diuretik","Diuretik tiazid","Angiotensin II bloker","Aldosteron reseptor bloker","Beta bloker"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Berdasarkan manifestasi klinis yang terdapat pada kasus tersebut asites yang terjadi lebih disebabkan oleh penyakit hati,kemungkinan sirosis hepatis.Asites diobati secara komprehensif dengantirahbaring,diet,diuretik,danparasentesisjikaperlu. Diuretikayang dianjurkan adalah diuretikayang bekerjasebagaiantialdosteron,misalnya spironolakton.Diuretik ini merupakan diuretik hemat kalium, bekerja di tubulus ginjal danmenahanreabsorbsi Na.Sebenarnya,potensi natriuretikdiuretikdistal lebihrendah dari diuretik loop bila etiologi peningkatan garam dan air tidak berhubungan dengan hiperaldosteronisme. Dosis yang dianjurkan antara 100 - 600 mg/hari. Diuretik loop sering dibutuhkan sebagai kombinasi. Diuretik ini sebenarnya lebih berpotensi dari diuretik distal. Pada sirosis hati karena mekanisme utama reabsorbsi air dan natrium adalah hiperaldosteronisme, diuretik loop menjadi kurang efektif. Jawaban yang paling tepat pada kasus di atas adalah loop diuretik dan diuretik tiazid. Akan tetapi, diuretik tiazid lebih cocok digunakan untuk penyakit kelainan jantung. Oleh karena itu, pilihan yang paling tepat adalah diuretik loop.","answerPage":198,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-195","number":195,"package":"Paket 2","topic":"Campuran","title":"Soal 195 · Seorang perempuan berusia 25 tahun datang berkonsultasi…","page":148,"stem":"Seorang perempuan berusia 25 tahun datang berkonsultasi ke dokter dengan keluhan ketidakpuasan saat berhubungan dengan suaminya. Pasien baru merasa puas saat disiksa secara fisik. Gangguan seksual yang dialami Oleh pasien ini adalah„.","options":["Fetihisme","Ekshibisionisme","Masokisme","Voyeurism","Troilisme"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"C. Masokisme: kepuasaan seksual dengan disiksasecara fsikatau mental. e. Voyeurismekepuasanseksualdngamengintip,ataumelhatoranglainmelaan hubungan seksual.","answerPage":199,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-196","number":196,"package":"Paket 2","topic":"Mata","title":"Soal 196 · Seorang anak Iaki-laki berusia 4 tahun dibawa…","page":148,"stem":"Seorang anak Iaki-laki berusia 4 tahun dibawa Oleh orangtuanya ke IGD dengan keluhan pucat dan lemas. Pada pemeriksaan fisik, tekanan darah 100/70 mmHg, nadi 74 kali/menit, frekuensi napas 22 kali/menit, dan suhu 36,60C.Konjungtiva palpebra tampak pucat. Hasil pemeriksaan laboratorium darah yaitu hemoglobin 4,6 g%, hematokrit MCV 52,2 n, serta hair on end. Hasil pemeriksaan darah Iain yang mungkin didapat adalah„.","options":["Penurunan haptoglobin","Penurunan feritin","Penurunan binding iron","Penurunan retikulosit","Penurunan kadar besi serum"],"bookKey":"E","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Adanya keluhan pucat pada pasien ini merupakan gejala umum dari anemia. Hal tersebut juga didukung dengan hasil pemeriksan darah hemoglobin 4,6 g% dan hematokrit 13.7% Informasi yang harus diperhatikan pada kasus ini adalah MCV 52,2 fl yang menunjukan kurang dari nilai normal sehingga pada pasien ini menderita anemia hipokromik mikrositer. Pada anemia jenis ini kadar besi serum menurun. Jika feritin menurun dan TIBC meningkat maka anemia defisiensi besi Jika TIBC menurun dan feritin normal atau meningkat maka anemia akibat penyakit kronik.","answerPage":199,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-197","number":197,"package":"Paket 2","topic":"Bedah","title":"Soal 197 · Seorang Iaki-laki usia 20 tahun mengalami kecelakaan…","page":148,"stem":"Seorang Iaki-laki usia 20 tahun mengalami kecelakaan lalu lintas dan terdapat Iuka terbuka pada kaki kiri dan mengalami perdarahan. Perdarahan sulit dihentikan dan ditemukan Iuka memar pada kepala dan tangan. Pasien memiliki riwayat pada saat anak- anak mengalami Iuka kecil yang masa penyembuhannya lebih lama. Pemeriksaan fisik didapatkan tekanan darah 120/80 mmHg, denyut nai 80x/menit, frekuensi nafas 20x/ menit dan temperature 370 COC. Berdasarkan hasil di atas pada pemeriksaan laboratorium akan didapatkan?","options":["Masa protombin (PT) memanjang","Masa pembekuan (CT) memanjang","Faktor VIII dan XI normal","Masa tromboplastin partial teraktivasi (aPTT) normal","Masa plasma protombin (PTT) memanjang"],"bookKey":"B","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pasien ditemukan keluhan perdarahan berkelanjutan yang merupakan tanda klinis khas dari hemophilia. Dikenal dua macam hemophilia yang diturunkan secara sexlinked recessive yaitu: a.Hemofilia A (hemophilia klasik) akibat defisiensi factor pembekuan Vll(F Vlllc) b.Hemoflia B(Christmas disease) akibat defisiensi factor IX(F Christmas) LaboratoriumpadahemophiliaA dan hemophiliaB: HemofiliaA Hemofilia B Jumlahtrombosit N N Waktu perdarahan N N PT N N CT Memanjang Memanjang PPT N N aPTT Memanjang Memanjang FVIIC Rendah N FVllag N N FIX N Rendah Tes ristosetin N N","answerPage":199,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-198","number":198,"package":"Paket 2","topic":"Penyakit Dalam","title":"Soal 198 · seorang perempuan berusia 30 tahun menderlta DM…","page":149,"stem":"seorang perempuan berusia 30 tahun menderlta DM mengalami gaga! ginjal progresif dalam kurun Waktu 2 tabun terakhlr. Pasien belum dilakukan dialysis. Pemeriksaan fisik dalam batas normal. Hasil pemerlksaan laboratorium menunjukkan kadar hemoglobin 9 g/dl. Pada apusan arah tepi menunjukkan sei-sel eritrosit normositer normokromik, hematokrit 28 % dan MCV 94 fl. Penyebab kondisi pasien tersebut adalah.„","options":["Perdarahan akut","Leukimia limfositik kronlk","Defisiensi erythropoietin","Defisiensi enzim eritrosit","Anemia sideroblasti"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Anemianormokromik normositerditemukan pada: e.Anemia pada gagal ginjal kronik a.Anemia pasca perdarahan akut f. Anemla pada sindrom mielodisplastik b.Anemia aplastik g. Anemia pada keganasan hematologik c. Anemia hemolitik didapat d. anemia akibat penyakit kronik Anemia pada penyakit kronik ditandai dengan memperpendek masa hidup eritrosit dan gangguan produksi eritrosit akibat tidak efektifnya rangsangan eritropoetin.","answerPage":200,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-199","number":199,"package":"Paket 2","topic":"Neurologi","title":"Soal 199 · seorang laki-laki usia 50 tahun dating ke…","page":149,"stem":"seorang laki-laki usia 50 tahun dating ke IGD dengan penurunan kesadaran. Pemeriksaan fisik diapatkan tekanan darah 80/60 mmHg, nadi teraba lemah dan cepat dan kedua akral dingin. Pemeriksaan laboratorium didapatkan hemoglobin 1 3,8 g/dl, leukosit 4200/mm3, hematokrit 38% dan trombosit 222.000/mm3. Kemudian diketahui bahwa pasien ada riwayat pemberian suntikan penisilin 30 menit sebelumnya. Bagaimana mekanismenya dalam keadaan tersebut?","options":["Terjadi reaksi anafilatik akibat reaksi antigen dengan IgE yang terbentuk","Terjadinya reaksi sitotaksi karena terbentuknya IgM/IgG Oleh antigen","Terjadinya reaksi kompleks imunitas","Terjadinya respons system imunitas humoral","Terjadi respon sel T yang telah disensitasi Oleh antigen tertentu"],"bookKey":"A","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Pemberian obat penisilin rentan terjadinya reaksi hipersensitivitas tipeI. Biasanya terjadi 30 menit setelah pemberian obat. Pada reaksi hipersensitivitas tipe I terjadi manifestasi klinis renjatan anaflatik yang merupakan efek mediator kimia akibat reaksi antigen dengan IgE yang telah terbentuk.Gejalanya adalah: a. Sesak nafas akibat kejang bronkus ataupun kejang laring b. Urtikaria c.Angioedema d. Pingsan dan hipotensi","answerPage":200,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p2-200","number":200,"package":"Paket 2","topic":"Campuran","title":"Soal 200 · Seorang laki-laki usia 55 tahun dating dengan…","page":149,"stem":"Seorang laki-laki usia 55 tahun dating dengan keluhan adanya tumor pada paha kanannya yang sudah diderita selama 3 bulan. Pada pemeriksaan tampak tumor berdiameter IO cm, konsistensi padat kenyal, dan fixed. Pada pemeriksaan foto rontgen tampak gambaran tumor mesenkimal setempat yang sudah menimbulkan erosi pada tulang paha. Pemeriksaan biopsi tampak gambaran sel-sel fibroblastik yang pleomorfik yang tersusun storiform. Diagnosis mana yang paling tepat?","options":["Fibrosarcoma","Liposarcoma","Malignant fibrous histiocytoma","Ewing's sarcoma","Alveolar rhabdomyosarcoma"],"bookKey":"C","answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"impor","scored":false,"reviewed":false,"checked":null,"bookExplanation":"Histiositoma fbrousmalignant adalah salah satu sarcoma yangpaling sering terjadi pada usia dewasa,merujukpada suatu grup tumor jaringan lunakyang heterogen dan agresif yang ditandai dengan adanya gambaran sel yang pleomorfik, adanya sel bizzare multinucleated, membentuk arsitektur storiform dan terdapat stoma kolagen yang meradang dankadang tampakmakrofag dengan sitoplasmabervakuola.","answerPage":200,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-001","number":1,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 001 · seorang anak laki-laki berusia 13 tahun dibawa…","page":201,"stem":"seorang anak laki-laki berusia 13 tahun dibawa Oleh ibunya ke RS dengan keluhan nyeri perut bagian bawah hilang timbul sejak 4 bulan yang lalu. Pasien juga merasakan perut kembung, frekuensi BAB 3-4 x per hari, dan nyeri perut akan menghilang setelah BAB. Diagnosis yang tepat pada anak tersebut adalah...","options":["Esofageal reflux","Diverticulitis","Irritable Bowel Syndrome","Colitis ulseratif","Crohn disease"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-002","number":2,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 002 · Seorang pria berusia 52 tahun datang ke…","page":201,"stem":"Seorang pria berusia 52 tahun datang ke poliklinik dengan keluhan timbuJ benjolan pada bahu kiri. Benjolan tersebut mulai dirasakan sejak I tahun yang lalu dan membesar sejak 3 bulan terakhir yang disertai dengan nyeri. Vital sign dalam batas normal. Pemeriksaan fisik teraba benjolan di bahu kiri, ukuran 7 cm x 5 cm x 4 cm, konsistensi keras dan padat serta menempel pada dasarnya. Terdapat gambaran kalsifikasi pada pemeriksaan radiologi. Diagosis yang tepat pada kasus di atas adalah...","options":["Osteokondroma","Kondrosarkoma","Osteosarkoma","Metastasis bone disease","Miositis osifikans"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-003","number":3,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 003 · Seorang pria berusia 40 tahun datang dengan…","page":201,"stem":"Seorang pria berusia 40 tahun datang dengan keluhan mual, kadang muntah dan nafsu makan berkurang. Pada pemeriksaan laboratorium terdapat peningkatan SCOT dan SGPT, anti HAV (-), HbsAg (-), anti HCV (-). Saat ini pasien sedang dalam pengobatan rutin dengan OAT. Diagnosis yang tepat pada pasien ini adalah...","options":["Drug induced hepatitis","Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis B dan C"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-004","number":4,"package":"Paket Prediksi","topic":"Anak","title":"Soal 004 · Seorang bayi berumur 3 bulan dibawa oleh…","page":201,"stem":"Seorang bayi berumur 3 bulan dibawa oleh ibunya ke RS dengan keluhan saat BAK keluar dari tempat yang tidak semestiya. Pada pemeriksan tanda vital dalam batas normal. Status lokalis didapatkan adanya pembesaran klitoris seperti labia mayora dan muara AUE di perineum. Diagnosis pasien ini adalah..","options":["Biseks","Transgender","Hermafrodit","Transeks","Interseks"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-005","number":5,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 005 · Seorang perempuan berusia 60 tahun datang dengan…","page":202,"stem":"Seorang perempuan berusia 60 tahun datang dengan keluhan nyeri pada sendi lutut kanan. Melalui anamnesis keluhan bertambah jika berjalan atau naik tangga. Keluhan ini sudah dirasakan sejak 2 tahun yang lalu. Pasien adalah penjual jamu gendong yang mempunyai riwayat hipertensi IO tahun terkontrol. Dari pemeriksaan lab didapatkan CRP meningkat dan faktor rematoid (-). Gambaran radiologis dari kasus tersebut adalah...","options":["Tampak erosi marginal dengan osteoporotik","Tampak osteofit","Epifisis menyempit dengan skerotik","Bowing pada tulang panjang","Bamboo spine"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-006","number":6,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 006 · Seorang pria berusia 40 tahun datang dengan…","page":202,"stem":"Seorang pria berusia 40 tahun datang dengan keluhan mulutnya mencong sejak 2 jam yang lalu. Keluhan tersebut dirasakan pasien setelah mengendarai sepeda motor dan tidak menggunakan helm. Pada pemeriksaan fisik didapatkan pada saat tersenyum sudut mulut tertarik ke arah kanan, mata kiri tidak dapat menutup sempurna, dan tidak ada kerutan pada dahi kiri. Kemungkinan saraf apakah yang terkena?","options":["N. trigeminus sinistra sentral","N. fasialis dextra perifer","N. fasialis sinistra dextra","N. fasialis sinistra perifer","N. trigeminus dextra perifer"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-007","number":7,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 007 · Penduduk suatu desamemiliki kebiasaan minum dan melakukan…","page":202,"stem":"Penduduk suatu desamemiliki kebiasaan minum dan melakukan aktifitas cuci dan mandi di sungai tersebut. Penduduk juga memiliki kebiasaan makan sayur mentah dan keong air.Sebagian penduduk dan anak-anak mengalami pembesaran hati dan limpa serta memiliki fisikyang kurus. Endemik diare juga terjadi di desa tersebut, biasanya didahului dengan nyeri perut. Apakah penyebab dari kondisi di atas?","options":["Fasciola hepatika","Fasciolopsis buskii","Schistostomajapanicum","Parogonimus Westernmani","Schistostoma haemobitum"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-008","number":8,"package":"Paket Prediksi","topic":"THT","title":"Soal 008 · Seorang anak perempuan berusia 7 tahun dibawa…","page":202,"stem":"Seorang anak perempuan berusia 7 tahun dibawa ibunya ke dokterTHT dengan keluhan nyeri pada telinga sebelah kiri dan semakin memberat di malam hari. Terkadang anak menjerit karena kesakitan dan merasa ada yang bergerak di dalam telinga. Apa tindakan yg harus dilakukan pertama kali?","options":["Lakukan irigasi telinga","Berikan Obat analgesik paling kuat","Ambil serangga dengan narkose","Ambil serangga segera dengan pinset","Meneteskan telinga dengan gliserin"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-009","number":9,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 009 · Perempuan 32 tahun mengalami perdarahan menstruasi banyak…","page":202,"stem":"Perempuan 32 tahun mengalami perdarahan menstruasi banyak dan memanjang, menggunakan IUD. Dilakukan kuretase. Pemeriksaan patologi menemukan limfosit, makrofag, dan sel plasma di antara kelenjar dan stroma. Apakah diagnosisnya?","options":["Menopause","Perdarahan uterus fungsional","Endometritis akut","Endometritis kronis","Endometriosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-010","number":10,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 010 · Seerang pria berusia 54 tahun datang ke…","page":203,"stem":"Seerang pria berusia 54 tahun datang ke IGD dengan keluhan nyeri dada kiri mendadak dan terasa berat jika naik tangga. Pasien sebelumnya tidak pernah mengalami keluhan tersebut. Riwayat penyakit pasien adalah hipertensi dan tekanan darah saat itu adalah ISQ/IOO mmHg. Terapi yang tepat bagi pasien tersebut adalah.„","options":["Aspitet Bisoprolol","Ferdarahan uterus fungsional","Isosorbid dinitrat","Lisinopril","Nifedipine"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-011","number":11,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 011 · Seorang pria berusia 54 tahun datang ke…","page":203,"stem":"Seorang pria berusia 54 tahun datang ke IGD dengan keluhan nyeri dada kiri mendadak dan terasa berat jika naik tangga. Pasien sebelumnya tidak pernah mengalami keluhan tersebut. Riwayat penyakit pasien adalah hipertensi dan tekanan darah sat itu adalah 180/100 mmHg. Terapi yang tepat bagi pasien tersebut adalah...","options":["Aspilet","Bisoprolol","lsosorbid dinitrat","Lisinopril","Nifedipine"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-012","number":12,"package":"Paket Prediksi","topic":"Anak","title":"Soal 012 · Seorang anak berusia 3 tahun dibawa ke…","page":203,"stem":"Seorang anak berusia 3 tahun dibawa ke puskesmas dengan keluhan batuk sejak 3 minggu yang lalu. Keluhan diawali dengan pilek, bersin dan demam beberapa hari sebelumnya.Batukterutama terasa malam hari,kadang sampai sesak dan muntah.Batuk berirama cepat, berkepanjangan dan diselingi napas dalam inspirasi dengan nada tinggi. Padapemeriksaan mikroskopis muntahan ditemukan kuman coccobacil,gram negatif. Apakah kemungkinan kuman penyebab infeksi pada pasien ini?","options":["KlebsiellaPneumoniae","Staphylococcus aureus CBordetellapertusis","Bordetella pertusis","Mycobacteriumtuberculosa","Nisseriameningitides"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-013","number":13,"package":"Paket Prediksi","topic":"Mata","title":"Soal 013 · Seorang pria berusia 35 tahun datang ke…","page":203,"stem":"Seorang pria berusia 35 tahun datang ke puskesmas dengan keluhan kedua mata kabur dan merah sejak 3 hari yang lalu setelah kecipratan lumpur. Pekerjaan pasien adalah petani Visus ODS 6/30. Pada pemeriksaan mata ditemukan bercak putih berbentuk cakram di bagian kornea. Diagnosis pada pasien ini adalah..","options":["Glaukoma","Ulkus kornea","Uveitis","Konjungtivitis","lridosiklitis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-014","number":14,"package":"Paket Prediksi","topic":"Psikiatri","title":"Soal 014 · Perempuan 35 tahun datang bersama suaminya. Pasien…","page":204,"stem":"Perempuan 35 tahun datang bersama suaminya. Pasien mendengar suara yang memerintah, merasa dikendalikan dan dikejar, serta mencurigai suaminya berselingkuh. Pasien berulang kali ingin membunuh suaminya. Apakah kondisi yang dialami pasien?","options":["Gangguan cemas","Skizofrenia","Depresi","Manik","Paranoid"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-015","number":15,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 015 · Seorang laki-laki berusia 40 tahun datang kePKM…","page":204,"stem":"Seorang laki-laki berusia 40 tahun datang kePKM dengan di sekitar rahang bagian kanan sejak 3 tahun yang 12!u den Sedangsung lebih dari kali datam seminggu, nyeri muncul tiba-tiba sering di picu Oleh rasa dingin seperti minum es krim atau minum dingin lainnya. Pasien sudah menj21zni gigi beru!ang bahkan 2 giginya sempat dicabut tetapi nyerinya tid2k kunjung sembuh- Terapi apa yang tepat diberikan pada pasien ini?","options":["Carbamazepin","Diazepam","Clonazepam","Asam 'Aproat","Indcmæsin"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-016","number":16,"package":"Paket Prediksi","topic":"THT","title":"Soal 016 · Seorang wanita berusia 40 tahun datang dengan…","page":204,"stem":"Seorang wanita berusia 40 tahun datang dengan keluhzn keluar cairan bernarna dari telinga kanan sejak satu minggu yang lalu.T1dak disetai dengan demam. Pada pemeriksaan otoskopi ditemukan membrane timpani ruptur dan pada pemeriksaan garputala test rinne (-) pada telinga kanan, test swabach memanjang ke telinge kanan dan lateralisasi ke telinga kanan. Diagnosis yang paling tepat adalah—","options":["Otitis serosa","Otitis eksterna difusa","Otitis eksterna sirkumskripta","OMSK","OMSK dengan komp!ikasi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-017","number":17,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 017 · Seorang dokter hendak melakukan penelitian karena mencurigai…","page":204,"stem":"Seorang dokter hendak melakukan penelitian karena mencurigai adanya hubungan antara peningkatan kejadian nyeri kepala pada Siswa SMP dengan kebiasaan jajan di warung yang mengandung MSG. Waktu penelitian singkat. Metcde pene!itian apa yang tepat untuk digunakan?","options":["Case Control","Eksperimental","Cohort","Cross Sectional","Deskriptif"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-018","number":18,"package":"Paket Prediksi","topic":"Parasitologi","title":"Soal 018 · Seorang bayi perempuan berusia 2 hari dibawa…","page":204,"stem":"Seorang bayi perempuan berusia 2 hari dibawa ke IGD oleh orang tuanya dengan keluhan muntah-muntah berwarna hijau dan sudah 2 hari belum buang air besar. Pemeriksaan tanda vital dalam batas normal. Pemeriksaan fsik ditemukan anus normal, perut tampak distensi dan peristaltik meningkat. Pemeriksaan colok dubur didapatkan pergerakan mekonium melambat dan obtipasi berulang.Penanganan yang tepat adalah..","options":["Plasmodium malariae","Plasmodium falciparum","Plasmodium ovale","Plasmodiumknowlesi","Plasmodium vivax"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-019","number":19,"package":"Paket Prediksi","topic":"Parasitologi","title":"Soal 019 · seorang perempuan berusia 25 tahun dibawa ke…","page":205,"stem":"seorang perempuan berusia 25 tahun dibawa ke IGD karena penurunan kesadaran sejak 2 hari yang lalu. Pasien mempunyai riwayat demam yang disertai menggigil setiap 2 hari sejak 2 minggu yang lalu. Urine pasien berwarna seperti teh pekat. Terdapat hepatosplenomegali. pada pemeriksaan laboratorium didapatkan hasil Hb 5,9 g/dl, leukosit 18.500/mmj, trombosit 175.000/mm3. Ditemukan parasit malaria (+) pada apusan darah tepi. Parasit apakah yang menyebabkan penyakit di atas?","options":["Plasmodium malariae","Plasmodium falciparum","Plasmodium ovale","Plasmodium knowlesi","Plasmodium vivax"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-020","number":20,"package":"Paket Prediksi","topic":"Anak","title":"Soal 020 · Seorang ibu membawa bayi perempuannya berusia 5…","page":205,"stem":"Seorang ibu membawa bayi perempuannya berusia 5 bulan ke puskesmas dengan keluhan sesak nafas sejak 3 hari yang lalu. Sesak nafas disertai dengan panas tinggi dan batuk berdahak. Pasien mengalami flu sejak 4 hari yang lalu. Pemeriksaan fisik didapatkan nafas cuping hidung frekuensi nafas 45 x/menit dan suhu 39,20C. Ditemukan suara ronkhi basah halus pada auskultasi paru. Diagnosis yang tepat pada bayi ini","options":["Ateletaksis","Sindrom schwarte","Bronkopneumonia","Pneumonia","Efusi pleura"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-021","number":21,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 021 · Seorang laki-laki berusia 30 tahun datang dengan…","page":205,"stem":"Seorang laki-laki berusia 30 tahun datang dengan keluhan gatal dan kemerahan pada wajah dan punggung. Keluhan disertai ketombe. Pada pemeriksaan dermatologik didapatkan multipel plak eritematosa dengan batas tegas pada dahi kepala nasolabial, alis, punggung dan disertai skuama berwarna kekuningan. Diagnosis yang tepat adalah.„","options":["Impetigo","Psoriasis vulgaris","Pitriasis Rosea","Dermatitis kontak","Dermatitis seboroik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-022","number":22,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 022 · Seorang anak perempuan berusia 1,5 tahun dibawa…","page":205,"stem":"Seorang anak perempuan berusia 1,5 tahun dibawa ibunya ke IGD dengan keluhan nyeri Perut mendadak yang disertai dengan muntah. Menurut ibunya, pasien tidak demam dan tidakada riwayat trauma. Pada pemeriksaan USG menunjukkan adanya cincin hypoechoic concentric pada pertengahan perut kanan. Diagnosis apakah yang tepat pada pasien ini?","options":["Gallstone ileus","Volvulus","Wilms tumor","Hernia inguinal","Intussusceptions"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-023","number":23,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 023 · Seorang Iaki-laki berusia 35 tahun datang ke…","page":206,"stem":"Seorang Iaki-laki berusia 35 tahun datang ke ICD dengan keluhan nyeri pcrut kanan sejak I jam yang lalu. Nyeri hilang timbul, terasa tajam, mual muntah, lemas, dan keluar keringat. Nyeri muncul setelah makan ayam goreng. Diagnosis yang paling tepat adalah...","options":["Choledocholithiasis","Ulkus peptikum","Pankreatitis","Ulkus duodenum","Kolesistitis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-024","number":24,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 024 · Seorang pria berumur 35 tahun datang dengan…","page":206,"stem":"Seorang pria berumur 35 tahun datang dengan keluhan utama demam. Keluhan sudah dirasakan sejak3 hari yang lalu dengan disertai sakit kepala, nyeri sendi, mual, muntah, perdarahan gusi dan BAB hitam. Pasien tampak mengantuk, nadi teraba kecil dan cepat, tekanan darah 90/60 mmHg, dan akral dingin. Pemeriksaan laboratorium didapatkan hemoglobin 9,6 g/dl, leukosit 3200/mm3, hematokrit 41% dan trombosit 25.000/mrn'. Diagnosis apakah yang paling tepat?","options":["DBD","Typhoid fever","Malaria","Tetanus","Avian influenza"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-025","number":25,"package":"Paket Prediksi","topic":"THT","title":"Soal 025 · Seorang laki-laki berusia 30 tahun datang ke…","page":206,"stem":"Seorang laki-laki berusia 30 tahun datang ke dokter dengan keluhan nyeri menelan sejak 2 hari lalu. Nyeri dirasakan kambuh-kambuhan. Pada pemeriksaan fisik rongga mulut ditemukan kripte melebar, detritus (+) dan ada perlekatan dengan jaringan sekitarnya. Pasien didiagnosa tonsilitis. Apakahjenis tonsillitis dari pasien ini?","options":["Lakunaris","Akut","Tuberkulosa","Folikularis","Kronis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-026","number":26,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 026 · Seorang perempuan berusia 19 tahun dibawa Oleh…","page":206,"stem":"Seorang perempuan berusia 19 tahun dibawa Oleh petugas kepolisian ke IGD RS akibat kejadian kecelakaan lalu lintas I jam yang lalu. Pada saat setelah kejadian, pasien sempat pingsan kemudian tersadar kembali dan dapat berkomunikasi baik dengan petugas kepolisian tersebut. Menurut pengakuan polisi tersebut, pasien tidak muntah-muntah saat setelah kejadian. Setelah tiba di IGD RS, pasien mengalami penurunan kesadaran dengan GCS 7 (E2M3V2). Tekanan darah 80/60 mmhg, frekuensi pernapasan 24 x/menit. Diagnosis pasien yang tepat yang mengakibatkan pasien mengalami kejadian tersebut adalah:","options":["Cedera kepala berat dengan perdarahan subdural","Cedera kepala sedang dengan perdarahan intraserebral","Cedera kepala berat dengan perdarahan epidural","Cedera kepala berat dengan kontusio serebral","Cedera kepala sedang dengan perdarahan subdural"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-027","number":27,"package":"Paket Prediksi","topic":"Psikiatri","title":"Soal 027 · Seorang perempuan berusia 30 tahun datang dengan…","page":206,"stem":"Seorang perempuan berusia 30 tahun datang dengan keluhan sulit tidur, nafsu makan berkurang, jantung berdebar-debar, nafas terasa berat dan sesak, lemah dan mudah tersinggUng. Dia tlnggal bersama 2 anaknya, suaminya sering pergi keluar kota dan hanya pulang setiap I bulan sekali. Pada pemeriksaan fisik dan laboratorium semuanya menunjukkan hasil yang normal. Diagnosis apa yang paling tepat?","options":["Gangguan bipolar","Psikosomatik","Fobia social","Depresi","Cemas menyeluruh"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-028","number":28,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 028 · Seorang Jaki - Jaki berusia 55 tahun…","page":207,"stem":"Seorang Jaki - Jaki berusia 55 tahun mengeluh saat bangun tidur pada pagi hari tiba - :tiba merasa lemah separuh tubuh kanan. Dalam perjalanan ke rumah sakit selama 6 jam, tubuhnya merasa ringan dan setelah tiba di rumah sakit keluhannya hilang sama sekali. Diagnosis yang paling tepat dari kasus di atas adalah...","options":["Transient iskemic attack","Stroke iskemik","Stroke hemoragik","Perdarahan sub arachnoid","Neuropati"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-029","number":29,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 029 · Seorang wanita berusia 30 tahun sudah memiliki…","page":207,"stem":"Seorang wanita berusia 30 tahun sudah memiliki 2 anak, datang dengan keluhan mengalami perdarahan pervaginam yang hilang timbul sejak I bulan terakhir. Pasien tidak memiliki riwayat KB dan tidak memiliki riwayat terlambat haid. Pemeriksaan tanda vital dalam batas normal. Pada pemeriksaan inspekulo tampak darah mengalir dari ostium uteri eksternum. Dari pemeriksaan bimanual didapatkan : uterus antefleksi, kesan membesar, bentuk biasa, kenyal, kedua adnexa tidak teraba. Diagnosis yang tepat pada pasien ini adalah...","options":["Kehamilan ektopik terganggu","Perdarahan uterus disfungsional","Mola hidatidosa","Hiperplasia endometrium","Kanker mulut rahim"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-030","number":30,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 030 · Seorang pria berusia 50 tahun datang dengan…","page":207,"stem":"Seorang pria berusia 50 tahun datang dengan keluhan terdapat benjolan di leher dengan ukuran 2 x 2,5 x 1,5 cm, benjolan bersifat kenyal dan tidak nyeri. Pasien juga mengeluh merasa seperti berdebar-debar, badan selalu berkeringat, dan berat badan menurun. Vital sign didapatkan tekanan darah 150/80 mmHg, nadi 94 x/menit, RR 20 x/menit, dan suhu 380C. Pada pemeriksaan laboratorium didapatkan hasil TSH menurun, FT4 meningkat, FT3 normal. Diagnosis apakah yang tepat pada pasien ini?","options":["Hipertirodisme","Struma nodusa toksik","Grave disease","Kista tiroid nontoksik","Scrofluroderma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-031","number":31,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 031 · Seorang laki-laki berusia 45 tahun mengeluhkan pusing…","page":207,"stem":"Seorang laki-laki berusia 45 tahun mengeluhkan pusing berputar yang sangat hebat sampai pasien tidak bisa membuka kedua matanya. Pasien juga mengeluhkan mual dan muntah yang hebat. Pada pasien tidak disertai dengan gangguan pendengaran dan berdenging. Diagnosis yang paling tepat untuk pasien tersebut di atas adalah„.","options":["Vertigo tipe perifer","Vertigo tipe sentral","Meneire disease","Labirinitis","BPPV"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-032","number":32,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 032 · Seorang wanita berusia 55 tahun datang ke…","page":208,"stem":"Seorang wanita berusia 55 tahun datang ke IGD dengan keluhan utama muntah darah sejak I hari yang lalu. Pasien diketahui sering mengkonsumsi obat untuk penyakit nyeri lutut dalam jangka waktu lama. Pada pemeriksaan fisik pasien tampak anemis dan didapatkan nyeri epigastrium. Hasil laboratorium menunjukkan Hb 7,8 gr/dl, leukosit 4.600 / ml, dan trombosit 270.000/mI. Kemungkinan penyebab muntah darah dari pasien tersebut adalah„.","options":["Gastritis erosif","Varises esophagus","Ulkus Iambung","Ca gaster","Dispepsia"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-033","number":33,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 033 · Seorang wanita berusia 37 tahun G2P,Ao hamil…","page":208,"stem":"Seorang wanita berusia 37 tahun G2P,Ao hamil 35 minggu datang ke RS dengan keluhan keluar darah dari liang vagina. Pasien juga mengeluh mulas-mulas. Vital sign dalam batas normal. Pada pemeriksaan obstetri fundus uteri teraba tegang dan janin sulit teraba. Diagnosis yang paling mungkin adalah.„","options":["Plasenta previa totalis","Plasenta Ietak rendah","Plasenta previa marginalis","Vasa previa","Solusio plasenta"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-034","number":34,"package":"Paket Prediksi","topic":"Mata","title":"Soal 034 · Seorang wanita berusia 32 tahun yang sudah…","page":208,"stem":"Seorang wanita berusia 32 tahun yang sudah menikah selama 5 tahun datang ke tempat praktik dokter. Pasien mengeluh nyeri perut secara tiba-tiba. Keluhan ini disertai dengan tubuh lemas dan pucat. Ada riwayat haid terlambat dua bulan. Pada pemeriksaan tanda vital didapatkan tekanan darah 90/60 mmHg, nadi 96 x/menit, frekuensi nafas 22 x/ menit. Pada pemeriksaan fisik konjungtiva palpebra pucat dan akral dingin. Pemeriksaan laboratorium hemoglobin 7,2 g/dl. Diagnosis yang paling tepat pada pasien ini","options":["KET","Appendicitis acut","Kolestitis akut","Pankreatitis","Cistitis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-035","number":35,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 035 · Seorang anak perempuan berusia 9 tahun dibawa…","page":208,"stem":"Seorang anak perempuan berusia 9 tahun dibawa Oleh ibunya dengan keluhan sudah mengalami menstruasi lebih awal dibandingkan dengan teman sekolahnya, kuncup payudara juga sudah terbentuk. Wajah berjerawat, rambut pubis dan aksila juga sudah tumbuh. Pada pemeriksaan LH dan FSH meningkat. Diagnosis yang tepat adalah...","options":["Normal","Tumor hipofisis","Tumor payudara","Tumor adrenal","Pubertas prekoks"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-036","number":36,"package":"Paket Prediksi","topic":"Mata","title":"Soal 036 · seorang perempuan berusia 35 tahun datang ke…","page":209,"stem":"seorang perempuan berusia 35 tahun datang ke puskesmas dengan keluhan mata kiri nyeri sejak 3 hari yang lalu. Pasien mengalami demam dan tampak mata menonjol. Tidak ada keluhan penurunan penglihatan, 4 hari sebelumnya pasien memencet jerawat di wajah. Pasien nampak kesakitan. Kemungkinan diagnosa pada pasien ini adalah...","options":["Glaukoma","Abses palpebra","Selulitis orbita","Panofthalmitis","Endofthalmitis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-037","number":37,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 037 · seorang anak Iaki-laki berusia 13 tahun dibawa…","page":209,"stem":"seorang anak Iaki-laki berusia 13 tahun dibawa ke IGD dengan keluhan penurunan kesadaran sejak I minggu yang lalu, sebelumnya demam 3 hari dan sebelum sakit pasien tenggelam di kolam renang. Dilakukan pungsi lumbal pada pemeriksaan mikroskopik LCS didapatkan organisme bulat berinti besar dan 1 inti berisi kariosöm, kromatik inti sedikit. Apa jenis organisme penyebab dari kondisi di atas?","options":["Taenia solium","Naegleria fowleri","Trikomonas tenax","Plasmodium Falciparum","Toxoplasma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-038","number":38,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 038 · Seorang anak Iaki-laki berusia 7 tahun dibawa…","page":209,"stem":"Seorang anak Iaki-laki berusia 7 tahun dibawa ke IGD RS dengan keluhan badan lemah sekali sejak 1 jam yang lalu. Sejak 3 hari yang lalu pasien diare terus-menerus cair seperti cucian beras dan berbau amis tanpa disertai lendir atau darah. Pada pemeriksaan fisik didapatkan tanda-tanda dehidrasi berat. Diagnosis yang tepat dari pasien adalah...","options":["Helmintiasis","Tifus","Kolera","Disentri","Amoebiasis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-039","number":39,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 039 · Seorang wanita berusia 49 tahun datang dengan…","page":209,"stem":"Seorang wanita berusia 49 tahun datang dengan keluhan sesak nafas disertai dengan bunyi mengi. Pasien tetap sesak walaupun sedang istirahat. Pemeriksaan tekanan darah 170/90 mmHg, nadi 88 x/menit, frekuensi nafas 26 x/menit dan suhu 37,1 oc. Pada pemeriksaan paru didapatkan suara dasar vesikuler (+) normal, tidak ditemukan ronki maupun wheezing. Retraksi dada (-). Pemeriksaan laboratorium SGOT dan SGPT normal. Didapatkan cairan dibawah diafragma. Ditemukan tumor ovarium dan kepadatan peritoneum. Sindrom apakah yang dialami Oleh pasien?","options":["Sindrom eisenmenger","Sindrom meig","Sindrom cartegener","Sindrom hepatorenal","Sindrom nefrotik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-040","number":40,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 040 · Seorang laki-laki berusia 24 tahun datang dengan…","page":209,"stem":"Seorang laki-laki berusia 24 tahun datang dengan keluhan terdapat benjolan di leher kiri sejak 1 minggu yang lalu. Pada pemeriksan biopsi halus didapatkan limfadeopati coll sinstbudat m,enyana, tidak asi lt atanya hiperemisDari pemeriksanlaboratoriumdidapatkan serbukan selimfosit, el PMNdan sel Blast, Diagnosis yang tepat pada kasus iniadalah..","options":["Cat scratch's disease","Sinus Catarrhalis","Limfadenopati akut","Limfadenopati kronis tak khas","Limfadenitis tuberculosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-041","number":41,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 041 · Seorang pasien perempuan berusia 50 tahun datang…","page":210,"stem":"Seorang pasien perempuan berusia 50 tahun datang dengan keluhan kaku pada jari-jari tangan selama 3 hari. Keluhan ini sudah dirasakan sejak 3 tahun yang lalu. Pemeriksaan fisik ditemukan jari-jari kaku, dan sendi interphalang tidak dapat digerakan. Vital sign dalam batas normal. Diagnosis yang tepat pada kasus ini adalah.„","options":["Gout","Osteoartritis","Osteomielitis","Reumathoid artritis","Ankylosing artritis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-042","number":42,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 042 · Seorang anak perempuan berusia 9 tahun dibawa…","page":210,"stem":"Seorang anak perempuan berusia 9 tahun dibawa Oleh orang tuanya ke PUSkesmas dengan keluhan timbul koreng bersisik yang tebal dan bintil-bintil kecil di kaki kiri. Tidak ada demam. Pada pemeriksaan fisik kulit tampak vesikel dan vesikopustulosa dengan krusta tebal di seluruh permukaan kulit kaki kiri. Apabila krusta diangkat, tampak Iuka dangkal, dasar kasar, dan tepi meninggi. Diagnosis pada kasus ini adalah...","options":["Impetigo vulgaris","Impetigo bulosa","Impetigo ulseratif","Impetigo kontagiosum","Impetigo krustosa"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-043","number":43,"package":"Paket Prediksi","topic":"Psikiatri","title":"Soal 043 · Seorang perempuan berusia 30 tahun dibawa keluarganya…","page":210,"stem":"Seorang perempuan berusia 30 tahun dibawa keluarganya ke IGD RS karena tiba-tiba membakar lemari bajunya. Pasien tampak kurus, rambut acak- acakan, tertawa tanpa alasan. Keluarga menyebutkan bahwa pasien sudah pernah dirawat di RS Jiwa terakhir 6 bulan yang lalu. Di rumah pasien suka makan jarum, paku, kotorannya sendiri. Indikasi rawat inap dari pasien ini adalah„.","options":["Paranoid","Halusinasi","Waham","Perilaku kacau","Insomnia"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-044","number":44,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 044 · Seorang pria 20 tahun datang diantar polisi…","page":210,"stem":"Seorang pria 20 tahun datang diantar polisi ke IGD post KKL Pada pasien ditemukan fraktur femur kanan terbuka dengan perdarahan ±1500ml. Pemeriksaan fisik TD 70/40 mmHg, HR 140 x/menit, RR 28 x/menit. Akral dingin, pucat, basah. Apakah gangguan keseimbangan asam basa yang mungkin ditemui apabila syok tidak di atasi?","options":["Asidosis metabolik","Asidosis respiratorik","Alkaloais metabolik","Alkalosis respiratorik","Asidosis metabolik& respiratorik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-045","number":45,"package":"Paket Prediksi","topic":"Mata","title":"Soal 045 · Seorang anak perempuan berusia 4 tahun dibawa…","page":210,"stem":"Seorang anak perempuan berusia 4 tahun dibawa Oleh ibunya ke puskesmas dalam keadaan lemah. Pada anamnesis didapatkan muka dan kedua kaki bengkak sejak 2 bulan yang lalu. Nafsu makan menurun. Sehari-hari makan 2 kali dengan nasi dan sayur seadanya, tanpa daging atau ikan. Pada pemeriksaan didapatkan konjungtiva anemis, rambUt kemerahan, turnbuh jarang, mudah dicabut, tidak sakit. Abdomen membuncit dan ada pitting oedemi crazy pavement dermatosis pada ekstremitas inferior. unsur gizi yang dibutuhkan untuk mencegah terjadinya kasus di atas adalah.„","options":["Vitamin B I","Vitamin C","Energi","Zat besi","Protein"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-046","number":46,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 046 · Seorang perempuan berusia 30 tahun datang dengan…","page":211,"stem":"Seorang perempuan berusia 30 tahun datang dengan keluhan terdapat benjolan pada leher bagian depan. Pasien tidak mengeluh sering berkeringat dan jantung tidak berdebar-debar. Sekitar I minggu yang lalu pasien menderita nyeri dan demam. Pada pemeriksaan vital sign dalam batas normal. Pemeriksaan lokalis terdapat massa bulat, kenyal, mudah digerakkan ukuran 3 x 3 x 2 cm, pada saat menelan ikut bergerak. pemeriksaan laboratorium didapatkan leukositosis, LED meningkat,T3 dan T4 meningkat. Diagnosis yang tepat pada pasien ini adalah.„","options":["Karsinoma tiroid","Goiter nodosa non toksik","Goiter difusa toksik","Goiter nodosa toksik","Tiroiditis akut"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-047","number":47,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 047 · Seorang perempuan berusia 25 tahun dibawa ke…","page":211,"stem":"Seorang perempuan berusia 25 tahun dibawa ke IGD dalam kondisi tidak sadarkan diri setelah mengalami kecelakaan lalu lintas. Kecelakaan terjadi sekitar 30 menit yang lalu. Pasien memakai helm tetapi saat kejadian helmnya pecah dan kepalanya membentur aspal. Vital sign tekanan darah 100/60 mmHg, nadi 96 x/menit, frekuensi napas 22 x/menit, dan suhu 37,20C. Pemeriksaan fisik ditemukan racoon eyes dan battle sign. Diagnosis yang tepat pada pasien ini adalah.„","options":["Fraktur basis cranii","Fraktur calvaria cranii","Perdarahan subdural","Perdarahan subarachnoid","Perdarahan epidural"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-048","number":48,"package":"Paket Prediksi","topic":"Mata","title":"Soal 048 · Seorang Iaki-laki berusia 45 tahun datang ke…","page":211,"stem":"Seorang Iaki-laki berusia 45 tahun datang ke puskesmas dengan keluhan nyeri disekitar mata kiri sejak 3 hari yang lalu. Selain nyeri pasien juga merasakan banyak keluar air mata, merah, pandangan kabur dan terdapat halo. Pada pemeriksaan mata kiri terdapat blepharospasme, konjungtiva hiperemis, kornea edema, COA dangkal, pupil mid dilatasi, funduskopi sulit dinilai, TIO dengan palpasi teraba keras, mata kanan tampak tenang. Kemungkinan diagnosis pada pasien ini adalahm","options":["Glaukoma sudut tertutup akut primer","Glaukoma sudut tertutup kronik subakut","Glaukoma sudut tertutup sekunder","Glaukoma sudut terbuka primer","Glaukoma sudut tertutup"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-049","number":49,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 049 · Seorang pasien wanita berumur 55 tahun, masuk…","page":212,"stem":"Seorang pasien wanita berumur 55 tahun, masuk RS dengan serangan stroke ringan, tanpa demam, batuk, maupun sesak. Setelah 5 hari di RS kemudian pasien menjadi demam dan disertai batuk berdahak kekuningan. pada pemeriksaan fisik didapatkan suhu 39,30C. Pemeriksaan foto rontgen didapatkan infiltrat pada paru kanan. Dari hasil pemeriksaan darah didapatkan leukosit 23500/mm3. Kondisi apakah yang dialami Oleh pasien tersebut?","options":["Bronchitis kronik","PPOK","Pneumonia nosokomial","Pneumonia masyarakat","Pneumonia interstitialis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-050","number":50,"package":"Paket Prediksi","topic":"Anak","title":"Soal 050 · Seorang bayi perempuan berusia I tahun dibawa…","page":212,"stem":"Seorang bayi perempuan berusia I tahun dibawa Oleh ibunya ke rumah sakit dengan keluhan lebam-lebam pada tubuh sejak 4 hari yang lalu. Pada pemeriksaan fisik didapatkan bengkak pada lutut dan lebam lengan bawah. Dari hasil pemeriksaan laboratorium darah ditemukan hemoglobin, leukosit dan trombosit normal. Hasil yang Iain didapatkan clotting time memanjang, bleeding time normal, APTT memanjang dan PT normal. Diagnosis yang tepat pada pasien ini adalah.„","options":["Syndrom Bernard Sollier","Hemofilia","Disfibrinogenemia","Tromboastenia","Von willebrand disease"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-051","number":51,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 051 · Seorang Iaki-laki berusia 21 tahun datang ke…","page":212,"stem":"Seorang Iaki-laki berusia 21 tahun datang ke dokter dengan keluhan bengkak pada kantung dan buah zakar sebelah kanan sejak 2 hari yang lalu. Keluhan dirasakan setelah pasien mengangkat benda berat. Pasien menderita sakit kelenjar parotis 5 hari yang lalu. Pada pemeriksaan fisik didapatkan skrotum dan testis kanan bengkak, kemerahan, dan nyeri. Nyeri akan berkurang jika skrotum diangkat. Diagnosis apakah yang tepat?","options":["Torsio testis","Tumor testis","Epididimoorkitis","Hernia scrotalis","Hidrokel"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-052","number":52,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 052 · Seorang pasien datang dengan keluhan wajah mencong…","page":212,"stem":"Seorang pasien datang dengan keluhan wajah mencong dan kelopak mata kiri tidak dapat digerakkan menutup. PF tanda vital tak ada kelaianan, PF neurologi Iagoftalmus kiri, alis mata kiri tidak dapat diangkat, plica nasolabial datar dan tertinggal dibanding yang kanan. Apakah kemungkinan kelainan N. VII di atas?","options":["Kanan sentral","Kanan perifer","Kiri sentral","Kiri perifer","Nuclear"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-053","number":53,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 053 · Seorang pria berusia 25 tahun datang ke…","page":212,"stem":"Seorang pria berusia 25 tahun datang ke praktek dokter umum dengan keluhan nyeri seperti terbakar saat buang air kecil sejak 3 hari yang lalu. Dari anamnesis keluhan disertai sekret warna seperti susu. Pada pemeriksaan mikroskopis sekret dijumpai banyak neutrofil dan mikroorganisme diplokokus gram (-) intraselular. Apakah penyebab dari kasus tersebut?","options":["Trichomonas vaginalis","Neisseria gonorrhea","Herpes simpleks","Treponema palidum","Candida albicans"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-054","number":54,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 054 · Seorang wanita berusia 40 tahun mengalami pembesaran…","page":213,"stem":"Seorang wanita berusia 40 tahun mengalami pembesaran uterus simetris tanpa disertai nodul atau massa. Pasien juga mengalami nyeri pelvis dan menorrhagia. Pemeriksaan vital sign tekanan darah 130/80 mmHg, nadi 86 x/menit, frekuensi nafas 20 x/menit dan suhu 36,8 oc. Tes kehamilan Diagnosis yang paling tepat adalah...","options":["Adenomiosis","Hiperplasia endometrium","Endometritis kronis","Endometriosis","Leimyoma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-055","number":55,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 055 · seorang anak perempuan berusia 6 tahun diantar…","page":213,"stem":"seorang anak perempuan berusia 6 tahun diantar Oleh orang tuanya datang ke dokter umum dengan keluhan terdapat Iuka di dalam mulutnya, keluhan tersebut sudah timbul 3 hari yang lalu diawali dengan demam dan gelembung-gelembung berisi air dan kemudian pecah menjadi Iuka. Dari pemeriksaan fisik intraoral didapatkan ulserasi bentuk tidak teratur ditutupi pseudomembran kekuningan yang terdapat pada mukosa bibir, pipi, dan anterior Iidah. Penyebab kasus di atas adalahm","options":["Virus HIV","Virus Epstein-Barr","Virus papiloma","Virus varicela zoster","Virus herpes simplek"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-056","number":56,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 056 · Seorang perempuan berusia 45 tahun menderita diabetes…","page":213,"stem":"Seorang perempuan berusia 45 tahun menderita diabetes mellitus sejak 4 tahun yang lalu, datang dengan keluhan keputihan dan terasa gatal sejak 2 bulan yang lalu. Pada pemeriksaan didapatkan mukosa vulva dan vagina hiperemis, maserasi, serviks edema, hiperemis dan erosi serta fluor albus berwarna putih kental seperti susu. Diagnosis yang tepat pada pasien ini adalah„.","options":["Vulvovaginitis trikomonas","Vulvovaginitis candida","Servisitis bacterial","Servisitis gonorrhea","Servisitis klamidial"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-057","number":57,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 057 · Seorang pria berusia 35 tahun datang ke…","page":213,"stem":"Seorang pria berusia 35 tahun datang ke IGD dengan penurunan kesadaran sejak tadi pagi. Menurut keluarganya pasien mengeluh sejak 1 bulan yang lalu sulit tidur dan badan terasa panas ± 3 hari dan batuk berdahak. Badan tampak kurus, sejak satu tahun yang lalu pernah mendapatkan terapi untuk keluhan yang sama namun berhenti sejak 3 bulan yang lalu. Pemeriksaan fisik kesadaran koma, tekanan darah 150/90, Nadi 120x/menit, t: 380 C, mata menonjol, leher teraba ada pembesaran kelenjar tiroid difus. GDS: 80 mg/dl. Kondisi apakah yang dialami Oleh pasien tersebut?","options":["Krisis Tiroid","Koma miksedema","Koma hipoglikemi","Hipotiroid subklinis","Hipertiroid subklinis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-058","number":58,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 058 · Seorang wanita berusia 38 tahun datang ke…","page":214,"stem":"Seorang wanita berusia 38 tahun datang ke poliklinik RS dengan keluhan mulut mencong ke kanan, mata kanan tidak bisa menutup dan alis kanan sulit digerakkan. Keluhan ini dirasakan tiba-tiba setelah bangun tidur di pagi hari. Riwayat sebelumnya pasien tidak pernah seperti ini. Pada pemeriksaan fisik didapatkan kekuatan motorik keempat ekstremitas normal. Didapatkan paresis Nervus VII komplit total. Diagnosis yang tepat adalahm","options":["Stroke non hemoragik","Stroke hemoragik","Bell's Palsy","Insufisiensi vertebrobasiler","Trauma nervus fascialis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-059","number":59,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 059 · Seorang laki - laki berusia 45 tahun…","page":214,"stem":"Seorang laki - laki berusia 45 tahun datang dengan keluhan sesak napas yang semakin memberat sejak kemarin. Kemudian dilakukan pemeriksaan rontgen dada. Hasilnya terlihat gambaran radiolusen di paru kiri, trakea terlihat tertarik ke kiri dan ditemukan adanya gambaran radioopak berbentuk bulat di hilus paru kiri. Gambaran yang paling mungkin dari rontgen ini","options":["Hidropneumotoraks paru kiri","Pneumotoraks paru kiri","Atelektasis paru kanan","Atelektasis paru kiri","Pneumotoraks paru kanan"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-060","number":60,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 060 · Seorang pria berusia 35 tahun ditemukan tergantung…","page":214,"stem":"Seorang pria berusia 35 tahun ditemukan tergantung di dalam kamar. Polisi lalu meminta untuk dilakukan otopsi, di dapatkan jejas serong pada leher dari depan ke belakang ukuran 3 cm, berwarna coklat tua, tepi Iuka bengkak, wajah berwarna hijau gelap, sklera merah, jari biru, bendungan organ dalam (-), tanda kekerasan (-). Penyebab kematian pada kasus di atas adalah...","options":["Bendungan pembuluh darah","Mati lemas karena kekurangan 02","Penutupan jalan napas","Sianosis mukosa dan kulit","Kerusakan organ dalam"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-061","number":61,"package":"Paket Prediksi","topic":"Psikiatri","title":"Soal 061 · Seorang perempuan berusia 40 tahun dibawa ke…","page":214,"stem":"Seorang perempuan berusia 40 tahun dibawa ke rumah sakit Oleh keluarganya dengan keluhan menjadi pendiam dan murung sejak IO hari yang lalu. Menurut keluarganya pasien terlihat murung dan mengatakan merasa ada yang mengajak dirinya bicara. Pasien juga merasa lelah dan kurang berminat atas segala sesuatu. Nafsu makan pasien juga berkurang. Pemeriksaan vital sign dalam batas normal. Diagnosis yang tepat pada kasus di atas","options":["Skizofrenia katatonik","Skizofrenia paranoid","Skizofrenia hebrefenik","Skizoafektiftipe depresi","Skizoafektif tipe manik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-062","number":62,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 062 · Seorang Iaki-laki berusia 43 tahun, datang dengan…","page":214,"stem":"Seorang Iaki-laki berusia 43 tahun, datang dengan keluhan batuk-batuk selama I bulan, terdapat penurunan nafsu makan dan berat badan. Pasien sudah berobat dan didiagnosis TB paru aktif. Pasien bekerja sebagai buruh dan tinggal bersama istri, anak, dan kedua orang tuanya yang sudah tua dan sakit-sakitan. Bentuk keluarga apakah yang dimiliki","options":["single parent family","communal family","nuclear family","extended family","blended family"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-063","number":63,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 063 · seorang Iaki-laki berusia 35 tahun datang ke…","page":215,"stem":"seorang Iaki-laki berusia 35 tahun datang ke poliklinik RS dengan keluhan demam, mual, muntah dan nyeri pada perut sebelah kanan sejak 3 hari yang lalu. Dari pemeriksaan fisik ditemukan pembesaran hepar 3 jari di bawah arcus costae. Pemeriksaan laboratorium Hb 1 1, Ht 29, trombosit 320.000, HbsAg (+), IgG anti-HAV anti-HCV Diagnosis pada pasien ini yang paling tepat adalah...","options":["Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis D","Hepatitis E"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-064","number":64,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 064 · Seorang wanita berusia 28 tahun, hamil 34…","page":215,"stem":"Seorang wanita berusia 28 tahun, hamil 34 minggu datang dengan keluhan nyeri saat berkemih sejak 2 hari yang lalu. Pasien tidak merasakan demam, nyeri pinggang, mual, dan muntah. Pemeriksaan urine rutin nitrit (+), leukosit (+4). Pengobatan apa yang tepat pada pasien tersebut?","options":["Periksa kultur urine, Ciprofloxacin 2 x 250mg, 3 hari","Periksa kultur urine, Cefalexin 3 x I tab, 7 hari","Cotrimoxazole 2 x 1 tab, 3 hari","Tetrasiklin 3 x 500mg, 7 hari","Ciprofloxacin 2 x 250mg, 3 hari"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-065","number":65,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 065 · Seorang laki — Iaki berusia 40 tahun…","page":215,"stem":"Seorang laki — Iaki berusia 40 tahun datang ke dokter dengan keluhan pembesaran pada leherbagian depan sejak 3 bulan yang lalu. Pasien tersebut tinggal di daerah pegunungan. Pasien mengatakan di sekitar tempat tinggalnya banyak yang mengalami keluhan serupa. Dari pemeriksaan laboratorium didapatkan T3 &T4 normal dan TSH meningkat. Diagnosis pada pasien ini adalah...","options":["Hipertiroid","Goiter","Penyakit graves","Karsinoma tiroid","Tirotoksikosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-066","number":66,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 066 · Seorang dokter peneliti ingin mengetahui pengaruh vaksin…","page":215,"stem":"Seorang dokter peneliti ingin mengetahui pengaruh vaksin campak terhadap terjadinya penyakit campak. Dari 100 orang yang mengikuti vaksin campak sejak 5 tahun yang lalu didapatkan 50 orang yang menderita campak. Dari 100 orang pendamping didapatkan IO yang menderita campak. Dasar penelitian yang digunakan pada penelitian ini adalahm","options":["Eksperimental","Kohort","Kasus kontrol","Cross sectional","Deskriptif"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-067","number":67,"package":"Paket Prediksi","topic":"Anak","title":"Soal 067 · Bayi berusia 3 harl dibawa ke RS…","page":216,"stem":"Bayi berusia 3 harl dibawa ke RS Oleh ibunya dengan keluhan Utama kelemahan lengan sebelah kanan yang diketahui ibunya seJak bayi berusia 2 hari. Bayi lahir secara spontan belakang kepala, ditolong bidang praktek swasta, usla kehamilan cukup bulan, BBL 4000 gr, didapatkan kesulitan saat lahir. Pada pemeriksaan fisik didapatkan posisi ekstremitas superior dekstra ekstensi, pronasi, dan endorotasi. Refleksi moro asimetris, reflex genggam Diagnosis yang tepat pada pasien ini adalah...","options":["Neonatus Aterm/BMK + paralise Klumpke","Neonatus aterm/BMK + paralise Erb","Neonatus Prematur / BMK + paralise Klumpke","Neonatus Aterm/BBLR + Paralise Erb","Neonatus Aterm/BMK + total paralise plexus brachialis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-068","number":68,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 068 · Seorang perempuan berusia 19 tahun datang ke…","page":216,"stem":"Seorang perempuan berusia 19 tahun datang ke IGD RS dengan keluhan telah diperkosa Oleh pamannya sekitar 12 jam yang lalu. Pasien mengajukan permintaan visum et repertum. Pemeriksaan didapatkan Iuka memar di paha bagian dalam, pemeriksaan hapusan vulva tidak didapatkan spermatozoa kemudian dokter membuat visum et repertum dan menyimpulkan tidak didapatkan tanda-tanda persetubuhan. Dokter tersebut kemudian dipanggil Oleh pengadilan 6 bulan kemudian untuk menjadi saksi ahli. Keterangan apa yang sebaiknya diberikan Oleh dokter tersebut?","options":["Memberikan penjelasan bahwa korban dianiaya bukan diperkosa","Memberi penjelasan bahwa korban tidak diperkosa","Menolak karena melanggar kaedah dasar moral yaitu otonomi","Memberikan pendapat terhadap pemeriksaan perempuan pada waktu pemeriksaan","Mengatakan sejujurnya, tidak ingat kalau pernah memeriksa perempuan tersebut"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-069","number":69,"package":"Paket Prediksi","topic":"THT","title":"Soal 069 · Seorang Iaki-laki berusia 45 tahun yang berprofesi…","page":216,"stem":"Seorang Iaki-laki berusia 45 tahun yang berprofesi sebagai penyapu jalan datang ke Puskesmas dengan keluhan setiap menyapu bersin lebih dari 5x disertai ingus yang encer jernih dan keluhan hidung terasa buntu. Keluhan berlangsung selama 2 tahun ini hampir tiap hari, pasien juga mengeluh telinga sering gatal dan kadang terasa basah. Pasienjuga merasakan sakit kepala dan rasa tidak nyaman dengan keluhan ini. Pada pemeriksaan fisik hidung kavum nasi kanan dan kiri sempit konka inferior hipertrofi warna pucat dan tampak sekret serous jernih. Diagnosis yang tepat pada pasien ini adalah...","options":["Rinitis vasomotor berat","Rinitis alergi intermitten ringan berat","Rinitis alergi persisten ringan","Rinitis alergi intermitten sedang","Rinitis alergi persisten sedang"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-070","number":70,"package":"Paket Prediksi","topic":"THT","title":"Soal 070 · Seorang anak laki-laki berusia 5 tahun dibawa…","page":216,"stem":"Seorang anak laki-laki berusia 5 tahun dibawa ke IGD dengan keluhan batuk disertai tenggorokan tercekik. Menurut keterangan orang tuanya, ada riwayat makan permen karet kemudian tersedak. Dari pemeriksaan didapatkan pasien compos mentis, stridor, denyut nadi 1 OOx/menit dan frekuensi pernafasan 50x/menit. selain itu didapatkan nafas cuping hidung, retraksi suprasternal dan tidak ada retraksi lain. Tindakan yang tepat bagi pasien di atas adalah...","options":["Abdomen thrust","Sellick","Hemlich maneuver","Back blow","Chest thrust"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-071","number":71,"package":"Paket Prediksi","topic":"Anak","title":"Soal 071 · Seorang bayi lahir 3 hari yang lalu,…","page":217,"stem":"Seorang bayi lahir 3 hari yang lalu, lahir spontan di bidan praktek swasta, BBL 3750 gram, lahir langsung menangis. Pada usia 2 hari muncul benjolan pada kepala bayi, melewati sutura dan meluas sampai ke parietal, bayi juga tampak anemis. Diagnosis yang tepat pada pasien ini adalah...","options":["Perdarahan subgalea!","Perdarahan intracranial","Caput suksadenum","Cephal hematom","Hidrocephalus"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-072","number":72,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 072 · Seorang anak perempuan berusia II tahun dibawa…","page":217,"stem":"Seorang anak perempuan berusia II tahun dibawa ke puskesmas dengan keluhan gatal dan merah pada tungkai kiri sejak 6 bulan. Lesi awalnya berupa bintil-bintil kecil yang melebar dan menjadi basah bila digaruk. Lesi sempat hilang namun timbul kembali di sekitarnya, Riwayat kontak dengan bahan iritan dan logam (-). Riwayat atopi (-). Pasien sudah pernah memakai salep oksitetrasiklin tapi tidak ada perbaikan. Dari pemeriksaan, eflorosensi makula eritema, papul-papul, vesikel-vesikel. Bentuk lesi bulat multipel, beberapa lesi tertutup krusta pada ekstremitas inferior sinistra. Diagnosis pada pasien tersebut adalah...","options":["Psoriasis","Impetigo krustosa","Liken simpleks kronis","Dermatitis atopik","Dermatitis numularis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-073","number":73,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 073 · Seorang Jaki-Jaki berusia 55 tahun datang ke…","page":217,"stem":"Seorang Jaki-Jaki berusia 55 tahun datang ke dokter dengan keluhan sering haus dan sering kencing. Pasien mengaku mempunyai riwayat hipertensi. Pemeriksaan vital sign tekanan darah 170/100 mmHg, nadi 94 x/menit, frekuensi napas 20 x/menit, dan suhu 36.50C. Pemeriksan laboratorium gula darah puasa : 235 mg/dL, gula darah 2 jam PP : 258 mg/dL Hasil pemeriksaan EKG menunjukkan adanya hipertrofi ventrikel kiri. Terapi yang tepat pada pasien ini adalah...","options":["Diuretik","ACE inhibitor","Caantagonis","a-blocker","ß-blocker"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-074","number":74,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 074 · Seorang priaberusia tahu datang ke plijntung dengankluhansesaknapassak…","page":217,"stem":"Seorang priaberusia tahu datang ke plijntung dengankluhansesaknapassak 1 bulan yang lalu. Keluhan disertai bengkak pada muka, perut dan kaki. Nafsu makan menurun, susah tidur. Pasien sempat berobat 5 bulan yang lalu dengan keluhan yang sama, minum obat tidak teratur, karena setiap kali habis minum obat jadi kencing2.Saat itu pasien direncanakan untuk dilakukan tindakan pelebaran katub jantung tapi pasien belum bersedia. Vital sign tekanan darah 100/80 mm/Hg, Nadi82 x/menit, R 30 x/menit, S 36,4 0C. JVP meningkat, tidak ada pergeseran jantung ke kiri, ronkhi(-), wheezing (-), terdengar bising diastol derajat IV/VI di apek, teraba thrill di apek. Hepar teraba 4 jari di bawah arkus costa, lien tidak teraba, ascites (+), Oedem tungkai kanan&kiri (+). Pemeriksaan lab Hb 11,5 g/d, SGOT 210,albumin 2,5, Kalium 3,2 Natrium 132, EKG irama sinus 78 x/menit, deviasi sumbu ke kanan, RAD, LAA, hipertrof ventrikel kanan. Diagnosis yang tepat pada kasusini adalah..","options":["Mitral stenosis","Mitral regurgitasi","Aorta regurgitasi","Aorta stenosis","Pulmonal stenosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-075","number":75,"package":"Paket Prediksi","topic":"Mata","title":"Soal 075 · Seorang perempuan berusia 50 tahun dirujuk ke…","page":218,"stem":"Seorang perempuan berusia 50 tahun dirujuk ke klinik mata dengan keluhan mata kiri kabur. Hasil pemeriksaan VOS 3/60, konjungtiva tenang, kornea jernih, COA sedang, pupil bulat, reflex cahaya (+), lensa jernih, tekanan intra ocular 15 mmHg, dan funduscopy cup disc ratio 0,9. Gonioskopi dengan sudut terbuka. Pemeriksaan apakah yang kita perlukan untuk membantu penegakkan diagnosis?","options":["Octopus perimetry","Retinometer","Streak retinoscopy","USG","Refractometry"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-076","number":76,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 076 · Seorang pria berusia25tahundatangdengan keluhan nyerisaatberjaIan.Keluhan dirasakan sejak…","page":218,"stem":"Seorang pria berusia25tahundatangdengan keluhan nyerisaatberjaIan.Keluhan dirasakan sejak I minggu yang lalu. Pada pemeriksaan fisik didapatkan ada benjolan dilipat paha kanan, tampak eritem dan tampak seperti anak tangga dan nyeri. Kemungkinan diagnosis pada kasus di atas adalahm","options":["Hernia scrotalis","Hernia inguinalis","Abses","Limfogranuloma","Granuloma inguinali5"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-077","number":77,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 077 · Seorang pria berusia 35 tahun datang ke…","page":218,"stem":"Seorang pria berusia 35 tahun datang ke puskesmas dengan keluhan bengkak di seluruh tubuh sejak 3 bulan yang lalu. Awalnya bengkak pada kedua kelopak mata, lalu wajah, lalu pada seluruh tubuh. Urin pasien menjadi sedikit sejak 3 minggu yang lalu. Pemeriksaan vital sign tekanan darah 140/90 mmHg, nadi 98x/menit, regular, equal, isi cukup, frekuensi nafas 24x/menit, temperatur 37,10 C, puffy face, anemis, malar rash (+), JVP dbn, ronki -/-, suara jantung dbn. Hasil apakah yang ditemukan pada pemeriksaan urinalisis pasien tersebut?","options":["Normal","Leukosituria","Hematuria","Protemuria","Bakteriuri"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-078","number":78,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 078 · seorang wanita sedang hamil 6 bulan berobat…","page":219,"stem":"seorang wanita sedang hamil 6 bulan berobat ke Puskesmas. Pasien mengeluh batuk yang terkadang disertai lendir dan darah. Pasien mengaku sudah menderita batuk sejak sebelum hamil dan sudah mendapat terapi OAT. Kata dokter ia harus mendapat pengobatan kategori 2 tetapi tidak dianjurkan menggunakan streptomisin. Pengaruh penggunaan streptomisin pada pasien ini adalah...","options":["Urin ibu berwarna merah","Ototoksik pada janin","Buta permanen pada bayi","Rasa kesemutan pada tubuh ibu","Nyeri sendi pada ibu"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-079","number":79,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 079 · seorang wanita berusia45 tahun mengidap penyakit asmasejakkecil.…","page":219,"stem":"seorang wanita berusia45 tahun mengidap penyakit asmasejakkecil. Kemudian sekarang mengalami sesak nafas sehingga dibawa ke IGD RS. Pada pemeriksaan fisik ditemukan bengkak pada buah zakar, asites, dan edema pada ekstremitas inferior. Pemeriksaan tanda vital didapatkan tekanan darah 120/90 mmHg, nadi 100 x/menit, frekuensi nafas 28 x/menit. Hasil pemeriksaan EKG menunjukkan gambaran P pulmonal dan FEVI 70%. Penyebab gangguan pernafasan pada pasien ini adalah...","options":["Regulasi pernapasan","Difusi Paru","Ventilasi obstruktif","Ventilasi restriktif","Perfusi jaringan"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-080","number":80,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 080 · Seorang wanita berusia 30 tahun datang ke…","page":219,"stem":"Seorang wanita berusia 30 tahun datang ke dokter umum dengan keluhan nyeri sendi sejak 3 bulan yang lalu. Nyeri dirasakan berpindah-pindah, sering pada sendi siku dan sendi lutut. Pasien juga mengaku berat badannya turun sebanyak 5 kg. Vital sign dalam batas normal. Pemeriksaan fisik didapatkan bercak mafar dan berca discoid sendi. Dilakukan pemeriksaan laboratorium dan hasilnya adalah ANA dan dsDNA (+), antigen rematoid artritis (-). Diagnosis pada kasus di atas adalah...","options":["Anemia hemolitik","SLE","Spondiloartritis","Vitiligo","Artritis rematoid"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-081","number":81,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 081 · Seorang pria berumur 55 tahun datang diantar…","page":219,"stem":"Seorang pria berumur 55 tahun datang diantar keluarganya ke IGD dengan keluhan sesak napas. Sesak mendadak saat pasien pulang dari sawah. Pasien saat akan dibawa ke RS batuk berdahak seperti darah. Pasien memiliki riwayat hipertensi 5 tahun terakhir dan rajin kontrol, pasien 6 bulan yang lalu dirawat di RS karena seranganjantung. Pemeriksaan fisik tekanan darah 180/110mmHg, nadi 98 x/mnt, RR 28x/mnt, Suhu 36,3 oc, didapatkan pembesaran jantung, ronki halus di kedua lapang paru kanan & kiri. Akral dingin tanpa disertai edema. Pemeriksaan laboratorium GDS 175 mg/dl. Ureum 53 mg/dl, kreatinin mg/dl. CKMB 14, SGOT 14 II-J. Pada pemeriksaan EKG. Irama sinus 92 x/menit dan didapatkan gambaran infark miokard lama anterior. Diagnosis yang tepat pada pasien ini adalah.„","options":["Gagal ginjal","Gaga! jantung kongestif","Hipertensi emergensi","Edema paru","Sindrom koroner akut"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-082","number":82,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 082 · Seorang Iaki-laki berusia 21 tahun mengalami kecelakaan…","page":220,"stem":"Seorang Iaki-laki berusia 21 tahun mengalami kecelakaan lalu lintas.Terdapat Iuka terbuka di kepala sebelah kiri. Riwayat muntah dan pingsan positif. Pada CT-Scan didapatkan gambaran hiperdens bikonveks pada temporal kiri, dan terdapat fraktur pada temporal kiri. Diagnosis yang tepat pada pasien tersebut adalah...","options":["EDH","SAH","SDH","IVH","ICH"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-083","number":83,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 083 · Seorang anak perempuan berusia 3 tahun datang…","page":220,"stem":"Seorang anak perempuan berusia 3 tahun datang ke IGD RS diantar ibunya. pasien rewel dan menangis dengan suara melengking seperti kesakitan. Pasien mulai tidak mau makan dan minum, sebelumnya pasien demam tinggi dan keluar cairan kehijauan dari telinganya. Imunisasi tidak lengkap. Pada pemeriksaan fisik nadi : 115x/mnt, suhu: 39.30C. Pada pemeriksaan neurologis GCS: 1 1, kaku kuduk (+), tonus otot meningkat, tes babinsky (+/+) . Pada pemeriksaan LCS warna keruh sel 1100, protein 180, pada kultur kuman ditemukan H. influenza. Vaksin yang seharusnya diberikan untuk mencegah penyakit tersebut","options":["MMR","HPV","Meningokokus","Influenza","Hepatitis B"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-084","number":84,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 084 · Seorang pria berusia 30 tahun datang dengan…","page":220,"stem":"Seorang pria berusia 30 tahun datang dengan keluhan jantung berdebar - debar sejak 5 hari yang lalu, keluhan disertai sulit tidur, gelisah, gemetaran dan sering berkeringat. Pemeriksaan fisik tampak sakit sedang, kesadaran compos mentis, tekanan darah 130/80 mm/Hg, nadi 120 x/menit, RR 24 x/menit, S 37 oc, teraba pembesaran struma difus, ikut gerakan menelan, bunyi jantung 1,2 irreguler. Kemungkinan gambaran EKG yang dapat ditemukan pada kasus di atas adalahm","options":["Atrium flutter","Atrium fibrilasi","Ventrikel ekstra sistol","Ventrikel takikardi","Ventrikel fibrilasi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-085","number":85,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 085 · Seorang perempuan berusia 25 tahun dibawa ke…","page":220,"stem":"Seorang perempuan berusia 25 tahun dibawa ke IGD karena kecelakaan lalu lintas. Dari hasil pemeriksaan didapatkan mata membuka dengan rangsang nyeri, mengerang dan ekstremitas ekstensi maksimal. Berapa GCS pada pasien ini?","options":["E2V2M2","E3V2M3","E2V2M4","E2V3M2","E3V2M2"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-086","number":86,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 086 · Seorang pria berusia 40 tahun datang dengan…","page":220,"stem":"Seorang pria berusia 40 tahun datang dengan keluhan utama demam sejak 5 hari yang lalu. Keluhan disertai dengan nyeri kepala, nyeri sendi, nyeri otot, mual, muntah, tidak nafsu makan dan kencing sedikit. Satu minggu yang lalu rumah yang ditinggali pasien kebanjiran. Pada pemeriksaan fisik didapatkan tekanan darah 130/80 mmHg, nadi 64x/ menit, frekuensi nafas 20 x/rnenit, suhu 38,7 C, serta hepatomegali. Pada pemeriksaan darah leukosit 8700/mrn3. Pada urine diternukan proteinuri. Pada mikroskopik urine ditemukan kuman yang berbentuk spiral dengan kedua ujungnya berkait. Diagnosis apa yang paling tepat?","options":["Salmonelosis","Shigellosis","Buselosis","Leptospirosis","Treponematosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-087","number":87,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 087 · Seorang ibu membawa anaknya yang berusia 3…","page":221,"stem":"Seorang ibu membawa anaknya yang berusia 3 tahun ke Puskesmas. Ibu tersebut kaget karena saat memandikan anaknya menemukan kantong pelir kanan anaknya kosong tidal( ada buah zakarnya. Saat dilakukan pemeriksaan fisik ditemukan testis berada di inguinal. Kelainan apakah yang dialarni Oleh anak tersebut?","options":["Varikokel","Testis retraktil","Kriptorchismus","Funikulokel","Testis ektopik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-088","number":88,"package":"Paket Prediksi","topic":"Mata","title":"Soal 088 · Seorang pasien pria berusia 35 tahun datang…","page":221,"stem":"Seorang pasien pria berusia 35 tahun datang ke dokter umum dengan keluhan gangguan penglihatan. Pasien mengaku pandangannya kabur. Saat dilakukan pemeriksaan didapatkan VOD 2/60 dan VOS 2/60. Bagaimana interpretasi andajika hasil pemeriksaannya seperti pasien di atas?","options":["Pasien dapat menghitung jari pemeriksa pada jarak2 meter yang pada orang normal bisa dilihat dengan jarak 60 meter","Pasien dapat melihat lambaian tangan pada jarak 2 kaki yang pada orang normal bisa dilihat dengan jarak 60 kaki","Pasien dapat melihat cahaya pada jarak 2 meter yang pada orang normal bisa dilihat dengan jarak 60 meter","Pasien dapat melihat lambaian tangan pada jarak 2 meter yang pada orang normal bisa dilihat dengan jarak 60 meter","Pasien dapat menghitung jari pemeriksa pada jarak 2 kaki yang pada orang normal bisa dilihat dengan jarak 60 kaki"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-089","number":89,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 089 · Seorang Iaki-laki berusia 55 tahun datang ke…","page":221,"stem":"Seorang Iaki-laki berusia 55 tahun datang ke praktek dokter umum dengan keluhan nyeri kepala sebelah. Keluhan ini dirasakan sejak usia 20 tahun. Sebelum serangan pasien mengeluh pandangan berkunang-kunang, mual, dan muntah. Pada saat serangan, penderita hanya dapat berbaring. Keluhan ini tidak dirasakan memberat. Diagnosis yang tepat pada pasien ini adalah...","options":["Trigeminal headache","Migrain with aura","Migrain without aura","Cluster headache","Bell's palsy"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-090","number":90,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 090 · Seorang pasien perempuan berusia 25 tahun datang…","page":222,"stem":"Seorang pasien perempuan berusia 25 tahun datang dengan keluhan gatal dan kemerahan pada ketiak. Riwayat pasien sering memakai deodoran. Pada pemeriksaan fisik didapatkan edema, erosi, vesikel, eritematous. Penyebab dari kasus di atas adalah.„","options":["Reaksi hipersensivitas I","Reaksi hipersensivitas 2","Reaksi hipersensivitas 3","Reaksi hipersensivitas 4","Reaksi hipersensivitas 1 dan 2"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-091","number":91,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 091 · Seorang wanita usia 28 thn datang dengan…","page":222,"stem":"Seorang wanita usia 28 thn datang dengan keluhan sesak napas. Keluhan dirasa semakin memberat jika lari dan disertai batuk berdahak yang sulit dikeluarkan. Sudah pernah diobati tapi kambuh lagi. Pasien hamil 18 minggu pada pemeriksaan fisik RR 30x/menit eksperium diperpanjang, sheezing (+). Apa obat kontraindikasi pada kasus di atas?","options":["Teofilin","Epinefrin","Aminofilin","Salbutamol","Metilprednisolon"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-092","number":92,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 092 · Seorang Iaki-laki 30 tahun datang ke poliklinik…","page":222,"stem":"Seorang Iaki-laki 30 tahun datang ke poliklinik dngan keluhan gangguan ejakulasi. Dari anamnesa diketahui bahwa pasien pernah mendapat trauma psikoseksual sewaktu kecil. Pasien tidak dapat ejakulasi dalam liang vagina istrinya saat berhubungan seksual. Pasien masih dapat ejakulasi saat ia masturbasi atau dilakukan oral seks. Diagnosis yang tepat pada pasien ini adalah","options":["Aversi seksual","Disfungsi ereksi","Gangguan libido","Ejakulasi terhambat","Rangsangan seksual hipoaktif"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-093","number":93,"package":"Paket Prediksi","topic":"Mata","title":"Soal 093 · Seorang wanita berumur 45 tahun datang ke…","page":222,"stem":"Seorang wanita berumur 45 tahun datang ke tempat praktik dokter umum dengan keluhan badan lemas sejak I minggu yang lalu. Keluhan disertai wajah pucat dan jantung berdebar-debar. Keluhan demam tidak ada dan nyeri bagian tubuh Iain tidak ada. Pada pemeriksaan fisik didapatkan tekanan darah 100/70 mmHg, denyut nadi 74 x/menit, frekuensi pernapasan 18x/menit dan temperature 36,9 oc. Pada konjungtiva palpebra terlihat pucat. Hematom dan purpura pada tubuh tidak ada. Diagnosis pada kasus di atas","options":["Leukimia","Anemia","Trombositopenia","Polisitemia","Limfoma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-094","number":94,"package":"Paket Prediksi","topic":"Mata","title":"Soal 094 · Seorang pria berusia 25 tahun datang ke…","page":222,"stem":"Seorang pria berusia 25 tahun datang ke Puskesmas dengan keluhan timbul benjolan di kelopak mata kanan sejak 3 hari yang lalu. Pemeriksaan vital sign tekanan darah 120/70 mmHg, nadi 86 x/menit, RR 18 x/menit, dan suhu 36,50C. Pemeriksaan fisik pada benjolan konsistensi keras, tidak nyeri dan warnanya sama dengan sekitarnya. Diagnosis yang tepat pada pasien ini","options":["Konjungtivitis","Keratitis numularis","Hordeolum","Kalazion","Ulkus kornea"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-095","number":95,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 095 · seorang pria berusia 65 tahun datang ke…","page":223,"stem":"seorang pria berusia 65 tahun datang ke rumah sakit dengan keluhan pendengaran berkurang. Keluhan dirasakan dalam 1 tahun ini. Pendengaran berkurang secara perlahan namun tidak disadarinya. Pasien kurang bisa mendengar dan jika berbicara harus keras. pada pemeriksaan fisik didapatkan membrana timpani yang intak dan tidak ada tanda peradangan. Diagnosis yang tepat pada pasien ini","options":["Meniere disease","Presbiakusis","Otosklerosis","NIHL","Neuritis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-096","number":96,"package":"Paket Prediksi","topic":"THT","title":"Soal 096 · Seorang perempuan berusia 24 tahun datang ke…","page":223,"stem":"Seorang perempuan berusia 24 tahun datang ke puskesmas dengan keluhan hidung tersumbat sejak minggu yang lalu. Lubang hidung kanan keluar cairan kental warna kehijauan berbau busuk. Pasien sering mengeluh nyeri gigi dan gusi bengkak, membaik dengan antinyeri. Pemeriksaan rhinoskopi anterior udem konka inferior dan terdapat sekret di meatus media. Pemeriksaan penunjang yang tepat untuk pasien tersebut adalahm","options":["Xfoto Owen","Xfoto Schuller","Xfoto Waters","X foto Caldwell","X foto Rheese"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-097","number":97,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 097 · Seorang anak Iaki-laki berusia 5 tahun dibawa…","page":223,"stem":"Seorang anak Iaki-laki berusia 5 tahun dibawa ke IGD RS akibat diare dan muntah. Pasien tampak Ietargi, mata dan ubun-ubun cekung. \\TltaI sign tekanan darah 90/70 mmHg, nadi cepat lemah 120x/mnt, rr 24x/mnt, akral dingin, BB 5 kg, sudah dilakukan perbaikan selama 3 jam tetapi pasien masih letargi. Tindakan apa yang selanjutnya harus kita lakukan?","options":["1 jm pertama 70cc/kgBB ringer laktat, 5 jam ke-2 30 cc/kgBB RL","I jm pertama 70cc/kgBB ringer laktat, 3 jam ke-2 70 cc/kgBB RL","I jm pertama 30cc/kgBB ringer Iaktat, 5 jam ke-2 70 cc/kgBB RL","Ijam pertama 30cc/kgBB ringer laktat, 3 jam ke-2 70 cc/kgBB RL","h jam pertama 30cc/kgBB ringer laktat, 2 h jam ke-2 70 cc/kgBB RL"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-098","number":98,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 098 · Seorang anak perempun berusia 11 tahun dibawa…","page":223,"stem":"Seorang anak perempun berusia 11 tahun dibawa orang tuanya ke IGD dengan keluhan nyeri kepala dan muntah. Pasien baru saja jatuh dari sepeda I jam yang lalu dan sempat tidak sadarkan diri. Saat ini kesadaran pasien compos mentis dan vital sign dalam batas normal. Keluhan nyeri kepala juga sudah berkurang. Diagnosis yang paling tepat pada pasien tersebut adalah...","options":["Contusio cerebri","Commotio cerebri","Hipoksia cerebri","Cedera kepala sedang","Perdarahan subdural"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-099","number":99,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 099 · Seorang anak perempuan berusia 8 tahun dibawa…","page":224,"stem":"Seorang anak perempuan berusia 8 tahun dibawa ke dokter Oleh ibunya karena mengalami gatal-gatal di lubang dubur pada malam hari. Tidak ada demam. Vital sign dalam batas normal. Pada pemeriksaan apus anal ditemukan telur. Penyebab dari keluhan pasien di atas adalah...","options":["Oxyuris vermicularis","Trichuris trichiura","Trichuris strongyloides","Ancylostoma duodenale","Ascaris lumbricoides"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-100","number":100,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 100 · Seorang anak perempuan berusia usia 3 tahun…","page":224,"stem":"Seorang anak perempuan berusia usia 3 tahun mengeluh nyeri pada paha kiri sejak 2 hari ini. Sebelumnya 4 hari ini anak mengalami batuk dan pilek. Pada pemeriksaan didapatkan bengkak pada paha kiri, nyeri tekan (+), nyeri pada pergerakan, pergerakan terbatas. Terdapat gambaran pembesaran jaringan lunak pada foto ronsen. Penyebab dari kasus di atas adalah.„","options":["Pneumococcus","Streptococcus epidermidis","Clostridium tetanii","Staphylococcus aureus","Haemophilus influenza"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-101","number":101,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 101 · Di sebuah IGD RS, datang secara bersamaan…","page":224,"stem":"Di sebuah IGD RS, datang secara bersamaan 5 pasien kecelakaan lalu lintas. Pasien pertama perempuan usia 17 tahun, dalam keadaan tidak sadar, terdapat Iuka pada lengan kiri, banyak mengeluarkan darah. Pasien kedua Iaki-laki usia 65 tahun, sadar, terdapat Iuka pada paha kanan, sedikit mengeluarkan darah. Pasien ketiga laki-laki usia 32 tahun, sadar, patah pada tungkai kanan. Pasien keempat anak perempuan usia 5 tahun, dalam keadaan sadar, terdapat lebam pada kedua lengan. Pasien kelima perempuan umur 55 tahun, sadar, terkejut saat mengetahui kejadian yang menimpanya. Pasien manakah yang perlu penanganan lebih awal?","options":["Pasien I","Pasien 2","Pasien 3","Pasien 4","Pasien 5"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-102","number":102,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 102 · Seorang anak Iaki-laki berusia I tahun, dibawa…","page":224,"stem":"Seorang anak Iaki-laki berusia I tahun, dibawa orang tuanya ke tempat praktik dokter dengan keluhan utama muntah-muntah. Anak sudah sering muntah sejak I bulan yang lalu. Anak telah beberapa hari susah BAB. Pada pemeriksaan fisik didapatkan, dalam batas normal termasuk berat badan dan tinggi badan normal. Tidak ditemukan tanda- tanda dehidrasi. Diagnosis yang tepat pada kasus tersebut adalah„.","options":["Stenosis pylorus","Atresia duodenal parsial","Hipotiroid","Fistula trakeo-esofagus","Refluk gastro-esofagus"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-103","number":103,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 103 · Seorang pria berusia 35 tahun datang ke…","page":224,"stem":"Seorang pria berusia 35 tahun datang ke IGD karena keluar darah dari saluran kencingnya setelah mengalami kecelakaan sepeda motor. Pada pemeriksaan didapatkan darah keluar dari uretra dan skrotum membesar. Pemeriksaan penunjang apakah yang tepat dilakukan pada pasien ini?","options":["Sistografi","Uretrografi","Uretrosistografi","BNO","USG"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-104","number":104,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 104 · Di suatu daerah banyak terjadi kasus Chikungunya.…","page":225,"stem":"Di suatu daerah banyak terjadi kasus Chikungunya. Sebagai tindak lanjut, dokter puskesmas memberikan edukasi tentang Chikungunya melalui siaran radio setempat. Berperan sebagai apakah dokter puskesmas tersebut?","options":["Manager","Communicator","Care provider","Community leader","Decision maker"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-105","number":105,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 105 · seorang pria berusia 45 tahun mengalami penurunan…","page":225,"stem":"seorang pria berusia 45 tahun mengalami penurunan nafsu makan. Hasil pemeriksaan fisik menunjukkan adanya ikterus dan hepatomegali. Hasil pemeriksaan serologis didapatkan HbsAg (+), HbeAg (-), anti Hbe (+). Interpretasi dari hasil pemeriksaan di atas adalah...","options":["Hepatitis B akut, infektivitas rendah rendah","Hepatitis B akut, infektivitas tinggi","Hepatitis B kronis, infektivitas tinggi","Hepatitis B kronis, infektivitas","Hepatitis B karier"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-106","number":106,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 106 · Seorang perempuan berusia 50 tahun datang ke…","page":225,"stem":"Seorang perempuan berusia 50 tahun datang ke praktek dokter dengan keluhan perut membesar sejak 3 bulan yang lalu. Pada pemeriksaan fisik tampak anemis, tanda vital dalam batas normal, sklera ikterik, hepar teraba keras, permukaan tidak rata dan nyeri tekan. Pada pemeriksaan laboratorium didapatkan HbsAg (+) dan alfa fetoprotein 1000 mg/dl. Diagnosis yang tepat pada kasus di atas adalah...","options":["hepatitis akut","hepatitis kronik","abses hati","sirosis hepatis","hepatoma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-107","number":107,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 107 · Seorang laki-laki berusia 50 tahun datang dengan…","page":225,"stem":"Seorang laki-laki berusia 50 tahun datang dengan keluhan pusing sejak I bulan terakhir ini, pusing tidak disertai dengan mual, rasa berputar, nyeri berdenyut di kedua Sisi kepala. Pusing disertai nyeri tengkuk, namun masih bisa tidur. Tekanan darah pasien 170/100 mmHg. Pemeriksaan fisik lainnya normal. Diet yang paling tepat pada pasien tersebut adalah...","options":["Diet rendah lemak","Diet rendah garam","Diet tinggi serat","Diet tingi protein","Diet tinggi kalsium"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-108","number":108,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 108 · Seorang pria berusia 55 tahun datang ke…","page":225,"stem":"Seorang pria berusia 55 tahun datang ke IGD dengan keluhan nyeri dada sebelah kiri sejak 12 jam yang lalu. Pada pemeriksaan enzim jantung CK-MB meningkat, Troponin T meningkat. Oleh dokter didiagnosa Infark Myokard. Apakah gambaran EKG yang dapat mendukung diagnose?","options":["Ventrikel ekstrasistole","Poor R-Wave progression","STEIevasi","Atrium Fibrilasi","T-lnverted"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-109","number":109,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 109 · Seorang Iaki-laki berusia 58 tahun datang ke…","page":226,"stem":"Seorang Iaki-laki berusia 58 tahun datang ke UGD dengan keluhan buang air besar hitam sejak 6 jam yang lalu. Pada pemeriksaan fisik didapatkan keadaan status gizi sedang, pucat, sklera ikterik dan terdapat bercak kemerahan seperti laba-laba pada dada dan punggung, perut terlihat membuncit dan Udem pada tungkai. Apakah kemungkinan penyebab BAB hitam pada pasien di atas?","options":["Pecahnya varises esophagus duodenum","Perdarahan dari tumor Iambung kolorektal","Perdarahan dari erosi di Iambung","Perdarahan dari tukak di","Perdarahan dari karsinoma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-110","number":110,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 110 · Seorang anak perempuan berusia 5 bulan dibawa…","page":226,"stem":"Seorang anak perempuan berusia 5 bulan dibawa ke rumah sakit dengan anemia gravis,pucat,ubun-ubun lebar,lien hepar membesar.Dilakukan pemeriksaan GDT dan didapatkanhasil:eritrosit ukuransama dengan inti limfositkecil,daerahpucat< diameter eritrobasophilic stipling, target cell, ear drop dan howel jelly bodies. Penyebab anemia dari kasusdiatasadalah...","options":["Thalasemia","Defisiensi Fe-hipokrom mikrositer","Anemia hemolitik","Defisiensifolat-makrositer","DefisiensiB12-makrositer"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-111","number":111,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 111 · Wanita 40 tahun mengeluh benjolanpada leherbagian depan…","page":226,"stem":"Wanita 40 tahun mengeluh benjolanpada leherbagian depan sejak2 minggu ini.Keluhan disertai berdebar-debar,berkeringat,sulit tidur,beratbadan turun,sering mosi,dan tidak tahan dingin.Pemeriksaan fisik:TD:130/70 mmhg,N:110x/menit irreguler,T:36,8 OC, RR: 25x/menit, ekxoltalmus +/+. Apa kemungkinan diagnosa yang paling tepat pada kasus di atas?","options":["Goiter","Hipotiroid Tirotoksikosis","Tirotoksikosis","Hipotiroid simtomatik","Hipertiroid non simtomatik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-112","number":112,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 112 · Pasien perempuan usia 9 tahun datang dengan…","page":226,"stem":"Pasien perempuan usia 9 tahun datang dengan keluhan gatal pada tangan dan tubuhnya terutama saat malam hari. Kakak pasien juga menderita gatal yang sama dengan pasien. Dari pemeriksaan fisik didapatkan papul, pustule, disertai bekas garukan terutama pada punggung jari-jari tangan. Apa diagnosisnya?","options":["Dermatitis atopi","Scabies","Dermatitis alergika","Tinea corporis","Psoriasis vulgaris"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-113","number":113,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 113 · Seorang wanita 34 tahun mengeluhkan nyeri dada…","page":227,"stem":"Seorang wanita 34 tahun mengeluhkan nyeri dada sejak 2 bulan yang lalu, berat badan dirasa menurun dan tidak menstruasi sejak 5 bulan yang lalu. Dari hasil PF di dapatkan TD .. 170/80 mmHg, Nadi irama tidak teratur, cepat, dan volume berubah-ubah, Detak jantung tidak teratur. Pada tungkai di dapatkan edema pretibial +. Dari hasil pemeriksaan laboratorium didapatkan Glukosa sewaktu 160 mg/dl, glikosa puasa 90 mg/dl dan tes kehamilan negatif. Diagnosis pasien ini","options":["Penyakit Jantung Koroner","Keganasan Ginekologi","Diabetes Melitus","Penyakit Grave","Neurosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-114","number":114,"package":"Paket Prediksi","topic":"Mata","title":"Soal 114 · Seorang wanita berusia 30 tahun datang ke…","page":227,"stem":"Seorang wanita berusia 30 tahun datang ke dokter dengan keluhan mata gatal, merah dan terdapat secret seperti susu sejak 3 hari yang lalu. Pada pemeriksaan slit lamp ditemukan papilla pada konjungtiva tarsal superior dan inferior. Pasien mengaku dalam keluarganya mempunyai riwayat penyakit dermatitis atopic dan asma bronchial. Diagnosis pada pasien ini","options":["Acute conjungtivitis","Atopic conjungtivitis","Flictenularis conjungtivitis","Vernal conjungtivitis","Follicle conjungtivitis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-115","number":115,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 115 · Laki-laki 28 tahun dibawa ke UGD karena…","page":227,"stem":"Laki-laki 28 tahun dibawa ke UGD karena penurunan kesadaran sejak 3 jam yang lalu. Sebelumnya pasien mengalami benturan di kepala 2 hari yang lalu karena kecelakaan lalu lintas. Pada CT Scan didapatkan gambaran hiperdens berbentuk bulan sabit. Apakah perdarahan yang dimaksud?","options":["Epidural hematoma","Intracranial hematoma","Subdural hematoma","Subarachnoid hematoma","Lobar hematoma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-116","number":116,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 116 · Seorang laki-laki berusia 52 tahun datang ke…","page":227,"stem":"Seorang laki-laki berusia 52 tahun datang ke UGD RS dengan keluhan nyeri dada bila beraktivitas agak berat. Pemeriksaan fisik TB 165 cm, BB 72 kg, tekanan darah 150/90 mmHg, frekuensi nafas 24 x/menit, lingkar pinggang 95 cm. Pemeriksaan laboratorium koleterol total 240 mg/dL, LDL 175 mg/dL, HDL 30 mg/dL, Trigliserida 170 mg/dL, gula darah puasa 1 IO mg/dL, gula darah 2 jam post prandial 135 mg/dL Apakah pemeriksaan yang harus dilakukan?","options":["Fungsi hati Pemeriksaan epidemiologi","Fungsi ginjal Pemeriksaan HbAIC setelah konsumsi makanan pada acara kelulusan. Makanan tersebut didapat dari catering yg sama. Tindakan yang harus diambil sebagai dokter Puskesmas adalah... Pengambilan sampel makanan","Mengeluarkan surat WI","Pemeriksaan CK-CKMB Menetapkan kondisi KLB","Tes toleransi glukosa oral Identifikasi etiologi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-117","number":117,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 117 · Siswa sebuah TK dibawa ke PKM dengan…","page":228,"stem":"Siswa sebuah TK dibawa ke PKM dengan keluhan muntah-muntah, mual, badan lemas setelah konsumsi makanan pada acara kelulusan. Makanan tersebut didapat dari catering yg sama. Tindakan yang harus diambil sebagai dokter Puskesmas adalah...","options":["Pemeriksaan epidemiologi","Pengambilan sampel makanan","Mengeluarkan surat WI","Menetapkan kondisi KLB","Identifikasi etiologi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-118","number":118,"package":"Paket Prediksi","topic":"THT","title":"Soal 118 · Seorang anak Iaki-laki berusia 4 tahun diantar…","page":228,"stem":"Seorang anak Iaki-laki berusia 4 tahun diantar orang tuanya ke dokter umum dengan keluhan demam selama 3 hari. Pada vital sign suhu 38,50C, ditemukan ruam difus popular eritematosa, pucat didaerah mulut, dan lidah dikelilingi papilar yang bengkak dan kemerahan. Ditemukan tonsilitis folikular. Pada kasus di atas manajemen yang paling tepat","options":["Perawatan IO hari dengan sulfenamida","Pemberian penisiline selama IO hari rumah","Pemberian hiperimunoglobulin","Rawat inap dan isolasi","Symptomatic treatment di"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-119","number":119,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 119 · Seorang laki - laki berusia 16 tahun…","page":228,"stem":"Seorang laki - laki berusia 16 tahun datang ke dokter dengan keluhan pucat. Riwayat di keluarga dengan keluhan yang sama disangkal. Anak tampak anemia, ikterik sebagian. Pada pemeriksaan didapatkan Hepar teraba 3 cm dibawah arcus costae dan 3 cm dibawah proseccus xyphoideus. Limpa: scuffner III dan tidak ditemukan limfadenopati. Hasil lab ditemukan : Hb 5,6, leukosit 7.100, Ht 15,7, trombosit 185.000, MCV 53%. Gambaran morfologi : eritrosit mikrositik, polikrom, hipokrom, anisopoikilositosis ringan. Apakah pemeriksaan yang tepat untuk menegakkan diagnosis tersebut?","options":["Pemeriksaan sumsum tulang","COMB test","Hb elektroforesis","Pemeriksaan darah lengkap","Pemeriksaan G6PD"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-120","number":120,"package":"Paket Prediksi","topic":"Anak","title":"Soal 120 · Seorang bayi perempuan usia 8jam, Jahir pada…","page":228,"stem":"Seorang bayi perempuan usia 8jam, Jahir pada usia kehamilan 32 minggu akibat trauma. Bayi lahir ditolong bidan dengan BBL=1400 gram. Pada pemeriksaan fisik ditemukan nadi 152x/mnt, RR 72x/mnt, suhu axilla 36,50C. Pemeriksaan gula darah sewaktu didapatkan 36 gr%. Saat ini pasien diletakkan di inkubator, dipasang oksigen, dan sudah diinfus cairan Dextrose 10% sesuai kebutuhan sehari-hari. Apa tindakan tambahan yang diperlukan untuk bayi tersebut?","options":["2 ml cairan Dextrose 10% bolus","2 ml cairan Dextrose 12,5% bolus bolus","2 ml cairan Dextrose 40% bolus","3 ml cairan Dextrose 1096 bolus","3 ml cairan Dextrose 12,596"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-121","number":121,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 121 · Seorang perempuan berusia 38 tahun, datang ke…","page":228,"stem":"Seorang perempuan berusia 38 tahun, datang ke IGD RS dengan keluhan kejang 2 jam yang lalu selama 5 menit. Pasien sedang hamil anak ke-2 dengan usia kehamilan 38 minggU. Pasien mengaku sering pusing dan penglihatan kabur selama 2 hari terakhir. ada riwayat hipertensi pada kehamilan sebelumnya dan tidak ada riwayat hipertensi pada awai kehamilan. Pada pemeriksaan:TD 180/110 mmhg, denyut nadi 120 x/menit, frekuensi pernapasan 28 x/menit, edema peritebia +/+. Diagnosis yang mungkin untuk","options":["Preeklampsi ringan","Preeklampsi berat","Eklampsi","Hipertensi berat","Krisis hipertensi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-122","number":122,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 122 · pasien perempuan berusia 65 tahun dibawa keluarganya…","page":229,"stem":"pasien perempuan berusia 65 tahun dibawa keluarganya ke IGD dengan penurunan kesadaran. Dari anamnesis, diketahui pasien ternyata seorang penderita Diabetes Melitus yang sudah diketahuinya selama IO tahun. Selama 3 bulan kebelakang, pasien rutin meminUm OHO. Dari pemeriksaan didapatkan GDS 575 g/dl dan pH darah 6,5. Apakah diagnosis dari kasus tersebut?","options":["Ketoasidosis Diabetikum","Asidosis Metabolik","Hiperosmolar Non Ketotik","Hiperglikemik","Hipoglikemik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-123","number":123,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 123 · Seorang perempuan berusia 22 tahun POAo datang…","page":229,"stem":"Seorang perempuan berusia 22 tahun POAo datang ke tempat praktek dokter dengan keluhan benjolan pada kemaluan sejak beberapa bulan terakhir. Riwayat keputihan (+). Dari hasil pemeriksaan tanda vital tekanan darah 120/80 mmHg, frekuensi nadi 76x/menit, frekuensi nafas 20x/menit dan suhu 36,9 oc. Pada pemeriksaan didapatkan benjolan di labia mayora arah jam 5 ukuran 5x6 cm, kistik, tanpa tanda radang dan mobile. Diagnosis pada pasien ini adalah...","options":["Kista bartolini","Kista gartner","Kista ovarium","Endometriosis","Mioma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-124","number":124,"package":"Paket Prediksi","topic":"THT","title":"Soal 124 · Seorang perempuan berusia 34 tahun datang ke…","page":229,"stem":"Seorang perempuan berusia 34 tahun datang ke poli THT dengan keluhan sering pusing berputar. Keluhan ini biasanya disertai dengan telinga berdengung dan pendengeran menjadi terganggu. Hal ini membuat pasien menjadi tidak bisa tidur dan sering mual muntah. Diagnosis yang tepat adalah...","options":["BPPV","Vertigo perifer","Vertigo central","Labirinitis","Meniere syndrome"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-125","number":125,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 125 · Seorang perempuan berusia 55 tahun datang ke…","page":229,"stem":"Seorang perempuan berusia 55 tahun datang ke IGD dengan keluhan sesak nafas dan batuk disertai lendir berwarna merah muda sejak 2 hari yang lalu. Riwayat pasien menggunakan captopril sejak 2 tahun yang lalu. Sekarang tekanan darah 100/60 mmHg, setelah diperiksa dokter mendignosis gagal ginjal, gagal jantung fase akut, dan oedem paru, sehingga dokter menghentikan penggunaan captopril. Alasan dari penghentian captopril adalah...","options":["Pasien dengan batuk produktif","Pasien yang mendapat diuretik kuat","Pasien dengan gagal jantvnp fase akut","Pasien dengan tekanan datah systole 90-100 mmHg","Pasien dengan gaga! ginial"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-126","number":126,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 126 · Seorang laki-!aki berusia 45 tahun. menderit2 Iuka…","page":230,"stem":"Seorang laki-!aki berusia 45 tahun. menderit2 Iuka di punggung kaki kanannya, Iuka bengka\\€ bau dan bernanah. Pasien memiliki riwayat DM sejak tahun yang lalu dan tidak rutin berobat. Pada pemeriksaan laboratorium didzpatkan Hb = ; 3 Leukosit = 21.000, GDS = 436. Pada rontgen didapatkan gambaran pembeatukan gas dan destruksi tulang. Diagnosis yang tepat pada pasien tersebut adalah—","options":["DM + ulkus pedis dekstra","DM + osteomyelitis","DM + gangren pedis dekstra","+ myositis pedis dekstra","DM + abses pedis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-127","number":127,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 127 · Seorang laki-laki betusia 40 tahun, datang dengan…","page":230,"stem":"Seorang laki-laki betusia 40 tahun, datang dengan keluhan (idah kaku, dan air liur menetes terus. Pasien ada riwayat gangguan jiwa sejak 2 Bulan yang 'alu dan rutin minum obat Haloperidol. Terapi tambahan yang perlu untuk pasien inia dalah:","options":["Amitriptilin","Lorazepam","Trihexyfenidil","Phenobarbital","Metildopa"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-128","number":128,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 128 · Seorang anak laki-laki berusia S tahun dibawa…","page":230,"stem":"Seorang anak laki-laki berusia S tahun dibawa ibunya ke Puskesmas dengan keluhan sulit BAK sejak 1 hari yang lalu. Keluhan tidak disertai dengan demam. Pada pemeriksaan fisik tampak preputium menutupi dan melekat pada glans penis hingga orifisium uretra eksterna. Diagnosis pada anak ini","options":["Hipospadia","Epispadia","Hidrokel","Fimosis","Parafimosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-129","number":129,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 129 · Seorang perempuan berusia 25 tahun POAO datang…","page":230,"stem":"Seorang perempuan berusia 25 tahun POAO datang ke tempat praktek dokter dengan keluhan benjolan pada kemaluan sejak beberapa bulan terakhir. Riwayat keputihan (+). Dari hasil pemeriksaan tanda vital tekanan darah 120iSO mmHg, frekuensi nadi 76 x/menit, frekuensi nafas 20x/menit dan suhu 36.9 Pada pemeriksaan didapatkan benjolan di labia mayora arahjam 5 ukuran 5x6 cm, kistik. tanpa tanda radang dan mobile. Diagnosis pada pasien ini adalatu","options":["Endometriosis","Mioma","Kista ovarium","Kista bartolini","Kista gartner"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-130","number":130,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 130 · Pasien perempuan, 35 tahun, keluhan nyeri dan…","page":230,"stem":"Pasien perempuan, 35 tahun, keluhan nyeri dan kaku sendi pada kedua tangannya, pagi hari, dirasakan 30 menit lebih. Pemeriksaan rematoid factor (+), dokter mendiagnosis artritis rematoid. Apa terapi yang harus segera diberikan pada pasien tersebut?","options":["NSAID","DMARDS","Steroid","Kalium","Fizioterapi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-131","number":131,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 131 · seorang bayi perempuan berusia 6 bulan dibawa…","page":231,"stem":"seorang bayi perempuan berusia 6 bulan dibawa berobat Oleh ibunya dengan keluhan bruntus-bruntus kemerahan dikedua pipi dan tampak gatal. Tidak ada riwayat kentak dengan bahan-bahan tertentu sebelum timbulnya keluhan kulit. Ayahnya menderita urtikaria dan kakak menderita asma. Status dermatologis distribusi lesi bilateral asimetris pada kedua pipi tampak lesi multiple sebagian berkonfluens berukuran sampai dengan 4x4xO,1 berbatas tegas. Sebagian besar berupa macula eritem, papula eritem, plak eritem squama dan erosi. Diagnosis apakah yang paling tepat?","options":["Dermatitis numularis","Dermatitis atopik","Dermatitis statis","Dermatitis kontak alergik","Dermatitis venenata"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-132","number":132,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 132 · Seorang wanita berusia 40 tahun datang dengan…","page":231,"stem":"Seorang wanita berusia 40 tahun datang dengan keluhan timbul benjolan dipayudara kanan sejak I th yang lalu. Tidak ada nyeri. Pada pemeriksaan fisik terdapat massa tidak berbatas tegas dan padat. Hasil biopsi PA terdapat kelenjar payudara yang dikelilingi sebukan padat, limfosit, sel epielioid dan sel datia langhans. Diagnosis yang tepat pada kasus di atas adalah...","options":["mastitis akut","mastitis kronik non spesifik","mastitis kronik eksaserbasi akut","mastitis jamur","mastitis e.cjamur"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-133","number":133,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 133 · Seorang anak Iaki-laki berusia 1 tahun dibawa…","page":231,"stem":"Seorang anak Iaki-laki berusia 1 tahun dibawa Oleh ibunya ke dokter karena sesak nafas, pasien sesak sejak 2 hari yang lalu, sebelumnya pasien batuk dan pilek sejak 5 hari yang lalu. Pada pemeriksaan fisik didapatkan pasien sesak, dengan retraksi interkostal dan subkosta, sianosis, didapatkan rhonki dan wheezing. Diagnosis yang tepat pada pasien tersebut adalahm","options":["TB paru","ISPA","Bronkitis","Asma bronkiale","Bronkiolitis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-134","number":134,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 134 · Seorang perempuan berusia 30 tahun diantar polisi…","page":231,"stem":"Seorang perempuan berusia 30 tahun diantar polisi ke IGD RS karena kecelakaan lalu lintas. Pada pemeriksaan fisik didapatkan trauma kepala dan patah tulang terbuka femur kiri dan kanan dan perdarahan masif, tekanan darah tidak dapat diukur, nadi tidak dapat diraba, napas gasping, akral dingin, pucat dan basah. Pemeriksaan apa yang paling tepat untuk menentukan bahwa pasien dalam kondisi henti jantung?","options":["Tidak bernapas","Tidak sadar","Tidak teraba denyut arteri di leher","Tidak teraba denyut arteri di pergelangan tangan","Tidak ada reaksi dengan rangsangan nyeri"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-135","number":135,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 135 · Seorang wanita berusia 28 tahun datang ke…","page":232,"stem":"Seorang wanita berusia 28 tahun datang ke praktek dokter kandungan dengan keluhan keputihan berwarna kuning kehijauan dan berbau yang disertai dengan demam sejak 1 minggu yang lalu. Pada pemeriksaan ginekologis didapatkan nyeri goyang serviks dan nyeri perut di kuadran kanan bawah. Diagnosis yang paling tepat pada pasien ini","options":["KET","Ruptur tuba","Pelvic Inflammatory Disease","Endometriosis","Appendisitis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-136","number":136,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 136 · Seorang pasien pria berusia 45 tahun datang…","page":232,"stem":"Seorang pasien pria berusia 45 tahun datang dengan keluhan batuk 3 minggu, batuk kental putih, demam tidak terlalu tinggi terutama malam hari, keringat banyak pada malam hari, penurunan berat badan, nafsu makan baik. IMT 17, I. Pasien bekerja sebagai satpam dan setiap hari merokok satu pak. Pemeriksaan fisik paru suara dasar bronkial, ronki basah pada kedua lapang paru. Kemungkinan apa yang paling meningkat pada pemeriksaan darah?","options":["Neutrofil","Eosinofil","Kadar procalcitonin","Laju endap darah","Leukosit"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-137","number":137,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 137 · Seorang Iaki-laki berusia 25 tahun mengeluh gatal…","page":232,"stem":"Seorang Iaki-laki berusia 25 tahun mengeluh gatal di kemaluan dan sekitarnya , bertambah gatal jika berkeringat, keluhan dirasakan sejak 3 hari yang lalu. Pasien memakai salep hidrokortison namun makin meluas sampai paha. Pada pemeriksaan ditemukan makula eritematosa berbatas tegas tepi lebih aktif, kerokan kulit ditemukan hifa panjang. Etiologi dari kasus di atas adalah.„","options":["Epidermophyton foloccocus","Malassezia furfur","Candida albicans","Sporothrix scheneckii","Exophiala werneckii"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-138","number":138,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 138 · Seorang wanita berusia 27 tahun datang dengan…","page":232,"stem":"Seorang wanita berusia 27 tahun datang dengan keluhan nyeri ulu hati sejak 2 bulan yang lalu, keluhan munculnya hilang timbul, dan kadang disertai dengan mual dan muntah, dan pasien mengaku sering mengkonsumsi makanan pedas dan soft drink. Pada pemeriksaan fisik didapatkan nyeri tekan epigastrik ringan, Diagnosis yang paling tepat dari kasus di atas menurut criteria Romme III","options":["GERD","Dispepsia","Epigastric pain syndrome","Tukak peptik","Tumor Iambung"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-139","number":139,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 139 · Seorang wanita umur 48 tahun datang ke…","page":232,"stem":"Seorang wanita umur 48 tahun datang ke puskesmas dengan keluhan sering kencing sejak 2 bulan yang lalu. Keluhan disertai rasa haus dan penurunan berat badan. Pada pemeriksaan tanda- tanda vital semua dalam batas normal. Pada pemeriksaan lab didapat KGDS 360, kolestrol total 240. Keluhan utama yang timbul pada pasien ini disebabkan oleh?","options":["Polidipsi","Dislipidemia","Lipolisis","Hiperglikemi","Proteolisis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-140","number":140,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 140 · seorang pasien laki-laki 65 tahun diantar keluarganya…","page":233,"stem":"seorang pasien laki-laki 65 tahun diantar keluarganya ke UGD RSUMM karena sesak. Terdapat riwayat batuk lama dan batuk disertai darah. Pemeriksaan fisik didapatkan takipneu. Gerak dada kiri tertinggal. Pada asukultasi paru kiri menurun. Pada perkusi hipersonor di hemithorax sinistra. Pada foto rontgen thorax gambaran hiperlusen avaskuler pada thorax sinistra. Kemungkinan diagnosis?","options":["Empysema pulmonal","Pneumothorax","Hematothorax","TB","Hematokele"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-141","number":141,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 141 · pasien perempuan, 39 tahun, keluhan batuk 3…","page":233,"stem":"pasien perempuan, 39 tahun, keluhan batuk 3 minggu, batuk kental putih, demam tidak terlalu tinggi terutama malam hari, keringat banyak pada malam hari, penurunan berat badan, nafsu makan baik. RPD: ± 3 tahun yang lalu pernah didiagnosis TB, tetapi pasien hanya meminum obat selama 3 bulan karena sudah merasa bosan. PF paru suara dasar bronkial, ronki basah pada kedua lapang paru. Px BTA (+). Termasuk kasus apa pasien tersebut?","options":["Kasus baru","Kasus putus obat","Kasus gagal pengobatan","Kasus kambuh","Kasus resistensi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-142","number":142,"package":"Paket Prediksi","topic":"THT","title":"Soal 142 · Pasien dengan keluhan pusing berputar dan terdapat…","page":233,"stem":"Pasien dengan keluhan pusing berputar dan terdapat gangguan pendengaran, serta bunyi berdenging pada telinga kanan. Hasil pemeriksaan garpu tala didapatkan rinne kanan (-), swabach kanan memanjang, tes weber lateralisasi ke kanan. Termasuk dalam gangguan pendengaran apa?","options":["Tuli konduksi telinga kanan","Tuli persepsi telinga kanan","Tuli konduksi telinga kiri","Tuli persepsi telinga kiri","Tidak terdapat kelainan"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-143","number":143,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 143 · pasien laki-laki umur 25 tahun datang ke…","page":233,"stem":"pasien laki-laki umur 25 tahun datang ke IGD karena kecelakaan lalu lintas, pasien mengalami robekan hepar danperlu dioperasi emergency, dan membutuhkan tranfusi, dan ternyata darah pasien mengumpalkan anti-A dan anti-B Apa golongan darah pasien?","options":["A","B","AB","Rhesus positif","Rhesus negatif"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-144","number":144,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 144 · Seorang anak perempuan berusia 2 tahun dirawat…","page":234,"stem":"Seorang anak perempuan berusia 2 tahun dirawat di RS karena panas 4 hari, tetapi hari ini sudah tidak panas, tetapi anak masih tidak aktif bergerak, dan muntah-muntah. Pada pemeriksaan fisik kesadaran apatis, tidak sianosis, Suhu 37,40C, Leukosit 1500, Trombosit 60.000, BAK 3 jam yang lalu. Apa yang perlu dievaluasi setiap hari pada pasien ini?","options":["Diuresis dan suhu","Suhu dan nadi","Turgor dan frekuensi muntah","Nadi dan diuresis","RR dan suhu"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-145","number":145,"package":"Paket Prediksi","topic":"Anak","title":"Soal 145 · Seorang anak berusia 6 bulan, dibawa ke…","page":234,"stem":"Seorang anak berusia 6 bulan, dibawa ke IGD dengan keluhan muntah warna hijau sejak I hari yang lalu disertai perut kembung, tidak bisa BAB dan buang angin. Pasien menjadi rewel dan menangis terus. BB 8 kg, terdapat tanda ileus mekanik Ietak tinggi dan kehilangan cairan tubuh sebanyak 10%. Berapa jumalah tetesan mikro yang diberikan dalam 24 jam pertama?","options":["18 tetes","24 tetes","26 tetes","28 tetes","30 tetes"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-146","number":146,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 146 · Seorang laki-laki berusia 30 tahun datang ke…","page":234,"stem":"Seorang laki-laki berusia 30 tahun datang ke IGD RS dengan keluhan sesak napas. Pasien mengaku bila tidur memakai 2-3 bantal supaya tidak sesak, pasien jg suka terbangun malam hari karena batuk dan sesak, keluhan ini sejak 3 minggu yg lalu. Tekanan darah 180/120 mmHg, RR: 30x/menit, Nadi: 130x/menit. Auskultasi: terdapat gallop dan ronkhi basah halus di kedua basal paru. Ekstremitas bawah edema. JVP 5+2 H20. Terapi apakah yang pertama kita berikan?","options":["Captopril","Spironolactone","Verapamil","Digoksin","Hidroclorotiazid"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-147","number":147,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 147 · Seorang wanita berusia 24 tahun G2P1 AO…","page":234,"stem":"Seorang wanita berusia 24 tahun G2P1 AO datang ketempat praktik dokter dengan keluhan keluar darah dari kemaluan. Perdarahan keluar sedikit-sedikit disertai nyeri perut. Pada pemeriksaan fisik didapatkan tekanan darah 110/70 mmHg, nadi 84 x/menit, frekuensi nafas 20x/menit, suhu 36 oc, janin diluar vulva sebagian plasenta masih didalam, dan Hb 1 0,4 g/dl. Diagnosis pada pasien ini adalah...","options":["Abortus insipiens","Abortus inkomplit","Abortus imminens","Abortus komplit","Rekuren abortus"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-148","number":148,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 148 · Seorang pria berusia 27 tahun datang ke…","page":234,"stem":"Seorang pria berusia 27 tahun datang ke poli umum dengan keluhan demam. Pasienjuga merasakan jantungnya berdebar-debar. Sebelumnya I bulan yang lalu pasien pernah mengalami infeksi tenggorokan. Pemeriksaan fisik didapatkan tekanan darah 120/80 mmHg, nadi IOOx/menit, RR 16x/menit, Suhu 380 C. Dari pemeriksaan fisik jantung 3 jari mid clavicula dekstra, auskultasi didapat suara gallop. Bakteri yang mungkin dapat menyebabkan kasus di atas adalah...","options":["Pseudomonas aeuruginosa","Haemofilus influenzae Stapilokokus","wanita berusia 55 tahun dibawa ke IGD dengan keluhan badan lemas,keluar","Streptokokus hemolitikus","Streptokokus viridans"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-149","number":149,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 149 · seorang wanita berusia 55 tahun dibawa ke…","page":235,"stem":"seorang wanita berusia 55 tahun dibawa ke IGD dengan keluhan badan lemas,keluar keringat dingin sejak 8 jam lalu. Riwayat hipertensi sejak 10 tahun yang lalu. Vital sign tekanan darah 90/50 mmHg, nadi 100x/menit, RR 30x/menit. Gambaran EKG terdapat Q patologis. GDS 180mg/dl. Pemeriksaan penunjang yang diperlukan adalah...","options":["ureum","kreatinin","kolesterol","asam urat","troponin T"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-150","number":150,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 150 · Seorang perempuan berusia 20 tahun, datang ke…","page":235,"stem":"Seorang perempuan berusia 20 tahun, datang ke IGD dengan keluhan sesak napas sejak 3 jam yang lalu. 3 hari sebelumnya kaki tidak bisa digerakkan, lalu diikuti tangan kesemutan dan kebas. Pasien terkena ISPA 2 minggu yang lalu. Penyebab keluhan pasien di atas adalah...","options":["Infeksi meningen","Infeksi intracranial","Lesi medulla spinalis","Lesi vaskuler hemisfer serebri","Lesi radix anterior dan posterior"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-151","number":151,"package":"Paket Prediksi","topic":"Mata","title":"Soal 151 · Seorang pasien datang dengan keluhan mata gatal,…","page":235,"stem":"Seorang pasien datang dengan keluhan mata gatal, mata seperti berpasir, silau, dan penglihatan kabur. Terdapat sekresi mukus yang berlebihan, sukar menggerakan kelopak mata, mata tampak kering. Pemeriksaan fisik konjungtiva bulbi edema, hiperemik menebal, dan kusam. Diagnosis yang paling mungkin adalah...","options":["Konjungtivitis vernal","Konjungtivits katharalis","Konjungtivitis sicca","Konjungtivitis bakteri","Konjungtivitis fliketenularis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-152","number":152,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 152 · Seorang wanita berusia 50 tahun datang ke…","page":235,"stem":"Seorang wanita berusia 50 tahun datang ke praktek DU dengan keluhan sakit kepala hebat disertai mual muntah, pasien memiliki riwayat Hipertensi I O tahun yang lalu tetapijarang kontrol. Pemeriksaan fisik didapatkan kesadaran delirium, tekanan darah 200/120 mmHg, nadi 100 x/menit, suhu 36,80 C. Pada pemeriksaan oftalmoskop didapatkan perdarahan dan papil edem. Diagnosis pada kasus di atas adalah...","options":["HT grade I","HTgrade II","HT grade Ill","HT emergency","HTurgency"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-153","number":153,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 153 · Seorang pasien Iaki-laki berusia 35 tahun datang…","page":236,"stem":"Seorang pasien Iaki-laki berusia 35 tahun datang ke IGD dengan keluhan berdebar-debar dan lemas sejak3 hari yang lalu. Pasien mengeluh badan terasa lernas dan pada saat mandi terasa ingin pingsan selama I menit. Pemeriksaan fisik, tekanan darah 110/70mmHg, nadi 75x/menit, RR 20x/menit. Tidak ada ronki dan wheezing, pada jantung tidak diternukan pembesaran dan suara tambahan. Dari hasil EKG atrium fibrilasi dengan frekuansi 150. Pada pemeriksaan laboraturium K: dan Na: 144. Oleh dokter diberikan terapi acetosal 100mg. Fungsi acetosal pada kasus tesebut adalah...","options":["Mencegah trombus di otak","Mencegah perdarahan otak","Mencegah jantung koroner","Mencegah perdarahan pada arteri ekstremitas","Mencegah terjadinya aterosklerosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-154","number":154,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 154 · Seorang anak laki-laki berusia 5 tahun datang…","page":236,"stem":"Seorang anak laki-laki berusia 5 tahun datang diantar Oleh ibunya dengan keluhan berat badan anak tersebut tidak naik, saat ini BB 15 Kg. Ibu pasien mengaku ayah pasien sedang menjalani pengobatan TB sejak 2 bulan lalu. Apa pemeriksaan yang diusulkan untuk menegakkan diagnosis pada anak tersebut?","options":["Pemeriksaan darah","Foto rontgen thorax","Tes mantoux","Pewarnaan BTA","Pemeriksaan status gizi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-155","number":155,"package":"Paket Prediksi","topic":"THT","title":"Soal 155 · Seorang Jaki-Jaki datang ke klinik dengan keluhan…","page":236,"stem":"Seorang Jaki-Jaki datang ke klinik dengan keluhan gatal pada telinga kanan sudah 3 hari, diserta keluar sekret berwarna putih keabuan sedikit. Pada pemeriksaan telinga didapatkan membran timpani utuh, tidak ada nyeri/benjolan. Diagnosis yang tepat","options":["Otomikosis","Otosklerosis","Otitis eksterna furunkulosa","Otitis eksterna difus","Otitis eksterna maligna"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-156","number":156,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 156 · Seorang wanita berusia 50 tahun dibawa ke…","page":236,"stem":"Seorang wanita berusia 50 tahun dibawa ke IGD dengan keluhan nyeri dada kiri sejak I jam yang lalu, diberikan obat di bawah Iidah Oleh dokter, tetapi tidak berkurang nyerinya. Nyeri seperti tertusuk hingga tembus ke belakang lamanya lebih 20 menit. EKG menurun ST 3mm, T inverse di lead 11,111, AVF. Diagnosis pada pasien ini adalah„.","options":["Kardiomiopati","NSTEMI","STEMI","Angina pektoris stabil","Angina pektoris tidak stabil"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-157","number":157,"package":"Paket Prediksi","topic":"Mata","title":"Soal 157 · Seorang anak Jaki-Jaki usia 6 tahun dibawa…","page":236,"stem":"Seorang anak Jaki-Jaki usia 6 tahun dibawa ibunya karena kedua mata sering merah, terutama saat musim semi. Mata merah disertai gatal. Pasien mempunyai riwayat asma. Pada pemeriksaan oftalmologi didapatkan palpebra superior kedua mata edem, sekret mukoid, konjungtiva palpebra terdapat hipertrofi papil berbentuk cobblestone. Kornea tampak shield ulcer. Obat yang tepat pada pasien di atas adalah...","options":["Mast cell stabilizer","Artificial tear topikal","NSAID topikal","Antibiotik topikal","Steroid topikal"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-158","number":158,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 158 · Seorang pasien laki-laki datang ke IGD RS…","page":237,"stem":"Seorang pasien laki-laki datang ke IGD RS dengan keluhan nyeri dada kiritembus kebelakang menjalar kelengan dan tangan kiri. Nyeri berlangsung selama 5 menit dan timbul saat aktifitas serta menghilang jika dipakai istirahat. Pada pemeriksaan EKG normal. Diagnosis yang paling tepat adalah...","options":["Angina pectoris stabil","Angina Pectoris tidak stabil","STEMI","NSTEMI","Pericarditis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-159","number":159,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 159 · Seorang pasien berusia 30 tahun datang ke…","page":237,"stem":"Seorang pasien berusia 30 tahun datang ke Puskesmas dengan keluhan mual, muntah. Dari anamnesis didapatkan bahwa pasien menjalani pengobatan TB sudah berjalan 2 minggu. Pada pemeriksaan fisik vital sign normal, sklera ikterik, tidak ada pembesaran hepar. pemeriksaan laboratorium didapatkan bilirubin direk 5,7 mg/dl, bilirubin total 7,4 mg/dl. SCOT 48780, SGPT 680. Penatalaksanaan yang tepat pada pasien tersebut adalah.„","options":["Beri obat hepatoprotektor","Beri obat anti emetik","stop OAT","GantiOAT","Beri asam amino rantai pendek"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-160","number":160,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 160 · Seorang laki-laki berusia 55 tahun datang ke…","page":237,"stem":"Seorang laki-laki berusia 55 tahun datang ke IGD RS akibat diare lebih dari 20 kali, disertai muntah dan demam. Tidak bisa BAK sejak 1 hari ini. Pemeriksaan fisik didapatkan tekanan darah 90/50 mmHg, nadi 126 x/menit, RR: 30 x/menit, Suhu: 38 OC. Mata cekung, bibir dan mukosa kering, abdomen supel, bising usus meningkat, turgor turun, akral dingin. Diagnosis yang tepat pada pasien tersebut adalah...","options":["Syok hipovolemik","Syok distributive","Syok septik","Syok kardiogenik","Syok neurogenik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-161","number":161,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 161 · Seorang perempuan berusia 35 tahun datang ke…","page":237,"stem":"Seorang perempuan berusia 35 tahun datang ke tempat praktek dengan keluhan lemas terus menerus sejak 3 bulan terakhir. Setiap hari tampak murung dan tidak bisa tagi merencanakan menu makanan seperti biasa dengan baik. Dia memaksakan diri melakukan aktivitas seperti biasa, tetapi merasa semakin tidak mampu. Sebulan terakhir dia kehilangan minat bertemu dengan tetangganya, tidak mau pergi pengajian. Pasien menikah sudah 6 tahun, namun belum mempunyai keturunan. la merasa tidak berguna dan tidak bahagia seperti yang lain. Pasien kehilangan berat badan >5 kg. Pemeriksaan fisik dan laboratorium dalam batas normal. Terapi yang paling tepat diberikan pada pasien adalah„.","options":["Olanzapine I x 20 mg","Flouxetine I x 5 mg","Risperidone 2 x 2 mg","Sertralin I x 20 mg","Larozapine 1 x 1 mg"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-162","number":162,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 162 · Seorang bayi perempuan berusia 6 bulan dibawa…","page":238,"stem":"Seorang bayi perempuan berusia 6 bulan dibawa ke RS karena kejang I jam yang lalu. 24 jam sebelumnya pasien juga kejang. Di antara kejang pasien sadar. 2 hari sebelumnya pasien demam tinggi. Obat yang tepat untuk mencegah kejang adalah„.","options":["Fenobarbital","Carbamazepin","Asam valproat","Diazepam","Fenitoin"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-163","number":163,"package":"Paket Prediksi","topic":"Obstetri & Ginekologi","title":"Soal 163 · Seorang wanita hamil 38-40 minggu mengeluh kenceng-kenceng…","page":238,"stem":"Seorang wanita hamil 38-40 minggu mengeluh kenceng-kenceng sejak kemaren. Dari pemeriksaan didapatkan tekanan darah 120/90 mmHg, nadi 1 15 x/menit, RR 20 x/ menit, suhu 36 oc. Pembukaan 3 cm, penipisan 75 %, Ietak kepala, UPD normal. Setelah dievaluasi selama 8 jam tidak menunjukkan tanda-tanda kemajuan. Diagnosis pasien ini adalah...","options":["Secondary arrest of parturition","Arrest of descent","CPD","Prolong latent phase","Fetal distosia"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-164","number":164,"package":"Paket Prediksi","topic":"THT","title":"Soal 164 · Seorang pasien Iaki-laki berusia 27 tahun tahun,…","page":238,"stem":"Seorang pasien Iaki-laki berusia 27 tahun tahun, datang berobat dengan keluhan bersin- bersin, terutama pada pagi hari dan saat membereskan tumpukkan buku-buku lama. Bersin disertai hidung tersumbat dan berair, gatal, pada mata dan hidung. Riwayat penggunaan obat pada hidung dan mata disangkal. Ayah pasien memiliki riwayat asma. Diagnosis yang tepat pada pasien ini adalah...","options":["Rhinitis vasomotor","Rhinitis medikamentosa","Rhinitis alergi","Rhinitis akut","Rhinitis atrofi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-165","number":165,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 165 · Seorang wanita berusia 60 tahun datang dengan…","page":238,"stem":"Seorang wanita berusia 60 tahun datang dengan keluhan mata kanan bengkak, merah dan nyeri. Keluhan ini disertai demam sejak 4 hari yang lalu. Dari pemeriksaan fisik didapatkan masa cm, fluktuasi pus (+), hiperemis, nyeri tekan (+) pada palpebra ocular superior. Diagnosis yang tepat adalahm","options":["Blefaritis squamosa","Blefaritis superfisial","Blefaritis angular","Hordeolum","Meibomianitls"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-166","number":166,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 166 · Seorang perempuan pelajar SMU berusia 16 tahun…","page":238,"stem":"Seorang perempuan pelajar SMU berusia 16 tahun dibawa keluarga ke IGD karena nyeri dada dan kejang. Keluhan dirasakan sejak pasien bermain basket dilapangan, tiba-tiba pasien pingsan dan buta. Riwayat trauma tidak ditemukan, cedera kepala disangkal. Ditemukan kejang tipe kaku seluruh tubuh dengan tangan menggenggam. Pemeriksaan oftamologi tidak ada defek pupil afferens. Diagnosis pada kasus di atas adalah.„","options":["Hipokondriasis","Gangguan somatisasi","Gangguan penyesuaian","Reaksi konversi","Psikosomatik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-167","number":167,"package":"Paket Prediksi","topic":"Mata","title":"Soal 167 · Seorang pria berusia 30 tahun, datang ke…","page":239,"stem":"Seorang pria berusia 30 tahun, datang ke RS dengan keluhan penglihatan buram pada mata kiri sejak 5 hari yang lalu. Keluhan juga disertai dengan rasa mengganjal dan silau. Hasil pemeriksaan tajam penglihatan 6/30, konjungtiva injeksi siliar, injeksi para kornea; pada kornea ditemukan dendrit dan sensibilitas menurun. Tidak ditemukan lesi kulit pada dahi maupun di sekitar mata. Etiologi dari penyakit di atas adalah„.","options":["Herpes Simpleks","Herpes Zoster","Bakteri","Jamur","Protozoa"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-168","number":168,"package":"Paket Prediksi","topic":"THT","title":"Soal 168 · Seorang wanita berusia 25 tahun datang ke…","page":239,"stem":"Seorang wanita berusia 25 tahun datang ke puskesmas dengan keluhan telingan kanan keluar cairan kental dan kuning kehijauan. Keluhan ini disertai dengan adanya pendengaran berkurang dan tidak nyeri. Sebelumnya pasien sering mengeluarkan cairan dari telinga kanan sejak usia 5 tahun yang disertai dengan batuk dan pilek. Pada pemeriksaan otoskopi ditemukan membran tymphani perforasi di tengah, keluar cairan kuning kental dan tidak hiperemis. Diagnosis yang tepat pada pasien ini adalah.„","options":["Otitis media akut","Otitis media kronik akut","Otitis media akut rekurent","Otitis media serosa","Otitis media kronik eksaserbasi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-169","number":169,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 169 · Seorang perempua berusia 28 tahun datang dengan…","page":239,"stem":"Seorang perempua berusia 28 tahun datang dengan keluhan diare dan muntah. Diare dan muntah profus. Tidak ditemukan nyeri perut. Pasien tampak lemas, mulut kering, dan mata sayu. Tekanan darah 90/50 mmHg, nadi I IO x/menit, suhu tubuh 36,5 OC. Tindakan pertolongan pertama pada pasien ini adalah....","options":["Rehidrasi IV dengan cairan isotonik","Pemberian antiemetik","Pemberian antispasmodik","Pemberian antibiotik","Pemberian antipiretik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-170","number":170,"package":"Paket Prediksi","topic":"THT","title":"Soal 170 · • Seorang Iaki-laki berusia 28 tahun datang…","page":239,"stem":"• Seorang Iaki-laki berusia 28 tahun datang ke puskesmas dengan keluhan hidung tersumbat sejak 1 minggu yang lalu. Lubang hidung kanan keluar cairan kental warna kehijauan berbau busuk. Pasien sering mengeluh nyeri gigi dan gusi bengkak, membaik dengan antinyeri. Pemeriksaan rhinoskopi anterior udem konka inferor dan terdapat sekret di meatus media. Pemeriksaan penunjang yang tepat untuk pasien tersebut adalah.„","options":["X foto Rheese","X foto schuller","Xfoto Caldwell","X foto Waters","X foto Owen"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-171","number":171,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 171 · Seorang perempuan berusia 35 tahun datang ke…","page":240,"stem":"Seorang perempuan berusia 35 tahun datang ke RS dengan keluhan terdapat benjolan di bokong sebesar bola pingpong sejak I minggu yang lalu. Benjolan dirasakan nyeri dan panas, terdapat demam. Dermatologikus : nodul eritem, nyeri, panas, agak lembek di bagian puncaknya dan terdapat beberapa vesikel. Diagnosis yang tepat pada pasien di atas adalahm","options":["Karbunkel","Furunkel","Furunkulosis","Phlegmon","Skrofuioderma"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-172","number":172,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 172 · Seorang pasien pria berusia 65 tahun datang…","page":240,"stem":"Seorang pasien pria berusia 65 tahun datang dengan keluhan sesak napas, terutama saat berbaring. Sering terbangun pada malam hari karena sesak. Pasien juga merasakan lemas. Vital sign tekanan darah 160/90 mmHg, nadi 120yJmenit, RR 28x/menit, S: 36,90C. JVP meningkat, ronki basah (+) pada kedua basal paru. Hepatomegali (+), edema tungkai (+). Pembesaran jantung (+). Diagnosis yang paling tepat","options":["Gagal jantung akut","Gagal jantung kiri","Gagal jantung kanan","Gagal jantung kongestif","Gaga! jantung sistolik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-173","number":173,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 173 · Seorang wanita berusia 55 tahun datang diantar…","page":240,"stem":"Seorang wanita berusia 55 tahun datang diantar keluarga dengan keluhan penurunan kesadaran sejak 3 jam yang lalu. Sebelumnya pasien mengeluh nyeri kepala dan muntah- muntah. Dari pemeriksaan fisik didapatkan tekanan darah 200/1 IO mmHg, nadi 64 x/ menit, RR 16x/menit, suhu 40 OC. Posisi yang tepat dalam perawatan pasien tersebut adalahm","options":["Posisi syok","Posisi trandelenburg","Posisi miring ke kanan","Head trunk up 300","Head tilt dan Jaw trust"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-174","number":174,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 174 · Seorang perempuan berusia 16 tahun datang ke…","page":240,"stem":"Seorang perempuan berusia 16 tahun datang ke RS diantar keluarganya dengan keluhan pingsan sesaat sebelum ke RS. Sejak 1 minggu ini pasien sering pingsan. Keluhan disertai gusi berdarah dan lebam-lebam di tangan dan kaki, pasien sering merasa berdebar-debar. Sejak 2 bulan ini pasien sering sakit flu. Pada pemeriksaan fisik didapatkan tekanan darah 110/80 mmHg ,Nadi 102 x/mnt ,RR 16 x/mnt ,suhu 38,6, hepatomegali dan splenomegali. Pemeriksaan penunjang didapatkan Hb 4,5 g/dl, lekosit 2.700, trombosit 45.000, LED 75, eritrosit 5.800.000. Diagnosis yang tepat pada kasus di atas","options":["Anemia post hemoragik","Anemia aplastik","Anemia hemolitik","Anemia megaloblastik","Anemia defisiensi besi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-175","number":175,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 175 · seorang pasien laki-laki berusia 25 tahun datang…","page":241,"stem":"seorang pasien laki-laki berusia 25 tahun datang ke praktek dokter keluarga dengan keluhan suara serak sejak 2 bulan yang lalu. Keluhan disertai batuk lama dan terkadang batuk berdarah. Pasien tinggal serumah dengan kakak kandungnya yang sedang menderita TB paru. Apakah pemeriksaan penunjang yang paling tepat dianjurkan pada pasien tersebut?","options":["Pewarnaan gram","Pemeriksaan BTA","Pemeriksaan KOH","Pemeriksaan darah rutin","Foto rontgen leher AP lateral"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-176","number":176,"package":"Paket Prediksi","topic":"THT","title":"Soal 176 · seorang laki-laki berusia 30 tahun datang ke…","page":241,"stem":"seorang laki-laki berusia 30 tahun datang ke klinik dengan keluhan gatal pada telinga kiri sejak 3 hari yang lalu, disertai keluar sekret berwarna putih keabuan sedikit. Pada pemeriksaan fisik telinga didapatkan membran timpani utuh, tidak ada nyeri/ benjolan. Diagnosis yang tepat pada kasus di atas adalah...","options":["Otitis eksterna maligna","Otitis eksterna furunkulosa","Otitis eksterna difus","Otosklerosis","Otomikosis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-177","number":177,"package":"Paket Prediksi","topic":"Anak","title":"Soal 177 · Seorang anak berusia 8 tahun mengeluh sering…","page":241,"stem":"Seorang anak berusia 8 tahun mengeluh sering sesak serta kuku dan bibirnya berwarna kebiruan. Keluhan muncul terutama saat ia sedang kelelahan. Saat bermain ia sering tiba- tiba jongkok karena sesak. Badannya kurus dan kecil. Keluhan dirasakan sejak ia masih bayi dan saat menangis bibir dan kukunya kebiruan. pemeriksaan fisik didapatkan bising jantung sistolik disertai thrill dan adanya peningkatan aktivitas ventrikel kanan. Jari-jari pasien seperti jari tabuh. Apa diagnosis pasien ini?","options":["Tetralogi Fallot","Disfungsi ventrikel kanan","VSD dengan sindrom eisenmenger","Stenosis pulmonal","Atresia pulmonal"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-178","number":178,"package":"Paket Prediksi","topic":"Anak","title":"Soal 178 · Seorang bayi lahir 8 jam yang lalu…","page":241,"stem":"Seorang bayi lahir 8 jam yang lalu di bidan, usia kehamilan 34 minggu, berat lahir 2200 gr, lahir langsung sianosis, bunyi jantung 148 x/mnt pernafasan 72 x/mnt, retraksi intercostal ringan dan siaonis yang menghilang dengan pemberian oksigen, merintih dengan stetoskop suara paru kanan dan kiri normal. Berapakah score Dowone pada bayi tersebut?","options":["4","5","6","7","8"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-179","number":179,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 179 · Laki-laki 28 tahun mengalami sulit tidur selama…","page":241,"stem":"Laki-laki 28 tahun mengalami sulit tidur selama 3 bulan, berdebar, gelisah, sering buang air besar lebih dari 3 kali sehari, dan penurunan berat badan. Kesadaran compos mentis, tekanan darah 120/60 mmHg, nadi 120 kali/menit, napas 20 kali/menit. Ditemukan pembesaran leher dan proptosis. Pemeriksaan laboratorium apakah yang dipilih?","options":["T3","T4","Anti TPO","FT4","TSHs"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-180","number":180,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 180 · Seorang pasien perempuan berusia 25 tahun diantar…","page":242,"stem":"Seorang pasien perempuan berusia 25 tahun diantar keluarganya ke poliklinik dengan keluhan sulit tidur dan suka bicara sendiri sejak 2 bulan yang lalu. Keluhan seperti ini muncul sejak pasein diberhentikan dari tempat kerjanya. Saat tidak bisa tidur malam hari pasien mengganggu anggota keluarga Iain di rumah dengan membuat kegaduhan. Pasien juga sering mendengar ada suara yang mengikutinya. Orang tua pasien mengatakan pasien tidak mau mandi dan makan, serta pernah mencoba bunuh diri.Terapi yang tepat pada pasien di atas adalahm","options":["Haloperidol","Tiotined","Clorpromazin","Flukonazine","Risperidone"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-181","number":181,"package":"Paket Prediksi","topic":"THT","title":"Soal 181 · Seorang Iaki-laki berusia 35 tahun mengeluhkan nyeri…","page":242,"stem":"Seorang Iaki-laki berusia 35 tahun mengeluhkan nyeri saat menelan sejak 4 hari yang lalu. Pada pemeriksaan fisik di dapatkan bintik — bintik kemerahan pada langit — langit dan dinding belakang mulut, TO-TO. Vital sign dalam batas normal. Diagnosis yang tepat pada pasien tersebut adalah...","options":["Laringitis","Tonsilitis","Rhinitis","Sinusitis","Faringitis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-182","number":182,"package":"Paket Prediksi","topic":"Kesehatan Masyarakat","title":"Soal 182 · Seorang pasien perempuan berusia 32 tahun bekerja…","page":242,"stem":"Seorang pasien perempuan berusia 32 tahun bekerja di kebun, datang ke Puskesmas diantar Oleh suaminya dengan keluhan kaki kanan bengkak. Keluhan tersebut sudah dirasakan sejak I tahun ini, makin lama makin bengkak sampai sulit untuk berjalan. Pemeriksaan fisik didapatkan kaki kanan edem disertai ada abses di kaki dan edema pada scrotum. Pemeriksaan urine ditemukan chyluria. Vektor apakah penyebab kasus di atas?","options":["aides aegypti sp","anopeles sp","culex sp","toxochycanti cp","mansonia sp"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-183","number":183,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 183 · Seorang pria berusia 27 tahun datang ke…","page":242,"stem":"Seorang pria berusia 27 tahun datang ke Puskesmas dengan keluhan BAK berwarna merah dan nyeri sejak I hari. Kencing dirasakan tidak puas. Keluhan disertai demam tanpa ada riwayat batu ginjal. Pada pemeriksaan fisik didapat tekanan darah 120/60 mmHg, nadi 88x/menit, suhu 390C. Ditemukan nyeri ketok (+) pada costae vertebrae angle kanan dan kiri, Balotement -/-. Diagnosis yang paling tepat adalah...","options":["Infeksi saluran kemih","Caginjal","Pyelonefritis","Glomerulonefritis","Nefrolitiasis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-184","number":184,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 184 · Seorang laki-laki berusia 20 tahun datang dengan…","page":243,"stem":"Seorang laki-laki berusia 20 tahun datang dengan keluhan terdapat bercak hitam pada kedua pipinya. Pasien memiliki hobi menyelam. Pemeriksaan fisik terdapat makula bewarna coklat berpatas tegas dengan tepi tidak rata. Diagnosis yang tepat pada pasien tersebut adalah.„","options":["Melasma","Vitiligo","Karotenosis","Hemokromatosis","Likopenemia"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-185","number":185,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 185 · Seorang laki-laki berusia 20 tahun datang dengan…","page":243,"stem":"Seorang laki-laki berusia 20 tahun datang dengan keluhan terdapat bercak hitam pada kedua pipinya. Pasien memiliki hobi menyelam. Pemeriksaan fisik terdapat makula bewarna coklat berpatas tegas dengan tepi tidak rata. Diagnosis yang tepat pada pasien tersebut adalah.„","options":["Melasma","Vitiligo","Karotenosis","Hemokromatosis","Likopenemia"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-189","number":189,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 189 · Seorang Iaki-laki berusia 45 tahun datang ke…","page":244,"stem":"Seorang Iaki-laki berusia 45 tahun datang ke poliklinik dengan keluhan timbul benjolan pada bokong sebesar bola pingpong kemerahan dan nyeri sejak 3 hari yang lalu. Keluhan disertai dengan demam. Pada pemeriksaan dermatologikus ditemukan nodul eritema panas, nyeri, agak lunak pada puncaknya, dan terdapat beberapa pustul di atasnya. Penyebab yang paling mungkin pada kasus ini adalah...","options":["Staphylococcus aureus","Streptococcus beta hemolyticus","Enterobacter sp","Pseudomonas aeruginosa","Eikenella corrodens"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-190","number":190,"package":"Paket Prediksi","topic":"Anak","title":"Soal 190 · Seorang anak berusia 14 tahun datang dengan…","page":244,"stem":"Seorang anak berusia 14 tahun datang dengan keluhan pusing setelah memakai kacamata yang baru dipakainya seminggu yang lalu. Kaca mata yang digunakan memiliki S3.50 C+ 1.50 X180. Pemeriksaan apa yang seharusnya dilakukan terhadap pasien ini?","options":["Slitlamp","Keratometri","Lensometri","Funduskopi","Tonometri"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-191","number":191,"package":"Paket Prediksi","topic":"Neurologi","title":"Soal 191 · Seorang laki-laki berusia 17 tahun datang ke…","page":244,"stem":"Seorang laki-laki berusia 17 tahun datang ke Puskesmas dengan keluhan batuk sejak kemarin. Batuk berdahak kental dan sulit dikeluarkan, keluhan disertai sesak, keluhan sering berulang, pada pemeriksaan fisik GCS 15, tekanan darah 120/80 mmHg, nadi IOOx/ menit, RR 29x/menit, suhu 38,2 oc, pemeriksaan thorax : bentuk dada simetris, perkusi sonor, suara nafas vesikuler di apex, wheezing pada seluruh lapang paru, bising jantung (-), pemeriksaan abdomen dbN. Diagnosis yang tepat pada kasus di atas adalah...","options":["asma bronkial","bronchiectasis","emfisema paru","bronchitis kronis","pneumonia"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-192","number":192,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 192 · Seorang Iaki-laki berusia 55 tahun datang ke…","page":244,"stem":"Seorang Iaki-laki berusia 55 tahun datang ke dokter dengan keluhan kelumpuhan ke dua kaki. Dari pemeriksaan didapatkan kelumpuhan ke dua kaki tipe spastik, pada pemeriksaan sensorik terdapat gangguan setinggi Thorax XI. Pemeriksaan radiologis didapatkan destruksi pedikel thorax XI. Diagnosis yang tepat pada pasien tersebut adalah„.","options":["Multiple sclerosis","Guillain Barre Syndrome","Potts syndrome","Trauma","Hernia Nucleus Pulposus"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-193","number":193,"package":"Paket Prediksi","topic":"Kulit","title":"Soal 193 · Seorang perempuan berusia 23 tahun datang ke…","page":244,"stem":"Seorang perempuan berusia 23 tahun datang ke dokter dengan keluhan gatal dibokong sejak I tahun yang lalu. Gatal hilang timbul dan dirasakan setiap sehabis menstruasi. Keluhan tersebut dirasakan hampir setiap bulan. Pasien sudah berobat ke puskesmas. sembuh dan kemudian akan timbul lagi. Pasien memiliki kebiasaan memakai celana pendek ketat. Gambaran dermatologis plakat, makula hiperpigmentasi, Papul eritem, erosi, ekskoriasi. Diagnosis yang tepat pada pasien ini adalah...","options":["Tinea kruris","Dermatitis intertriginos","Kandidiasis kutis","Eritrasma","Psoriasis"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-194","number":194,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 194 · Seorang wanita berusia 22 tahun belum menikah…","page":245,"stem":"Seorang wanita berusia 22 tahun belum menikah datang dengan keluhan perdarahan dari kemaluan sejak 2 hari yang lalu. Sebelumnya pasien datang ke dukun diberi obat- obatan minum dan obat-obatan yang dimasukkan ke vagina. Saat datang pasien dalam kondisi lemah, tekanan darah 90/60 mmHg, nadi 114 x/menit, RR 20x/menit, dan suhu 39 OC. Didapatkan flek (+) bau (+), portio terbuka teraba jaringan . Diagnosis yang tepat pada pasien ini adalah...","options":["Abortus inkomplit","Abortus komplit","Abortus imminen","Abortus insipien","Abortus septik"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-195","number":195,"package":"Paket Prediksi","topic":"Penyakit Dalam","title":"Soal 195 · Seorang pria berusia 30 tahun datang dengan…","page":245,"stem":"Seorang pria berusia 30 tahun datang dengan keluhan demam tinggi, diare, dada dirasakan semakin berdebar, terdapat benjolan pada leher depan sejak 5 bulan yang lalu. Pasien mengeluh berat badannya menurun, sering berdebar-debar, dan berkeringat banyak. Pada pemeriksaan fisik ditemukan eksoftalmus, dan tremor pada kedua tangan. Index krisis tiroid 45. Penyebab kondisi pasien di atas adalah...","options":["Penggunaan propanolol","Penggunaan PTU overdosis","Angina","Infeksi berat","Lugolisasi hebat"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-196","number":196,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 196 · Seorang dokter forensik melakukan otopsi mayat digali…","page":245,"stem":"Seorang dokter forensik melakukan otopsi mayat digali dari kubur karena diduga mati tidak wajar. Ditemukan tulang belulang manusia lengkap didapatkan lubang pada calvaria kanan dan ditemukan proyektil peluru dalam rongga kepala. Setelah selesai pemeriksaan suami korban bertanya hasil otopsi. Sikap dokter yang tepat adalah...","options":["Memberitahu VeR karena yang meminta keluarga terdekat","Tidak memberitahukan VeR karena rahasia jabatan","Memberi saran untuk bertanya kepada polisi sebagai penyidik","Memberi ringkasan VeR","Memberitahu hasil otopsi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-197","number":197,"package":"Paket Prediksi","topic":"Bedah","title":"Soal 197 · Seorang laki-laki berusia 25 tahun mengalami kecelakaan…","page":245,"stem":"Seorang laki-laki berusia 25 tahun mengalami kecelakaan motor dengan kepala sebelah kanan membentur trotoar. Sesaat setelah kecelakaan pasien masih sadar. Setengah jam kemudian pasien merasa pusing dan mengantuk, lalu muntah dan tidak sadarkan diri. Foto ronsen kepala terdapat garis linier di temporal kanan. Perdarahan apakah yang dialami Oleh pasien terebut?","options":["Perdarahan subarakhnoid","Perdarahan intrakranial","Perdarahan subdural","Perdarahan intraserebral","Perdarahan epidural"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-198","number":198,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 198 · Seorang perempuan berusia 20 tahun datang dengan…","page":246,"stem":"Seorang perempuan berusia 20 tahun datang dengan keluhan nyeri perut kanan bawah sejak 3 hari yang lalu, awalnya nyeri di epigastrium kemudian menjalar ke kanan bawah. Keluhan disertai dengan muntah dan penurunan nafsu makan. Pada pemeriksaan didapatkan tanda Murphy sign (+) Rovsing sign Kemungkinan penyebab keluhan pasien tersebut adalah.„","options":["Gangguan pasase usus","Trauma","Keganasan","Infeksi","Perdarahan"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-199","number":199,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 199 · Seorang wanita berusia 30 tahun diantar Oleh…","page":246,"stem":"Seorang wanita berusia 30 tahun diantar Oleh suaminya ke IGD RS karena mengalami Iuka bakar akibat ledakan tabung gas. Pada pemeriksaan fisik pasien tampak sadar, tidak mengalami sesak nafas, TD 90/60 mmHg, nadi 116 x/menit, frekuensi nafas 20x/menit. Pasien mengalami Iuka bakar derajat II dan perkiraan luas Iuka bakar 50%. Pena talaksanaan yang tepat pada pasien ini adalah...","options":["Cairan infus RL 4ml/kgBB/Iuas Iuka bakar","Analgetik","Salep silver sulfadiazine","Antibiotik spectrum luas","Oksigenasi"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."},{"id":"p3-200","number":200,"package":"Paket Prediksi","topic":"Campuran","title":"Soal 200 · Seorang laki-laki berusia 25 tahun datang ke…","page":246,"stem":"Seorang laki-laki berusia 25 tahun datang ke dokter umum dengan keluhan demam sejak I minggu yang disertai mual, muntah dan BAB susah dalam 2 hari ini. Pasien dianjurkan untuk melakukan pemeriksaan darah. Pemeriksaan darah didapatkan Hb 13,1 gr%, Hct 38.6, Lekosit 24.000 dan trombosit 239.000. Pemeriksaan darah lanjutan yang disarankan pada pasien ini","options":["Widal dan IgG Salmonella","Widal dan IgM Salmonella","Widal dan kultur feses","Widal dan kultur darah","Widal dan kultur urine"],"bookKey":null,"answer":null,"reason":"","others":[],"takeaway":"","refs":[],"note":"","status":"tanpa_kunci","scored":false,"reviewed":false,"checked":null,"bookExplanation":"","answerPage":null,"transcriptionIssues":[],"adaptation":"Soal teks hasil transkripsi; belum diperiksa ulang secara medis."}]};
